// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":27,"question":"هل يجوز لنا شراء بضائع يبيعها الجمرك بالمزاد العلني، وهي مملوكة لأشخاصٍ، ولكنَّهم تأخَّروا في استلامها؟","title":"حكم شراء بضائع جمرك لم يستلمها أصحابُها","answer":"الجواب: إذا كان لها مسوغٌ شرعيٌّ فلا مانع من شرائها. أما إن كنت تعلم أنها مأخوذة ظلمًا، ما لها مُسوِّغ شرعي؛ ما يجوز لك شراؤها؛ لأنك تُعين على الإثم والعدوان حينئذٍ. أما إذا كنت تعلم أنها مأخوذة بوجهٍ شرعيٍّ؛ لأنه مهرب لما حرَّم الله؛ لأنه مُتعاطٍ على أشياء تُوجب مُصادرتها من جهة الدولة لكونه فعل ما يُوجب ذلك، فهذا يستحقُّ أن يُعاقب، ولك أن تشتري ما أُخذ منه؛ لكونه أُخذ بوجهٍ شرعيٍّ، وعقوبة شرعية. أما إذا علمتَ أنه لا يستحقُّ ذلك أو كانت عندك شُبَهٌ في ذلك؛ فلا تشترِ.","link":"https://binbaz.org.sa/fatwas/2807/حكم-شراء-بضاىع-جمرك-لم-يستلمها-اصحابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0280.mp3","categories":["البيوع"]},{"id":65,"question":"سماحة الشيخ حفظكم الله، هل يجوز لي شراء أثاث بالتقسيط من بنك الراجحي؛ لأن هناك من يقول: إن الشراء بالتقسيط حرام؛ لأن فيه ربا أفيدوني؟","title":"حكم الشراء بالتقسيط من البنوك","answer":"الجواب: لا بأس بالتقسيط، شراء سيارة أو أثاث أو ملابس أو بيت أو أرض بالتقسيط لا بأس، إذا كان مالكًا لها البائع، إذا كانت عند البائع مملوكة له، حائزًا لها في بيته في ملكه في حوشه إذا كانت عنده قد ملكها، وحازها وباعها بالتقسيط؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/2981/حكم-الشراء-بالتقسيط-من-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0040.mp3","categories":["البيوع"]},{"id":144,"question":"توجد شركة تبيع للناس بطاقات، قيمة البطاقة مئة وخمسون أو أكثر، ويحصل لحامل هذه البطاقة خصمٌ في بعض المُستشفيات والمحطات وكثير من المحلات التّجارية التي تتفق مع هذه الشركة؟","title":"حكم بيع بطاقات التخفيضات","answer":"الجواب: هذه ذكرناها في اللجنة، وكتبنا عنها أنها لا تجوز، وصلت إلينا وكتبنا عنها مدةً طويلةً أنا واللجنة الدائمة بإنكارها؛ لأنها من الربا، يُسلّمهم مئةً وخمسين وقد يستفيد مئات في مُقابلها.","link":"https://binbaz.org.sa/fatwas/3681/حكم-بيع-بطاقات-التخفيضات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0137.mp3","categories":["البيوع","الربا والصرف"]},{"id":205,"question":"في معارض بيع السيارات يلجأ صاحبُ المعرض إلى أخذ عربون من المُشتري الذي وقف عليه بسعر السيارة، فإذا ما عدل عن شراء السيارة فإنَّ صاحب المعرض يأكل العربون، فما حكم ذلك؟","title":"ما حكم \"العربون\" بين البائع والمشتري؟","answer":"الجواب: هذا فيه تفصيل: إذا تمَّ الاتفاقُ بينه وبين صاحب السيارة على ثمنٍ وقال له: العربون ألف ريـال، وأمهلني ثلاثة أيام أو أربعة أيام أو خمسة أيام حتى أُشاور وأنظر، فإن جئتُك وأخذتُها؛ سلَّمتُ باقي الثمن، وإلا فالعربون لك، هذا فيه خلافٌ بين أهل العلم، والصواب أنه يصحُّ، ويكون له العربون؛ لأنه عطله. أما من دون ذلك فلا يصحُّ العربون، فهو من الثمن، شرى وإلا يرده عليه، إلا إذا اتفقا على هذا؛ إذا اتفقا وقال: أمهلني أيامًا أنظر في أمري وأستخير الله، فإن جئتُك واشتريتُ فهو من الثمن، وإلا فهو لك؛ فلا بأس، المسلمون على شروطهم.","link":"https://binbaz.org.sa/fatwas/3969/ما-حكم-العربون-بين-الباىع-والمشتري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0212.mp3","categories":["الربا والصرف","البيوع"]},{"id":289,"question":"دار المال الإسلامي تُعطي أرباحًا شهريةً غير محددةٍ مقابل الأموال التي تُودع فيها من المواطنين، هل تلك الأرباح حلالٌ أم حرامٌ؟","title":"ما كيفية المضاربة الجائزة شرعًا والممنوعة؟","answer":"الجواب: هذا فيه تفصيل: فإن كان الأرباح حصلت عن بيعٍ وشراءٍ ومضاربةٍ، وحصل ربحٌ، فأعطته إياه على الشرط الذي بينهم: بالنصف، أو بالثلث؛ فلا بأس. وإن كانت أرباحه معينةً: في كل شهرٍ لك كذا ريـال، ريالين، 5% ، 10%، فهذا ربًا لا يجوز. أما إذا كان لا، تأخذ منهم أموالًا وتجعلها في سيارات، في أوانٍ، في أشياء أخرى تبيعها، حاجات تبيعها، وتُعطي حظّه من الربح بينهما أنصافًا، أو أثلاثًا، أو أرباعًا، تأخذ حقَّها وتُعطيه حقَّه من الربح؛ فهذا لا بأس به، مثل: المُضاربات، مثلما تُعطي أخاك مثلًا عشرة آلاف ريـال، وتحطّها فيما ترى من السلع، تقول: بعها والفائدة بيننا، فهذا لا بأس به، هذه جائزة بإجماع المسلمين، وهذا الواقع في العصور الأول: في عهد النبي ﷺ وقبله وبعده، هذا يُسمَّى: المُضاربة، وهي المُشاركة، فإذا صار الذي تسلم له المال بهذه الصِّفة بأن تأخذ الأموال وتجعلها في السلع، تبيعها بالربح، تبيع بين صاحب المال وبين الدار بالنصف أو بالثلث؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/4288/ما-كيفية-المضاربة-الجاىزة-شرعا-والممنوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0337.mp3","categories":["الربا والصرف","البيوع"]},{"id":291,"question":"ما حكم العمل في البنك بسبب الحاجة؟","title":"حكم العمل بالبنوك للحاجة والضرورة","answer":"الجواب: البنوك لا يجوز العمل فيها، بنوك الربا لا يجوز العمل فيها؛ لأنها تعاونٌ على الإثم والعدوان، فلا يجوز التَّعامل بها، الرسول لعن آكل الربا ومُوكله وكاتبه وشاهديه، وقال: هم سواء، فالكاتب للربا والشَّاهد عليه شريكٌ، والذي يُعينهم يكون محاسبًا أو يكون مُراسلًا أو يكون فرَّاشًا فيه إعانة لهم على بلائهم.\nس: والذي يُودع؟\nالشيخ: ما ينبغي الإيداع، لكن إذا دعت الضَّرورة لا بأس، الضَّرورة أن يُودع خوفًا على ماله، ليس عنده مكانٌ آخر يُودع بدون فائدةٍ.","link":"https://binbaz.org.sa/fatwas/4290/حكم-العمل-بالبنوك-للحاجة-والضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0339.mp3","categories":["الربا والصرف","البيوع"]},{"id":379,"question":"عندي محل لبيع الأجهزة الكهربائية، وكنتُ أبيع الجهاز نقدًا بمئة جنيه مصري، وأبيع الجهاز بالتقسيط على سنة بمئة وخمسين جنيهًا، فهل البيع بالتَّقسيط حلالٌ أم حرامٌ؟ وهل يُعتبر البيع بالتقسيط مثل نظام البنوك أم لا؟ مع الرجاء توضيح الفرق.","title":"حكم البيع بالتقسيط إلى أجل مسمى","answer":"الجواب: البيع إلى أجلٍ جائزٌ في الشرع بنصِّ الكتاب والسنة، وبعضهم حكاه إجماعًا، والله جلَّ وعلا بيَّن هذا في كتابه العظيم حيث قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282]، فالمُداينة إلى أجلٍ مُسَمًّى أو إلى آجالٍ مُسَمَّاة لا بأس بها، بشرط أن يكون المبيعُ مملوكًا للبائع، وتحت قبضته وقدرته، فإذا كان تحت قبضته وقُدرته فباعه إلى أجلٍ أو إلى آجالٍ -وهي الأقساط- فلا بأس، كأن يبيع أرضه المملوكة له، أو سيارته التي في حوزته، أو بناء عنده، أو أوانٍ، أو ملابس، كلها في حوزته وتحت قدرته، يبيعها إلى أجلٍ مُسمًّى: إلى دخول رمضان من عام 1408، أو إلى أقساط، كل قسط يُسلم في أول رمضان من عام ثمانٍ، ومن عام تسع، ومن عام عشر، ومقدار القسط كذا وكذا ألف ريـال، أو مئة ريـال، فإذا كانت الأقساط معلومةً، والآجال معلومةً، والثمن مباحًا، والسلعة مملوكةً وفي قبضة البائع، والشروط الشرعية متوفرة؛ فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/4700/حكم-البيع-بالتقسيط-الى-اجل-مسمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0435.mp3","categories":["الربا والصرف","البيوع"]},{"id":421,"question":"بعض الأسواق التّجارية تضع جوائز على بعض المُنتجات الغذائية: كالحليب وغيره، هل يجوز للمسلم أن يشتري لكي يحصل على الجائزة؟ وما حكم مَن اشترى وحصلت له جائزةٌ وليس قصده أن يشتري لكي يكسب، وإنما جاءت الجائزة صدفةً؟ هل هي جائزة أم لا؟","title":"حكم شراء بعض السلع للفوز بجائزة عليها","answer":"الجواب: إذا كانت الجائزة بالقمار: مَن صادفه رقم كذا أو رقم كذا يحصل له كذا، هذا ما يجوز؛ لأنَّ هذا من القمار، من الميسر. أما إذا كانت الجائزة معلومةً، يقولون: مَن اشترى منا أربع مرات نُعطيه كذا، نعطيه..... وزيادة، نُعطيه سلعة كذا، معروفة، ما فيها شُبهة؛ هذا لا بأس به، هذا معناه ترغيب في الشراء منهم، أو: مَن اشترى منا عاملنا ننزل له ريالًا في السلعة، أو ريالين في السلعة، هذه ما فيها بأس؛ لأنها معلومة، ما في غرر ولا ميسر. أما إذا كانوا يحطّون أرقامًا: مَن صادف رقم كذا يُعطى راديو، ومَن صادف رقم كذا يُعطى سيارة، ومَن صادف رقم كذا يُعطى ثلاجة؛ هذا من الميسر، من الربا، ما يجوز.","link":"https://binbaz.org.sa/fatwas/4845/حكم-شراء-بعض-السلع-للفوز-بجاىزة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0479.mp3","categories":["الربا والصرف","البيوع"]},{"id":442,"question":"المشتري إذا كانت السلعة بالدولار فنقص في السوق فيتضرر البائع بذلك، هل نقول القول إذا رد... حتى يمينه مقبولة...، مثلًا اشترى منه \"دولار\" فنقص في السوق؟","title":"حكم خيار المجلس للمشتري والبائع","answer":"الجواب: ما دام تم البيع انتهى، إلا إذا كانوا في المجلس لهم الخيار، كل واحد له الخيار، سواء دولار وإلا غيره البيعان بالخيار حتى يتفرقا ما لم يشترطا ترك الخيار.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/5916/حكم-خيار-المجلس-للمشتري-والباىع","audio":"https://files.zadapps.info/binbaz.org.sa/dolar.mp3","categories":["الربا والصرف","البيوع"]},{"id":445,"question":"الآن بعض تجار السيارات إذا أراد أن يشتري سيارة يشتريها وتبقى باسم من اشتراها منه بحجة أن السيارة تصير أرغب للناس وهو يريد أن يبيعها، فيقول: ابق على اسمك، ويعطيه تفويضًا، هل يجوز لهذا المشتري أن يبيع؟","title":"ما حكم بيع السلعة قبل حيازتها؟","answer":"الجواب: هذا كذب، لا بدّ يبيعها باسم صاحبها؛ لأن هذا قد تترتب عليه أحكام. يبيعها من صاحبها ويعطيه وثيقة بأنه باعها عليه ولا يبيعها إلا بعد إخراجها من المعرض إلى معرض آخر أو إلى بيته أو إلى السوق؛ لما في الحديث نهى أن تُباع السلع حتى يحوزها التجار إلى رحالهم. (دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6153/ما-حكم-بيع-السلعة-قبل-حيازتها","audio":"https://files.zadapps.info/binbaz.org.sa/car.mp3","categories":["الربا والصرف","البيوع"]},{"id":450,"question":"بعض أهل العلم لا يفرِّق بين مسألة العِينَة والتَّوَرُّق؟","title":"ما الفرق بين بيع العِينَة والتَّوَرُّق؟","answer":"الجواب: غلط، التَّوَرُّق غير، التَّوَرُّق أن تشتري السلعة إلى أجل معلوم وتبيعها على الناس، واللي يشتريها ما يبيعها عليك، اللي يشتريها يبيعها على الناس الآخرين، إن باعها عليك هذه العِينة، لكن إن كان باعها على غيرك ما جاءت العِينة، يبيعها على غيرك، يتزوج أو يبني بيتًا أو يقضي دينًا، اشترى منه سيارة بمائة ألف ريال ثم باعها على غيره ما فيه شيء، العينة يبيعها عليه، أما إذا باعها على غيره فليس فيه ربا، والناس في حاجة إلى هذا.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6173/ما-الفرق-بين-بيع-العينة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/tawark008.mp3","categories":["الربا والصرف","البيوع"]},{"id":451,"question":"هناك من استدل على جواز بيع العِينَة بحديث أبي سعيد وأبي هريرة قال ﷺ: \"بع الجمع بالدراهم ثم اشتر بالدراهم جنيبًا\"؟","title":"معنى حديث \"بع الجمع بالدراهم ثم اشتر..\"","answer":"الجواب: لا، ما هو بعِينة، هذا يبيعها ويأخذ الفلوس ثم يشتري. تبيع التمر الرديء بالدراهم ثم تأخذ الدراهم وتشتري التمر الطيب.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6174/معنى-حديث-بع-الجمع-بالدراهم-ثم-اشتر","audio":"https://files.zadapps.info/binbaz.org.sa/3eana009.mp3","categories":["شروح الحديث","البيوع"]},{"id":717,"question":"بعض المحلات التّجارية عند الافتتاح تضع جوائز من سيارات وغيرها، وتضع أرقامًا لمَن يشتري منها، وبعد الانتهاء من العرض يُسحب على أرقام مماثلةٍ، وصاحب الحظِّ السعيد مَن يفوز بالرقم المطلوب، فما حكم ذلك؟","title":"حكم الجوائز عند افتتاح المحال التجارية","answer":"الجواب: هذا صدرت فيه فتاوى عدة مرات، وتنبيه على أنه لا يجوز، وأنه من القمار، من الميسر؛ لأن معناه تشجيع سلعهم..... لعلهم يحرصون على هذه الأرقام، لعلهم يفوزون بشيءٍ منها، فيُغْرُونهم ويُعطلون سلع الناس الآخرين، فهو قمار وخداع وضررٌ على المجتمع الآخر، على أهل السلع، فلا يجوز.","link":"https://binbaz.org.sa/fatwas/20565/حكم-الجواىز-عند-افتتاح-المحال-التجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0522فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الربا والصرف","البيوع"]},{"id":751,"question":"لقد جاءني رجلٌ طلب مني سيارةً دَيْنًا مُؤَجَّلًا، وقبل أن نتفق على القيمة ذهبت إلى المعرض واشتريتُ السيارة بالحاضر، وبعد شرائي للسيارة قررتُ قيمتها بالمُؤجل بمبلغٍ أكثر من القيمة التي دفعتُها، ثم بعتُها عليه، فهل هذه الصيغة شرعية أم أنَّ فيها شيئًا من الربا؟","title":"حكم شراء سيارة نقدًا وبيعها إلى أجل بفائدة","answer":"الجواب: لا حرج إذا اشتريتها وحُزتها وقبضتها وكُتبت على حسابك وانتهى كل شيءٍ، ثم بعتها إلى أجلٍ معلومٍ بفائدةٍ، فلا بأس على الصَّحيح، وهذا يُسمَّى: التَّوَرُّق، ويُسميه الناس: الوِعْدَة، ولا بأس بها على الصحيح، هذه من المداينة الشرعية، بشرط أن تحوزها، وتكون في ملكك، وتُكتب باسمك، وتنتهي إجراءاتها، وتنقلها إلى بيتك، أو إلى السوق، أو إلى المحل الآخر غير محل البائع، ثم بعد هذا تتصرف فيها بالبيع إلى أجلٍ معلومٍ، أو ببيعٍ نقدًا، كله واحد، وإذا بعتَها إلى أجلٍ فلا بأس بفائدةٍ، كأن تشتريها بعشرةٍ وتبيعها باثني عشر، ثلاثة عشر، أربعة عشر، تشتريها بعشرين وتبيعها بثلاثين، بخمسة وعشرين، إلى آجالٍ معلومةٍ، لا بأس بذلك، على الصحيح من أقوال العلماء.","link":"https://binbaz.org.sa/fatwas/20643/حكم-شراء-سيارة-نقدا-وبيعها-الى-اجل-بفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0566مسألة  في التورق ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":755,"question":"لقد وضعتُ مالًا بالبنك، وبعد عامٍ أرسل إليَّ البنك الحساب، وإذا به زيادة لم أضعها، وإنني في حيرةٍ من هذا المال الزائد على ما وضعتُه في البنك: أأتركه لصاحب البنك، أما ماذا أتصرف به حفظكم الله؟","title":"ما كيفية التصرف في فوائد البنوك الربوية؟","answer":"الجواب: هذه الزيادة هي الربا، المعروفة عندهم: الفائدة الربوية، والواجب في مثل هذا عدم التعامل مع البنوك بالربا، لا قليلًا، ولا كثيرًا، لا 5%، ولا 10%، ولا أقلَّ، ولا أكثر.\nوإذا كنت لم تتفق معهم على الربا ولم تشرطه عليهم وجاءك المالُ فأنفقه في وجوه الخير، هذه الزيادة للفقراء والمساكين، في بعض المشاريع الخيرية، ويكفيك رأس مالك.\nأما الاتفاق معهم فلا يجوز، لا تتفق معهم، تقول: أشترط عليهم الربا وأنفقه، لا، دع الربا بالكلية، لكن لو قدر أنَّهم دفعوا لك المال، أو أنك تساهلت وأخذت المال، ثم تبتَ إلى الله؛ تُنفقه في وجوه الخير، ولا تأكله أنت، ولا تصرفه في حاجاتك، ولكن تُنفقه في وجوه الخير، مثل: بعض الفقراء، مثل: إرساله للمُجاهدين الأفغان، مثل: إصلاح الطُّرقات، دورات المياه، وأشباه ذلك.","link":"https://binbaz.org.sa/fatwas/20636/ما-كيفية-التصرف-في-فواىد-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0562حكم آخذ الفوائد الربوية من البنوك وكيف يتصرف بها ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":787,"question":"هل يجوز أخذ الذهب بالدَّين –أي: يشتري الذهب والدفع يكون بعد عدة شهور لعدم توفر المال؟","title":"هل يجوز أخذ الذهب بالدَّين؟","answer":"الجواب: إذا اشترى الذهب بالنقود لا يجوز، هذا ربا، لكن لو اشترى الذهب بعروض أخرى: كملابس، أو سيارات، أو أطعمة؛ فلا بأس، أما أن يشتري بالنقود فهذا ربا، لا بدّ يدًا بيدٍ، لكن لو اشترى قلادةً من الذهب بخامٍ من الملابس الأخرى، أو بقهوةٍ، أو بسكرٍ، أو بأوانٍ، أو بسيارةٍ؛ لا بأس، نعم، ولو مُؤَجَّلة.","link":"https://binbaz.org.sa/fatwas/20789/هل-يجوز-اخذ-الذهب-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0619هل يجوز أخذ الذهب بالدين أي يشتري الذهب والدفع يكون بعد عدة شهور لعدم توفر المال؟ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":860,"question":"البنوك الربوية مُنتشرة في كثيرٍ من الدول العربية، لدرجة أنه يتعذر على المسلم أن يتحصل على سكنٍ أو قرضٍ لإنجاز أي مشروعٍ إلا عن طريق هذا البنك، ما العمل؟","title":"حكم القرض الربوي لأخذ مسكن أو مشروع","answer":"الجواب: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، ما هو ملزومٌ بالبنوك، يتسلّف من إخوانه، لا يَبْنِ، لا يقوم بالمشروع إلا بعدما يتيسر له الأمر، مَن الذي حادّه على المشروع الذي يحدّه على الربا؟! المشروع الذي يدعوه إلى الربا لا يُقيمه، يُقيم مشروعًا بالحرام؟! يصبر حتى يفرج الله، حتى يأتيه الحلال، أو يقترض من إخوانه بدون ربا، أما أن يقول: يُقيم مشروعًا، أو يتزوج، أو يَعْمُر بيتًا بالحرام؛ هذا منكرٌ، هذا غلطٌ.","link":"https://binbaz.org.sa/fatwas/20894/حكم-القرض-الربوي-لاخذ-مسكن-او-مشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القرض الربوي لأخذ مسكن أو مشروع.mp3","categories":["الربا والصرف","البيوع"]},{"id":955,"question":"السلام عليكم ورحمة الله وبركاته، يوجد في بعض المحلات التّجارية ألبان، وهذه الألبان إذا اشترى المُشتري بما يُعادل مئة ريـال تقريبًا يأخذ رقمًا، وهذا الرقم قد يقع على سيارةٍ أو ساعةٍ ثمينةٍ، فهل ذلك لا بأس به؟ أفيدونا جزاكم الله خيرًا.","title":"حكم منح المشتري بقيمة معينة رقمًا في سحب","answer":"الجواب: هذا كتبنا فيه واللجنة بأنه من القمار، لا يصلح؛ لأنه يشتري على الرقم: ما يُدريه؟ هل يحصل جائزةً أو ما يحصل جائزةً؟ وربما تذهب منهم أموالٌ كثيرةٌ بسبب هذه الجائزة. أما لو عيَّن قال: مَن اشترى منا أربع مرات بكذا أو خمس مرات بكذا نُعطيه كذا من سلعة كذا، نعطيه زيادة كذا شيء معلوم، ما يضرُّ إن كان معلومًا، إذا اشترى منا مثلًا بمئة ريـال أعطيناه لترًا أو اثنين أو كذا، أو اشترى منا بعشرة آلاف ريـال من كذا وكذا، ومن سبلٍ معينةٍ، ومن أصنافٍ؛ نقصنا عنه في الساعات الأخيرة كذا وكذا، وكان من هكذا وهكذا، فالأمر في هذا واضحٌ، ما فيه غرر.","link":"https://binbaz.org.sa/fatwas/21002/حكم-منح-المشتري-بقيمة-معينة-رقما-في-سحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0799في بعض المحلات يبيع ألبان فإذا اشترى المشتري بقيمة100ريال يأخذرقم قد يكون له سيارةفهل هذاجائز.mp3","categories":["الربا والصرف","البيوع"]},{"id":985,"question":"إذا كنتُ في حاجةٍ شديدةٍ إلى مبلغٍ كبيرٍ من المال، وليس أمامي سوى الاقتراض من البنك، علمًا بأنَّ البنك عند السَّداد يزيد مبلغًا على المبلغ الأصلي، فما الحل جزاكم الله خيرًا؟","title":"حكم قرض البنك الربوي في حال الضرورة","answer":"الجواب: ليس لك أن تأخذ بالربا مطلقًا، ولو كنتَ في حاجةٍ التمس الطرق الأخرى: اقترض من إخوانك الطيبين، أو اشترِ سلعةً إلى أجلٍ وبِعْها، وهي التي تُسمَّى: الوعدة، يُسمّيها العلماء: التَّورق، تشتري سلعةً إلى أجلٍ: تشتري سيارةً أو غيرها، ثم تبيعها وتقضي حاجتك.\nأما أخذ القرض بالربا فلا يجوز ولو كنتَ محتاجًا، ولو للزواج، أو لقضاء الدَّين، ليس لك أن تأخذ الربا أبدًا، الله يسَّر لك طرقًا أخرى غير الربا.","link":"https://binbaz.org.sa/fatwas/21023/حكم-قرض-البنك-الربوي-في-حال-الضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0820إذا كنت في حاجة شديدة إلى مبلغ كبير من المال وليس أمامي سوى الاقتراض من البنك الربوي؟.ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":1002,"question":"أفتونا مشكورين عن حكم شرب الدخان، وكذلك مَن يُتاجر في بيعه وهو لا يشربه، هل مكسبه حلالٌ أم حرامٌ؟","title":"ما حكم شرب الدخان وبيعه وكَسْبه؟","answer":"الجواب: بيع الدخان حرامٌ، والتجارة فيه حرامٌ، ومكسبه حرامٌ، وشربه حرامٌ، والواجب الحذر من ذلك، الواجب التَّواصي بتركه؛ لما فيه من مضارٍّ كثيرةٍ، والعواقب الوخيمة، وإضاعة المال، والمضرَّة في الدين والدنيا، فالواجب الحذر من ذلك، فليس للمؤمن بيعه، ولا التجارة فيه، ولا شربه بالكلية. وهكذا بقية المضرَّات والمخدرات والمسكرات، كلها حرام، كلها شرُّها عظيم، فالمسكر محرَّمٌ من أي جنسٍ كان، والذي يضرُّك في دينك ودُنياك محرَّمٌ وإن لم يُسْكِر.","link":"https://binbaz.org.sa/fatwas/21052/ما-حكم-شرب-الدخان-وبيعه-وكسبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0848ما حكم شرب الدخان وحكم من يتاجر ببيعه؟ ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":1007,"question":"شخصٌ اشترى ليرات لبنانية بريالات سعودية، وسلَّم الريالات ولم يستلم الليرات، بل استلم مقابلها شيكًا بالمبلغ، فهل هذا العمل جائز؟","title":"حكم شراء عملة باستلام شيك مصرفي بقيمتها","answer":"الجواب: هذا فيه خلافٌ بين علماء العصر: منهم مَن يرى الشيك يقوم مقام القبض؛ لأنه كالعملة. ومنهم مَن لا يرى أنه يقوم مقام القبض، فالذي ينبغي أن يقبض العملة، إذا سلَّم له دولارات أو جنيهات أو عملة لبنانية أو غير ذلك يأخذ مقابلها في المجلس، حتى يبتعد عن شبهة الربا؛ لأنَّ هذه العُمَل مُنَزَّلة منزلة الذهب والفضة، فينبغي لمن أخذ عملةً بعملةٍ أن يتقابضا في المجلس..... أو على بنك أو نحو ذلك، هذا هو محل النظر، وفيه شبهة: بعض أهل العلم جعله من قبيل عملة بعملة؛ لأن الشيك ماضٍ ويمشي بين الناس، ومنهم مَن لم يجعله كذلك، وقال: إنَّ هذا الشيك بمنزلة صكّ الدَّين والوثيقة، وذلك لا يجوز. وسوف يُعرض هذا على مجلس هيئة كبار العلماء لتبادل الرأي في موضوعه؛ لأنه موضوعٌ مهمٌّ، والحاجة إلى إعلانه وحكمه أمرٌ مهمٌّ، لا بد إن شاء الله من النظر في ذلك وإعلان ما يتمّ في ذلك.","link":"https://binbaz.org.sa/fatwas/21046/حكم-شراء-عملة-باستلام-شيك-مصرفي-بقيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0842شخص اشترى ليرات لبنانية بريالات سعودية وسلم الريالات ولم يستلم الليرات بل استلم بدل عنها شيك؟.mp3","categories":["الربا والصرف","البيوع"]},{"id":1047,"question":"سائلٌ يسأل عن حكم الاتِّجار بالعملة: بالدولار، أو بالليرة، أو باليِنّ الذي نراه في البنوك، ويلجأ إليه الأفراد لطلب الكسب وتحقيق الربح، لكنه لا يحصل فيه التَّقابض، فهل يصحّ ذلك؛ لأن ذلك كله يكون على الورق فقط؟","title":"ما الكيفية الصحيحة للتجارة بالعملات؟","answer":"الجواب: هذه الفتوى كثر السؤال عنها قديمًا وحديثًا، ولكن في هذه الأيام السؤال أكثر. والصواب: أنه لا يجوز إلا يدًا بيدٍ، فيأخذ العملة التي يُريد، ويدفع العملة التي عنده، يدًا بيدٍ، ثم يُمسكها عنده، أو يُودعها عند مَن شاء إلى أن يبيعها، أما كونه يأخذ ورقةً فقط فهذا حرَّمه جمع من أهل العلم، وبعضهم تساهل في هذا الشيء، ولكن الذي يظهر أنه لا ينبغي التَّساهل في ذلك، بل ينبغي له أن يأخذها يدًا بيدٍ، أو يدع؛ لأنَّ الشيك أشبه بالوثيقة، وأشبه بالمُداينة، والنبي ﷺ قال في الحديث الصحيح: إذا اختلفت هذه الأصناف لما ذكر الذهبَ والفضةَ والبُرَّ والشعيرَ والتَّمر وغيرها قال: فإذا اختلفت هذه الأصناف فبيعوا كيف شئتُم، إذا كان يدًا بيدٍ.\nوهكذا في العُملات: كالدولار، والجنيه، والريال، والين، وغيرها، إذا اختلفت فلا بد أن تكون يدًا بيدٍ، سواء ينّات، أو جنيهات، أو دولارات، أو دنانير، أو غير هذا، الواجب يدًا بيدٍ، ثم يُودعها إذا شاء، أما كتابة شيك فالأحوط والواجب تركه؛ لأنه ليس هناك ما يقتضي إقامته مقام العملات، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/21108/ما-الكيفية-الصحيحة-للتجارة-بالعملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0904ما حكم التجارة بالعملات؟ ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":1077,"question":"ما حكم شراء العملات، بحيث يدفع المُشتري مبلغًا من الريالات السعودية، لكن لا يقبض هذه العملات، وإنما يقبض سندًا من البنك فقط، وقد يكون القبض بوسيلة التليفون؟","title":"حكم شراء العملات بسند بنكي دون تقابض","answer":"الجواب:\nالدلائل التي جاءت في الكتاب والسنة تدل على أنه لا بدّ من التقابض، الله جلَّ وعلا قال: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النور:54]، وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، وقد دلَّ ﷺ أمَّته على أنه لا بد من التَّقابض يدًا بيدٍ، ثم ذكر الذهب والفضة والبرَّ والشَّعير والتَّمر والملح، قال في ذكر بيع بعضها ببعض: مِثْلًا بمثلٍ، يدًا بيدٍ، سواء بسواء، فإذا اختلفت هذه الأصناف فبيعوا كيفما شئتُم إذا كان يدًا بيدٍ.\nفلا بد من التَّقابض عند اختلاف الأصناف: ريالات سعودية بريالات يونانية، أو دولارات أمريكية، أو دنانير، أو جنيهات مصرية، لا بد من التقابض، أما ورقة: يُعطيه شيكًا، لا يكفي، هذا هو المعتمد الذي دلَّت عليه الأدلةُ؛ لأن الشيك يُشبه الوثيقة، وقد يعتريه ما يعتري الوثيقة.\nفالحاصل أنه لا بد من أن يقبض اللّيرات أو الجنيهات أو الدولارات، ويُعطي ما في يده، ثم بعد ذلك إذا أحبَّ يُحوِّلها أو يُودعها، هو حرٌّ.","link":"https://binbaz.org.sa/fatwas/21140/حكم-شراء-العملات-بسند-بنكي-دون-تقابض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0936ما حكم شراءالعملات من الريال السعودي ويقبض المبلغ من البنك سنداً وقد يكون القبض بوسيلة التليفون؟.mp3","categories":["الربا والصرف","البيوع"]},{"id":1115,"question":"لدي سوقٌ، وأرغب في توزيع هدايا في شهر رمضان، منها سيارة، ويكون توزيع الهدايا بعد شراءٍ بمبلغ مئة ريـال لأخذ كوبون. أفتوني مأجورين، هل هذا العمل صحيح؟","title":"حكم توزيع هدايا بمتجر بعد شراءٍ معيّن","answer":"الجواب:\nهذا فيه إجمالٌ: إن كنتَ تُوزع الهدايا تُعطي الفقراء والمساكين دون شيءٍ، تُوزع عليهم، تُعطيهم صدقات، تُعطيهم أموال، ملابس، للفقراء والمساكين في رمضان. أما على طريقة القمار: تأخذ يعني: بطاقات تُقدِّمونها، فيدخل البطاقة مئة أو مئتين، ثم يُكتب عليها أرقام، مَن فاز بالرقم حصل كذا، هذا ما يجوز، هذا رِبا، بل قمار، مَيْسِر، إذا كنتَ صادقًا تريد البِرَّ ؛تصدَّق ولا تحطّ بطاقات، ولا تحطّ شيئًا، تصدَّق على الناس بما يسَّر الله لك من النقود، أو الملابس، أو الطعام.\nأما كوبونات أو بطاقات يكتب فيها مبالغ مطلوبة، مَن قدَّمها يقدم مئة ريـال، أو يعني: ما يُعطاها إلا بتقديم مئة ريـال أو مئتين، وعليها أرقام، ومَن فاز بالرقم حصل سيارةً أو راديو، أو كذا، أو كذا، هذه من أعمال المقامرة، ما تصلح، هذه ما هي بصدقة، هذا نهب أموال الناس.","link":"https://binbaz.org.sa/fatwas/21164/حكم-توزيع-هدايا-بمتجر-بعد-شراء-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0960أقوم بتوزيع هدايا في رمضان ويكون توزيع الهدايا بعد شراء مبلغ مائة ريال لأخذ كربون فما الحكم.mp3","categories":["الربا والصرف","البيوع"]},{"id":1166,"question":"تنتشر في بلادنا البنوك الربوية، ويعمل فيها الكثيرُ من الموظفين من أبناء المسلمين، وتحت رعاية شيوخ ونساء وأطفال، فهل دخلُ هؤلاء المُوظفين حرامٌ أم حلالٌ؟ أي: هل يدخل في الربا المُحرَّم؟","title":"هل العمل في البنوك الربوية حرام؟","answer":"الجواب:\nالعمل في البنوك محرَّمٌ؛ لأنه من باب التَّعاون على الإثم والعدوان، وقد صدر مني ومن اللَّجنة الدائمة فتاوى كثيرة في هذا الباب، والأصل في هذا قوله جلَّ وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]، وقول النبيِّ ﷺ في الحديث الصحيح: أنه ﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء، فجعلهم ملعونين لتعاونهم مع المُرابين، فلا يجوز التَّعاون مع المرابين، لا بكونك مُحاسبًا، ولا أمين صندوقٍ، ولا مُراسلًا، ولا غير ذلك؛ لأنَّ هذا كله من التَّعاون: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، عساها تتعطل كلها: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، لعلها تتعطل كلها، أو يتوب الله عليهم ويتركوا الربا.","link":"https://binbaz.org.sa/fatwas/21217/هل-العمل-في-البنوك-الربوية-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1013ما حكم العمل في البنوك الربوية؟ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":1190,"question":"اشتريتُ سلعةً بمالي، وسلمتُ له الدراهم، ولكن قلتُ له: اتركها عندك لتبيعها لي، هل يجوز له شراؤها أو أجعله وكيلًا لي في بيعها؟ نرجو التفصيل.","title":"ضابط البيع المشروع وتمييزه عن بيع العِينة","answer":"الجواب:\nإذا اشتريتَ السلعة لا بد أن تنقلها من محلِّ البائع إلى محلٍّ آخر، وتبيعها في محلٍّ آخر؛ لقول النبي ﷺ: لا تبع ما ليس عندك؛ لأنه ﷺ نهى أن تُباع السلع حيث تُبتاع، حتى يحوزها التُّجار إلى رحالهم، وقال ﷺ: لا يحل سلفٌ وبيعٌ، ولا بيعُ ما ليس عندك، تُنقل السلعةُ من محلِّ البائع إلى السوق، أو إلى بيتك، أو إلى محلٍّ آخر، يبيعها لك إنسانٌ آخر، ولا تخليها عند الذي شريتها منه، تنقلها، وإذا بعتَها عليه بعدما نقلتها فلا بأس، وإن بعتها عليه؛ لأنه هو الذي اشتراها منك، فلا بأس، إذا كان الثمنُ حالًّا حاضرًا، أما إذا اشتريتَه منه بمؤجَّلٍ ثم بعتها له بأقلّ؛ هذا ما يجوز، هذه يُقال لها: العِينة.\nإذا اشتريتَها مثلًا بـ100 ريـال، ثم بعتَها عليه بـ80 أو 70 حاضرة، ويبقى في ذمَّتك الدَّين المؤجَّل، هذا يُسمَّى: العِينة، لا يجوز هذا، لكن إذا اشتريتَها بثمنٍ حاضرٍ 100 ريـال، سلَّمتَها له، ثم طرأ عليك أن تبيعها عليه بثمنها أو بأقلّ أو بأكثر فلا بأس.","link":"https://binbaz.org.sa/fatwas/21242/ضابط-البيع-المشروع-وتمييزه-عن-بيع-العينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1152اشتريت سلعة بمالي وسلمت له الدراهم ولكن قلت له أتركها عندك لتبيعها هو يجوز هو شراؤها.mp3","categories":["الربا والصرف","البيوع"]},{"id":1219,"question":"أولًا: اعلم حفظك الله أني أُحبُّك في الله.ثانيًا: نود من فضيلتكم بيان مقدار الربح فيما يُتاجر به التُّجار، وهل هناك ضابط معينٌ لمقدار الربح أم أنه لا يوجد؛ لأنَّ بعض التجار الآن هداهم الله يربحون أضعاف أضعاف ما اشتروا به؟ نرجو التفصيل حفظكم الله؟","title":"هل هناك ضابط لمقدار الربح في التجارة؟","answer":"الجواب:\nالشيخ: أولًا: نقول: أحبَّك الله الذي أحببتنا له، جاء في الحديث: يقول ﷺ: مَن أحبَّ منكم أحدًا فليُخبره، أو كما قال عليه الصلاة والسلام، وإذا أخبره فليقل: أحبَّك الله الذي أحببتنا له، نسأل الله جلَّ وعلا أن يجعلنا وإيَّاكم من المتحابين في جلاله، وأحبَّكم الله الذي أحببتُمونا له.\nويقول النبيُّ ﷺ في الحديث الصحيح: سبعة يُظلُّهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه -هذا مثالٌ- ورجلٌ دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله، وهكذا المرأة إذا دعاها ذو منصبٍ وجمالٍ قالت: إني أخاف الله، من السبعة الذين يُظلهم الله في ظلِّه، ورجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، يعني: يتصدَّق ويحرص على السر، وإن جهر فلا بأس، قال تعالى: إِنْ تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَ وَإِنْ تُخْفُوهَا وَتُؤْتُوهَا الْفُقَرَاءَ فَهُوَ خَيْرٌ لَكُم [البقرة:271]، فالإخفاء أفضل، وإن جهر لمصلحةٍ، مثل: صدقة في المسجد حتى يتبعه الناسُ، أو في اجتماعٍ حتى يتبعه الناسُ، فهذا أفضل، والسابع: رجل ذكر الله خاليًا ففاضت عيناه، ذكر الله ما عنده أحدٌ، فبكى من خشية الله جلَّ وعلا.\nوفي الحديث الآخر: يقول ﷺ: يقول الله  يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلّهم في ظلِّي يوم لا ظلَّ إلا ظلي.\nأما السؤال الثاني: فليس للربح حدٌّ محدودٌ، لم يأتِ في الشرع تحديدٌ للربح: لا بالثلث، ولا بالربع، ولا بغير ذلك، بعض الفقهاء -بعض العلماء- قالوا: الثلث، ولكن ليس عليه دليلٌ، والأولى بالمؤمن الرفق، وألا يكون جشعًا، وأن يرضى بالربح القليل، وأن يرفق بإخوانه، هذا هو المشروع، وهذا هو الأفضل: أن يتحرى الربح القليل الكافي الذي يُعينه على البيع والشراء، ويُعينه على أداء أجور المحل من العمال ونحو ذلك، ولا يكون كثيرًا يُتعب الناس، يتحرَّى ويجتهد الربح المناسب، هذا هو المشروع للتاجر وغير التاجر.\nأما التَّحديد: فليس له حدٌّ محدودٌ، قد اشترى النبيُّ ﷺ البعير بالبعيرين، من إبل الصدقة، البعير الواحد بالبعيرين، ولا حرج أن يبيع ما اشتراه بمئةٍ بمئتين إذا تغيَّرت الأحوال، أو جاءه إنسان ظالم مثل هذا الشيء وهو ما يُريد أن يبيعه لكن لأجله باعه إيَّاه بربح مئة في مئة لا حرج، ليس فيه حدٌّ محدودٌ، قد تكون عندك سيارة تُريدها وليس لك رغبة في بيعها، ثم يأتي إنسانٌ له رغبة فيها، ويُحب أن يشتريها ولو بالكثير، لا حرج في ذلك وهكذا بيته، وهكذا أرضه، لكن إذا رفق الإنسانُ وأخذ الربحَ المناسبَ الذي يُناسب حاله وحال نفقاته فهو أحسن.","link":"https://binbaz.org.sa/fatwas/21275/هل-هناك-ضابط-لمقدار-الربح-في-التجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1119هل هناك ضابط لمقدار الربح؟ ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":1243,"question":"كنتُ في بعثةٍ في خارج المملكة، ووضعتُ فلوسي في بنك، وفُوجئتُ بعد سنتين أنهم قد قدَّموا لي ربحًا من هذا الرصيد، فهل آخذه أم أتركه لأولئك الكفَّار لكي يستفيدوا منه؟","title":"حكم وكيفية التصرف في أرباح البنوك الربوية","answer":"الجواب:\nهذا ما دمتَ لم تُشارطهم عليه تأخذه وتتصدَّق به، لك رأس مالك، والربح الذي هو الربا تصرفه في وجوه الخير: من مساعدة الفقراء والمجاهدين، وتعمير الطرقات ودورات المياه، وغير هذا مما ينفع الناس.\nوبعض أهل العلم يرى أنه لا حرج فيه إن كنتَ لم تشترطه ولم تقصده ولم تُواطئهم عليه؛ لقوله ﷺ: إنَّ خيار الناس أحسنُهم قضاءً، ولقول عمر  لما أعطاه النبيُّ بعضَ الشيء قال: يا رسول الله، أعطه مَن هو أفقر مني، فقال: ما جاءك من هذا المال وأنت غير مشرفٍ ولا سائلٍ فخذه، وما لا فلا تتبعه نفسك، فإذا كنت غير مشرفٍ له ولم تقصده ولم تتواطأ معهم عليه فظاهر النصِّ حلُّه، لكن لما كان التَّعاون مع البنوك معروفًا أنه ربا، والإنسان يعرف أنهم يعطون الربا، ولم يقل لهم: هذه وديعة بدون ربا؛ فإنَّ هذا المال الذي يأخذه لا ينبغي له أن يستطيبه، بل يُنفقه في وجوه البر وأعمال الخير؛ لأنهم أعطوه على أنه ربا، على أنه في مقابل وضعه وديعةً، وهذا عُرْفٌ بين الناس معروف، فكأنه مشروطٌ، فإذا أخذته ودفعته لوجوه الخير كان ذلك حسنًا.  أما أن تتفق معهم على ذلك فتشترط الربح وتقول: أُعطيه أهل الخير، لا، ما يجوز هذا.","link":"https://binbaz.org.sa/fatwas/21291/حكم-وكيفية-التصرف-في-ارباح-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1034كنت في بعثة خارج البلد ووضعت فلوسي في بنك فوجئت بعد سنتين أنه قدموا لي ربحاً هل آخذه أو أتركه.mp3","categories":["الربا والصرف","البيوع"]},{"id":1273,"question":"ما حكم التَّعامل في أحد البنوك المحلية في صناديق الاستثمار، ويكون عقد بين البنك وواضع النقود بالربح والخسارة؟","title":"ما حكم معاملات صناديق الاستثمار بالبنوك؟","answer":"الجواب:\nهذا إذا أُمِن، لا بدّ أن يكون من طريق الربح والخسارة، يعني: من طريق المضاربة، جزء مشاع، يُعطيه مئة ألف أو أكثر أو أقلّ ويقول: تعمل فيها بالمضاربة، يشتري سيارات، يشتري عملات ويبيعها، يقول: لك النصف، أو لك الربع، أو لك الخمس، لا بأس.  أما فائدة معينة: لك 5%، 10%، هذا الربا، ما يجوز.  لكن إذا كان بربع الحاصل: ربع الربح، عُشر الربح، يعني 10% من الربح، 20، 50،  النصف لا بأس، هذه تُسمَّى المضاربة، وهي جائزة عند جميع العلماء، لكن هل يُؤْمَنون؟ هذا محل نظرٍ، هل يُؤْمَنون على هذه العملية، أو يبيعون بالربا؟ بعضهم لا يُؤْمَن، وأشكّ أنهم يُؤْمَنون في هذا الشيء؛ لأنهم قد اعتادوا الربا، لكن إن كان مع أناسٍ مأمونين فهذا طيبٌ.","link":"https://binbaz.org.sa/fatwas/21332/ما-حكم-معاملات-صناديق-الاستثمار-بالبنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1075ما حكم التعامل مع البنوك في صناديق الأستثمار ويكون عقد بين البنك وواضع النقود في الربح والخسارة.mp3","categories":["البيوع","الربا والصرف"]},{"id":1352,"question":"يعطي البنك الرجل هدية، عنده عمالة عند البنك يعطيه هدية؟","title":"ما حكم أخذ هدايا البنوك؟","answer":"الجواب:\nالبنك لا تجوز معاملته؛ لأنه ربا، لا هديته ولا معاملته، كله.  والواجب الحذر من الربا، يقول الله جل وعلا: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275]، وهديتهم دعوة إلى الربا.\nس: بعض البنوك يعطوننا هدية \"دفتر\" أو \"تقويم\" أو شيئًا كذا؟\nج: لا، هذا ترغيب لك في المعاملة. أما إذا كان لأسباب كإيداع عندهم يعطونك وثيقة بأن مالك عندهم؛ هذا ما فيه بأس.\nس: هو بقصد الترغيب؟\nج: لا لا، الترغيب لا، ما يصلح، أما وثيقة عندهم لك مال، هذا مثل غيرهم، الوثيقة لا بأس بها، لكن من دون معاملة إذا اضطر إلى وديعة عندهم أو تحويل مال بواسطتهم يأخذ وثيقة؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/21445/ما-حكم-اخذ-هدايا-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ هدايا البنوك.mp3","categories":["الربا والصرف","البيوع"]},{"id":1410,"question":"العمل بالأسهم التجارية؟","title":"ما حكم العمل بالأسهم التجارية؟","answer":"الجواب:\nإذا كان ما فيها ربا لا بأس. إذا كان أسهم في حديد، في بناء، في أراضٍ، في سيارات؛ لا بأس، أما الربا لا.\nس: الأسهم التي تتداول في البنوك؟\nج: البنوك لا، ما يصلح، أما أسهم ما فيها ربا فالحمد لله، شركات يشتركون في أراضٍ، في سيارات، في معدات، في ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/21505/ما-حكم-العمل-بالاسهم-التجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العمل بالأسهم التجارية.mp3","categories":["البيوع","الربا والصرف"]},{"id":1451,"question":"بعضهم يبيعون الدخان، ويحتجون بأنه ليس لهم بل لكفيلهم؟","title":"ما حكم مَن يُلزمه كفيله ببيع الدخان؟","answer":"الجواب:\nولو، لا يساعد على باطل، بيع الدخان محرم مثل بيع الخمر، لا يساعد ولو ما هو له، لا يصير دلَّالًا ولا وكيلًا في البيع المحرم، يقول الله: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]، والذي يبيع الخمر أو يبيع الدخان أو يبيع شيئًا مما حرَّمه الله يكون شريكًا لمن وكَّله، مُعِينًا له على الإثم.\nس: إذا رفض هذا أحدُ الناس فقد يقوم كفيله بتسفيره إلى بلاده وهو في أمس الحاجة إلى التحصّل على وسيلة المعاش، فكيف يصنع في مثل هذه الحالة؟\nج: ولو، لا يتعاون على غش ولا محرم ولا بيع محرم، إنما الطاعة في المعروف، لا طاعة لمخلوقٍ في معصية الخالق، لكن يُراجع المحكمة، بحيث لا يُمَكِّنه من التساهل، فيذهب إلى المحكمة أو إلى الأمير إن كان في بلدٍ فيها أمير.","link":"https://binbaz.org.sa/fatwas/21548/ما-حكم-من-يلزمه-كفيله-ببيع-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المساعدة على الباطل.mp3","categories":["الربا والصرف","البيوع"]},{"id":1483,"question":"راتبنا الآن إلى بعض البنوك الربوية، وأحيانًا عند الصرف يبقى لنا عندهم مثلًا عشر هللات، أو يعطونا زيادة عشر هللات، ما الحكم حينئذٍ؟","title":"حكم تحويل الرواتب بواسطة البنوك الربوية","answer":"الجواب:\nالأمر سهل، هذه حوالة على أموال الدولة، ما يضركم.","link":"https://binbaz.org.sa/fatwas/21581/حكم-تحويل-الرواتب-بواسطة-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التعامل مع البنوك الربوية.mp3","categories":["الربا والصرف","البيوع"]},{"id":1507,"question":"يحصل من بعض التجار أنه يشتري كميةً كبيرةً، مثلًا: نحو عشرة آلاف كرتونة صابون، أو عشرة آلاف كيس أرز، وما أشبه ذلك، فتكون هذه أحيانًا مستوردةً، وأحيانا غير مستوردةٍ، فهل يُشترط في هذه الحالة قبل أن أبيعها أن أنقلها؟ وإذا نقلتها يقول: ما الفائدة حينئذٍ ما دمتُ سأبيعها؟ ما الفائدة؟","title":"حكم القبض والتخلية في البيع والشراء","answer":"الجواب:\nإذا شقَّ عليه النقلُ فلا يلزم، فالشيء الذي يشق يُعْفَى عنه؛ لعظمه وكثرته، كالمنزل والأرض، فقبضها التَّخلية، أما إذا تيسر النقلُ فالنبي ﷺ أمر بالنقل، فقد نهى رسول الله ﷺ أن تُباع السلع حيث ابتيعتْ حتى يحوزها التُّجار إلى رحالهم، فإذا تيسَّر حوزها فليحوزها.","link":"https://binbaz.org.sa/fatwas/21606/حكم-القبض-والتخلية-في-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في القبض والتخلية في البيع والشراء.mp3","categories":["الربا والصرف","البيوع"]},{"id":1574,"question":"بالنسبة لشخصٍ أُعطي من البنك فوائد، ورأى أن تُصرف هذه الفوائد في بناء حمامات مثلًا، أو ما شابه ذلك؟","title":"ما كيفية التصرف في فوائد البنك المالية؟","answer":"الجواب:\nما في بأس، الحمامات، أو إصلاح الطرق، أو ما أشبه ذلك.\nس: لو كان له أقارب فقراء، هل له أن يُعطيهم ولا يُخبرهم؟\nج: إذا كانوا مستحقين للزكاة لا يلزم أن يُخبرهم، نعم، ما هو بلازم أن يُخبرهم، إلا إذا كان في شكٍّ يقول تراها زكاة، سواء كان من أهلها وإلا..","link":"https://binbaz.org.sa/fatwas/21677/ما-كيفية-التصرف-في-فواىد-البنك-المالية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التصرف في مال فوائد البنك.mp3","categories":["الربا والصرف","البيوع"]},{"id":1586,"question":"يقول السائل: احتجتُ إلى قرضٍ من المال، فلم أجد مَن يُقرضني، وقال لي شخصٌ أنه سوف يُقرضني بالدولار على أن أُسدد بالريال، وحسب الدولار بخمسة ريالات، تُسدد على أقسامٍ، والمعروف أنَّ الدولار...؟","title":"ما حكم من اقترض بالدولار وسدَّد بالريال؟","answer":"الجواب:\nلا تُكْمِل، هذا ربا، ما يجوز، ربا، ما يصلح.","link":"https://binbaz.org.sa/fatwas/21689/ما-حكم-من-اقترض-بالدولار-وسدد-بالريال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اقترض بالدولار وسدد بالريال.mp3","categories":["الربا والصرف","البيوع"]},{"id":1911,"question":"بيع كلب الصيد؟","title":"حكم شراء الكلب والقط والثعلب ونحوها","answer":"الجواب:\nلا يجوز شراء كلب الصيد ولا غيره.\nس: طيب، هل تدخل بيع السباع والثعالب والقطط هل تدخل فيه؟\nج: لا تُباع، الرسول ﷺ نهى عن بيع السِّنَّوَر –القط- فلا يباع، فالرسول نهى عن ثمن السِّنَّوَر والكلب.\nس: إذا اضطر لشِّراء كلب الصيد؟\nج: ما يجوز شراؤه، لكن يمكن أن يُربِّي كلبًا صغيرًا عند غنمه حتى ينفع.\nس: هناك محلات تبيع هذا، أحسن الله إليك؟\nج: عملهم ما هو بحجة، جاء في حديثٍ عند النسائي: إلا كلب صيد، لكنه حديث ضعيف، وفي \"الصحيحين\" النهي عن بيع الكلاب مطلقًا، والنهي عن ثمن الكلاب وأنه خبيث.","link":"https://binbaz.org.sa/fatwas/22024/حكم-شراء-الكلب-والقط-والثعلب-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم شراء بعض الحيوانات كالكلب ونحوه.mp3","categories":["الربا والصرف","البيوع"]},{"id":1960,"question":"البََيِّعان بالخِيَار يشترط استلام النقود، أم أنه لو قال مثلًا: \"غدًا أُعطيك الفلوس\" وتفارقوا، فهل البيع تم دون استلام النقود؟","title":"معنى حديث \"البََيِّعان بالخِيَار\"","answer":"الجواب:\nيختلف: إن كان ربويًّا ما يتم، وإن لم يكن ربويًّا يتم، فلو قال: تمت المبايعةُ بينه وبينه على سيارةٍ، أو على كتابٍ، أو على ثوبٍ، أو ما أشبه ذلك؛ وتفرَّقوا، فالبيع يتم، والثمن على ما أجَّله.\nس: لو رجع هل يأثم البائع؟\nج: لا، إذا تفرَّقوا لزم البيع، إلا إذا تسامحوا ورَضَوا بالفسخ، ما يُخالف، الحق لهم.","link":"https://binbaz.org.sa/fatwas/22075/معنى-حديث-البيعان-بالخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرح حديث البيعان بالخيار.mp3","categories":["البيوع","شروح الحديث"]},{"id":2016,"question":"يقول السائل: فضيلة الشيخ أنا أعمل في البنك السعودي البريطاني منذ عشر سنوات والبنك يقدم قروضًا ربوية، فهل كوني أعمل في بنك ربوي حرام، علمًا بأنني بحثت عن وظيفة أخرى فلم أجد؟","title":"هل يجوز العمل في البنوك الربوية؟","answer":"الجواب:\nنعم، لا يجوز لك العمل فيه، ما دام بنكًا ربويًا لا تعمل فيه، والله يرزقك عملًا آخر أفضل منه، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2-3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] يجب عليك البُعْد عن هذا الربا، والتوبة مما سلف.","link":"https://binbaz.org.sa/fatwas/22132/هل-يجوز-العمل-في-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1013ما حكم العمل في البنوك الربوية؟ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":2177,"question":"أريد أن أشتري عقارًا عن طريق إحدى الشركات بالتقسيط، ولكنَّها لا تملكه، وإنما أدلّها أنا عليه، فتمتلكه وأنا أشتريه عن طريقها؟","title":"حكم شراء العقار عن طريق شركات التقسيط","answer":"الجواب:\nإذا كان بالتّقسيط فلا بأس.\nس: الشركة لا تملك هذا العقار، لكني أنا أدلها عليه؟\nج: لا بأس.............\nس: لا، أقصد الشركة مثلًا ما عندها عقار، وأنا عندي أرض أدلُّ الشركة عليها لتشتريها؟\nج: تبيع عليها أرضك؟\nس: لا، أنا أريد أن أشتريها (كاش) لكن ما عندي قدرة، فلذلك أشتريها عن طريق إحدى شركات التقسيط؟\nج: إذا عمَّروها وباعوها عليك اشترِها، فلا تشترِها إلا بعدما يُعَمِّروها.\nس: أنا أريد أن أشتريها أرضًا؟\nج: اشترِ أرضًا منها أو من غيرها.\nس: لا، من الشركة نفسها.\nج: اشترِ الأرض من مالِكَ، من شركةٍ أو من غير شركة، بالنقد أو بالأقساط المعلومة، لا بأس.","link":"https://binbaz.org.sa/fatwas/22298/حكم-شراء-العقار-عن-طريق-شركات-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شراء العقار بالتقسيط عن طريق شركات التقسيط.mp3","categories":["الربا والصرف","البيوع"]},{"id":2250,"question":"يقول السائل: أحيانًا يطلب مني بعضُ الزملاء أن أصرف له مبلغ مئة ريـال، ولا يكون معي إلا خمسة وتسعون ريالًا، وأعطيه الخمسة ريالات المتبقية بعد ذلك، وتكون في حكم الدَّين عليَّ له، فهل يُعدّ ذلك من الرِّبا؟","title":"حكم صرف مئة ريال مع بقاء جزء مؤجل","answer":"الجواب:\nما يصلح، لكن تأخذها أمانةً عندك، ثم إذا جاءت الخمسة تُعطيه إياها مع ما مضى، وتقبض منه المئة فتكون كأمانةٍ، وتكون الأولى سلفةً كالقرض حتى يتيسر لك التكميل، ثم تُكمل، ثم تأخذ المئة، ثم يكون الصرف، فالصرف لا بد أن يكون بالتّقابُض، مثلما قال ﷺ، لا بأس أن تأخذها بسعر يومها، ما لم تفترقا وبينكما شيء، فتبقى عنده المئة أمانة كالرهن.","link":"https://binbaz.org.sa/fatwas/22373/حكم-صرف-مىة-ريال-مع-بقاء-جزء-موجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صرف مبلغ مئة ريال بخمسة وتسعين ريال.mp3","categories":["الربا والصرف","البيوع"]},{"id":2268,"question":"رجلٌ يسأل عن حكم البيع بالتَّصريف؟","title":"ما معنى وحكم البيع بالتَّصريف؟","answer":"الجواب:\nهذا الكلام مُجْمَل.\nس: صفته أن التاجر يأتي بالبضاعة ويقول: ما أُريد منك مالًا، إذا بعتَ أعطني المال؟\nج: لا، لا بد من بيعها إمَّا لأجل معلومٍ أو حالّ؛ حتى يكون على بصيرةٍ، فإمَّا أن يقول أنه حالّ ومتى شاء طالبه به، وإلا إلى أجلٍ معلومٍ.\nس: يقول: الذي ما تبيعه ردّه لي لا بأس؟\nج: لا بدَّ من أجلٍ معلومٍ.\nس: إذن يُقال: يُترك احتياطًا أم لا يجوز؟\nج: لا يجوز، لا بد من جزم البيع.\nس: وأيش يُسمَّى هذا؟\nج: يُسمّونه: أن يبيع بشرطٍ على خسارته، متى شاء ردّه، وهذا من الشروط الباطلة.","link":"https://binbaz.org.sa/fatwas/22391/ما-معنى-وحكم-البيع-بالتصريف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بالتَّصريف.mp3","categories":["الربا والصرف","البيوع"]},{"id":2299,"question":"يقوم بعضُ الناس ببيع الكلاب المُعَلَّمة، ويقولون أنهم أنفقوا من أموالهم ووقتهم في سبيل تعليمها، فهل يدخل ذلك في نهي النبيِّ ﷺ عن ثمن الكلب؟","title":"حكم بيع الكلاب المُعَلَّمة","answer":"الجواب:\nالكلب لا يُباع مطلقًا، سواء كان مُعَلَّمًا أو غير مُعَلَّمٍ، ورواية النَّسائي: إلا كلب الصيد ضعيفة، فالرسول نهى عن بيع الكلب، وثمنه خبيثٌ مطلقًا، سواء كان مُعلَّمًا أو غير مُعلَّمٍ.","link":"https://binbaz.org.sa/fatwas/22423/حكم-بيع-الكلاب-المعلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع الكلاب المعلمة.mp3","categories":["الربا والصرف","البيوع"]},{"id":2302,"question":"يقول أحدُ الطلبة: ذهب بعضُ العلماء إلى أنَّ مسألة التَّورق التي يشتري فيها شخصٌ سلعةً ما بثمنٍ مُؤَجَّلٍ، ثم يبيعها لشخصٍ آخر بثمنٍ أقلَّ حاضرٍ: إلى أنها بيعٌ ربويٌّ، فعلى مَن يقع إثم الرِّبا في هذا البيع؟","title":"هل بيع التَّورق من البيوع الربوية؟","answer":"الجواب:\nهذا ما هو بربا، الصحيح أنه ليس ربًا، فمسألة التَّورق ليست ربًا، وقول مَن قال أنها ربا غلطٌ، فإذا اشترى سلعةً بأجلٍ، ثم باعها بنقدٍ على غير مَن اشتراها منه لحاجته فلا بأس، هذا هو الصواب، فالله  يقول: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275]، فالأصل حِلُّ البيع.","link":"https://binbaz.org.sa/fatwas/22426/هل-بيع-التورق-من-البيوع-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل بيع التَّورق بيعٌ ربويٌّ.mp3","categories":["الربا والصرف","البيوع"]},{"id":2305,"question":"إنسان عنده ورقة بعشرة ريالات يُبدلها بتسعة ريالات هلل؟","title":"حكم استبدال عملة ورقية بمعدنية أقل عددًا","answer":"الجواب:\nلا بأس، الهلل جنس آخر، يدًا بيدٍ، مثل أو بقياس؛ لأنَّ هذا غير هذا، مثل العملة الأخرى.","link":"https://binbaz.org.sa/fatwas/22429/حكم-استبدال-عملة-ورقية-بمعدنية-اقل-عددا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استبدال ورقة عشرة ريالات بتسعة ريالات هلل.mp3","categories":["الربا والصرف","البيوع"]},{"id":2431,"question":"ما رأيكم في حديث لا تشتروا السمك في الماء...؟","title":"ما صحة حديث \"لا تشتروا السمك في الماء\"؟","answer":"الجواب:\nما له أصل، إلا إذا عرف إذا لم يتيسر شراؤه، أما إذا كان في ماء محصور في بركة ما يضر، أما إذا كان في البحر لا يبيعه؛ غرر، لا يدري يحصّله وإلا ما يحصّله.","link":"https://binbaz.org.sa/fatwas/22559/ما-صحة-حديث-لا-تشتروا-السمك-في-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا تشتروا السمك في الماء..mp3","categories":["شروح الحديث","الحكم على الأحاديث","فتاوى متنوعة","البيوع"]},{"id":2473,"question":"حكم البيع بعد النداء الأول؟","title":"حكم البيع بعد النداء الأول يوم الجمعة","answer":"الجواب:\nما في بأس، التحريم يكون بعد النداء الثاني، إذا أذّن النداء الثاني حَرُم البيع وبَطَل، الأذان الثاني بين يدي الإمام عند دخوله للخطبة، هذا الأذان الثاني، يُسمّى الأذان الثاني، وهو الأول بالنسبة إلى الإقامة.","link":"https://binbaz.org.sa/fatwas/22602/حكم-البيع-بعد-النداء-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بعد النداء الأول يوم الجمعة.mp3","categories":["الربا والصرف","البيوع"]},{"id":2511,"question":"موضوع التقسيط فيه شركات يقسطون بحيث يقولون:السيارة بمائة ألف لو خليتها على سنه واحدة نأخذ منك مائة وعشرة، سنتين مائة وعشرين، ثلاث سنوات مائة وثلاثين؟","title":"حكم البيع بالتقسيط مع عدم الجزم بالثمن","answer":"الجواب:\nلا بد مِنْ جَزْم، ما يصلح هكذا، لا بد من جزم على قسطين ثلاثة أربعة، إذا جزم عليها فلا بأس، كل سنة كذا، كل شهر كذا...\nس: إذا قال له: على السنة نسبة معينة؟\nالشيخ: لا بد من جزم.\nس: كيف يعني الجزم؟\nالشيخ: أربعين ألف كل سنة عشرة آلاف جزما، أو خمسين ألف كل سنة عشرة آلاف.\nس: بعض الشركات الآن يأخذون نسبة على السنة يقول ثمانية ونصف في المائة على السنة، أو عشرة بالمائة على السنة؟\nالشيخ: المقصود أن يتفقوا على شيء معلوم، هذا هو المقصود، كل سنة أو كل شهر أو كل شهرين.","link":"https://binbaz.org.sa/fatwas/22641/حكم-البيع-بالتقسيط-مع-عدم-الجزم-بالثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بالتقسيط مع زيادة في الثمن.mp3","categories":["الربا والصرف","البيوع"]},{"id":2560,"question":"تقول: عندما يريدون أن يسافروا إلى هناك (بالخراج) يودِعون أموالهم في البنوك ويعطونهم \"كرت\" فيه نوع من الربا فلا بدّ أن يفعلوا هذا، فماذا يصنعون في مثل هذه الحالة؟","title":"حكم الاضطرار لإيداع أموال في بنك ربوي","answer":"الجواب: لا، يضعونها بدون ربا، يأخذون الوثيقة بدون الربا، يضعونها عندهم كأمانة ويحولون عليها بالتحويلات المعتادة بينهم.\nس: على حسب سؤالها تقول: لا بدّ يعطونها الكرت هذا الذي فيه ربا؟\nالشيخ: يمكن هذه القيمة، يقول: سَلِّم قيمة هذا الكرت، هذا قيمة الورقة، مثل الحوالة التي تحول أنت على زيد أو على عمرو تعطيهم قيمة الحوالة عن تعبهم، أما يكون في جداولهم هذه قيمة السفتجة، أما الربا عن المال ما يصلح.\nس: إذا اضطر إلى ذلك يفعل أو لا يفعل؟\nالشيخ: هذا للوثيقة، قيمة الوثيقة، يعطونه قيمة الوثيقة التي يحول بها، مثل وثيقة السفتجة، الحوالة.","link":"https://binbaz.org.sa/fatwas/22692/حكم-الاضطرار-لايداع-اموال-في-بنك-ربوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاضطرار لإيداع الأموال في البنوك الربوية.mp3","categories":["الربا والصرف","البيوع"]},{"id":2570,"question":"هل يجوز فتح محل لبيع الملابس الرجالية الإفرنجية، ويرتادها نسبة كبيرة من الشباب الذين يريدون السفر إلى بلاد العهر والدعارة؟","title":"حكم فتح محل لبيع الملابس الرجالية الإفرنجية","answer":"الجواب: إذا كان مما يلبسه المسلمون ولو مصنوعة في الخارج، إذا كان من ملابس المسلمين ولو هو مصنوع في لندن وفي أمريكا، أما إذا كان فيه تشبه بالكفار؛ لا.\nس: بنطلونات وكرفتات؟\nالشيخ: المقصود إذا كان من لباس الكفار ما هي من لباس المسلمين، ما يجوز، لا يساعدهم على الباطل، الله جل وعلا يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] نسأل الله العافية.\nس: إذا كانت مشتركة بين المسلمين والكفار؟\nالشيخ: إذا كانت مشتركة فمثل السيارة؛ ما هي من خواص الكفار، والطائرة كذلك المشتركة ما فيها شيء، الطائرات ما هي من خواص الكفار، والسيارات ما هي خاصة للكفار.","link":"https://binbaz.org.sa/fatwas/22703/حكم-فتح-محل-لبيع-الملابس-الرجالية-الافرنجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتح محل لبيع الملابس الرجالية الأفرنجية.mp3","categories":["الربا والصرف","البيوع"]},{"id":2790,"question":"ما معنى قوله: لا شرطان في بيع؟","title":"ما معنى \"لا شرطان في بيع\"؟","answer":"الجواب: على ظاهره عند جمع من أهل العلم، وآخرون أوّلوها على بيعتين في بيعة. وظاهره أنه ما يشترط شرطان في بيع، خارج عن مقتضى العقد، شرطين زائدين، لكن واحد لا بأس، واحد مثل ما اشترط جابر لما باع البعير على النبي ﷺ قال: يا رسول الله أشترط أني أبقى عليه حتى أصل إلى المدينة، فأعطاه النبي ﷺ الشرط. فإذا اشترى البيت على أن يسكنه شهرًا شهرين سنة، أو سيارة قال: أبيعك إياها لكن بشرط أني أذهب عليها للمحل الفلاني، وما أشبه ذلك، أما الشرطان كأن يشترط البائع أو المشتري شرطين خارجين عن البيع بخلاف المتعلقة بالثمن أو بالمبيع، هذه من أوصافها، كأن يقول: أبيعك عبدًا كاتبًا بالغًا صفته كذا، هذه ولو كَثُرت من صفة المبيع، لكن الشيء الخارج البعيد ما هو من صفات المبيع، مثل ما قال الفقهاء: حمل الحطب وتكسيره، شرطي أن تحمله وتكسره، شرطي أن تحمل الدواب وتطبخها، عند جمع من أهل العلم أن هذا لا يصلح، شرط واحد بس.","link":"https://binbaz.org.sa/fatwas/22938/ما-معنى-لا-شرطان-في-بيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لا شرطان في بيع.mp3","categories":["البيوع","شروح الحديث"]},{"id":2800,"question":"الذي عنده أغنام يعدها للبيع يسمّنها ويغذّيها قبل أن يعرضها للبيع، هل في ذلك محظور؟","title":"حكم تسمين الأغنام لتنتفخ قبل بيعها","answer":"الجواب: وأيش المانع، يسمّنها حتى تَسْمَن وتنفعه. أما اللبن لا يغش الناس باللبن، أما كونه يسمَنها ويخليها أسبوعين ثلاثة حتى تزيد ما في شيء.\nس: بعضهم يعطيها ماءَ وملحًا فتنتفخ؟\nالشيخ: لا، الشيء الذي فيه غش ما يجوز، أما السمينة عادي ما في شيء، يسمّنها، مطلوب منه يسمنها حتى تنفعه... أما الغش لا يجوز، الشيء الذي ينفخها ما يجوز، أو...كذلك يجمع اللبن فيها ويقول إنه من الصبح، وهو ما هو من الصبح، لبن البارحة ولبن الصبح ولبن أمس، هذا ما يجوز؛ غِشّ.","link":"https://binbaz.org.sa/fatwas/22948/حكم-تسمين-الاغنام-لتنتفخ-قبل-بيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هنده أغنام يعدها للبيع فيسمنها لتنتفخ.mp3","categories":["الربا والصرف","البيوع"]},{"id":2809,"question":"ما حكم الذي يقرأ في الماء ويبيعه؟","title":"حكم القراءة في الماء وبيعه","answer":"الجواب: تركه أوْلى، إذا كان يقرأ لأحد معين يعطيه إياه، أما يبيعه على الناس ما ينبغي هذا، ولا له أصل، يُخشى أن يكون مُحَرَّمًا ما هو طيب. أما كونه يقرأ على واحد معين ويعطيه مساعدة؛ ما في بأس، مثلما قرأ النبي ﷺ لثابت بن قيس ثم صبه عليه.","link":"https://binbaz.org.sa/fatwas/22958/حكم-القراءة-في-الماء-وبيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القراءة في الماء وبيعه.mp3","categories":["البيوع"]},{"id":3101,"question":"رجل أراد أن يشتري حاجة من محل، ما معه إلا مائة ريال واشترى حاجة بمبلغ خمسين ريال وبقي له خمسين، ولم يكن موجودًا الباقي مع صاحب المحل...؟","title":"حكم مَن اشترى سلعة وبَقي له مبلغ مما دفعه","answer":"الجواب: يُمْهِله وإلا يخلّي عنده المائة أمانة حتى يحضر له الخمسين، وإلا يعطيه إياها ويرد عليه خمسين، الأمر واسع، إما يعطيه إياها ويرد عليه خمسين، وإلا يُمْهِله ويُنْظِره حتى يأتي له بالخمسين، وإلا يخليها عنده أمانة حتى يأتي له بالخمسين كالرهانة.","link":"https://binbaz.org.sa/fatwas/23261/حكم-من-اشترى-سلعة-وبقي-له-مبلغ-مما-دفعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشترى سلعة وبقي له مبلغ عند صاحب المحل.mp3","categories":["الربا والصرف","البيوع"]},{"id":3111,"question":"يجوز الإنكار على بعض الناس، يبيع \"مساويك\" إلى بعد الأذان الثاني، فإذا كان الشخص يعني قبل دخول الخطيب هل يجوز له أنْ يُنكر عليه يقول: لا تبِع؟","title":"كيف يُنْكَر على البيع بعد الأذان الثاني للجمعة؟","answer":"الجواب: نعم نعم، إذا مَرّ وهو يبيع ينكر عليه في طريقه... وهو ذاهب إلى الصلاة.","link":"https://binbaz.org.sa/fatwas/23271/كيف-ينكر-على-البيع-بعد-الاذان-الثاني-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار على من يبيع بعد الأذان الثاني يوم الجمعة.mp3","categories":["البيوع"]},{"id":3133,"question":"ما حكم بيع الرجل المشرك ثوب الحرير؟","title":"حكم بيع ثوب الحرير إلى الرجل المشرك","answer":"الجواب: الأقرب عندي أنه لا يجوز، لا يعينه على الباطل، يُروى عن عمر أنه كان يرسل بعض الثياب لأقارب له من الكفار الحرير؛ لكن لعله أرسلها لهم لصلة بينهم حتى يُلبسوها نساءهم.\nس: ما يدل على الجواز؟\nالشيخ: لا ما هو بصريح، قد يكون أراد أنهم يُلبسونها نساءهم.","link":"https://binbaz.org.sa/fatwas/23294/حكم-بيع-ثوب-الحرير-الى-الرجل-المشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع الرجل المشرك ثوب الحرير.mp3","categories":["الربا والصرف","البيوع"]},{"id":3232,"question":"معاملة غير المسلمين بالغش؟","title":"حكم الغش في معاملة غير المسلمين","answer":"الجواب: لا يغش المسلمين ولا غير المسلمين، حتى الكفار لا يغشهم.","link":"https://binbaz.org.sa/fatwas/23395/حكم-الغش-في-معاملة-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم معاملة غير المسلمين بالغش.mp3","categories":["الربا والصرف","البيوع"]},{"id":3235,"question":"تشترط كثير من المحلات شرطًا يُكتب في الفاتورة: البضاعة لا تُرَدّ ولا تُسْتَبْدَل؟","title":"حكم شرط البائع \"البضاعة لا تُرَدّ ولا تُسْتَبْدَل\"","answer":"الجواب: هذا ما هو صحيح، تُرَدّ وتُسْتَبْدَل إذا وجد ما يقتضي ذلك، إذا وجد غشٌّ تُرَدّ ولا تُسْتَبْدَل، هذا كذب.\nس: لكن إذا قَبِل به المشتري يلزمه؟\nالشيخ: إذا قبله ووجد عيبًا له الرد...، إذا وجد عيبًا خدعوه به، له الرد، أما إذا كان ما في عيب يلزمه، لو جئت السيارة قلت: والله ما أعلم فيها \"عيب\" واشترى.. يلزم البيع. لكن ثبت أنه غاشّه له الخيار.\nس: يكون هذا الشرط باطلًا؟\nالشيخ: ما هو باطل، لكن ما يَمْنع، ما يمنع الرجوع فيه إذا وجد عيبًا يعلمه البائع وستره خَدَعَه به، أما إذا قال ما أعلم بها عيبًا واشترى.... يلزمه البيع.","link":"https://binbaz.org.sa/fatwas/23398/حكم-شرط-الباىع-البضاعة-لا-ترد-ولا-تستبدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم شرط المحلات التجارية البضاعة لا ترد ولا تستبدل.mp3","categories":["الربا والصرف","البيوع"]},{"id":3459,"question":"يسأل بعض الإخوة الحاضرين يقول: أنا موظف في كهرباء الخرج ومُجبر على ترك حساب في أحد البنوك، ولكن حسابي بدون فائدة يسمى حسابي \"دائم\"، والبنك يأخذ خدمات بنكية اثنين ونصف في المائة؟","title":"حكم الإيداع في البنك الربوي للضرورة","answer":"الجواب: إذا كان ما في ربا، ودعت الضرورة للإيداع؛ لا بأس بدون ربا. لكن الإيداع عند غيرهم أحوط، المحرمُ الرِّبا.","link":"https://binbaz.org.sa/fatwas/23636/حكم-الايداع-في-البنك-الربوي-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإيداع في النبك الربوي للضرورة.mp3","categories":["الربا والصرف","البيوع"]},{"id":3461,"question":"شخص يقول: لدي محل تجاري، وأضع فيه جوائز للزبائن، ولكني أشتري هذه الجوائز قبل وضع الدعاية، أي لا أشتري هذه الجوائز من مال الزبائن، فهل يصح عملي هذا أم لا؟","title":"حكم وضع الجوائز لزبائن المحلات","answer":"الجواب: ينبغي ترك هذا؛ لأنه قد يؤذي من حوله، يعطيهم جوائز حتى يرغّبهم في الشراء منه، ويعطّلون الناس الآخرين، فالأحوط ترك ذلك، ويكون مثل الناس.","link":"https://binbaz.org.sa/fatwas/23638/حكم-وضع-الجواىز-لزباىن-المحلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع الجوائز لزبائن المحلات.mp3","categories":["الربا والصرف","البيوع"]},{"id":3467,"question":"لو أن الإنسان أراد أن يعقد عقدًا بين بعض الناس، وهم يريدون أن يشرطوا عليه شرطًا باطلًا، فأراد ألّا يخبرهم حتى يمضي العقد ثم يقول: الشرط باطل، يصح ذلك؟","title":"هل يجوز إتمام العقد وفيه شرط باطل؟","answer":"الجواب: لا، يعلّمهم، ما يتم الشرط، يعلّمهم أن الشرط باطل، لا يعقد لهم، يبيّن لهم، لا يغشهم.\nس: جاء في الحديث هذا....... ؟\nالشيخ:.... يعلمهم، الرسول ﷺ علّمهم، قال: علّميهم، وأخبريهم أن العقد باطل، أنه لا بأس أن تشتريها والولاء لها إنما الولاء لمن أعتق.\nس: في بعض الروايات أنه قال لعائشة: اشتريها، واشترطي الولاء؟\nالشيخ: لأنه بلّغهم، ما دام بلّغوا، يعني من باب النكال لهم، والتثريب عليهم، يعني: اشترطتم أو لم تشترطوا قد بُلّغتم أنه لا يجوز.","link":"https://binbaz.org.sa/fatwas/23644/هل-يجوز-اتمام-العقد-وفيه-شرط-باطل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العقد إذا كان فيه شرطا باطلا.mp3","categories":["الربا والصرف","البيوع"]},{"id":3737,"question":"بيع الملابس المتبرجة...؟","title":"ما حكم بيع الملابس المتبرجة؟","answer":"الجواب: هذا يختلف: إذا كنت تعلم أنهن يلبسن ذلك على صفة تخالف الشرع لا تبع عليهن.  وإذا كنت لا تعلم، واللباس يصلح لهذا وهذا، قد يكون تحت الثياب، ما يلزم يكون فوق الثياب، قد يكون تحت الثياب أو عند الزوج، فالأمر فيه تفصيل.","link":"https://binbaz.org.sa/fatwas/23929/ما-حكم-بيع-الملابس-المتبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بيع الملابس المتبرجة.mp3","categories":["البيوع","اللباس والزينة"]},{"id":3763,"question":"بعض البياعين ما يبيع شيئًا إلا ويحلف عليه؟","title":"حكم الحلف على البيع والشراء","answer":"الجواب: ما ينبغي، مثل ما نهى النبي عن ذلك، ما ينبغي الحلف على البيع والشراء في الحديث:  ثلاث لا يكلمهم الله.. الحديث وفيه: ورجل جعل الله بضاعته لا يبيع إلا بيمينه ولا يشتري إلا بيمينه فينبغي التحفظ من اليمين، الله يقول: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] لكن إذا كان اليمين في تأكيد الخير والدعوة إلى الخير والتحذير من الشر؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/23956/حكم-الحلف-على-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف على البيع والشراء.mp3","categories":["الأيمان والنذور","البيوع"]},{"id":3788,"question":"ولو زيد الثَّمن بالتقسيط؟","title":"حكم زيادة الثمن في البيع بالتقسيط؟","answer":"الجواب: ولو زيد نعم، لا بدّ أن يُزاد في الغالب، بيع الآجل غير بيع النقد، إذا صار الشيء يُباع بالنقد بألف، يُباع بالأجل بألفين، ثلاثة، بالآجال، الأجل يُزاد، لا حرج فيه عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/23986/حكم-زيادة-الثمن-في-البيع-بالتقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة الثمن في البيع الآجل.mp3","categories":["الربا والصرف","البيوع"]},{"id":3923,"question":"هل الجمرك حرام أو حلال؟","title":"ما حكم الجمرك؟","answer":"الجواب: الجمرك محرم، مكس، يقال المكوس محرمة لا تجوز، لكن الدول.. يقع من الدول أشياء ممنوعة، وقد يكون لهم فيها بعض التأويلات أحيانًا، فالأصل في هذا كله تحريم مال المسلم على أخيه، وإذا كان المال ممنوعًا يُمنع... وما حرم الله يُمنع، كالخمور وما حرم الله، يجب منعه.","link":"https://binbaz.org.sa/fatwas/24141/ما-حكم-الجمرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمرك وحكمه.mp3","categories":["الربا والصرف","البيوع"]},{"id":4181,"question":"المنح للأراضي الآن، وتكون فيها بيعها قبل استلامها؟","title":"هل يجوز بيع الأراضي قبل الاستلام والقبض؟","answer":"الجواب: ما يجوز هذا حتى يحوزها، يُعطى صكًّا بها ويتملكها، حتى الأراضي ليس له بيعها حتى يحوزها، يعني حتى يُعطى صكًا بذلك ويثبت الأمر، لا يصير غرر.","link":"https://binbaz.org.sa/fatwas/24438/هل-يجوز-بيع-الاراضي-قبل-الاستلام-والقبض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع قبل الاستلام والقبض.mp3","categories":["الربا والصرف","البيوع"]},{"id":4182,"question":"من يشتري السيارة ثم يبيعها قبل نقل ملكيتها؟","title":"حكم شراء سيارة ثم بيعها قبل نقل ملكيتها","answer":"الجواب: لا بدّ أن يقبضها قبضًا تامًا وينقلها من معرضه إلى محل آخر، يُتِمُّ الملكية، الرسول ﷺ نهى أن تباع السلع حيث ابتاعت حتى يحوزها التجار إلى رحالهم...  لا يشتري شيئًا إلا عن قبض تام، وعلى الطريقة التي رسمتها الدولة على حسب التعليمات تبع الدولة، لا يخالف التعليمات حتى لا يقع الغرر والخطر.","link":"https://binbaz.org.sa/fatwas/24439/حكم-شراء-سيارة-ثم-بيعها-قبل-نقل-ملكيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع السيارة قبل نقل ملكيتها.mp3","categories":["الربا والصرف","البيوع"]},{"id":4183,"question":"بيع النخل بالنخل؟","title":"هل يجوز بيع النخل بالنخل؟","answer":"الجواب: ما في بأس، بيع النخل بالنخل لا بأس.  المقصود بيع الثمرة؛ لا تباع الثمرة مفردة إلا بعد أن يطيب الثمر. أما إذا باع النخل فالثمر تبع؛  يكون للمشتري إذا كان قد لُقِّح، يعني أُبِّر.","link":"https://binbaz.org.sa/fatwas/24440/هل-يجوز-بيع-النخل-بالنخل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع النخل بالنخل.mp3","categories":["الربا والصرف","البيوع"]},{"id":4184,"question":"بعض المحلات يبيعون أشياء محرمة.. كالمجلات.. والدخان؟","title":"حكم الشراء من محلات تبيع أشياء محرمة","answer":"الجواب: تشتري منهم الشيء المباح، الشيء المباح تشتريه إذا باعوه، أشياء طيبة تشتريها، باعوا مجلات طيبة تشتريها، باعوا كتبًا طيبة تشتريها، باعوا أواني تشتريها، ولا تشتر الدخان، ولا تشتر المحرمات، تنصحهم وتنكر عليهم وتعلّمهم الخير.\nس: هناك بقالات تكون بجانبها، يعني من باب تشجيع هذه البقالات التي لا تبيع الدخان والمجلات..؟\nالشيخ: لا بأس، يشتري من هؤلاء ومن هؤلاء وإذا شجع الطيبين طيب، لكن قد يكون الذي عنده طيب غال واللي عنده الرديء رخيص أرخص، لا بأس عليه، اليهود من أكفر الناس واشترى منهم النبي ﷺ.\nس: ما يُهجرون للتأديب يا شيخ؟\nالشيخ: إذا رأى المصلحة في ذلك لا بأس.","link":"https://binbaz.org.sa/fatwas/24441/حكم-الشراء-من-محلات-تبيع-اشياء-محرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الشراء من المحلات التي تبيع أشياء محرمة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4187,"question":"الأرض التي عليها قرض، أرض قيمتها مئة ألف، وعليها قرض يجعلها مئة وثلاثين ألفًا، هل يجوز أن تباع بقرضها بالزيادة؟","title":"حكم بيع أرض عليها قرض زائد على قيمتها","answer":"الجواب: المقصود إذا كان عنده أرض اشتراها من الحكومة وأراد أن يبيعها يبيعها، إذا اشتراها من الحكومة يبيعها ويوفي الحكومة حقهم، وإن سامحته الحكومة فلا بأس، إذا كان عنده أرض وعليه للحكومة فيها مائة ألف أو أقل أو أكثر، وباعها وسدد للحكومة حقهم أو حولهم على المشتري؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/24444/حكم-بيع-ارض-عليها-قرض-زاىد-على-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع الأرض التي عليها قرض زائد على قيمتها.mp3","categories":["الربا والصرف","البيوع"]},{"id":4189,"question":"الاحتكار لغير الطعام؟","title":"حكم الاحتكار لغير الطعام","answer":"الجواب: الأقرب أنه يُمنع أيضًا، حتى غير الطعام إذا كان فيه ضرر على المسلمين؛ بجامع العلة.","link":"https://binbaz.org.sa/fatwas/24446/حكم-الاحتكار-لغير-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاحتكار لغير الطعام.mp3","categories":["الربا والصرف","البيوع"]},{"id":4190,"question":"الوكالات التجارية هل هي من الاحتكار؟","title":"هل تدخل الوكالات التجارية في الاحتكار؟","answer":"الجواب: أيش الوكالات التجارية؟\nس: يعني إنسان يحتكر نوعًا  معينًا من السيارات لا يبيعها إلا هو؟\nالشيخ: هذا فيه تفصيل، إن كان يضر الناس يمنع، وإن كان ما فيه ضرر الأمر سهل.","link":"https://binbaz.org.sa/fatwas/24447/هل-تدخل-الوكالات-التجارية-في-الاحتكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الاحتكار الوكالات التجارية.mp3","categories":["الربا والصرف","البيوع"]},{"id":4281,"question":"عندنا جار مؤجر لواحد يبيع شيشة وكلمناه وقال: أنه مؤجر لواحد ثانٍ خمس سنين وبقى له سنة، وأجّره للثاني صاحب الشيشة وقال كلمنا شيخ وقال معليش..؟","title":"حكم تأجير المحلات لبائعي الشيشة","answer":"الجواب: لا، غلط غلط، يُعَلَّمُ الناس أن هذا لا يجوز، الله يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] ينبغي لجيرانه أن يتكلموا معه وينصحوه حتى لا يعود لهذا، وإن دعت الحاجة للمحكمة يحاكمونه.\nس: يفسخ العقد؟\nج: إما يفسخ العقد أو يرفعونه إلى المحكمة؛ لعلها تعينهم على هذا.","link":"https://binbaz.org.sa/fatwas/24551/حكم-تاجير-المحلات-لباىعي-الشيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تأجير المحلات لمحلات الشيشة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4752,"question":"الحكايات والأخبار التي تُروى في مشاهدة بعض الناس لشيءٍ من النَّعيم؟","title":"ما صحة الأخبار في رؤية نعيم القبر أو أهواله؟","answer":"هذا واقع، ذكره ابنُ رجبٍ رحمه الله وغيره، ذكره ابنُ رجب في \"أهوال القبور\"، والقرطبي في \"التذكرة\"، والسَّفاريني في \"البحور الزاخرة\"، وغيرهم ذكروا أشياء من هذا كثيرة، ابن رجب ذكر من هذا أشياء في \"أهوال القبور\"، أطلع الله الناس على ما يشاء ؛ عبرةً، للعظة والتَّذكر، مثلما أطلع اللهُ نبيَّه ﷺ على القبرين، قال: إنهما ليُعذَّبان، وما يُعذَّبان في كبيرٍ، أما أحدهما فكان لا يستتر من بوله، وأما الآخر فكان يمشي بالنَّميمة، هذا مما أطلع عليه النبيَّ ﷺ، وفي غلام -مولاه كركرة- قال: إنَّ الشَّملة التي غلَّها لتشتعل عليه نارًا، وأشياء من هذا جاءت عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/25096/ما-صحة-الاخبار-في-روية-نعيم-القبر-او-اهواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأخبار التي تُروى في مشاهدة بعض الناس لشيءٍ من نعيم القبر أو أهواله.mp3","categories":["شروح الحديث","الحكم على الأحاديث","فتاوى متنوعة","البيوع"]},{"id":4766,"question":"يقول ما الحكم في البيع بعد الأذان عند المساجد؟","title":"حكم البيع بعد الأذان عند المساجد؟","answer":"لا يصح البيع بعد أذان الجمعة - الأذان الثاني - عند دخول الخطيب، أما غيره فتركه أولى، الصلوات الأخرى تركه أولى؛ لعدم ورود شيء في ذلك، إذا أذن يبادر بالسعي إلى الصلاة ولا ينبغي له أن يتشاغل ببيع ولا غيره بعد الأذان، لكن النص إنما جاء في صلاة الجمعة؛ لضيق وقتها وعظم شأنها، ولأن المقصود من الصلاة حضور الخطبة، فإذا اشتغل بشيء فاتت الخطبة.","link":"https://binbaz.org.sa/fatwas/25127/حكم-البيع-بعد-الاذان-عند-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بعد الأذان عند المساجد.mp3","categories":["الربا والصرف","البيوع"]},{"id":4860,"question":"هل تجوز التجارة في كلاب الصيد؟","title":"ما حكم التجارة في كلاب الصيد؟","answer":"لا، الكلب لا يباع. النبي ﷺ نهى عن بيع الكلاب، وقال : ثمن الكلب خبيث، لكن يربّيه فقط ويعلّمه بس.\nس: ويغرم ثمنه؟\nج: ولا يغرم ولا شيء، ما له قيمة.","link":"https://binbaz.org.sa/fatwas/25326/ما-حكم-التجارة-في-كلاب-الصيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التجارة في كلاب الصيد.mp3","categories":["البيوع"]},{"id":4869,"question":"في بعض البلاد تباع الأصنام للسُّوَّاح للشيخ من غير قصد أنها تعبد، للزينة؟","title":"حكم بيع الأصنام للسُّوَّاح بقصد الزينة","answer":"تحرم.\nس: ما يكفر بهذا؟\nج: لا، ما يكفر، مثل هذا الذي يبيع الصور، الآن يبيعون صور النساء وصور الرجال.","link":"https://binbaz.org.sa/fatwas/25348/حكم-بيع-الاصنام-للسواح-بقصد-الزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بيع الأصنام للسواح بقصد الزينة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4874,"question":"إذا أعطاه أجرة على التبرع بالدم؟","title":"هل تجوز الأجرة على التبرع بالدم؟","answer":"لا ما يصلح، الرسول ﷺ نهى عن بيع الدم، ونهى عن ثمن الدم؛ فلا يأخذ شيئًا مقابله.","link":"https://binbaz.org.sa/fatwas/25360/هل-تجوز-الاجرة-على-التبرع-بالدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأجرة على التبرع بالدم.mp3","categories":["الربا والصرف","البيوع"]},{"id":4883,"question":"في شركة مضاربة يقولون: إذا أعطيتنا رأس المال لسنة نعطيك نسبة 10% من الربح، إذا تركت رأس المال معنا سنتين نعطيك 20%؟","title":"هل تجوز المضاربة على نسبة ربح معلومة؟","answer":"من الربح، أو شيء معلوم دراهم معلومة؟\nس:  يقول: من الربح، لكن تختلف نسبة الربح في زيادة السنوات؟\nج: ما في بأس، إذا كان الربح بنسبة فلا بأس، أما دراهم معلومة فلا.","link":"https://binbaz.org.sa/fatwas/25388/هل-تجوز-المضاربة-على-نسبة-ربح-معلومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المضاربة على نسبة ربح معلومة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4884,"question":"بعض أهل العلم لا يفرِّق بين مسألة العِينة والتورُّق؟","title":"ما الفرق بين بيع العِينة والتورُّق؟","answer":"غلط، التورُّق غير، التورُّق أن تشتري السلعة إلى أجل معلوم وتبيعها على الناس، واللي يشتريها ما يبيعها عليك، اللي يشتريها يبيعها على الناس الآخرين، إن باعها عليك هذه العِينة، لكن إن كان باعها على غيرك ما جاءت العينة. يبيعها على غيرك، يتزوج أو يبني بيتًا أو يقضي دينًا، اشترى منه سيارة بمائة ألف ريال ثم باعها على غيره: ما فيه شيء. العِينة يبيعها عليه، أما إذا باعها على غيره فليس فيه ربا، والناس في حاجة إلى هذا.","link":"https://binbaz.org.sa/fatwas/25389/ما-الفرق-بين-بيع-العينة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين مسألة العينة والتورق.mp3","categories":["الربا والصرف","البيوع"]},{"id":4885,"question":"من قال: يجوز بيع الدين بالدين، لكن بشرط قبض العوض قبل مفارقة المجلس؟","title":"ما حكم بيع الدين بالدين؟","answer":"هذا لا بأس، مثل ما قال ﷺ: لا بأس أن تأخذها بسعر يومها، الدين بالدين كلها مؤجلات.\nس: إذا كان مؤجلًا؟\nج: لا، أما إذا كان الدين بشيء معجّل ما يسمى \"دين\".","link":"https://binbaz.org.sa/fatwas/25392/ما-حكم-بيع-الدين-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بيع الدين بالدين بشرط قبض العوض ومفارقة المجلس.mp3","categories":["الربا والصرف","البيوع"]},{"id":4890,"question":"بالنسبة لبيع رقم أرض وهو محتاج، يبيعها بسعر بخس؟","title":"ما حكم من يبيع أرضًا لم يستلمها؟","answer":"إذا كانت في ملكه وقد استوفى شروط الملك ما يوجد فيها دعوة ولا خصومة؛ يبيعها وإذا نزل؛ لأنه محتاج أن يبيعها.\nس: هو لم يستلمها بعد، استلم الأوراق.\nج: لا، ما يصح، ما بعد مَلَكها، لا يبيع حتى يملكها ويأخذ صكًّا عليها أو وثيقة.\nس: بيع الأرض بوصف منضبط؟\nج: إذا كانت موجودة.\nس: موجودة لكن بصكٍّ المشتري لم يره؟\nج: ولو، إذا وصفها، طولها كذا وعرضها كذا وصفتها كذا؛ ما في بأس، تنضبط.","link":"https://binbaz.org.sa/fatwas/25402/ما-حكم-من-يبيع-ارضا-لم-يستلمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع أرض لم يستلمها.mp3","categories":["الربا والصرف","البيوع"]},{"id":4893,"question":"بالنسبة للعربون: هل يكون من نصيب البائع لو ما كان بينهم شرطٌ بين البائع والمُشتري؟","title":"هل يكون العربون للبائع أو للمشتري؟","answer":"لا، على حسب الشروط، المسلمون على شروطهم، العربون تارةً يشترط أنه له، وتارةً أمانة، ما هو له، أمانة، إن تمَّ البيعُ وإلا أعطاه إياه، إن كان أمانةً فهو أمانة، وإن كان لا، قال: ما أسمح، ولا ...\nس: إذا كان العربون يأخذ نصف القيمة؟\nج: الذي اتَّفقوا عليه، المسلمون على شروطهم.\nس: يأخذه بدون مقابل؟\nج: المقابل تضييع الفرص، وتفرَّقوا، الناس يمكن لو دوَّر مَن يشتريها ما يحصل أحدًا، تفرَّقوا.","link":"https://binbaz.org.sa/fatwas/25408/هل-يكون-العربون-للباىع-او-للمشتري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لمن يكون العربون للبائع أو للمشتري.mp3","categories":["الربا والصرف","البيوع"]},{"id":4894,"question":"الشيك يُعتبر قبضًا؟","title":"هل يعتبر الشيك البنكي قبضًا؟","answer":"عند جمعٍ من أهل العلم يُعتبر قبضًا؛ لأنه في أي بنك حصل به المطلوب، ولكن إذا تيسر له أن يكون قبضًا تامًّا لا بأس أن يُعطيه دراهم، وأما الشيك فهو قبض في الحقيقة؛ لأنه أينما ذهب حصل به المطلوب.","link":"https://binbaz.org.sa/fatwas/25409/هل-يعتبر-الشيك-البنكي-قبضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعتبر الشيك قبضًا.mp3","categories":["البيوع"]},{"id":4895,"question":"الذي يشتري ملابس بخمسين ريالًا، ويبيعها بمئةٍ وخمسين، يعني: ثلاثة أضعاف قيمتها؟","title":"هل للربح في البيع حدٌّ معين؟","answer":"إذا كان لها أسباب: ما لها سعر معلوم في الأسواق، على حسب البيع والشراء، إذا ما كان لها ربحٌ معين، ما لها سوقٌ معين، لا يخدع الناس، إن كان لها سوقٌ معينٌ وسعرٌ معينٌ لا يخدع الناس، يقول: ترى سعرها كذا وكذا، أما إذا ما كان لها سعر معين: ما أبيعها إلا بكذا وكذا، إلا بفائدة كذا؛ لا بأس.\nس: الربح ما له حدٌّ؟\nج: ما له حدٌّ، إذا كان ما له أسعار مُعينة، أما إذا كان السوقُ مُسَعَّرًا: هذا في السوق يُباع بعشرة ريالات، وأنت تقول: لا، أبيعه بعشرين تضر الناس، لا.","link":"https://binbaz.org.sa/fatwas/25410/هل-للربح-في-البيع-حد-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للربح في البيع حدٌّ معين.mp3","categories":["الربا والصرف","البيوع"]},{"id":4899,"question":"لو قال في السلم الوصف ليس منضبطًا؟","title":"ما شروط السَّلَم؟ وهل يكون حالًّا أم مؤجلًا؟","answer":"لا، هم يتفقون على أصل مضبوط وإلا ما يصح البيع، لا بدّ أن يتفرقا على شيء معلوم.\nس: ما هي شروط السلم؟\nج: مثل ما تقدم: على شيء معلوم. والشروط الأخرى في محلها، لكن إذا أسلف في شيء معلوم إلى أجل معلوم؛ فلا بأس، هذا في الذمة مما يوجد غالبًا.\nس: قول بعض الفقهاء أن العقار لا يدخل في السلم؛ لأنه لا ينضبط فيه الوصف، هل هو سليم؟\nج: العقار ما يسمى \"سلم\" يسمى بيع أعيان، إذا كان عنده عقار مضبوط يعرفه هذا بيع أعيان، ما هو بيع سلم.\nس: إذا كانت هذه السلعة تباع بألف ريال لكن رفض أن يبيعنيها إلا بألفين؟\nج: أو بثلاثة ما يخالف، أو بأربعة، إذا تراضيتم إلى أجل معلوم لا بأس.\nس: هل يجوز أن يكون السلم حالًّا؟\nج: ما يكون سلمًا إلا مؤجلًا، ما يكون حالًّا، لا يسمى سلمًا إلا مؤجلًا.","link":"https://binbaz.org.sa/fatwas/25414/ما-شروط-السلم-وهل-يكون-حالا-ام-موجلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في السَّلَم.mp3","categories":["الربا والصرف","البيوع"]},{"id":4904,"question":"بالنسبة لاستبدال القديم بالجديد في البضاعة، ويقدرونها كسيارة أو أي شيء؟","title":"حكم بيع بضاعة قديمة بجديدة مع زيادة في الثمن","answer":"ما في بأس؛ يبيعه سيارة بسيارة ويزيده، أو يبيعه بيت ببيت ويزيده، أو يبيعه أرضًا بأرض ويزيده، أو يبيعه \"بشت\" ببشت ويزيده؛ ما في بأس؛ لأن هذه أجناس ما يدخلها ربا.","link":"https://binbaz.org.sa/fatwas/25419/حكم-بيع-بضاعة-قديمة-بجديدة-مع-زيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استبدال القديم بالجديد بزيادة في الثمن، هل يدخل فيها الربا.mp3","categories":["الربا والصرف","البيوع"]},{"id":5061,"question":"بعضهم يحتج يقول: \"الدخان إذا ما بعته ما يشترون مني\" هل من كلمةٍ توجيهيةٍ لهم؟","title":"حكم من يبرر بيعه الدخان بحاجته للزبائن","answer":"الجواب: هذا ما هو بعذرٍ شرعيٍّ، هذا مثل الذي يقول: \"إذا لم أضع خمرًا لم يجئني أحدٌ\"، هذا ما هو بعذرٍ، يجب عليه تقوى الله، والحذر مما حرَّم الله ولو ما جاءه ناسٌ، فالذي يكتبه الله يأتي، يضع سلعًا ينتفع بها الناس، جاؤوا أو لا، ولا يلزم أن يضع شيئًا محرَّمًا، هذا من تسويل الشيطان، ومن تلاعب الشيطان.","link":"https://binbaz.org.sa/fatwas/29349/حكم-من-يبرر-بيعه-الدخان-بحاجته-للزباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يبرر بيعه الدخان بالحاجة للزبائن.mp3","categories":["الربا والصرف","البيوع"]},{"id":5089,"question":"سائل يقول: فضيلة الشيخ عبد العزيز، نفعنا الله بعلمك: لي أب يعمل في شركة (أرامكو) منذ ثلاثة وثلاثين عامًا، ومنذ بدايته وهو يضع نقوده في بنك الضمان الاجتماعي في الشركة، والآن انتهى من العمل، وسوف يعطونه أمواله وزيادة، أو مضاعفة، فماذا يعمل في هذه النقود؟ وهل هي ربا؟ وماذا أفعل لو أخذها، أفدنا أطال الله بقاءك؟","title":"أين تُصرف أموال الربا؟ وهل يحلُّ تملكها؟","answer":"الجواب: هذا صدر فيه فتوى من اللجنة الدائمة: أن النقود التي توضع في الشركات التي تشترط من العامل إذا دفع نقودًا من راتبه كل شهر أنه بعد خمس سنوات يعطي كذا، وبعد عشر سنوات يعطي كذا، (60%) أو (50%) أو (100%) فإن هذه الزيادة ربا؛ لأنها تنتفع بأمواله، وتنمّيها، وترابي فيها، وتعطيهم ذلك، وهذا شيء اطلعنا عليه في بعض بنود الشركات، وأنها بعد مرور خمس سنوات تعطيك (50%) مثلًا أو أقل أو أكثر، وإذا مضى عليه عشر سنوات أعطته (100%) في مقابل ما دفعه من أقساط، وهذا ربا. والذي يظهر لنا أن الواجب عليه الصدقة بها، أو صرفها في مشاريع خيرية؛ لا يأكلها؛ لأنها ربا، فيأخذ ماله الذي جمع وحصل له من الأقساط التي قدمها لهم. وأما الربا الذي أعطوه زيادة فهذه تصرف في وجوه البر وأعمال الخير، وبناء الطرق والمدارس، ودورات المياه، ومواساة الفقراء وقضاء دين المدينين، وإعطاء المجاهدين والمبتلين بالفقر في أي مكان. هذا هو الذي يجب؛ لأنه مال جاءه من غير حله، فلا يُحرق ولا يُتلف؛ ولكن يُصرف في مصارف الأموال الضائعة والأموال التي ليس لها أحد.","link":"https://binbaz.org.sa/fatwas/29992/اين-تصرف-اموال-الربا-وهل-يحل-تملكها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 09.mp3","categories":["الربا والصرف","البيوع"]},{"id":5112,"question":"سماحة الشيخ حفظكم الله، هل يجوز لي شراء أثاث بالتقسيط من بنك الراجحي؛ لأن هناك من يقول: إن الشراء بالتقسيط حرام؛ لأن فيه ربا أفيدوني؟","title":"ما حكم شراء السلع بالتقسيط من البنك؟","answer":"الجواب: لا بأس بالتقسيط، شراء سيارة أو أثاث أو ملابس أو بيت أو أرض بالتقسيط؛ لا بأس إذا كان مالكًا لها البائع، إذا كانت عند البائع مملوكة له، حائزًا لها في بيته، في ملكه، في حوشه، إذا كانت عنده قد ملكها، وحازها وباعها بالتقسيط؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/30020/ما-حكم-شراء-السلع-بالتقسيط-من-البنك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 40.mp3","categories":["الربا والصرف","البيوع"]},{"id":5146,"question":"هذا السائل يقول يا سماحة الشيخ: ما حكم التعامل مع أحد البنوك المحلية في صناديق الاستثمار، ويكون عقد بين البنك وواضع النقود في الربح والخسارة؟","title":"ما حكم التعامل مع البنوك بعقد في الربح والخسارة؟","answer":"الجواب: هذا إذا أُمِن لا بدّ أن يكون من طريق الربح والخسارة، يعني من طريق المُضاربة جزء مشاع، مثل: أن يُعطيه مئة ألف أو أكثر أو أقلّ، ويقول: اعمل فيها بالمُضاربة، فاشترِ سيارات، اشترِ عُمَلًا، وبعها، ويكون لك النصف، أو الربع، أو الخمس؛ فلا بأس. أما فائدة معينة لك: 5%، 10% فهذا هو الربا، ما يجوز، لكن إذا كان بربع الربح أو عُشر الربح يعني: 10% من الربح، أو 20%، أو النصف؛ فلا بأس. هذا يُسمَّى: المُضاربة، وهي جائزة عند جميع العلماء، لكن هل يُؤْمَنُون على هذه العملية أو يبيعون بالربا؟ هذا محل النظر، بعضهم لا يُؤمَن، وأشكّ أنَّهم يُؤْمَنُون في هذا الشيء، وهم قد اعتادوا الربا، لكن إذا كان معه أناس مأمونون فهذا طيبٌ.","link":"https://binbaz.org.sa/fatwas/30061/ما-حكم-التعامل-مع-البنوك-بعقد-في-الربح-والخسارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 82.mp3","categories":["الربا والصرف","البيوع"]},{"id":5149,"question":"هذا السائل يقول يا سماحة الشيخ: ما حكم إيداع النُّقود في البنوك الأهلية التِّجارية كحسابٍ جارٍ؟","title":"ما حكم إيداع النُّقود في البنوك كحسابٍ جارٍ؟","answer":"الجواب: إذا دعت الحاجةُ إلى هذا فلا بأس أن نفعله، ونفعل غيره من دون فائدةٍ؛ لأنَّ وضعها في غير ذلك خطرٌ، كوضعها في البيوت، أو عند إنسانٍ غير مأمون؛ ما يمكن. فوضعها في البنوك إذا دعت الحاجةُ إلى ذلك من دون فائدةٍ لا حرج فيه، وإن تيسَّر وضعها في مكانٍ آمنٍ أو بنك إسلامي وجب ذلك؛ لئلا يُساعد هؤلاء على رباهم، لكن إذا ما تيسرت الأمور ووضعها الإنسانُ في بنكٍ للحفظ لئلا تضيع عليه فهو معذورٌ للضَّرورة، والله يقول: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]، فالضَّرورات لها أحكامها، حتى الميتة تجوز عند الضَّرورة، والخنزير عند الضَّرورة، إذا اضطُرَّ إليه ولم يجد غيره. فالمقصود أنَّ هذه الأمانات والودائع في البنوك جائزة عند الضَّرورة، وإذا تيسَّر مكانٌ آخر انتقل إليه، مكان آمن، ليس ببنكٍ ربويٍّ.","link":"https://binbaz.org.sa/fatwas/30064/ما-حكم-ايداع-النقود-في-البنوك-كحساب-جار","audio":"https://files.zadapps.info/binbaz.org.sa/fatwa 85.mp3","categories":["الربا والصرف","البيوع"]},{"id":5172,"question":"هذا سؤال عن تبديل الأوراق المالية أو العملة الورقية بالعملة المعدنية، هل يجوز التَّفاضل فيه؟","title":"ما حكم التفاضل في تبديل العملة الورقية بالمعدنية؟","answer":"الجواب: ترك التفاضل أولى وأحوط، فكونه يأخذ عشرة بعشرة ومئة بمئة أحوط، وبعض أهل العلم جوَّز التفاضل؛ لأنهما مختلفتان، هذه من معدن، وهذه من ورق، ولكن الأحوط للمؤمن ترك ذلك؛ لأنها ريـال، كلها ريـال، كلها عملة واحدة، فإذا ترك التَّفاضل فهو أحوط.","link":"https://binbaz.org.sa/fatwas/30099/ما-حكم-التفاضل-في-تبديل-العملة-الورقية-بالمعدنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 124.mp3","categories":["الربا والصرف","البيوع"]},{"id":5236,"question":"ما حكم العمل في البنك بسبب الحاجة؟","title":"ما حكم العمل والإيداع في البنوك الربوية؟","answer":"الجواب: البنوك لا يجوز العمل فيها، بنوك الربا لا يجوز العمل فيها؛ لأنها تعاونٌ على الإثم والعدوان، فلا يجوز التَّعامل بها، الرسول لعن آكل الربا ومُوكله وكاتبه وشاهديه، وقال: هم سواء، فالكاتب للربا والشَّاهد عليه شريكٌ، والذي يُعينهم يكون محاسبًا أو يكون مُراسلًا أو يكون فرَّاشًا فيه إعانة لهم على بلائهم. س: والذي يُودع؟ الشيخ: ما ينبغي الإيداع، لكن إذا دعت الضَّرورة لا بأس، الضَّرورة أن يُودع خوفًا على ماله، ليس عنده مكانٌ آخر يُودع بدون فائدةٍ.","link":"https://binbaz.org.sa/fatwas/30578/ما-حكم-العمل-والايداع-في-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 39.mp3","categories":["الربا والصرف","البيوع"]},{"id":5517,"question":"يا شيخ، بالنسبة إذا عُلم أنَّ هذا التاجر رافضي، وأنَّ بضاعته معروفة عند الناس، يعني: بضاعة موجودة في الأسواق، هل يُحذر منه على أساس أنهم ما يشترون منه، ويقال للناس: لا تشتروا منه هذه البضاعة؛ حتى لا يدعمونه؟","title":"حكم معاملة المبتدع في البيع والشراء ونحوه","answer":"الجواب: هذا محل نظرٍ، الشراء والبيع من الكفرة جائز؛ النبي ﷺ اشترى من اليهود، ومات ودرعه مرهونة عند يهودي في طعامٍ لأهله عليه الصلاة والسلام، لكن يُبين له عقيدتهم؛ حتى لا يتَّخذهم أصحابًا ولا رُفقاء، أما كونه يشتري منهم إذا دعت الحاجةُ لشرائه؛ فالأمر سهل، لكن لا يُواليهم، ولا يأكل من ذبيحتهم، ولا طعامهم؛ فذبيحتهم محرَّمة. س: يا شيخ، يمكن أن يشتري من غيرهم؟ ج: أولى، لكن المقصود الحذر من المغالاة والمحبَّة، أو التَّساهل معهم، أو تمرير أعمالهم والتَّساهل فيها، ويُبين للناس كفرهم وضلالهم، وأنَّ هذه من أعمالهم: يسبُّون الصديق، ويسبون عمر، ويسبون الصحابة، ويستغيثون بأهل البيت، ويستغيثون بعليٍّ، هذا الشرك الأكبر، سبُّ الصحابة شرك مُستقل، معناه: تخوينهم، وأنهم ليسوا أهلًا ليُروى عنهم.","link":"https://binbaz.org.sa/fatwas/31450/حكم-معاملة-المبتدع-في-البيع-والشراء-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 032.mp3","categories":["الربا والصرف","البيوع"]},{"id":5596,"question":"هل البيع في غير يوم الجمعة جائز بين الأذان والإقامة؟","title":"حكم البيع بين الأذان والإقامة في غير الجمعة","answer":"الجواب: ينبغي تركه؛ لأنه قد يعوقه عن الصلاة، ولكن النص في الجمعة، ولكن غير الجمعة ينبغي أن يتركه؛ حتى لا يعوقه عن الصلاة، الأولى والأحوط له ترك ذلك، وإن كان النص في الجمعة، لكن الأحوط للمؤمن ترك ذلك، إذا نودي للصلاة: الظهر أو العصر أو المغرب أو العشاء؛ لأن الصلوات متقاربة في المعنى، كلها فريضة، كلها يجب السعي لها، فالنص على الجمعة يدل على عظم شأن الجمعة، ولكن لا يمنع من كون غيرها كذلك، كون المؤمن يتحرى فإذا أذَّن بادر هذا هو الأحوط للمؤمن.[1]","link":"https://binbaz.org.sa/fatwas/31560/حكم-البيع-بين-الاذان-والاقامة-في-غير-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 037.mp3","categories":["الربا والصرف","البيوع"]},{"id":5637,"question":"الذي يعمل في البنك هل هو ملعون؟","title":"من يعمل في البنك هل هو ملعون؟","answer":"الجواب: يدخل في هذا، آكِل الربا وموكله وكاتبه وشاهده، الكاتب والشاهد لأنهم مساعدون على الباطل، والله يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] هكذا الموظفون الآخرون. س: هذه من الكبائر؟ الشيخ: من الكبائر نعم، المعاصي التي يُلعن صاحبها من الكبائر، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31638/من-يعمل-في-البنك-هل-هو-ملعون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 006.mp3","categories":["الربا والصرف","البيوع"]},{"id":5855,"question":"رجل ساهم في  أرض بمبلغ من المال، وحيث إن الأرض قد بيعت وقد كسبت المساهمة، ولكن لحاجتي لمبلغ قد اضطريت إلى بيع المساهمة إلى شخص آخر بمكسب 40%، حيث إني محتاج، فهل بيعي له جائز، أم فيه شيء من الربا؟","title":"حكم من باع سهمه في أرض قد بيعت","answer":"الجواب: إذا ساهم في أرض، وهي للتجارة؛ وجب عليه أن يزكيها كل سنة على حسب ما تسوي الأرض، إذا زادت قيمتها؛ زكى الزيادة، وإذا صرف رأس مالها، ما زدات؛ يزكي رأس المال، وإن نقصت قيمتها، وكسدت؛ زكى قيمتها، ولو دون رأس المال كل سنة. أما البيع فله البيع، وإذا باع؛ يزكي ما مضى من السنين إن كان ما زكاها كل سنة بحسب قيمة الأرض، ولكن ليس له بيعها بعدما تباع إذا بيعت لا يبيع  ما عنده إلا دراهم، يبيع دراهم، ما يبيع دراهم، لكن البيع يكون قبل أن تباع، يبيعها على من يشاء، ويزكي السنوات الماضية إن كان ما زكاها كل سنة بحسبها، بحسب قيمتها، أما إذا كانت بيعت، ولكن مستعجل، باع حقه بالدراهم قبل أن تصفى؛ فهذا ما يجوز، لأن الذي ... الدراهم بعدما بيعت فلا يبيع الدراهم، بل يصبر حتى يعطى حقه. أما إن اشتراها لأجل يبني عليها بيتًا، أو يجعلها حوشًا له يطرح فيها حاجات له فما فيها زكاة.","link":"https://binbaz.org.sa/fatwas/1190/حكم-من-باع-سهمه-في-ارض-قد-بيعت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_186.mp3","categories":["البيوع"]},{"id":5860,"question":"رجل ساهم في  أرض بمبلغ من المال، وحيث إن الأرض قد بيعت وقد كسبت المساهمة، ولكن لحاجتي لمبلغ قد اضطريت إلى بيع المساهمة إلى شخص آخر بمكسب 40%، حيث إني محتاج، فهل بيعي له جائز، أم فيه شيء من الربا؟","title":"حكم من باع سهمه في أرض قد بيعت","answer":"الجواب: إذا ساهم في أرض، وهي للتجارة؛ وجب عليه أن يزكيها كل سنة على حسب ما تسوي الأرض، إذا زادت قيمتها؛ زكى الزيادة، وإذا صرف رأس مالها، ما زدات؛ يزكي رأس المال، وإن نقصت قيمتها، وكسدت؛ زكى قيمتها، ولو دون رأس المال كل سنة. أما البيع فله البيع، وإذا باع؛ يزكي ما مضى من السنين إن كان ما زكاها كل سنة بحسب قيمة الأرض، ولكن ليس له بيعها بعدما تباع إذا بيعت لا يبيع  ما عنده إلا دراهم، يبيع دراهم، ما يبيع دراهم، لكن البيع يكون قبل أن تباع، يبيعها على من يشاء، ويزكي السنوات الماضية إن كان ما زكاها كل سنة بحسبها، بحسب قيمتها، أما إذا كانت بيعت، ولكن مستعجل، باع حقه بالدراهم قبل أن تصفى؛ فهذا ما يجوز، لأن الذي ... الدراهم بعدما بيعت فلا يبيع الدراهم، بل يصبر حتى يعطى حقه. أما إن اشتراها لأجل يبني عليها بيتًا، أو يجعلها حوشًا له يطرح فيها حاجات له فما فيها زكاة.","link":"https://binbaz.org.sa/fatwas/1190/حكم-من-باع-سهمه-في-ارض-قد-بيعت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_186.mp3","categories":["البيوع"]},{"id":6038,"question":"فضيلة الشيخ، كما تعلمون الاختلاف في الفتيا في بيع التقسيط، لكن هناك قول لابن عباس أورده ابن تيمية في الفتاوى، ومفاده: أنه إذا قومت السلعة، فبيعت في الحال؛ فليس هناك بأس، لكن إذا أجلت، فيعتبر غير جائز، فما هو رأيكم؟","title":"هل البيع بالتقسيط فيه خلاف؟","answer":"الجواب: الصواب: أن بيع التقسيط ليس فيه خلاف، إذا باع سلعة بأقساط إلى آجال معلومة ليس في هذا خلاف، وقد باع أصحاب بريرة بريرة، باعوها بأقساط في عهد النبي ﷺ فأقرهم، باعوها بثمن مقسط على عشر سنين، كل سنة أربعين درهمًا، يعني أوقية، أوقية كل سنة، وهي أربعون درهمًا، وما أنكر النبي عليهم بيعها بالتقسيط، فالبيع بالتقسيط .. للتجارة عشرين ألفًا كل سنة، أو كل شهر ألفًا، أو كل شهر مائة؛ لا حرج في ذلك إذا كان أقساطًا معلومة. لكن بعض أهل العلم قال: إذا قوَّمها، قال: تساوي كذا ألفًا نقدًا، وبألف ومائة إلى أجل، أن هذا يشبه الربا، ولكن الصحيح أن هذا ليس ربا، وليس فيه شيء؛ لأنه يقول له: إن كنت تشتريها الآن بالنقد؛ فالثمن كذا، وإن كنت تشتريها بالآجل؛ فالثمن كذا، فإذا قطعه على شيء معلوم، قطعه بالمعجل؛ فلا بأس، أو قطعه بالمؤجل؛ فلا بأس، لكن لا يتفرقان إلا وقد قطعا على شيء معلوم؛ فلا بأس في ذلك.","link":"https://binbaz.org.sa/fatwas/1455/هل-البيع-بالتقسيط-فيه-خلاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_384.mp3","categories":["البيوع"]},{"id":6069,"question":"هل يجوز ربا النسيئة ببيع لحم بحيوان من غير جنسه؟","title":"حكم بيع اللحم بحيوان غيره نسيئة","answer":"الجواب: لا بأس؛ بيع اللحم بحيوان لا بأس، هذا مستقل، حيوان مستقل، ما يجري فيه الربا مع شيء آخر، فإذا اشترى خروفًا بشيء من الإبل، أو بشيء من لحم الغنم، أو البقر؛ فلا بأس، لا يدخل في الربا.","link":"https://binbaz.org.sa/fatwas/1480/حكم-بيع-اللحم-بحيوان-غيره-نسيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_410.mp3","categories":["البيوع"]},{"id":6071,"question":"ما حكم رجل يصيد النمور، ويبيع جلودها، فيأكل من ثمنها؟ فإذا كان حرامًا، فماذا يفعل فيما مضى؟","title":"حكم بيع جلود النمور بعد صيدها","answer":"الجواب: النبي ﷺ نهى عن جلود السباع، والنمر من السباع، والذي يظهر: أن عليه التوبة من ذلك، فمن تاب؛ تاب الله عليه، الله قال في الربا: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ [البقرة:275] فإذا تاب عما مضى نرجو أن الله يعفو عنه، ولا يلزمه أن يحاسب نفسه عما مضى، وعما دخل إليه من هذه الأشياء، بل يعفو الله عنه -إن شاء الله- وإن أحب أن يخرج من ماله ما يظنه ... ما دخل عليه من باب الورع، ومن باب الإحسان إلى الفقراء، أو إلى المشاريع الخيرية؛ فطيب. أما الوجوب، فالظاهر -والله أعلم- لا يلزمه شيء؛ لأنه فعله عن جهالة، وعن قلة علم، فلما جاءه العلم؛ انتهى، وتاب، والحمد لله.","link":"https://binbaz.org.sa/fatwas/1482/حكم-بيع-جلود-النمور-بعد-صيدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_412.mp3","categories":["البيوع"]},{"id":6157,"question":"رجل أراد شراء منزل، وليس عنده مال كاف للشراء، فذهب ليستلف، فقيل له: نحن لا نسلف، بل نشتري المنزل، ثم تسدد لنا على أقساط، مع زيادة في الثمن، فمثلًا يكلف شراء المنزل أربعين، وتسدد لنا خمسة وأربعين، وقالوا: هذا نظير المدة التي عطلت فيها أموالنا؟","title":"حكم البيع بالتقسيط مع زيادة الثمن؟","answer":"الجواب:  ما في بأس، إذا باعوا عليه سلعة بزيادة، لا بأس، هذا بيع إلى أجل، إذا اشتروا البيت، ثم باعوه عليه بثمن معلوم إلى أجل معلوم، دفعة واحدة، أو بأقساط، فهو صحيح، وقد نص عليه أهل العلم، فإذا اشترى التاجر البيت بأربعين ألفًا، وباعه على المحتاج إليه بخمسة وأربعين ألفًا، أو بخمسين ألفًا إلى آجال، أو إلى أجل واحد؛ فلا حرج في ذلك، أو باع عليه أكياس من السكر، أو أكياس من الطعام إلى أجل معلوم؛ فلا بأس. السؤال:...؟ الجواب: لا حرج إذا اشتروا البيت له على حسابهم، ثم باعوا عليه؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1602/حكم-البيع-بالتقسيط-مع-زيادة-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_496.mp3","categories":["البيوع"]},{"id":6213,"question":"طلبت من أحد التجار ديانة بخمسة وعشرين ألف ريالًا، وذهبنا للسوق، واشترى بضاعة بعشرين ألف ريال، وقلبها عليّ بخمسة وعشرين ألف ريال بدون سابق شرط بيننا، فما حكم ذلك؟","title":"مسألة التورق وحكمها","answer":"الجواب: هذا فيه تفصيل، والناس يتساهلون فيه، يسمونه الوعدة إذا اتفق إنسان مع آخر أنه يشتري له سكر، أو أكياس، أو سيارات، ثم يبيعها عليه؛ فلا بأس، بشرط أن الأول الذي باع يملكها، يملك الأكياس، يحوزها إلى بيته، يحوزها إلى دكانه، يحوز السيارة إليه، يملكها، ثم يبيعها بعد ذلك على الراغب إلى أجل معلوم بربح معلوم؛ لا بأس، أما أن يبيعها عليه وهو ما ملكها من التجار ما يجوز هذا؛ لأنه بيع ما لا يملك، النبي ﷺ قال: لا تبع ما ليس عندك فليس له أن يبيع ما ليس عنده.  وكذلك الذي اشتراها لا يجوز أن يبيعها، ويعيد البائع في ملكه، في دكانه لا، حتى يقبضها، ويحوزها، النبي ﷺ نهى أن تباع السلع حيث ابتاعت، حتى يحوزها التجار إلى رحالهم، فالذي يبيع أولاً، لا بدّ أن يكون قد حاز المال، وعنده المال، وإن كان قد اتفقا سابقًا على البيع المعلوم؛ فلا بدّ أن يكون ملك هذا الشيء، وحازه، ثم يبيعه على الراغب بأجل معلوم، وربح معلوم، والذي يشتريه بعد ذلك ليس له أن يبيعه في محله حتى ينقله إلى السوق، أو إلى بيته، أو إلى دكانه، ثم يتصرف بعد ذلك. السؤال: إذا حاز السلعة، ولكن النية ليست السلعة بحد ذاتها، ولكن النية أن يأخذ مبلغاً من المال، فهل يجوز ذلك؟ الجواب: ولو؛ لأن هذه الوعدة يريد من هذه السلعة أن يبيعها حتى يتزوج، أو حتى يقضي دينه، أو يبني عمارة، ويتحاشى الربا، يخشى أن يذهب إلى البنوك، فيقع في الربا، فهذا مما يسلمه من الربا، ومن المداينات الشرعية، والبيوع الشرعية، ولو كان قصده بيع السلعة، التجار كثير منهم يشتري السلع ليبيعها، ما قصده أن يقتنيها، ولا أن يأخذها، ولا أن يلبسها، فهكذا المحتاج يتزوج، يشتري السيارة ليبيعها، ويستعين بثمنها على الزواج، يشتري السكر، أو الأرز، أو كذا، أو كذا ليبيعه، ويقضي دينه، عنده غرماء، آذوه يشتري من هذا ليبيعه، ويقضي دينه، ليعمر بيته ليتزوج؛ فلا حرج في هذا على الصحيح، فيه خلاف، لكن هذا هو الأصح.","link":"https://binbaz.org.sa/fatwas/1711/مسالة-التورق-وحكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_566.mp3","categories":["البيوع"]},{"id":6233,"question":"وسائل يسأل فيقول: أنا رجل أبيع، وأشتري في الدخان، وكل دخلي تقريبًا من الدخان، فهل يجوز لي الطعام، والشراب، والحج، والزكاة، والصدقة، وكل أعمال الخير؟ وأرجو من فضيلتكم أن توضحوا لي هل لي أجر فيما قدمت من أعمال الخير، أم لا؟","title":"حكم التجارة في الدخان","answer":"الجواب:  هذا يا أخي من البلاء العظيم، كونك تتجر بالدخان، وغالب دخلك من الدخان هذا من البلاء؛ فعليك أن تبادر بالتوبة، وأن تقلع عن هذا البلاء، وأن تسأل ربك العافية منه، وأن تسلك مسلكًا آخر من التصرف المالي، والله وسع ويسر. أما الدخان فقد قرر أهل العلم -المعروفون- والبصائر قرروا بتحريمه، وشره العظيم، وأنه يسبب مشاكل كثيرة، ومضار عظيمة، وأنه بهذا محرم لا تجوز التجارة فيه، لا بيعًا، ولا شراءً، وأن الواجب الحذر منه، وعدم استيراده، وعدم الأكل من ثمنه، فما حصل لك من هذا الباب ينبغي أن تصرفه في وجوه البر، وإن كان ما عندك شيء يقوم بحالك؛ أبقيت عندك منه ما تحتاج إليه، ويقوم بحالك، حتى يغنيك الله من فضله بالطرق المباحة، وما زاد على ذلك من هذا الثمن الخبيث من طريق الدخان؛ يصرف في وجوه الخير، للتخفيف من شره، ونفع المسلمين به في مساعدة فقير، ومساعدة غريم، وإصلاح دورات المياه، وأشباه ذلك من الطرق الخيرية؛ حتى تسلم من شره -إن شاء الله- ونرجو أن لا حرج عليك فيما مضى، فالتوبة تجب ما قبلها، ومن تاب؛ تاب الله عليه . السؤال: يقول: وهل هذا يدخل في حديث من غشنا فليس منا؟ الجواب: هذا قد يكون نوعًا من الغش لبيعه على الناس، فالغش يكون بالسر، ويكون بالإخفاء، وأما الدخان بيعه ظاهر، ما هو غش؛ لكنه غش من جهة تمكين الإنسان مما يضره، ويحسب أنه جيد، وأنه نافع، وأنت تمكنه ما يضره إن بيعت عليه الدخان، وتمكينه من الدخان وهو يضره، وقد يظن أنه لا يضره بسبب أنك تبيعه عليه، وربما اعتقد فيك أنك جيد، وأنك لا تبيع ما يضر الناس، فهو نوع من الغش من  هذا  الباب. فالواجب الحذر منه، وأن تتوب إلى الله من ذلك، وأن تبعد ما عندك، وتحرق ما عندك من الدخان، وتستجيب لداعي الله .","link":"https://binbaz.org.sa/fatwas/1757/حكم-التجارة-في-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_596.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6254,"question":"وآخر أرسل إلينا سؤالاً بخط ركيك نحاول قراءته على علته، فيقول: سمعت يوم عرفة محدثًا يقول: العيد أربعة أيام، مثل عدد الرمي، أن الرمي أربعة أيام، فيقول العيد أربعة أيام كذلك، وسمعه يقول: من تعجل؛ فيرمي أربعة بحجر اليوم الثاني عشر مع الحادي عشر، يعني يرمي يوم حادي عشر، ثم يرمي يوم الثاني عشر؟","title":"بيان عدد أيام عيد الأضحى والتعجيل للحاج فيها","answer":"الجواب: هذا كلام معقول، معناه أن أيام العيد التي هي أيام الذبح، وتسمى أيام العيد أربعة، يوم العيد، وثلاثة أيام بعده، وكلها فيها رمي يوم العيد، يرمي جمرة العقبة، والحادي عشر، يرمي الجمرات الثلاث، والثاني عشر، يرمي الجمرات الثلاث، وهكذا الثالث عشر فيمن لم يتعجل، فيرمي الجمرات الثلاث، فهي كلها أيام عيد، كلها أيام رمي، كلها أيام ذبح، كلها أيام أكل، وشرب، وذكر لله .  فإذا رمى يوم العيد، ورمى اليوم الحادي عشر الجمار الثلاث بعد الزوال، ورمى الثاني عشر بعد الزوال، الجمار الثلاث؛ فله التعجل قبل غروب الشمس، له أن يتعجل من منى إلى مكة قبل غروب الشمس، ويعود إلى وطنه إذا شاء؛ فلا بأس في ذلك، يتعجل، ولا شيء عليه، وإن بات ليلة الثالث عشر، ورمى يوم الثالث عشر؛ فهو أفضل؛ لأن الرسول -عليه الصلاة والسلام- بات، ورمى في اليوم الثالث عشر، هذا هو الأفضل؛ لما فيه من زيادة العمل، والتأسي بالنبي -عليه الصلاة والسلام- وإن تعجل بعد الزوال، وبعد الرمي في اليوم الثاني عشر؛ فلا بأس عليه. وله أن يقيم في مكة ما شاء، فإذا أراد السفر؛ طاف للوداع بعد ذلك، وإن تعجل في الحال، وسافر بعد الوداع بعدما رمى يوم الثاني عشر، مر إلى مكة، وطاف الوداع، ومشى، وسافر؛ فلا بأس. ولكن بعض الناس قد يغلط، ويعد يوم العيد هو اليوم الأول من أيام التشريق، وإذا رمى يوم الحادي عشر؛ تعجل، وهذا غلط يوم العيد، ليس من أيام التشريق المذكورة في قوله -جل وعلا-: وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى [البقرة:203] هذه الأيام غير يوم العيد، هي الحادي عشر، والثاني عشر، والثالث عشر، فالتعجل في يومين معناه الثاني عشر، ويوم العيد، لا يعد منها.  فينبغي أن يفهم هذا الأيام الثلاثة، هي: الحادي عشر، والثاني عشر، والثالث عشر، والتعجل يكون في الثاني عشر، والتريث يكون إلى الثالث عشر، ولا يجوز الرمي إلا بعد الزوال في هذه الثلاثة أيام، كله بعد الزوال، والتعجل يكون من بعد رمي الجمار، وبعد زوال الشمس، يرميها بعد الزوال، ثم يتعجل إلى مكة، فيطوف طواف الوداع، ثم يسافر إذا شاء، وإن بقي في مكة؛ فيبقى حتى يعزم على السفر، فإذا عزم على السفر؛ طاف للوداع.","link":"https://binbaz.org.sa/fatwas/1775/بيان-عدد-ايام-عيد-الاضحى-والتعجيل-للحاج-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_614.mp3","categories":["مسائل متفرقة في الحج والعمرة","البيوع","الأخلاق المذمومة"]},{"id":6263,"question":"وآخر أرسل إلينا سؤالاً بخط ركيك نحاول قراءته على علته، فيقول: سمعت يوم عرفة محدثًا يقول: العيد أربعة أيام، مثل عدد الرمي، أن الرمي أربعة أيام، فيقول العيد أربعة أيام كذلك، وسمعه يقول: من تعجل؛ فيرمي أربعة بحجر اليوم الثاني عشر مع الحادي عشر، يعني يرمي يوم حادي عشر، ثم يرمي يوم الثاني عشر؟","title":"بيان عدد أيام عيد الأضحى والتعجيل للحاج فيها","answer":"الجواب: هذا كلام معقول، معناه أن أيام العيد التي هي أيام الذبح، وتسمى أيام العيد أربعة، يوم العيد، وثلاثة أيام بعده، وكلها فيها رمي يوم العيد، يرمي جمرة العقبة، والحادي عشر، يرمي الجمرات الثلاث، والثاني عشر، يرمي الجمرات الثلاث، وهكذا الثالث عشر فيمن لم يتعجل، فيرمي الجمرات الثلاث، فهي كلها أيام عيد، كلها أيام رمي، كلها أيام ذبح، كلها أيام أكل، وشرب، وذكر لله .  فإذا رمى يوم العيد، ورمى اليوم الحادي عشر الجمار الثلاث بعد الزوال، ورمى الثاني عشر بعد الزوال، الجمار الثلاث؛ فله التعجل قبل غروب الشمس، له أن يتعجل من منى إلى مكة قبل غروب الشمس، ويعود إلى وطنه إذا شاء؛ فلا بأس في ذلك، يتعجل، ولا شيء عليه، وإن بات ليلة الثالث عشر، ورمى يوم الثالث عشر؛ فهو أفضل؛ لأن الرسول -عليه الصلاة والسلام- بات، ورمى في اليوم الثالث عشر، هذا هو الأفضل؛ لما فيه من زيادة العمل، والتأسي بالنبي -عليه الصلاة والسلام- وإن تعجل بعد الزوال، وبعد الرمي في اليوم الثاني عشر؛ فلا بأس عليه. وله أن يقيم في مكة ما شاء، فإذا أراد السفر؛ طاف للوداع بعد ذلك، وإن تعجل في الحال، وسافر بعد الوداع بعدما رمى يوم الثاني عشر، مر إلى مكة، وطاف الوداع، ومشى، وسافر؛ فلا بأس. ولكن بعض الناس قد يغلط، ويعد يوم العيد هو اليوم الأول من أيام التشريق، وإذا رمى يوم الحادي عشر؛ تعجل، وهذا غلط يوم العيد، ليس من أيام التشريق المذكورة في قوله -جل وعلا-: وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى [البقرة:203] هذه الأيام غير يوم العيد، هي الحادي عشر، والثاني عشر، والثالث عشر، فالتعجل في يومين معناه الثاني عشر، ويوم العيد، لا يعد منها.  فينبغي أن يفهم هذا الأيام الثلاثة، هي: الحادي عشر، والثاني عشر، والثالث عشر، والتعجل يكون في الثاني عشر، والتريث يكون إلى الثالث عشر، ولا يجوز الرمي إلا بعد الزوال في هذه الثلاثة أيام، كله بعد الزوال، والتعجل يكون من بعد رمي الجمار، وبعد زوال الشمس، يرميها بعد الزوال، ثم يتعجل إلى مكة، فيطوف طواف الوداع، ثم يسافر إذا شاء، وإن بقي في مكة؛ فيبقى حتى يعزم على السفر، فإذا عزم على السفر؛ طاف للوداع.","link":"https://binbaz.org.sa/fatwas/1775/بيان-عدد-ايام-عيد-الاضحى-والتعجيل-للحاج-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_614.mp3","categories":["مسائل متفرقة في الحج والعمرة","البيوع","الأخلاق المذمومة"]},{"id":6307,"question":"وآخر يسأل فيقول: لي عيال يشتغلون في القرصان، وهم مشاركون، ويجعلون في الكرتونة خمسة وثلاثين قرصًا، فإذا جاء المشتري قالوا: إن فيها خمسين، وهكذا كل أصحاب القرصان، فما رأي سماحتكم في ذلك؟","title":"حكم الغش في البيع","answer":"الجواب: هذا من الغش، والخيانة، والكذب، الذي حط في الكرتون خمس وثلاثين، ويقول للمشتري: فيه خمسون، أو فيه أربعون، هذا حرام، ومنكر، ويجب عليه أن يتوب إلى الله، وأن يتصدق بما يقابل ذلك، مما أخذ من أموال الناس؛ لأن هذا غش، والواجب أنه يقول: ما في الكرتون سواء، إذا كان في الكرتون عشرة يقول: عشرة، وإذا أربعين يقول: أربعين، لا يزيد، هذا هو الواجب عليه.  فإذا زاد؛ فقد كذب، وأخطأ، وغش المسلمين؛ فعليه التوبة إلى الله، وعليه رد الزيادة إلى صاحبها إن كان يعرفه، وإن كان ما يعرفه؛ يتصدق بالزيادة التي أخذها بغير حق، وفق الله الجميع، وصلى الله وسلم على نبينا محمد، وعلى آله، وأصحابه.","link":"https://binbaz.org.sa/fatwas/1882/حكم-الغش-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_667.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6316,"question":"هناك نوعان من البيع والشراء تشكك الناس اليوم في صحتهما، نرجو توضيح الحكم فيهما، جزاكم الله خير الجزاء، أولاً: ما يجري الآن في سوق الجفرة بالرياض الذي لا يخفى على أحد من الاقتراض بزيادة، ثانيًا: التجارة الحديثة في البورصات الدولية، لاسيما وقد كثر المتعاملون فيها هذه الأيام من خلال البنوك الدولية المفتوحة حديثًا في المملكة.","title":"حكم الاقتراض بزيادة والتعامل في البورصة","answer":"الجواب: أما القرض بزيادة فهذا لا يجوز، كونه يقول: أعطني خمسة، وأعطيك ستة سبعة، أو أقرضني ألفًا، وأعطيك ألفًا، وعشرين، أو ألفًا، وثلاثين، أو ألفًا، وأربعين، كما تفعل البنوك، وغير البنوك، هذا منكر، وهذا من الربا المحرم بلا شك، كونه يقترض مالًا بالزيادة، ولو قليلة، فهذا لا يجوز. وله حيلة، وطريقة شرعية -بحمد الله- تغنيه عن هذا، يشتري إذا كان مضطرًا، يشتري سلعة إلى أجل، ويبيعها على اختياره، يشتري السلعة من زيد، أو عمرو من التاجر، ويقبضها، ويحوزها، ثم يتصرف فيها على مهله، يبيعها على مهلة بالنقد، ويقضي حاجته. وبعض الناس في هذا يغلط أيضًا، يشتري من إنسان ما عنده سلعة، يشتري منه، ثم يروح يشتريها من الثاني، لا، لا تشتري سلعة إلا وهي مملوكة لمن باعها، قد حازها في دكانه، في بيته، ثم يبيع عليك، ثم أنت إذا اشتريتها تحوزها أيضًا، وتنقلها إلى بيتك، أو إلى السوق، ثم تبيعها بعد ذلك على من يسر الله، وتقضي حاجتك، والزيادة التي عليك بالأجل سوف يسهل الله -جل وعلا- النبي ﷺ يقول: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه.  ومن استدان لقصد حاجة للزواج، أو لقضاء دين، أو للإنفاق على عياله سوف يقضي الله عنه إذا صلحت نيته، سوف يقضي الله عنه، ويوفي عنه، والله أباح المداينة  إلى أجل، فلا بأس أن تستدين من إنسان عنده المال، في حوزته المال، تشتري منه المال بحوزته، ثم تنقله، وتقبضه ثم تبيع على مهلك، تبيع المال مرة واحدة، أو أجزاء تبيع، وتقضي حاجاتك، أما أن تقترض من البنك، أوغير البنك بالربا، الألف بألف بخمسمائة ألف ومائة، المائة ألف بمائة ألف وخمسة آلاف زيادة، كل هذا ربا لا يجوز، ولو مائة بمائة ونصف ريال، ما يجوز الزيادة، لا تصلح. وأما البورصة فقد بلغنا عنها أنها بيع في الهواء، بيع لا فيه قبض، ولا فيه شيء، فهو منكر، ومحرم، يتبايعون بالمكاتبات، ويبيع بجميع أنواع المكاتبات، من برقية، ومن لبس، ومن غير ذلك، أموال لا قبضوها، وهذا يبيع، وهذا يبيع، وهي موجودة عند أهلها، هذا منكر، وهي بيوعات باطلة، لا تصلح، لكن حب المال، وكثرة المال بين الناس ما وجدوا له مكانًا إلا هذا التصرف، نسأل الله السلامة!.","link":"https://binbaz.org.sa/fatwas/1873/حكم-الاقتراض-بزيادة-والتعامل-في-البورصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_662.mp3","categories":["الربا والصرف","البيوع","الآداب والأخلاق"]},{"id":6328,"question":"وآخر يسأل فيقول: لي عيال يشتغلون في القرصان، وهم مشاركون، ويجعلون في الكرتونة خمسة وثلاثين قرصًا، فإذا جاء المشتري قالوا: إن فيها خمسين، وهكذا كل أصحاب القرصان، فما رأي سماحتكم في ذلك؟","title":"حكم الغش في البيع","answer":"الجواب: هذا من الغش، والخيانة، والكذب، الذي حط في الكرتون خمس وثلاثين، ويقول للمشتري: فيه خمسون، أو فيه أربعون، هذا حرام، ومنكر، ويجب عليه أن يتوب إلى الله، وأن يتصدق بما يقابل ذلك، مما أخذ من أموال الناس؛ لأن هذا غش، والواجب أنه يقول: ما في الكرتون سواء، إذا كان في الكرتون عشرة يقول: عشرة، وإذا أربعين يقول: أربعين، لا يزيد، هذا هو الواجب عليه.  فإذا زاد؛ فقد كذب، وأخطأ، وغش المسلمين؛ فعليه التوبة إلى الله، وعليه رد الزيادة إلى صاحبها إن كان يعرفه، وإن كان ما يعرفه؛ يتصدق بالزيادة التي أخذها بغير حق، وفق الله الجميع، وصلى الله وسلم على نبينا محمد، وعلى آله، وأصحابه.","link":"https://binbaz.org.sa/fatwas/1882/حكم-الغش-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_667.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6351,"question":"إذا غصب أحد مال أخيه بغير حق، فكيف لصاحب الحق أن يستعيد ماله؟ أو كيف نوفق بين قوله ﷺ: أد الأمانة إلى من ائتمنك، ولا تخن من خانك وبين قوله تعالى: وَجَزَاء سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا [الشورى:40] وقوله : وَإِنْ عَاقَبْتُمْ فَعَاقِبُواْ بِمِثْلِ مَا عُوقِبْتُم بِهِ [النحل:126]؟","title":"كيفية استرجاع المال المغصوب","answer":"الجواب: إذا غصب أحد منك مالاً، فإن قدرت على أن تأخذ حقك منه من دون فتنة، ولا شر يتعدى على الناس، ولا يقع منك شر؛ فخذ مالك، والحمد لله، أما إذا كنت لا تستطيع إلا بالله، ثم بالدولة، فتستعين بالله، ثم بالدولة، ترفعه إلى المحكمة، إلى إمارة البلد؛ حتى يعطيك حقك، وتقيم الشهود الذين عندك على أنه غصبك هذا المال.  أما إن كان يمكنك أخذ المال من مال عندك له، أمانة عندك له، تأخذ حقك منه؛ فلا بأس، تأخذ حقك، وتقول: هذا حقي قد غصبتني هذا الشيء، وهذا الباقي عندي لك، غصبني مائة بغير حق، أخذت مائتي، وهذا باقي مالك، وإذا قال خاصمني، أو الدعوى ترفع في المحكمة، والمحكمة تنظر في أمركما.","link":"https://binbaz.org.sa/fatwas/1923/كيفية-استرجاع-المال-المغصوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_708.mp3","categories":["الغصب","البيوع"]},{"id":6356,"question":"لي مال في بنك ما، هل يجوز لي أن أتفق مع البنك، أن أجعل هذا المال مضاربة بيني  وبينه؛ ليكون لي نصف الربح، وله نصفه، ولو خسر أيضاً فالخسارة مناصفة، فماذا يكون الحل، والحرفة في ذلك؟","title":"ضوابط المضاربة بين العامل وصاحب المال","answer":"الجواب: المضاربة ما على العامل خسارة، المضاربة العامل شريك في الربح، والخسارة على رب المال؛ لأنه أمانة في يد العامل، إذا كان العامل ما فرط، ولا قصر؛ فالخسارة على رب المال، والربح مشترك بالنصف، أو بالربع، أو بالثلث إذا كان في سلعة معلومة، إذا كان في البنك سلع معلومة يحطها في سيارات خاصة، يحطها في بيوت، في مزارع، بالنصف، بالثلث، بالربع. هذه مضاربة عليه أن يتقي الله فيها، وأن يعتني بها، وأن لا يقصر فيها، وأن يحفظها، فإذا جاء ربح؛ فهو بينهما على الشرط، وإن ما جاء ربح؛ فالخسارة على صاحب المال، هذا إذا كان متحدًا، ولكن أهل البنوك، وأهل الربا لا يؤمنون، قد يخلطونها بغيرها، فينبغي له أن يكون هذا مع غير المرابي، مع غير البنوك المرابية، مع أشخاص سليمين؛ حتى يأمن على ماله أنه لم يعن به من يرابي.  السؤال: طيب لو هو اتفق مع البنك على الخسارة؟ الجواب: لا يصح شرط يخالف.","link":"https://binbaz.org.sa/fatwas/1935/ضوابط-المضاربة-بين-العامل-وصاحب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_720.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6370,"question":"إذا غصب أحد مال أخيه بغير حق، فكيف لصاحب الحق أن يستعيد ماله؟ أو كيف نوفق بين قوله ﷺ: أد الأمانة إلى من ائتمنك، ولا تخن من خانك وبين قوله تعالى: وَجَزَاء سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا [الشورى:40] وقوله : وَإِنْ عَاقَبْتُمْ فَعَاقِبُواْ بِمِثْلِ مَا عُوقِبْتُم بِهِ [النحل:126]؟","title":"كيفية استرجاع المال المغصوب","answer":"الجواب: إذا غصب أحد منك مالاً، فإن قدرت على أن تأخذ حقك منه من دون فتنة، ولا شر يتعدى على الناس، ولا يقع منك شر؛ فخذ مالك، والحمد لله، أما إذا كنت لا تستطيع إلا بالله، ثم بالدولة، فتستعين بالله، ثم بالدولة، ترفعه إلى المحكمة، إلى إمارة البلد؛ حتى يعطيك حقك، وتقيم الشهود الذين عندك على أنه غصبك هذا المال.  أما إن كان يمكنك أخذ المال من مال عندك له، أمانة عندك له، تأخذ حقك منه؛ فلا بأس، تأخذ حقك، وتقول: هذا حقي قد غصبتني هذا الشيء، وهذا الباقي عندي لك، غصبني مائة بغير حق، أخذت مائتي، وهذا باقي مالك، وإذا قال خاصمني، أو الدعوى ترفع في المحكمة، والمحكمة تنظر في أمركما.","link":"https://binbaz.org.sa/fatwas/1923/كيفية-استرجاع-المال-المغصوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_708.mp3","categories":["الغصب","البيوع"]},{"id":6374,"question":"أنا اشتريت لي عشر سيارات من معرض، وخليتها في المعرض، ما حركت منها شيئًا، وسلمت فلوسها، ولم أحيلها باسمي بالمرة، وكلما حصلت لي رجل دينت عليه السيارة، وهي بمكانها، ما حركت شيئًا منها، لا حركتها، دفعت المبلغ فقط، كيف هذا البيع، وهذا الشراء؟","title":"بيع ما تم شراؤه دون نقله من مكان الشراء","answer":"الجواب:  ينبغي أنك تنقلها من محل البيع إلى محل آخر، إلى معرض آخر، النبي ﷺ نهى أن تباع السلع حيث ابتاعت حتى يحوزها التجار إلى رحالهم.  فلا ينبغي أن تبيعها وهي في المعرض الذي اشتريتها منه، بل تنقلها إلى معرض آخر، أو إلى بيتك، أو إلى سوق من سوق المسلمين آخر، ولا تبعها وهي في محلها؛ عملاً بقول النبي ﷺ وعملاً بتوجيهه -عليه الصلاة والسلام- في عدم بيع السلع في محلها.  السؤال: ولكني مشترط عليه أنها تبقى حتى أنهيا من المحل هذا؟ الجواب: تبقى حتى تنقلها إلى معرض آخر.","link":"https://binbaz.org.sa/fatwas/1954/بيع-ما-تم-شراوه-دون-نقله-من-مكان-الشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_741.mp3","categories":["البيوع"]},{"id":6384,"question":"أنا اشتريت لي عشر سيارات من معرض، وخليتها في المعرض، ما حركت منها شيئًا، وسلمت فلوسها، ولم أحيلها باسمي بالمرة، وكلما حصلت لي رجل دينت عليه السيارة، وهي بمكانها، ما حركت شيئًا منها، لا حركتها، دفعت المبلغ فقط، كيف هذا البيع، وهذا الشراء؟","title":"بيع ما تم شراؤه دون نقله من مكان الشراء","answer":"الجواب:  ينبغي أنك تنقلها من محل البيع إلى محل آخر، إلى معرض آخر، النبي ﷺ نهى أن تباع السلع حيث ابتاعت حتى يحوزها التجار إلى رحالهم.  فلا ينبغي أن تبيعها وهي في المعرض الذي اشتريتها منه، بل تنقلها إلى معرض آخر، أو إلى بيتك، أو إلى سوق من سوق المسلمين آخر، ولا تبعها وهي في محلها؛ عملاً بقول النبي ﷺ وعملاً بتوجيهه -عليه الصلاة والسلام- في عدم بيع السلع في محلها.  السؤال: ولكني مشترط عليه أنها تبقى حتى أنهيا من المحل هذا؟ الجواب: تبقى حتى تنقلها إلى معرض آخر.","link":"https://binbaz.org.sa/fatwas/1954/بيع-ما-تم-شراوه-دون-نقله-من-مكان-الشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_741.mp3","categories":["البيوع"]},{"id":6430,"question":"ما رأي سماحتكم في بيع ريال الفضة باثني عشر ريال ورق كما هو الحال في السوق الآن؟","title":"حكم بيع ريال فضة باثني عشر ريال ورق","answer":"الجواب:  لا نعلم شيئًا في هذا؛ لأن الريال الفضة غير الريال السعودي، فهو مختلف، هذا ورق، وهذه فضة، مختلف، لكن يدًا بيد.","link":"https://binbaz.org.sa/fatwas/2146/حكم-بيع-ريال-فضة-باثني-عشر-ريال-ورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_794.mp3","categories":["البيوع"]},{"id":6431,"question":"إذا كان الاحتكار في أوقات ليس الناس بحاجة إلى المحتكر، ولكن البائع يتوقع ارتفاع الأسعار، فهل هذا جائز؟","title":"حكم من احتكر سلعة ليس في احتكارها مشقة على الناس","answer":"الجواب: النبي ﷺ قال: لا يحتكر إلا خاطئ ومن احتكر؛ فقد خطئ، فهذا الاحتكار محرم، ولكن بين العلماء محل الاحتكار، وأنه في الأوقات التي فيها مشقة على الناس، الطعام فيها غال مثلًا، فيشتريه ليبيعه بأغلى، هذا لا يجوز، هذا يضر بالناس.  أما في أوقات السعة، ووجود الخير الكثير، والأموال الواسعة، وإذا اشترى ما يؤثر على السوق، ولا يسبب زيادة على الناس، فإذا اشترى شيئًا، وادخره ليبيعه في وقت آخر؛ ليربح فيه؛ فهذا شأن التجارة، يشتري هذا، ويبيع هذا، ويدخر هذا، فإذا كان ما في مشقة؛ لا يسمى احتكارًا. كذلك إذا قبضه من المزارع، حبوبًا من المزارع، وأبقاه عنده إلى وقت يرجو أن يكون بيعها فيه أنفع له، وأغلى؛ لأن الوقت الآن كاسد، والطعام رخيص، فحفظ إنتاج مزرعته من الحبوب، والتمور إلى وقت آخر؛ لا يسمى احتكارًا.","link":"https://binbaz.org.sa/fatwas/2140/حكم-من-احتكر-سلعة-ليس-في-احتكارها-مشقة-على-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_789.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6433,"question":"هل وضع الرجل الذي من البادية سيارته في المعرض سمسرة ليبيعها صاحب المعرض له، هل هذا من بيع الحاضر للبادي، أم أنه من الوكالة؟ وكيف يكون بيع الحاضر للباد محرمًا إذا كان الناس الآن يأتون من البادية، ويضعون سياراتهم في المعارض، وهم مضطرون لذلك؟","title":"حكم وضع صاحب البادية سيارته في المعرض لغرض البيع","answer":"الجواب: ثبت عنه -عليه الصلاة والسلام- أنه نهى أن يبيع حاضر لباد، وهذا ثابت في الصحيحين، وفي غير الصحيحين، في أحاديث كثيرة نهى عن بيع الحاضر للبادي، والحاضر هو الذي يتولى بيع سلعته، والبادي هو الذي يتولى بيع سلعته، ولا يتولاه الحاضر؛ لأن الحاضر قد عرف السلع، وعرف قيمها؛ فيكون بيعه عن البادي فيه مشقة على الناس، والرسول ﷺ يقول: دعوا الناس يرزق الله بعضهم ببعض.  فالذي يجلبه البادي من السلع من الإبل، والبقر، أو الدهن، أو الأقط، أو غير ذلك يترك هو الذي يتولى البيع؛ حتى لا يشدد على الناس، وحتى يتسع الخير للناس، إذا باعه لا يشدد، أما إذا باع حافظ له، ودلال له؛ فقد يشدد، وقد لا يبيع إلا بأغلى الأثمان؛ فيكون في توليه لذلك مشقة على الناس. وهل يدخل حكم السيارة في ذلك؟ هذا محل نظر، هل تدخل فيما ذكره النبي ﷺ أما لا؟ محل نظر، والأقرب -والله أعلم- دخولها إذا جاء أهل البوادي من مكان بعيد، ومعهم سياراتهم، وجلبوها في الأسواق عند المعارض، ووكلوا صاحب المعرض أن يبيعها، هل تدخل في هذا، أو ما تدخل؟ محل نظر.  والأقرب -والله أعلم- دخولها للعموم، وقد يقال: لا تدخل؛ لأنهم عرفوا السلع، وعرفوا الأثمان، ولا بقي فيها إشكال، فهم يبيعون برضاهم، وبمشاورتهم أشياء يعرفونها، وليست مجهولة لهم، بخلاف البوادي أولًا في بعض الأمور التي يجلبونها، لا يعرفون قيمها، أما الأسواق فقد تقاربت الآن، والناس قد عرفوا السلع، والبادية صارت كالحاضرة في معرفة -الآن- السلع، ومعرفة قيم السيارات، اشتروهاـ واستعملوها، وعرفوا قيمها، فقد يقال في هذه الحال: إن العلة التي قالها النبي ﷺ منتفية الآن؛ لأن البادي لو تولى ما يبيع إلا بالأسعار التي يعرفها الناس، ويعرفها الحاضرة؛ فلا يكون في هذا خطر على الناس، قد يقال هذا وهو قريب، وقوي.","link":"https://binbaz.org.sa/fatwas/2141/حكم-وضع-صاحب-البادية-سيارته-في-المعرض-لغرض-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_790.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6434,"question":"هل يثبت خيار الغبن حيث قال صاحب سبل السلام: ذهب جماهير العلماء إلى عدم ثبوته، وقال: إن حديث إذا تبايعت؛ فقل لا خلابة خاص بهذا الرجل المشار إليه؟","title":"هل يثبت خيار الغبن؟","answer":"الجواب: الصواب أن الغبن ثابت مطلقًا إذا كان الرجل ... ولا يفهم في السلع، ولا يعرف البيع، وغبنوه له الخيار؛ لأنه مظلوم، والنبي ﷺ بين أن الظلم محرم، وأن المسلم أخو المسلم لا يظلمه، ولا يسلمه.  فالواجب على المسلمين ألا يخدعوا إخوانهم، وألا يظلموهم، وأن يبيعوهم بالبيع المعتاد، فالذي لا يحسن البيع يعامل كالذي يحسن البيع، لا يخدع، فإذا خدع؛ فهو مظلوم؛ فله الخيار عند الحكام.","link":"https://binbaz.org.sa/fatwas/2142/هل-يثبت-خيار-الغبن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_791.mp3","categories":["البيوع"]},{"id":6700,"question":"ما حكم الدينة يا شيخ، العشرة بخمسة عشر، والعشرة بأربعة عشر، والعشرة بثلاثة عشر؟","title":"حكم البيع المؤجل بزيادة في الثمن","answer":"الجواب:\n\nالأرباح ما لها حد، إن اصطلحوا عليه، واتفقوا عليه لأجل معلوم؛ فلا بأس، النبي اشترى البعير بالبعيرين من الصدقة -عليه الصلاة والسلام- فكونه يشتري سلعة بمائة، بمائة وخمسين، أو مائة وستين، أو مائتين إلى أجل، أو إلى آجال؛ لا حرج في ذلك؛ لأن الأجل له شأنه، وله قيمته.\n\nالسؤال: يسلم بعض الفلوس في مجلس العقد....؟\n\nالجواب: لا بأس يسلم بعضها، والباقي مؤجل أقساط، لا حرج في ذلك إذا كانت أقساطًا معلومة، وليس للربح حد معلوم، لكن الأفضل للمؤمن ألا يشدد على أخيه، وأن يخفف عليه الربح، هذا شأن المؤمن مع أخيه، ولكن ليس لهذا حد محدود.\n\nالسؤال: لكن يا شيخ: هنا الكثير منهم إذا جاب المقترض منا، وأخذ القماش هذا بخمسة عشر ألفًا عندما يجيء يأخذه، يقول: دعونا نخصم عن كل كيس، أو كل صندوق خمسة ريالات؟\n\nالشيخ: ما له؟\n\nالطالب: يعني الآن هذا قرض، هذا قال له: أريد منك سلف عشرة آلاف، قال: ما أعطيك العشرة إلا بخمسة عشر ألفًا، وأتى به عند صاحب الدكان يأخذ من عنده القماش، هذا بخمسة عشر ألفًا، وقيمته عشرة آلاف ريال، يعني حيلة للربا؟\n\nالجواب: ... يشتري قماشًا من مال معلوم إلى أجل معلوم، والذي اشترى لا يبيعه حتى ينقله إلى رحله، إذا اشترى منك أكياسًا، أو قماشًا إلى أجل معلوم؛ فأنت أيها المشترى لا تبعه حتى تنقله إلى رحلك، إلى دكانك، إلى بيتك، إلى السوق، لا تبعه عند التاجر حتى تنقله إلى رحلك، فإن الرسول ﷺ نهى أن تباع السلع .. حتى يحرزها التجار إلى رحالهم، وقال: لا تبع ما ليس عندك ولا بأس أن يشتريه بثمن مؤجل، ويعطيه البعض نقدًا، والباقي مؤجلًا إلى أقساط، إلى آجال معلومة، كل شهر كذا، كل سنة كذا، شيء معلوم لا حرج في ذلك، قد بيعت .. في عهد النبي ﷺ .. كل عام أوقية أقساطًا تسع سنوات.\n\nالسؤال: لكن إذا كانوا متفقين الاثنان: البائع، والتاجر على المشترى؟\n\nالجواب: ولو، إذا اتفقوا عليه، والمال موجود؛ لا بأس، لكن لا يبيع شيئًا ما هو في ملكه، إذا كان المال موجودًا عنده في الدكان، في البيت، وباع شيئًا معلومًا إلى أجل معلوم؛ فلا بأس، ولكن المشتري لا يبيعه حتى ينقله من عند التاجر إلى بيته هو، أو السوق، أو إلى دكانه، ثم يبيعه على من يشاء بعد ذلك.\n\nالسؤال: أما يبيعه بنفس الدكان؟\n\nالجواب: لا، ما يجوز، هذا ما يجوز.","link":"https://binbaz.org.sa/fatwas/2579/حكم-البيع-الموجل-بزيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1075.mp3","categories":["البيوع"]},{"id":6799,"question":"بالنسبة للدينة هذه التي الآن متعاملون بها كثير من الناس، العشرة بخمسة عشر، العشرة بأربعة عشر ونصف، العشرة بثلاثة عشر ونصف، ما قولهم فيها؟","title":"بيوع المداينات وأحكامها","answer":"الجواب: هذه فيها تفصيل، وقد كتبنا فيها رسالة .. السؤال: لكن هذه حرام، أم حلال؟ الجواب: مكتوبة موضحة، بينا فيها أحكام هذه المداينات، وهي توزع من دار الإفتاء من المستودع، وهذه المعاملات فيها تفصيل، وكثير من الناس ليس عنده فيها بصيرة. إذا كان الإنسان يبيع السلعة من سكر، أو سيارات، أو رز، أو غير ذلك بعد ما يحوزها، إن كانت في ملكه، في دكانه، في مخزنه، ثم باعها على غيره إلى أجل معلوم؛ فلا بأس، إذا باع مثلًا سكرًا، أو رزًا، أو المواد الخام، أو السيارة، وهي في ملكه، وفي حوزته، باعها إلى أجل معلوم، أو إلى آجال بأقساط، باع هذه السيارة التي تساوي عشرين ألفًا باعه إياها إلى آجال بثلاثين ألف، مثلًا كل شهر ألفًا، أو كل شهر خمسمائة ريال، أو كل سنة خمسة آلاف، أو ستة آلاف، بآجال معلومة، وأقساط معلومة؛ فلا حرج، فقد بيعت بريرة في عهد النبي ﷺ باعها أهلها بتسع أواق في تسع سنين، كل سنة أوقية، والأوقية أربعون درهمًا، ثم اشترتها عائشة منهم، واعتقتها، فهذا من بيع الأقساط.  وهكذا لو كان عنده خام في دكانه، أو في بيته، فباعه خام إلى أجل معلوم بألف ريال، بألفين، بعشرة آلاف، بخمسين ألفًا، بمائة ألف، إلى أجل معلوم واحد، أو إلى آجال متعددة معلومة، في كل أجل عشرة آلاف، في كل أجل خمسة آلاف، لكن بشرط: أن تكون معلومة، الآجال معلومة، والأقساط معلومة، فلا بأس لقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى [البقرة:282] فأباح لعباده هذا الدين.  ولقول النبي ﷺ لما قدم المدينة والناس يسلفون في الثمار السنة، والسنتين، فقال -عليه الصلاة والسلام-: من أسلف في شيء؛ فليسلف في كيل معلوم، ووزن معلوم، إلى أجل معلوم. فإذا كانت المبيعات معلومة، والآجال معلومة؛ فلا بأس، أما ما يفعله بعض الناس، يبيع السلعة وهي عند التجار -ما بعد شراها- يتفق هو وصاحبه على فوائد، أو على سيارة -ما بعد شراها- وما هي عنده، هذا لا يجوز، لا يبيع شيئًا إلا وقد ملكه، وحازه، صار في ملكه، في دكانه، في بيته، في حوشه، في سوق المسلمين، هذا هو محل البيع، ثم الذي اشتراها منه صاحب الحاجة، الذي اشترى هذه السلعة يريد يبيعها مثلًا حتى يتزوج، أو حتى يقضي دين، أو حتى يعمر بيتًا له، أو ما أشبه ذلك، ليس له بيع هذه السلعة حتى يحوزها، هو أيضًا، إذا شراها من التاجر لا يبيعها هو حتى ينقلها إلى رحله، حتى يحوزها، لما جاء في الحديث الصحيح: أن النبي  نهى أن تباع السلع حيث تبتاع حتى يحوزها التجار إلى رحالهم.  قال ابن عمر: \"كنا نبيع الطعام جزافًا لأهل السوق، فنضرب حتى ننقله إلى رحالنا في عهد النبي ﷺ\" وفي رواية: \"حتى ننقله من أعلى السوق إلى أسفله\" فلا بد من قبضه قبضًا تامًا من البائع قبل أن يبيع، وهكذا المشتري لا بد أن يقبضه من الذي باع عليه.  أما أن يبيعه بيعًا آخر، كل واحد منهما لا بد أن يقبض قبضًا تامًا كاملًا، ويحوزه إلى رحله، ثم يبيع بعد ذلك، أما أن يبيع وهو عند الناس، عند الملاك، ما بعد شرى منهم، ويبيع، ثم يروح يشتري، ثبت عن رسول الله -عليه الصلاة والسلام- أنه جاءه حكيم بن حزام، فقال: يا رسول الله، الرجل يأتيني يريد السلعة، وليست عندي، فأبيعها، ثم أذهب فأشتريها، قال: لا تبع ما ليس عندك، لا تبع ما ليس عندك. وقال ﷺ: لا يحل سلف، وبيع، ولا بيع ما ليس عندك فلا تبع على زيد، ولا عمرو إلا شيئًا قد ملكته، وحزته من التجار، أخذته منهم .. في بيتك، في دكانك، في مكان آخر، ثم تبيع، ومن يشتري منك كذلك، إذا اشترى لا يبيع حتى يحوزها أيضًا، حتى ينقلها، ما يخلي الفوائد الزر، أو نحوه عند التاجر، يقول اشتر لي، ما بعد ...، لا، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2698/بيوع-المداينات-واحكامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1197.mp3","categories":["البيوع"]},{"id":6803,"question":"بالنسبة للدينة هذه التي الآن متعاملون بها كثير من الناس، العشرة بخمسة عشر، العشرة بأربعة عشر ونصف، العشرة بثلاثة عشر ونصف، ما قولهم فيها؟","title":"بيوع المداينات وأحكامها","answer":"الجواب: هذه فيها تفصيل، وقد كتبنا فيها رسالة .. السؤال: لكن هذه حرام، أم حلال؟ الجواب: مكتوبة موضحة، بينا فيها أحكام هذه المداينات، وهي توزع من دار الإفتاء من المستودع، وهذه المعاملات فيها تفصيل، وكثير من الناس ليس عنده فيها بصيرة. إذا كان الإنسان يبيع السلعة من سكر، أو سيارات، أو رز، أو غير ذلك بعد ما يحوزها، إن كانت في ملكه، في دكانه، في مخزنه، ثم باعها على غيره إلى أجل معلوم؛ فلا بأس، إذا باع مثلًا سكرًا، أو رزًا، أو المواد الخام، أو السيارة، وهي في ملكه، وفي حوزته، باعها إلى أجل معلوم، أو إلى آجال بأقساط، باع هذه السيارة التي تساوي عشرين ألفًا باعه إياها إلى آجال بثلاثين ألف، مثلًا كل شهر ألفًا، أو كل شهر خمسمائة ريال، أو كل سنة خمسة آلاف، أو ستة آلاف، بآجال معلومة، وأقساط معلومة؛ فلا حرج، فقد بيعت بريرة في عهد النبي ﷺ باعها أهلها بتسع أواق في تسع سنين، كل سنة أوقية، والأوقية أربعون درهمًا، ثم اشترتها عائشة منهم، واعتقتها، فهذا من بيع الأقساط.  وهكذا لو كان عنده خام في دكانه، أو في بيته، فباعه خام إلى أجل معلوم بألف ريال، بألفين، بعشرة آلاف، بخمسين ألفًا، بمائة ألف، إلى أجل معلوم واحد، أو إلى آجال متعددة معلومة، في كل أجل عشرة آلاف، في كل أجل خمسة آلاف، لكن بشرط: أن تكون معلومة، الآجال معلومة، والأقساط معلومة، فلا بأس لقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى [البقرة:282] فأباح لعباده هذا الدين.  ولقول النبي ﷺ لما قدم المدينة والناس يسلفون في الثمار السنة، والسنتين، فقال -عليه الصلاة والسلام-: من أسلف في شيء؛ فليسلف في كيل معلوم، ووزن معلوم، إلى أجل معلوم. فإذا كانت المبيعات معلومة، والآجال معلومة؛ فلا بأس، أما ما يفعله بعض الناس، يبيع السلعة وهي عند التجار -ما بعد شراها- يتفق هو وصاحبه على فوائد، أو على سيارة -ما بعد شراها- وما هي عنده، هذا لا يجوز، لا يبيع شيئًا إلا وقد ملكه، وحازه، صار في ملكه، في دكانه، في بيته، في حوشه، في سوق المسلمين، هذا هو محل البيع، ثم الذي اشتراها منه صاحب الحاجة، الذي اشترى هذه السلعة يريد يبيعها مثلًا حتى يتزوج، أو حتى يقضي دين، أو حتى يعمر بيتًا له، أو ما أشبه ذلك، ليس له بيع هذه السلعة حتى يحوزها، هو أيضًا، إذا شراها من التاجر لا يبيعها هو حتى ينقلها إلى رحله، حتى يحوزها، لما جاء في الحديث الصحيح: أن النبي  نهى أن تباع السلع حيث تبتاع حتى يحوزها التجار إلى رحالهم.  قال ابن عمر: \"كنا نبيع الطعام جزافًا لأهل السوق، فنضرب حتى ننقله إلى رحالنا في عهد النبي ﷺ\" وفي رواية: \"حتى ننقله من أعلى السوق إلى أسفله\" فلا بد من قبضه قبضًا تامًا من البائع قبل أن يبيع، وهكذا المشتري لا بد أن يقبضه من الذي باع عليه.  أما أن يبيعه بيعًا آخر، كل واحد منهما لا بد أن يقبض قبضًا تامًا كاملًا، ويحوزه إلى رحله، ثم يبيع بعد ذلك، أما أن يبيع وهو عند الناس، عند الملاك، ما بعد شرى منهم، ويبيع، ثم يروح يشتري، ثبت عن رسول الله -عليه الصلاة والسلام- أنه جاءه حكيم بن حزام، فقال: يا رسول الله، الرجل يأتيني يريد السلعة، وليست عندي، فأبيعها، ثم أذهب فأشتريها، قال: لا تبع ما ليس عندك، لا تبع ما ليس عندك. وقال ﷺ: لا يحل سلف، وبيع، ولا بيع ما ليس عندك فلا تبع على زيد، ولا عمرو إلا شيئًا قد ملكته، وحزته من التجار، أخذته منهم .. في بيتك، في دكانك، في مكان آخر، ثم تبيع، ومن يشتري منك كذلك، إذا اشترى لا يبيع حتى يحوزها أيضًا، حتى ينقلها، ما يخلي الفوائد الزر، أو نحوه عند التاجر، يقول اشتر لي، ما بعد ...، لا، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2698/بيوع-المداينات-واحكامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1197.mp3","categories":["البيوع"]},{"id":6809,"question":"وما هي العينة يا شيخ، بيع العينة؟","title":"حقيقة بيع العينة وحكمه","answer":"الجواب: العينة نوع آخر، العينة كونك تشتري السلعة من زيد، أو عمرو إلى أجل في ذمتي، إلى أجل، ثم تبيعها لي بأقل، هو نفسه الذي باع علي.. إذا ثمن مثلًا مائة طاقة، أو مائة كيس بثمن معلوم، بمائة ألف ريال مثلًا، ثم قال: أنا أشتريها منك بدل ما تبيعها على الناس، أنا أشتريها منك، فأنت شريتها بمائة ألف إلى رمضان من عام 1406 مثلًا، قال: أنا بآخذها منك الآن بتسعين ألفًا، بنقص عشرة آلاف ريال، يعني أعطيك إياها بيدك، هذا ما يجوز، لأن المعنى أنه أعطاك تسعين، وأنت تعطيه مائة بعدها، حيلة على الربا، معناه أنك أخذت التسعين، وتؤدي مائة، هذه العينة، هذه مسألة العينة، لأنك بعت دينًا بعين، بعت دينًا في ذمتك بعين تأخذه منه. السؤال: والبيع الموجود في حراج السيارات كونه يبحث عن سلعة .. أو شيء؟ الجواب: لا، لا بد يشتريها، ويحوزها، ثم يبيعها بعد ذلك. السؤال: .. يدفع عربونًا للبضاعة تأتي فيما بعد؟ الجواب: .. يبيعها قبل. س: بعربون للشركة؟ ج: لا، ما يبيعها حتى يقبض.","link":"https://binbaz.org.sa/fatwas/2699/حقيقة-بيع-العينة-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1198.mp3","categories":["البيوع"]},{"id":6820,"question":"بالنسبة للدينة هذه التي الآن متعاملون بها كثير من الناس، العشرة بخمسة عشر، العشرة بأربعة عشر ونصف، العشرة بثلاثة عشر ونصف، ما قولهم فيها؟","title":"بيوع المداينات وأحكامها","answer":"الجواب: هذه فيها تفصيل، وقد كتبنا فيها رسالة .. السؤال: لكن هذه حرام، أم حلال؟ الجواب: مكتوبة موضحة، بينا فيها أحكام هذه المداينات، وهي توزع من دار الإفتاء من المستودع، وهذه المعاملات فيها تفصيل، وكثير من الناس ليس عنده فيها بصيرة. إذا كان الإنسان يبيع السلعة من سكر، أو سيارات، أو رز، أو غير ذلك بعد ما يحوزها، إن كانت في ملكه، في دكانه، في مخزنه، ثم باعها على غيره إلى أجل معلوم؛ فلا بأس، إذا باع مثلًا سكرًا، أو رزًا، أو المواد الخام، أو السيارة، وهي في ملكه، وفي حوزته، باعها إلى أجل معلوم، أو إلى آجال بأقساط، باع هذه السيارة التي تساوي عشرين ألفًا باعه إياها إلى آجال بثلاثين ألف، مثلًا كل شهر ألفًا، أو كل شهر خمسمائة ريال، أو كل سنة خمسة آلاف، أو ستة آلاف، بآجال معلومة، وأقساط معلومة؛ فلا حرج، فقد بيعت بريرة في عهد النبي ﷺ باعها أهلها بتسع أواق في تسع سنين، كل سنة أوقية، والأوقية أربعون درهمًا، ثم اشترتها عائشة منهم، واعتقتها، فهذا من بيع الأقساط.  وهكذا لو كان عنده خام في دكانه، أو في بيته، فباعه خام إلى أجل معلوم بألف ريال، بألفين، بعشرة آلاف، بخمسين ألفًا، بمائة ألف، إلى أجل معلوم واحد، أو إلى آجال متعددة معلومة، في كل أجل عشرة آلاف، في كل أجل خمسة آلاف، لكن بشرط: أن تكون معلومة، الآجال معلومة، والأقساط معلومة، فلا بأس لقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى [البقرة:282] فأباح لعباده هذا الدين.  ولقول النبي ﷺ لما قدم المدينة والناس يسلفون في الثمار السنة، والسنتين، فقال -عليه الصلاة والسلام-: من أسلف في شيء؛ فليسلف في كيل معلوم، ووزن معلوم، إلى أجل معلوم. فإذا كانت المبيعات معلومة، والآجال معلومة؛ فلا بأس، أما ما يفعله بعض الناس، يبيع السلعة وهي عند التجار -ما بعد شراها- يتفق هو وصاحبه على فوائد، أو على سيارة -ما بعد شراها- وما هي عنده، هذا لا يجوز، لا يبيع شيئًا إلا وقد ملكه، وحازه، صار في ملكه، في دكانه، في بيته، في حوشه، في سوق المسلمين، هذا هو محل البيع، ثم الذي اشتراها منه صاحب الحاجة، الذي اشترى هذه السلعة يريد يبيعها مثلًا حتى يتزوج، أو حتى يقضي دين، أو حتى يعمر بيتًا له، أو ما أشبه ذلك، ليس له بيع هذه السلعة حتى يحوزها، هو أيضًا، إذا شراها من التاجر لا يبيعها هو حتى ينقلها إلى رحله، حتى يحوزها، لما جاء في الحديث الصحيح: أن النبي  نهى أن تباع السلع حيث تبتاع حتى يحوزها التجار إلى رحالهم.  قال ابن عمر: \"كنا نبيع الطعام جزافًا لأهل السوق، فنضرب حتى ننقله إلى رحالنا في عهد النبي ﷺ\" وفي رواية: \"حتى ننقله من أعلى السوق إلى أسفله\" فلا بد من قبضه قبضًا تامًا من البائع قبل أن يبيع، وهكذا المشتري لا بد أن يقبضه من الذي باع عليه.  أما أن يبيعه بيعًا آخر، كل واحد منهما لا بد أن يقبض قبضًا تامًا كاملًا، ويحوزه إلى رحله، ثم يبيع بعد ذلك، أما أن يبيع وهو عند الناس، عند الملاك، ما بعد شرى منهم، ويبيع، ثم يروح يشتري، ثبت عن رسول الله -عليه الصلاة والسلام- أنه جاءه حكيم بن حزام، فقال: يا رسول الله، الرجل يأتيني يريد السلعة، وليست عندي، فأبيعها، ثم أذهب فأشتريها، قال: لا تبع ما ليس عندك، لا تبع ما ليس عندك. وقال ﷺ: لا يحل سلف، وبيع، ولا بيع ما ليس عندك فلا تبع على زيد، ولا عمرو إلا شيئًا قد ملكته، وحزته من التجار، أخذته منهم .. في بيتك، في دكانك، في مكان آخر، ثم تبيع، ومن يشتري منك كذلك، إذا اشترى لا يبيع حتى يحوزها أيضًا، حتى ينقلها، ما يخلي الفوائد الزر، أو نحوه عند التاجر، يقول اشتر لي، ما بعد ...، لا، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2698/بيوع-المداينات-واحكامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1197.mp3","categories":["البيوع"]},{"id":6826,"question":"وما هي العينة يا شيخ، بيع العينة؟","title":"حقيقة بيع العينة وحكمه","answer":"الجواب: العينة نوع آخر، العينة كونك تشتري السلعة من زيد، أو عمرو إلى أجل في ذمتي، إلى أجل، ثم تبيعها لي بأقل، هو نفسه الذي باع علي.. إذا ثمن مثلًا مائة طاقة، أو مائة كيس بثمن معلوم، بمائة ألف ريال مثلًا، ثم قال: أنا أشتريها منك بدل ما تبيعها على الناس، أنا أشتريها منك، فأنت شريتها بمائة ألف إلى رمضان من عام 1406 مثلًا، قال: أنا بآخذها منك الآن بتسعين ألفًا، بنقص عشرة آلاف ريال، يعني أعطيك إياها بيدك، هذا ما يجوز، لأن المعنى أنه أعطاك تسعين، وأنت تعطيه مائة بعدها، حيلة على الربا، معناه أنك أخذت التسعين، وتؤدي مائة، هذه العينة، هذه مسألة العينة، لأنك بعت دينًا بعين، بعت دينًا في ذمتك بعين تأخذه منه. السؤال: والبيع الموجود في حراج السيارات كونه يبحث عن سلعة .. أو شيء؟ الجواب: لا، لا بد يشتريها، ويحوزها، ثم يبيعها بعد ذلك. السؤال: .. يدفع عربونًا للبضاعة تأتي فيما بعد؟ الجواب: .. يبيعها قبل. س: بعربون للشركة؟ ج: لا، ما يبيعها حتى يقبض.","link":"https://binbaz.org.sa/fatwas/2699/حقيقة-بيع-العينة-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1198.mp3","categories":["البيوع"]},{"id":6902,"question":"أنا شاب أبلغ من العمر عشرين عامًا، والدي يعمل في التجارة، غير أنه يأخذ في بعض الأوقات قروضًا من البنك، ثم يردها إلى البنك، إضافة إلى الفائدة، وأنا بعض الأوقات أقوم بقضاء بعض الأعمال له،  هل يجوز لي أن آكل، أو آخذ من مال والدي؟","title":"حكم أكل الولد من مال والده المرابي","answer":"الجواب: ما دام والدك عنده دخول أخرى من الحلال، ولكنه قد يخطئ، فيأخذ سلفًا من البنك، لا حرج عليك أن تأكل مع والدك، وأن تعينه في الخير فقط، وتنصحه حتى لا يعود إلى القرض من البنك بالفائدة، تقول له: إن هذا محرم ولا يجوز لك، لعل الله يهديه بأسبابك، أو تقول لعمك، أو إخوانك الكبار، يقولون له بأسلوب حسن؛ حتى يهديه الله، ويقبل، عليك أن تفعل ما تستطيع من الخير، ولو بتحريك غيرك من أعمام، أو أخوال، أو إخوة كبار؛ حتى ينصحوه، ويتوجهوا إليه بما يعينه على ترك الربا.","link":"https://binbaz.org.sa/fatwas/2837/حكم-اكل-الولد-من-مال-والده-المرابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1285.mp3","categories":["الربا والصرف","البيوع","الآداب والأخلاق"]},{"id":7075,"question":"الآن بالنسبة لإنسان يشتري جيمس من واحد، وقال له: الجيمس هذا أنا أبيعك إياه تقسيطًا، بدلًا ما قيمته أربعين ألفًا، اشتريه بسبعين ألفًا تقسيطًا، يجوز هذا؟","title":"البيع بالتقسيط وحكمه","answer":"الجواب:\n\nما فيه بأس التقسيط، قد باع أصحاب بريرة بريرة نفسها باعوها إياها على أقساط، في كل عام أربعون درهمًا، تسعة أقساط في عهد النبي ﷺ. \n\nفالتقسيط إذا كان معلوم الآجال؛ لا بأس، كأن تشتري السيارة تساوي ثلاثين ألفًا، تشتريها بأربعين، أو بخمسين، كل سنة خمسة آلاف، أو في كل سنة ثمانية آلاف، أو كل شهر ألف، ما فيه شيء إذا كان معلومًا.","link":"https://binbaz.org.sa/fatwas/3090/البيع-بالتقسيط-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1470.mp3","categories":["البيوع"]},{"id":7085,"question":"من تعريف ربا النسيئة: أنه الزيادة في الشيء مقابل التأجيل، فما مدى انطباق هذا الشيء على دينة الأكياس، والسيارات المعمول بها الآن بدلاً من القرض الحسن، أفتونا جزاكم الله خيرًا؟","title":"الفرق بين ربا النسيئة والتورق","answer":"الجواب:\n\nما يعمها هذا، الربا هو أن يأخذ شيئًا بجنسه مع زيادة، هذا ربا الفضل، وإن كان دينًا بدين؛ صار ربا الفضل والنسيئة جميعًا، فإذا أخذ دراهم بدراهم وزيادة؛ فهذا ربا الفضل، سواء كان يدًا بيد، أو نسيئة.\n\nوأما مسألة التورق فليست من هذا الباب، يأخذ سلعة بدراهم إلى أجل، ثم يبيعها -وهو على اختياره- في يومه، أو غده، أو بعد ذلك هو ما أخذ ربويًا بربوي، وإنما أخذ سلعة من طعام، أو سيارة، أو أرض، أو غير ذلك بدراهم معدودة، إلى أجل معلوم، فليس من الربا في شيء.","link":"https://binbaz.org.sa/fatwas/3088/الفرق-بين-ربا-النسيىة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1469.mp3","categories":["الربا والصرف","البيوع"]},{"id":7090,"question":"ما رأي سماحتكم فيما يسمى ببيع المرابحة التي تقوم به بعض المصارف الإسلامية؟","title":"حكم بيع المرابحة","answer":"الجواب:\n\nبيع المرابحة إذا كان على الوجه الشرعي؛ ما فيه شيء، إذا باعه بربح معلوم، اشترى منه السلعة بربح معلوم، أو باعه السلعة بربح معلوم؛ ما فيها شيء، قال: أبيعك هذه السيارات، كل سيارة بربح 5% أو بربح 10% أو هذه الأراضي التي اشتريتها بكذا وكذا أبيعك إياها بربح كذا.","link":"https://binbaz.org.sa/fatwas/3096/حكم-بيع-المرابحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1474.mp3","categories":["البيوع"]},{"id":7093,"question":"ما حكم ما يأتي: اختار السيارة التي تريد، فيشتريها التاجر مثلًا بعشرين ألف ريال، ويبيعها على هذا الذي اختارها بخمسة وعشرين ألف ريال أقساطًا، وذلك بضمان، أو كفيل غارم، وتكون السيارة باسم المشتري أولًا وأخيرًا؟","title":"حكم بيع السلعة قبل قبضها","answer":"الجواب:\n\nالواجب أنه يشتريها أولًا على حساب البائع، فإذا قبضها، وحازها باسمه، وتمت إجراءات البيع والشراء بعد ذلك يبيعها على من رغب بيعها، وكل في حل حتى يتم البيع الأول، ويحوزها المشتري الأول، وتكتب باسمه، وتنتهي، ثم تباع بعد ذلك على الراغب الثاني.\n\nأما التحيل على هذا بأشياء أخرى حتى يشتريها قبل أن يتم الشراء الأول لها، هذا غلط، لا بد أن يكون البائع الأول اشتراها على حسابه، وتملكها على حسابه، وقبضها، ثم يبيعها بعد ذلك، ثم المشتري لا يبيعها إلا بعد قبضها أيضًا، وتوليها، وحوزها.\n\nوسمعتم في الندوة أمرًا فات التنبيه عليه، وهو مسألة السَّلَم، نبه عليه الدكتور ... والسَّلَم فيه غنية لو تيسر -الناس يعرفونه جيدًا- لأغناهم عن الوعدة، وأغناهم عن أشياء كثيرة.\n\nوالسلم وهو كما سمعتم: أن يشتري من ذمة الشخص شيئًا معلومًا، يشتري من ذمته، شيئًا معلومًا من حنطة، أو أرز، أو سيارة موصوفة إلى أجل معلوم، بمال يقدم، يحتاجه هذا البائع، فيقول: أنا أبيعك من ذمتي مثلًا ألف صاع من البر، أو ألف كيلو من البر، أو ألف كيلو من الأرز في كذا وكذا من المال مقدمًا، هذا يسمى السلم.\n\nأو أبيعك سيارة موديل كذا، صفتها كذا بعد سنة، أو بعد سنتين برأس مال يقدم، وهو الثمن يقدم حالًا، هذا يسمى السلم، وقد قرر العلماء جوازه. \n\nوقال فيه النبي ﷺ لما قدم المدينة وهم يسلفون في الثمار السنة والسنتين، قال -عليه الصلاة والسلام-: من أسلف فليسلف في كيل معلوم ووزن معلوم إلى أجل معلوم متفق عليه.\n\nفهذا السلم فيه أيضًا غنية عن بيع التورق، وفيه غنية عن أشياء كثيرة، قد يتورط فيها الإنسان من قرض الذي قد يمن عليه صاحبه، أو قد يأتيه وهو مستح من ذلك، هذا بيع ما فيه منة لأحد، بيع معلوم إلى أجل معلوم، يقدم فيه رأس المال.","link":"https://binbaz.org.sa/fatwas/3099/حكم-بيع-السلعة-قبل-قبضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1476.mp3","categories":["البيوع"]},{"id":7135,"question":"اشتغلت ببيع الدخان، فهل الأموال التي جمعتها حلال أم لا، علمًا بأنني قد أقلعت عن ذلك والحمد لله؟","title":"حكم المال المكتسب من بيع الدخان بعد التوبة من بيعه","answer":"الجواب:\n\nالتوبة يا أخي تجب ما قبلها، إذا كنت في بيع الدخان، أو غيره من المحرمات، ثم أقلعت عنها؛ فاحمد الله على ذلك، والتزم التوبة.\n\nأما الأموال التي دخلت عليك قبل أن تعلم، أو قبل أن يستقر عندك العلم؛ فنرجو ألا حرج عليك فيما أكلته منها، وفيما أتى منها، وأما الباقي الذي موجود عندك؛ فالأحوط لك الصدقة فيه، وإخراجه إلى وجوه البر، وأن تعيش على غيره، هذا هو الذي ينبغي لك؛ لأنه كسب بغير الطريق الشرعي، ولأن أمر الدخان معروف عندك وعند غيرك، تسمع من كلام أهل العلم ما يدلك على أنه منكر، أو فيه شبهة، ولكنك تساهلت.\n\nفعليك أن تزيل ما في يدك من هذا المال بصرفه في وجوه الخير والبر، وإن كنت مضطرًا إليه، ولم تعلم بالتحريم إلا عند التوبة منه؛ فنرجو ألا يكون عليك منه بأس إذا كنت فقيرًا، أو كنت قد أكلته؛ لئلا تغرمه، لقول الله  لما ذكر الربا قال: فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ [البقرة:275] فإذا كنت لم تعلم إلا عند التوبة؛ فنرجو أن يكون لك ما سلف، لكن إذا أخرجته، ووزعته في وجوه البر إذا كان عندك منه شيء يكون؛ هذا أحوط، وأبعد عن الشر، وأبرأ للذمة.","link":"https://binbaz.org.sa/fatwas/3155/حكم-المال-المكتسب-من-بيع-الدخان-بعد-التوبة-من-بيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1513.mp3","categories":["البيوع"]},{"id":7138,"question":"هل كل ما كان حرامًا استعماله بأي وجه يحرم بيعه وكسب المال منه، على سبيل المثال الدخان أنه حرام، فهل من باع الدخان دون أن يشربه يكون كسبه حرامًا؟","title":"حكم بيع كل ما يحرم استعماله","answer":"الجواب:\n\nيقول النبي ﷺ: إن الله إذا حرم شيئًا؛ حرم ثمنه فإذا حرم عليك الدخان؛ حرم عليك ثمنه، والتجارة فيه؛ لأنك معين على الإثم والعدوان، تعينهم على الشر، وتجره إليهم، وتوصله إليهم، فمن أعان على فعل المحرم؛ شارك في الإثم، سواء بالبيع، أو بالهدية، فلا تعط الدخان هدية، ولا بيعًا، ولا غير ذلك، إلا الشيء المحرم أكله ولكنه ينتفع به؛ فهذا لا بأس مثل: الحمير، والبغال ينتفع بها، تباع، لكن لا تؤكل، إنما تباع للعمل لركوبها والسني عليها، والعمل عليها.\n\nأما ما حرم الله أكله، والانتفاع به؛ فإنه يحرم ثمنه، كالدخان، والمسكرات، والخنازير، وأشباه ذلك مما حرم الله أكله، وحرم الانتفاع به.","link":"https://binbaz.org.sa/fatwas/3161/حكم-بيع-كل-ما-يحرم-استعماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1519.mp3","categories":["البيوع"]},{"id":7167,"question":"هل يجوز شراء الذهب بالشيكات، أم لا؟","title":"حكم شراء الذهب بالشيكات","answer":"الجواب:\n\nهذا فيه نظر، والأقرب -والله أعلم- أن قبض الشيك قبض له، إذا أعطاه شيكًا بالقيمة؛ فهو قبض له، لكن كونه يأخذ النقود بيده، هذا أولى وأحوط، فإذا سلم له الذهب، وأعطاه الدولارات، أو الدراهم، أو العملة الأخرى؛ يكون هذا هو الطريق الوحيد في السلامة، أما إذا أعطاه شيكًا عن البنك الفلاني، أو المحل الفلاني؛ فهو في الحقيقة قبض؛ لأنه متداول كقبض النقود سواء.","link":"https://binbaz.org.sa/fatwas/3204/حكم-شراء-الذهب-بالشيكات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1554.mp3","categories":["البيوع"]},{"id":7169,"question":"جاء عن الرسول ﷺ أنه نهى عن بيعتين في بيعة، ما هي صورة البيعتين في بيعة، وما علة التحريم؟","title":"صورة البيعتين في بيعة وعلة التحريم في ذلك","answer":"الجواب:\n\nأحسن ما قيل في ذلك: أن بيعتين في بيعة، بيعة العينة، صورة العينة، وبيع عقد في عقد، كونه يشترط عقدًا في عقد، وبيع العينة، ولهذا في الحديث الصحيح : من باع بيعتين في بيعة فله أوكسهما أو الربا. \n\nفهذا يفسر البيعتين بأنها العينة، وأن يبيع السلعة على إنسان مثلاً بمائة مؤجلة، ثم يشتريها منه بثمانين، أو بسبعين معجلة، فهذه بيعتان في بيعة، تحيلوا بها على الربا، يعطيها سبعين معجلة، ويأخذ منه مائة بعد أشهر، أو بعد سنة، هذه بيعتان في بيعة، فله الأوكس، له السبعون مثلاً التي سلمها ولا يأخذ الزيادة، يرد عليه ما قبض منه فقط.\n\nهذه يقال لها: بيع العينة، يأخذ عينًا بدين، يقول: هذه السلعة أبيعها عليك بألف ريال إلى رمضان الآتي، ثم هو يبيع عليها بثمن معجل بمائة ريالًا، أو سبعمائة ريالًا ليتخرجها في حاجته، فالمعنى أنه أخذ سبعمائة، أو ثمانمائة بألف مؤجل، وهذا عين الربا، هذه الصورة.\n\nومن الصور كما قرر أهل العلم من صور البيعتين: أن يشتري منه سلعة بكذا، على أنه يبيعه سلعة بكذا، أو على أنه يقرضه كذا وكذا، أو على أنه يؤجره كذا وكذا، فيشتري منه مثلًا السيارة الفلانية بعشرة آلاف، بشرط أنه يبيعه بيته بعشرين ألفًا، أو يشتري منه بيته بشرط أنه يبيعه أرضه الفلانية بكذا وكذا، أو بشرط أنه يقرضه كذا وكذا من المال، فهو عقد في عقد، هذا بيعتان في بيعة.\n\nالسؤال: هذه مقايضة، هذا له سعر، وهذا له سعر، يقسموا الفرق بينهما؟\n\nالجواب: شرط هذا بهذا.\n\nالسؤال: حكمه؟\n\nالجواب:  المنع.","link":"https://binbaz.org.sa/fatwas/3207/صورة-البيعتين-في-بيعة-وعلة-التحريم-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1556.mp3","categories":["البيوع"]},{"id":7176,"question":"انتشر منذ فترة نوع من المضاربة تسمى سلة العملات، وهي أن يقوم الشخص بإعطاء البنك مبلغًا من المال، بالإضافة إلى تفويض؛ ليقوم البنك نيابة عنه بشراء العملات، وبيعها، كالدولار مثلًا، ونتيجة لهذا البيع والشراء يحصل الشخص على الأرباح، كما أنه معرض للخسارة أيضًا، فما رأي سماحتكم في ذلك؟","title":"حكم الاتجار بالعملات","answer":"الجواب:\n\nالذي بلغنا هو ما ذكره السائل أن يعطوا البنك، أو غير البنك عُمَلا يتجر لهم فيها، فالتجارة في العُمَل فيه التفصيل:\n\nإن كان من طريق الربا؛ حرم، وإن كان من طريق الشرع؛ أبيح، فإذا باع العملة بعملة أخرى يدًا بيد؛ فلا بأس، كأن يبيع العملة التي هي الدولار مثلًا بالجنيه الاسترليني، أو بالجنيه المصري، أو بالريال السعودي يدًا بيد؛ فلا بأس، أما إلى أجل، أو غير مقبوض في المجلس، هذا لا يجوز، لأن العُمَل هذه منزلة منزلة النقود في أصح أقوال أهل العلم من جنسها، وقائمة مقامها، وقال -عليه الصلاة والسلام-: الذهب بالذهب ربًا، إلا هاء وهاء. \n\nوفي اللفظ الآخر: الذهب بالفضة ربًا، إلا هاء وهاء يعني إلا يدًا بيد والفضة بالفضة ربا إلا هاء وهاء، والبر بالبر ربا إلا هاء وهاء، والشعير بالشعير ربا إلا هاء وهاء. \n\nوهكذا قوله في الحديث الآخر -عليه الصلاة والسلام-: الذهب بالذهب مثلًا بمثل سواءً بسواء يدًا بيد، والفضة بالفضة مثلا بمثل سواء بسواء يدا بيد.  \n\nثم هكذا ذكر في البر والشعير والتمر والملح كلها يدًا بيد، سواء بسواء، فالعُمَل التي يتعاطها الناس إذا باع بعضها ببعض مناجزة يدًا بيد؛ فلا بأس إذا كانت من أجناس كالدولار بالجنيه الاسترليني، أو المصري، أو الدولار بالدينار الأردني، أو الدينار العراقي يدًا بيد؛ فلا بأس.\n\nأما دولار بدولارين ما يجوز ربا فضل، إذا كان باع دولارًا بدولارين إلى أجل هذا اجتمع فيه الربا بنوعيه: ربا الفضل، وربا النسيئة، أو باع مثلاً العملة السعودية عشرة بإحدى عشرة، أو عشرة باثني عشر، ولو يدًا بيد، هذا ربا فضل، فإذا كان نسيئة، أو مؤخرًا عن المجلس؛ اجتمع فيه النوعان: ربا الفضل، وربا النسيئة.","link":"https://binbaz.org.sa/fatwas/3216/حكم-الاتجار-بالعملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1563.mp3","categories":["الربا والصرف","البيوع"]},{"id":7317,"question":"رجل أراد أن يستلف من شخص مبلغًا وقدره عشرة آلاف ريال على أن يردها إليه أقساطًا ثلاثة عشر، وأن يذهب معه ويشتري سيارة بنفس المبلغ عشرة آلاف، ويبيعها عليه صاحب المبلغ، وهو يبيعه بعد ذلك كما أراد؟","title":"ضوابط مسألة التورق","answer":"الجواب: هذا فيه تفصيل، أما كونه يأخذ عشرة آلاف ويجعلها ثلاثة عشر ألفًا أقساطًا سلفة، هذا عين الربا، ولو كان من غير البنك، هذا عين الربا، سواء الربا من البنك، أو من صعلوك، أو من غيره، هذا عين الربا. أما شراء السيارة هذا بحث آخر، كونه يشتري سيارة هذا فيه تفصيل، إذا باعه سيارة عند التجار ما قبضها هذا ما يجوز، وبيع ما ليس عندك، والرسول ﷺ نهى أن يبيع الإنسان ما ليس عنده، وقال لحكيم : لا تبع ما ليس عندك. أما إذا اشترى السيارة، وحازها، وصارت عنده، وفي قبضته في بيته، أو في حوشه، أو في السوق، ثم باعها عليه بعدما حازها حيازة تامة، باعها عليه إلى أجل معلوم، فهذا لا بأس به، هذا يسمونها التورق إذا كان المشتري لم يشترها للاستعمال، ولكن اشتراها ليبيعها؛ ليأخذ ثمنها؛ ليستعين في زواج، أو في قضاء دين، أو في تعمير البيت، أو ما أشبه ذلك، تسمى مسألة الورق، يسميها العامة الوعدة، وفيها خلاف بين العلماء. لكن الصحيح: أنها جائزة بشرط أن يكون البائع قد باع ما يملك، وحازه، وصار عنده، ما باع ما عند التجار يبيع شيئًا عنده، الرسول ﷺ نهى أن تباع السلع حيث تبتاع، حتى يحوزها التجار إلى رحالهم، وقال: لا تبع ما ليس عندك. فالذي يعامل في مسألة التورق يجب عليه ألا يبيع شيئًا عند الناس، بل يكون قد ملكه، واشتراه، وحازه، وقبضه، ثم يبيع بعد ذلك، ثم الذي يشتريه لا يبيعه في محله الذي يشتريه، يقبضه أيضًا إلى بيته، أو إلى دكانه، وبعد ذلك ينظر في البيع، ولا يبيع عند الذي اشتراه منه، كل واحد يقبض نعم.","link":"https://binbaz.org.sa/fatwas/3392/ضوابط-مسالة-التورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1707.mp3","categories":["البيوع"]},{"id":7318,"question":"هل طريقة المداينة الموجودة الآن في سوق الجُفرة، والطريقة التي يتعاملون بها مع الناس، يقولون: العشرة خمسة عشر، ثم يقومون بكتابة ورقة بين الدائن والمدين، مثل ذلك رجل أتى إلى رجل، وقال له: أريد مائة ألف ريال، فقام الرجل الثاني بكتابة ورقة بثمانين ألف ريال، ثم قال له: إني أريد منك مائة ألف ريال تسمع؟ فيقول: نعم، ثم يشهد على ذلك الرجل أنه يريد منه المبلغ المذكور، ثم يقول له: هيا نذهب إلى صاحب بيع القماش، ثم يقول: كم الطاقة؟ فيقول: بكذا، فيقول الدائن لصاحب القماش: عد لنا ألف طاقة من القماش، ثم يدفع ثمنها، فيقول للمدين: هذه بضاعتك عدها، فإذا عدها وأراد أن يحملها قال له الدائن: لا تتعب نفسك بعها على صاحب الدكان؛ لأن حملها يتعبك. فيبيعها بثمن أقل من الثمن المشترى به، والسؤال ما حكم مثل هذا الدين؟","title":"بيع السلعة قبل حيازتها","answer":"الجواب: هذا واقع، وقد بلغنا ونبه عليه كثيرًا، وكتب عليه كثيرًا، وسمعتم الآن هذا لا يجوز، بل لا بد أن ينقله إلى رحله، وأن لا يبيع شيئًا عند التجار، بل ينقل ذلك، ثم يبيع بعد ذلك، ثم المشتري لا يبيعه في مكانه، بل يقبضه أيضًا؛ لأن الرسول ﷺ نهى أن تباع السلع حيث تبتاع، حتى يحوزها التجار إلى رحالهم، وقال: لا تبع ما ليس عندك وقال: لا يحل سلف وبيع، ولا بيع ما ليس عندك بل يجب عليه أن يحوزه ثم يتصرف بعد ذلك.","link":"https://binbaz.org.sa/fatwas/3393/بيع-السلعة-قبل-حيازتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1708.mp3","categories":["البيوع"]},{"id":7494,"question":"أيضاً للطالب عبد الوهاب عمر المريح سؤال آخر وهو يقول: هل شرب الدخان والاستفادة بثمنه حرام، أم مكروه؟ مع ذكر الدليل؟","title":"حكم شرب الدخان والاستفادة من ثمنه","answer":"الجواب: الدخان حرام عند أهل العلم، ولا يجوز شربه ولا بيعه ولا أكل ثمنه، لما فيه من المضرة العظيمة والخبث الكثير، وقد أجمع الأطباء وأجمع من عرف الدخان بالتجارب أنه مضر وأنه خبيث؛ ولهذا ذهب المحققون من أهل العلم إلى تحريمه؛ لمضاره الكثيرة وخبثه في نفسه، والدليل على هذا: قوله سبحانه في كتابه الكريم: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] الله سبحانه إنما أحل الطيبات لعباده، وقد أجمع الأطباء العارفون به أنه ليس من الطيبات بل هو من الخبائث الضارة، فهو يسبب أمراضاً كثيرة؛ منها: مرض السرطان، ومنها: موت السكتة الفجأة، ومنها: أمراض أخرى معروفة عند أهل الطب والعارفين بهذا، ..... شجرة خبيثة، ومن ذلك قوله جل وعلا في وصف نبيه محمد ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157] فالدخان من الخبائث التي تضر متعاطيها، فيكون محرماً، يعني: الدخان، فهو شجرة خبيثة مضرة ضرراً كبيراً، فوجب القطع بتحريمها، وتحريم ثمنها، وتحريم التجارة فيها. نعم.","link":"https://binbaz.org.sa/fatwas/4455/حكم-شرب-الدخان-والاستفادة-من-ثمنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_006/00605.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":7514,"question":"لدينا أيضاً سؤال من الأخ: محمد بن علي الزري من الدمام يقول: الآن عندي أسئلة عن البيع والشراء، والسؤال الأول: أنا أبيع بساعات وغيرها والسعر مثلاً على الساعة مائة وخمسين ريال، فيأتيني رجل وأبيعها عليه عن مائة وخمسة وأربعين ريال، ويأتيني آخر وأبيعها بمائة وخمسة وثلاثين نقداً، ويأتيني صديق وبحكم الصداقة أعطيها له بمائة وخمسة وعشرين ريال، وإذا أتاني واحد أعرفه فقال: آخذ الساعة عن مائة وخمسين لكن الدراهم مؤجلة إلى المعاش، فهل البيع جائز؟ وفقكم الله.","title":"حكم الزيادة في البيع على بعض المشترين والنقص لآخرين","answer":"الجواب: الواجب على المؤمن ألا يخدع الناس، بل يتحرى السعر المناسب الذي لا يضر الناس، فإذا كان سعر الساعات مائة وخمسين مثل الناس، يعني يبيع مثل ما يبيع الناس أمثالها مائة وخمسين؛ ولكنه يتنازل عن بعض الناس إذا ألح، أو لكونه صديقاً أو قريباً، لا حرج في ذلك، كونه يتنازل لبعض الأقارب أو لبعض الأصدقاء فيبيع بأقل من السعر المعتاد لا حرج في ذلك.\nأما كونه يغش الناس فإذا رأى الضعيف الجاهل زاد عليه، وإذا رأى الحاذق البصير أعطاه السعر المعتاد، هذا لا يجوز له، بل يجب عليه أن يلاحظ الجاهل كما يلاحظ الآخر فيبيع بسعر معروف للجميع، لا يغش به أحداً ولا يخون به أحداً، بل يبيع بالسعر المعروف الذي يبيع به الناس حتى لا يخدع الناس، وإذا نزل لبعض المحبين أو بعض الأصحاب أو بعض الأقارب شيئاً أو أعطاهم إياه هدية من دون ثمن فلا بأس، هذا إليه، لكن لا يتحرى أن يظلم الجهال والذين لا يعرفون الأسعار فيبيع عليهم بأسعار زائدة، بل يجب عليه أن يكون سعره مطرداً معروفاً مثل ما يبيع الناس، مع الحاذق ومع غير الحاذق، هذا الواجب عليه.\nوأما كونه ينزل لبعض الناس مثل ما تقدم لا بأس، أما كونه يبيع إلى المعاش، مؤجل للمعاش، هذا محل نظر، إن كان المعاش معروف يعني إلى آخر الشهر فلا بأس، أما إلى معاش ما يدرى متى يخرج، وفيه جهالة وفيه غرر، هذا لا يجوز، أما إذا كان بينهم معروف، يعني باعه في أول الشهر والأجل بينهم إلى آخر الشهر لأنه صرف المعاش المعروف المعتاد، لا بأس بهذا. نعم.\nالمقدم: لكن أعتقد سماحة الشيخ يختلف لو مثلاً أعطاه شيئاً سلفة إلى أن يستلم معاش وهو طالب مثلاً، هل يجوز ذلك أو لا يجوز؟\nالسلفة خير، القرض أمره واسع، القرض ما فيه بأس لكن البيع، لا يبيع إلى أجل فيه غرر، إذا كان المعاش معروف هذا لا بأس، مثل آخر الشهر، أو آخر الشهر الثاني، أو الثالث، فلا بأس.","link":"https://binbaz.org.sa/fatwas/4478/حكم-الزيادة-في-البيع-على-بعض-المشترين-والنقص-لاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00814.mp3","categories":["البيوع"]},{"id":7604,"question":"يقول أيضاً في من ضمن أسئلته: ما حكم شرب الدخان وبيعه وثمنه، هل هو حرام أم مكروه، مع ذكر الدليل إن أمكن ذلك، وفقكم الله؟","title":"حكم شرب الدخان وبيعه","answer":"الجواب: أما شرب الدخان فلاشك في تحريمه وأنه من الخبائث التي حرمها الله عز وجل، لما فيه من الأضرار العظيمة التي بينها الأطباء وعرفها شاربوه، وهو من الخبائث التي حرمها الله في كتابه، وعلى لسان نبيه محمد عليه الصلاة والسلام، قال الله عز وجل في سورة المائدة: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4]، فبين سبحانه وتعالى أنه ما أحل إلا الطيبات، والله لنبيه يقول: قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4]، والرسول ﷺ مأمور أن يبلغ الناس أن الله أحل لهم الطيبات، ما أحل لهم الخبائث، والطيبات هي الأشياء النافعة المغذية التي كلها منفعة أو منفعتها غالبة وضررها قليل مغمور، هذه هي التي أباح الله من بهيمة الأنعام، من الحبوب الطيبة والثمار، من الفواكه، من الملابس الطيبة إلى غير ذلك، فالله إنما أباح الطيبات ولم يبح الخبائث، وكل شيء يغلب ضرره أو كله ضرر يحرم تعاطيه أكلاً وشرباً ولباساً ونحو ذلك، والدخان من هذا القسم كله ضرر، ونفعه وإن قدر فيه نفع فهو لا يعد.. مغمور في جنب مضاره الكثيرة عند من عرفه من الأطباء وغير الأطباء، وقد قال الله في وصف نبيه محمد ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157] فهو من الخبائث بلا شك، وقد توقف بعض أهل العلم في تحريمه، وبعضهم قال بكراهته، ولكن الذي عليه المحققون من أهل العلم الذين عرفوه هو تحريم ذلك، وأنه حرام بيعه، حرام شراؤه، حرام التجارة فيه، حرام شربه وتعاطيه، كل ذلك حرام، فالتجارة فيه محرمة، وشربه محرم، فيجب الحذر من ذلك، ويجب على أهل الإسلام الحذر من هذا الخبيث وتحذير الناس منه، ويجب على الدول الإسلامية أن تحاربه، وأن تمنع زراعته ودخوله في بلادها؛ لما فيه من الضرر العظيم على أبنائها، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/4657/حكم-شرب-الدخان-وبيعه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02104.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":7728,"question":"أيضاً يقول: إن هناك بعض الكروت التي تحمل عنوان عيد أو أعياد المسيحيين مثل الكرسمس وغيره، هل يجوز حملها أو توريدها أو ما شابه ذلك؟ أفيدونا وفقكم الله؟","title":"حكم بيع كروت التهاني بأعياد النصارى","answer":"الجواب: الذي يظهر لي أن هذا لا يجوز؛ لأن هذا فيه إشاعة لها، وربما اغتر بها بعض الناس فظن أنها جائزة، وربما أفضت إلى تقليدهم والتشجيع على تقليدهم في هذه الأعياد المبتدعة، فلا ينبغي أن تروج هذه البطاقات ولا ينبغي أن تتداول بين الناس، بل ينبغي إتلافها. نعم.","link":"https://binbaz.org.sa/fatwas/4927/حكم-بيع-كروت-التهاني-باعياد-النصارى ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03203.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":7926,"question":"سماحة الشيخ نبدأ أولًا برسالة عبد الرحمن بن عبد العزيز الحميضي من بلدة القصب، الوشم.يقول المستمع عبد الرحمن: السلام عليكم ورحمة الله، إنني أبعث إليكم هذه الرسالة، وأرجو من الله العزيز أن تصلكم وأنتم بخير وعافية، وتتضمن رسالتي هذه استفسارًا عن كتاب \"الدلائل الواضحات على تحريم المسكرات والمفترات\"، ويقول: فلقد قرأته وأعجبت به، ولكن لفت نظرنا في هذه الصور المرفقة برسالتي - هو أرفق ثمان صفحات في رسالته هذه سماحة الشيخ- من هذا الكتاب الذي اسمه أعلاه، وبخاصة ما ذكر من مضار الدخان، ومنها أن صاحبه إذا مات ولم يتب منه فإن وجهه يصرف عن القبلة، فإذا كان الكتاب وما فيه تنصحنا بقراءته فأرجو من كل إنسان وبخاصة الذين يشربون الدخان هذا، وأكتب رسالتي من أجله، والله يحفظكم ويرعاكم والسلام عليكم ورحمة الله.ويقول: أرجو من فضيلة الشيخ التعليق على مضار الدخان كما هو موضح في هذه الصور، والصورة يا سماحة الشيخ لا أستطيع عرضها في هذا المقام لأنها ثمان صفحات، لكني لخصت ما كتبه المؤلف في الأمور التالية:يقول: إن الدخان يجامع الحشيش في كثير من المفاسد والمضار، وينفرد كل منهما بمضار، فالدخان يفسد العقل، وأنه يسكر، وأنه يخدر، ويفتر، وأنه يورث الذلة والمهانة، ويهدم الشرف والمروءة، وأنه يفسد المزاج، وأنه يفسد العقل ويورث الحمق والرعونة، وأنه يورث قلة الغيرة، وأنه يصد عن ذكر الله وعن الصلاة، وأنه يضر بالصحة، وأنه يورث موت الفجأة، وأنه سببٌ لسوء الخاتمة، وقد ضرب قصصًا رويت له من بعض الناس، وأنه يكون سببًا لصرف الميت عن القبلة قبل دخول القبر وبعده، وأنه يسود القلب، نرجو كما يرجو عبد الرحمن أن تعلقوا على هذا.","title":"التعليق على كتاب: (الدلائل الواضحات على تحريم المسكرات والمفترات)","answer":"الجواب:\nبسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفأقول أولًا: إن المؤلف وهو أخونا العلامة الشيخ حمود بن عبد الله التويجري إنما يكتب عن علم وعن بصيرة، وعن سؤال أهل الخبرة في هذه المسائل وأشباهها، والدخان بلا شك مضاره كثيرة، وعواقبه وخيمة، وقد أخبر الأطباء الذين درسوه وعرفوه عن مضاره الكثيرة، كما أخبر من يعتاد شربه عن مضار أخرى كثيرة، فهو بلا شك ذو مضار كثيرة جدًا، منها: أنه يسبب موت الفجأة موت السكتة، ومنها كما ذكر جماعة من الأطباء أنه يسبب مرض السرطان والعياذ بالله. ومنها: أنه قد يفضي إلى الإسكار إذا أبطأ عنه صاحبه ثم شربه قد يتأثر به ويسكر. ومنها: أنه إذا أكثر منه قد يتضرر بذلك أكثر من جهة السكر والتخدير الكثير. هذه أشياء معلومة قد أخبرنا بها الكثير من الأطباء، وكتب فيها الناس، ومن ذلك: أنه يسبب أيضًا سواد القلب، فإن المعاصي تسود القلب كما في الحديث الصحيح عن النبي ﷺ أن العبد إذا أذنب نكتت في قلبه نكتة سوداء، فإن تاب وأناب صقلت، وإن أذنب مرة أخرى صارت نكتة أخرى سوداء، وهكذا إذا تاب عن المعاصي، تكون نكت كثيرة في القلب حتى يسود القلب وحتى يظلم، وحتى لا يعرف معروفًا ولا ينكر منكرًا، وهذا ليس خاصًا بالدخان بل يعم جميع المعاصي. فالدخان له مضار كثيرة، ومنها: أنه مضر بالصحة ضررًا كثيرًا، ومتلف للمال ومضيع للمال في غير حق وبغير فائدة، فهو بحق ذو مضار كثيرة ينبغي للعاقل أن يحذره وأن يتباعد عنه، فإنه مضر بصحته.. مضر بسمعته.. مضر بعقله، مضر بآخرته، فإنه قد يسبب كثيرًا من الشرور، ويسبب كثيرًا من الضيق والقلق والغضب الكثير وسرعة الانفعال، فينبغي للمؤمن أن يبتعد عنه، وأن يحذره غاية الحذر. ثم هو أيضًا يسبب مضرة الذرية، فإن الذرية يتأسون بأبيهم وأجدادهم وإخوانهم، فإذا تعاطاه الإنسان فإنه بذلك يسبب تعاطي ذريته لهذا الخبيث، وأن يصبحوا أسرى لشره وأضراره الكثيرة. وقد أخبر كثير من الناس أن شاربه قد يصرف عن القبلة كما ذكر الشيخ حمود، وهذه وقائع توجب الحذر، فإن اطلاع الناس على بعض الوقائع وإخبارهم عنها يسبب الحذر، ويقتضي الحذر من هذا الشيء الذي أخبر عنه من شاهده ومن وقع له أنه اقتضى كذا وكذا مما يضر العبد، فصرفه عن القبلة أخبر به بعض من شاهد المدخنين، ولا يلزم من ذلك أن يكون كل مدخن بهذه المصيبة، لكن هذا يقتضي أن هذا الأمر قد يسبب هذه الحالة المنفرة، كونه أن يصرف عن القبلة في حال بعد موته قبل أن يدفن وبعد أن يدفن، هذا لا شك يوجب الحذر منه ويوجب كراهة تعاطيه؛ لأنه مشتمل على المضار الكثيرة التي هذه منها. والحاصل أنه محرم بلا شك، ويجب تركه بلا شك لمضاره الكثيرة، أما تعدادها فيحتاج إلى عناية من الأطباء وبصيرة ممن اعتاده فإنه أعلم به وأقدر على تعداد مضاره، الأطباء والذين ابتلوا بشربه والاكتياء بشره وناره هم أعلم الناس بمضاره الكثيرة. فنصيحتي لكل مسلم: أن يحذر هذا الخبيث، وأن يتباعد عنه، كما أني أنصح أن يحذر كل مسلم جميع المسكرات، جميع أنواع الخمور، جميع أنواع التدخين، جميع أنواع المفترات، وهكذا الحشيشة فإن مضارها كثيرة وخبيثة فيجب الحذر منها غاية، فهذه الأمور التي ذكرها السائل وذكرها الشيخ حمود في الكتاب يجب على المؤمن أن يتباعد عنها حفظًا لصحته، وحفظًا لعقله، وحفظًا لشرفه، وابتعادًا عن المضار التي تضر دينه وعقله وبدنه وسمعته وذريته، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5434/التعليق-على-كتاب-الدلاىل-الواضحات-على-تحريم-المسكرات-والمفترات","audio":"https://files.zadapps.info/binbaz.org.sa/008201.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":7993,"question":"أيضاً لديه سؤال في نفس التبادل بالذهب يقول: إذا كان صاحب الذهب الذي يريد بدلاً منه من نوعه، فإنه يبيعه على صاحب الدكان الذي يتبدل منه فيغريه بزيادة ليزيد عليه من الناحية الأخرى، أما إذا لم يرد بدلاً منه فإنه لا يعطيه تلك الزيادة أو الثمن الذي يعطى في المبادلة، فهل هذا كذلك من الربا أم لا؟الشيخ: أعد.. أعد السؤال.المقدم: يقول: إذا كان صاحب الذهب الذي يريد بدلاً منه من نوعه، فإنه يبيعه على صاحب الدكان الذي يستبدله أو يبدله منه فيغريه بزيادة، -يعني: صاحب الدكان يغري صاحب الذهب بزيادة- ليزيد عليه من الناحية الأخرى، يعني: في الذهب الذي سيعطيه هذا الذي أتى ليأخذ ذهباً، أما إذا لم يرد بدلاً منه فإنه لا يعطيه تلك الزيادة في الثمن، فهل يعتبر هذا .... ؟","title":"حكم البيعتين في بيعة","answer":"الجواب: هذا لا يصلح أيضاً؛ لأنه بيع في بيع، عقدان في بيع، يعني: صفقتان في صفقة، فلا يجوز؛ ولهذا قال النبي ﷺ: لا يحل سلف وبيع فهو يقول له: إن شريت مني زدتك بكذا، وإن ما شريت مني ما أزيدك، فالمعنى: أنه شرط بيعاً في بيع واشترط أيضاً زيادة إذا كان يشتري منه يزيده شيئاً، وإن كان ما يشتري منه ما يزيده هذا الشيء، فلا يصلح. نعم.","link":"https://binbaz.org.sa/fatwas/5541/حكم-البيعتين-في-بيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07302.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8054,"question":"سؤالها الثاني تقول: هل يجوز استعمال شيء من أموال الزكاة في شراء ذهب وغيره أم لا؟","title":"حكم شراء المرأة الفقيرة للذهب من أموال الزكاة","answer":"الجواب: إذا كانت المرأة فقيرة، وأعطيت من الزكاة شيئاً من المال، وأحبت أن تشتري منه سلعةً تلبسها من الذهب والفضة، فلا حرج في ذلك؛ لأن هذا من الأمور العادية، مثل ما تلبس الملابس الجميلة في المناسبات، وإن كانت من أهل الزكاة، فلا حرج عليها أن تشتري من مال الزكاة الذي دفع إليها، حاجتها من الملابس الذهبية وغيرها. نعم.","link":"https://binbaz.org.sa/fatwas/5849/حكم-شراء-المراة-الفقيرة-للذهب-من-اموال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08202.mp3","categories":["إخراج الزكاة وأهلها","البيوع","قضايا المرأة"]},{"id":8130,"question":"يقول: ما حكم بيع السيارات الفخمة الغالية الثمن والأثاث الغالي الثمن أيضاً؟","title":"حكم شراء الأثاث والسيارات الغالية الثمن","answer":"الجواب: هذا أمره واسع، إذا كان المشتري قادر، وليس قصده الإسراف ولا المفاخرة، إنما يريد الطيب الذي من باب الجمال أو من باب الزينة وهو أهل لذلك؛ لأن عنده المال وعنده القدرة، فلا نعلم فيه شيء، إذا اشترى سيارة فخمة أو فراشاً طيباً ما نعلم فيه شيء، لكن التواضع طيب، إذا تواضع لله واستعمل الشيء الوسط، يكون أفضل، يكون أفضل وأقصد، حتى يتمكن من صرف الزيادات في الصدقة، والمساعدة للفقراء، والمساهمة في المشاريع الخيرية، فالحاصل أن الاقتصاد والتوسط في الأمور أفضل، ولو اشترى شيئاً جميلاً نفيساً من السيارات أو من الفرش؛ لأنه قادر ويريد بذلك الجمال لا المفاخرة ولا المباهاة، فلا حرج في ذلك إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/5932/حكم-شراء-الاثاث-والسيارات-الغالية-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08804.mp3","categories":["الآداب والأخلاق المحمودة","البيوع"]},{"id":8144,"question":"شيخ عبد العزيز وردتنا هذه الرسالة من مقدمها محمد شاهر القومي يقول فيها: نقص علي فلوس حوالي عشرين ألف ريال، ولم أجد سلف، ورحت لواحد يعطي الدنية الدينة علي عدد صناديق أقمشة، ويقول: إنني بعدما اشتريت منه الصناديق، قال: ضع يدك عليها، ووضعت يدي عليها قال: هل عددتها؟ قلت: نعم، فقال صاحب الدكان أو الذي باعها علي: هل تريد أن تبيعها في السوق أو تبيعها على صاحب الدكان؟ قال صاحب الدكان: أتنازل من رأس المال مائتين ريال، وعد لي صاحب الدكان المبلغ تسعة عشر ألف وثمانمائة ريال وقال لي المدين: العشرين ألف تصبح عليك بمبلغ وقدره ثمانية وعشرين ألف، كل شهر يبلغ كذا وكذا التسديد. يقول: نريد أن نعرف صحة هذا البيع وهذا الشراء وفقكم الله، وهل هو من الربا؟","title":"صورة مسألة التورق وحكمها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه من اهتدى بهداه.\nأما بعد:\nفهذه المسألة يسميها الفقهاء: مسألة التورق، وهي مشهورة عند العامة بالوعدة، وهي ما إذا احتاج الإنسان إلى نقود لزواج أو لتعمير بيت، أو لقضاء دين أو لأشباه ذلك، ولم يجد من يقرضه، فإنه يحتاج إلى أن يشتري سلعاً إلى أجل ثم يبيعها على الناس بنقد، حتى يستفيد من النقد، وهذا العقد فيه خلاف بين أهل العلم، من أهل العلم من قال: إنه لا يجوز؛ لأنه دراهم بدراهم، ولأن المقصود دراهم بدراهم، يروى هذا عن عمر بن عبد العزيز وجماعة.\nوالقول الثاني: إنه لا بأس به، ولا حرج فيه، وهو من المداينة الشرعية، التي قال الله فيها سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282]، وهذا هو الصواب، وهو داخل في قوله: وَأَحَلَّ اللَّهُ الْبَيْعَ [البقرة:275]، فالصواب أن هذه المعاملة وهي معاملة التورق التي تسمى: الوعدة، صحيحة في الجملة، لكن بشروط: منها: أن يكون البايع قد ملك السلعة، ما يبيع شيء ما هو عنده عند الناس، ما يبيع إلا شيء قد ملكه وحازه في بيته، أو في دكانه أو في السوق؛ لأن النبي عليه السلام قال: لا تبع ما ليس عندك، وقال: لا يحل سلف وبيع، ولا بيع ما ليس عندك، فليس له أن يبيع ما عند الناس يروح هو والمشتري يعطيه من عند التجار، لا، بل يشتري أول ويحوزه، فإذا حازه في بيته أو في السوق أو في دكانه بعد ذلك يبيع، ثم المشتري الذي شراه لا يبيعه على صاحب الدكان ولا على غيره، حتى يحوزه أيضاً، حتى ينقله إلى السوق أو إلى بيته أو إلى دكانه ثم يبيعه، وبهذا يعلم أن هذه الصورة التي سأل عنها السائل غير صحيحة، وضع اليد على الصناديق ما يكفي، ولا عدها ما يكفي على الصحيح المعروف عند أهل العلم، مجرد العد لا يكفي لابد من قبض لابد من استيفاء المبيع، ولهذا ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لا تبع ما ليس عندك، قال: لا يحل سلف وبيع، ولا بيع ما ليس عندك، ونهى عليه الصلاة والسلام أن تباع السلع حيث تبتاع حتى يحوزها التجار إلى رحالهم، فالتاجر ممنوع أن يبيع ما ليس عنده، وهكذا غيره من الناس حتى يحوزها إلى رحله، قال ابن عمر: كنا نشتري الطعام جزافاً على عهد النبي ﷺ، وكنا نضرب إذا بعناه في محلنا، حتى ننقله إلى رحالنا وفي لفظ: من أعلى السوق إلى أسفله، ومن أسفله إلى أعلاه.\nوالخلاصة أن هذا البيع الذي سأل عنه السائل لا يصح؛ لأنه باع ما لم يقبض، باعه البايع شيئاً لم يقبضه، ثم هو باع على راعي الدكان ما لم يقبض فلا يصلح، لا يصلح هذا البيع، وليس للبايع إلا الدراهم التي سلمها له صاحب الدكان، لأنها هي ثمن المثل، هي ثمن المثل، فيعطيه ثمن المثل، أو يرد عليه من جنس ما شراه من السلعة التي شراها منه، يعني اشترى منه سلعة معروفة ولم يقبضها القبض الشرعي، فباعها قبل ذلك فليس له بيعها، بيعها غير صحيح وحينئذ فهي باقية في عصمته، عليه أن يقبضها ويبيعها يتصرف فيها حيث شاء، والشخص الذي أعطاه الدراهم يرد عليه الدراهم فقط دراهمه، الذي أعطاه الدراهم يردها عليه بنفسها؛ لأنه باعه شيء لم يقبضه، والشخص المشتري للصناديق وأشباهه كالسكر وكالخام وأشباه ذلك، هذا تبقى السلعة على حسابه، فيرد قيمتها ذلك الوقت، أو يردها إن كانت موجودة بعينها على بائعها.\nوالحاصل أن البيع الأخير غير صحيح؛ لأنه باع ما لم يقبض، والبيع الأول غير صحيح، إذا كان باعه شيء لم يقبضه، أما إن كان قد قبضه، ونقله إلى دكانه أو إلى السوق يصح؛ لأن هذا الرجل ما قبض لا الأول ولا الآخر كلاهما ما قبض، فقد باع شيئاً لم يقبضه فلا يصح، والبيع غير صحيح، وليس للبايع إلا الدراهم التي سلمها المشتري الأخير، سلمها البايع الأخير بل المشتري الأخير؛ لأنه اشتراها منه بنقد، فله جنس تلك الدراهم التي سلمها لصاحب الوعدة، الذي هو صاحب التورق المحتاج، فإذا كان مثلاً شراها من الأول مثلاً بألفين، ثم باعها على صاحب الدكان بألف وستمائة، فالذي يلزمه هو الألف والستمائة؛ لأن الألف والستمائة هي التي قبضها فيردها فقط، نعم، يردها على الذي باع عليه السلعة، والأول بيعه ما صح. نعم.","link":"https://binbaz.org.sa/fatwas/5942/صورة-مسالة-التورق-وحكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08901.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8156,"question":"هذه الرسالة وردتنا من العراق من ياسين العبد الحليم العراق محافظة نينوى ناحية الشورة، يقول في رسالته: يوجد شخصان أحدهما يملك سيارة، والآخر يريد أن يشتريها منه، فقال له الرجل الذي يملك السيارة: إن تدفع النقود نقداً عليك بمبلغ ثمانية آلاف، أما إن تدفع النقود غير نقد، تعطيني كل شهر كذا فهي عليك بعشرة آلاف، أي: مبلغ السيارة، أفيدونا جزاكم الله عنا خيراً، هل هذا صحيح أم لا؟","title":"حكم الزيادة في بيع الآجل","answer":"الجواب: لا حرج في ذلك، أن يقول: السيارة نقداً بكذا ومؤجلة بكذا، السيارة أو البيت أو الدكان أو الأرض أو سلعاً أخرى لا بأس، هذا هو الصواب الذي لا شك فيه، لكن لا يتفرقون إلا وقد قطعوا البيع، فإن تفرقوا ولم يقطعوا البيع ما تم شيء، لم يتم شيء، فإذا تفرقوا على أن البيع بثمانية آلاف نقداً صح، وإن تفرقوا على أن البيع بعشرة آلاف كل شهر خمسمائة أو كل شهر ألف فلا بأس بذلك على ما تفرقوا عليه من أجل أو نقد. نعم.","link":"https://binbaz.org.sa/fatwas/5954/حكم-الزيادة-في-بيع-الاجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09006.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8159,"question":"هذه رسالة وردتنا من أحد السادة المستمعين، يقول في رسالته: في بعض المحلات لبيع الذهب تباع ميداليات مكتوب عليها آيات قرآنية أو كلمة (الله)، فهل يجوز أن تقول للبائع: بعنا هذه الميدالية أم أهدها لنا، باعتبار أنا سوف نعطي له ثمن هذه الميدالية كهدية مقابل هدية أخرى، نرجو توضيح ذلك لنا وللناس وفقكم الله؟","title":"حكم بيع وشراء الذهب المكتوب عليه آيات قرآنية","answer":"الجواب: هذه أشياء تعم بها البلوى، وشراؤها وبيعها جائز، وإنما الكلام في لبسها، وقد كتب عليها الآيات أو كلمة الله، وقد يتعرض بها الإنسان دخول الأماكن القذرة، فالأولى في مثل هذا أن الآيات التي فيها تزال، كلمة (الله)، حتى لا يمتهن هذا الأمر، قد لا تلقى في محلات، يعني: تمتهن فيها مع الأشياء التي قد تلقيها المرأة في صندوقها، أو في أشياء تلقى في وسط الصندوق، أو في وسط الدولاب، يكون فيه نوع من الامتهان.\nفالحاصل أن هذه القلائد ونحوها التي يكتب فيها الآيات، الأولى ألا تكتب الآيات، وأن يسعى صاحبها في إزالة الآيات التي فيها حتى لا تمتهن، أو يعتقد فيها كما يعتقد أرباب التمائم الذين يعلقون التمائم، في قراطيس يجمعونها ويعلقونها كتميمة، أو في رقاع أخرى، فالحاصل أن كتابة الآيات فيها إيهام وفيها خطر، قد يتخذ هذا للحروز، واتقاء الجن، أو اتقاء العين أو ما أشبه ذلك، فتكون من باب التمائم، فلا ينبغي اتخاذها، وقد يكون المتخذ لها ما أراد هذه الأشياء، ولكن يخشى أن يزين له بعض الناس أن هذا كذا وأن هذا كذا، فيقع فيما يتعلق بالتمائم.\nفالمطلوب أنه يشتري هدية ليس فيها هذه الآيات؛ حتى لا يقع فيما يقع به من يقصد التمائم، وحتى لا يمتهنها في الحمامات وأشباهها من المواضع القذرة. نعم.","link":"https://binbaz.org.sa/fatwas/5974/حكم-بيع-وشراء-الذهب-المكتوب-عليه-ايات-قرانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_091/09106.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8165,"question":"هذه رسالة وردتنا من أحد السادة المستمعين، يقول في رسالته: في بعض المحلات لبيع الذهب تباع ميداليات مكتوب عليها آيات قرآنية أو كلمة (الله)، فهل يجوز أن تقول للبائع: بعنا هذه الميدالية أم أهدها لنا، باعتبار أنا سوف نعطي له ثمن هذه الميدالية كهدية مقابل هدية أخرى، نرجو توضيح ذلك لنا وللناس وفقكم الله؟","title":"حكم بيع وشراء الذهب المكتوب عليه آيات قرآنية","answer":"الجواب: هذه أشياء تعم بها البلوى، وشراؤها وبيعها جائز، وإنما الكلام في لبسها، وقد كتب عليها الآيات أو كلمة الله، وقد يتعرض بها الإنسان دخول الأماكن القذرة، فالأولى في مثل هذا أن الآيات التي فيها تزال، كلمة (الله)، حتى لا يمتهن هذا الأمر، قد لا تلقى في محلات، يعني: تمتهن فيها مع الأشياء التي قد تلقيها المرأة في صندوقها، أو في أشياء تلقى في وسط الصندوق، أو في وسط الدولاب، يكون فيه نوع من الامتهان.\nفالحاصل أن هذه القلائد ونحوها التي يكتب فيها الآيات، الأولى ألا تكتب الآيات، وأن يسعى صاحبها في إزالة الآيات التي فيها حتى لا تمتهن، أو يعتقد فيها كما يعتقد أرباب التمائم الذين يعلقون التمائم، في قراطيس يجمعونها ويعلقونها كتميمة، أو في رقاع أخرى، فالحاصل أن كتابة الآيات فيها إيهام وفيها خطر، قد يتخذ هذا للحروز، واتقاء الجن، أو اتقاء العين أو ما أشبه ذلك، فتكون من باب التمائم، فلا ينبغي اتخاذها، وقد يكون المتخذ لها ما أراد هذه الأشياء، ولكن يخشى أن يزين له بعض الناس أن هذا كذا وأن هذا كذا، فيقع فيما يتعلق بالتمائم.\nفالمطلوب أنه يشتري هدية ليس فيها هذه الآيات؛ حتى لا يقع فيما يقع به من يقصد التمائم، وحتى لا يمتهنها في الحمامات وأشباهها من المواضع القذرة. نعم.","link":"https://binbaz.org.sa/fatwas/5974/حكم-بيع-وشراء-الذهب-المكتوب-عليه-ايات-قرانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_091/09106.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8212,"question":"الرسالة التالية باعثها أخونا: محمد أحمد تركي سوداني مقيم في المدينة المنورة يقول: لقد وجد بعض الناس عندنا وهم يحتكرون السلع الاستهلاكية وقت الوفرة خاصة الحبوب، ثم القيام بتخزينها حتى تتصاعد أسعارها وتصبح جنونية -كما يقول- فيبيعونها وهم في أماكنهم بما يشتهون، فبماذا ينصح الإسلام أمثال هؤلاء، وما هو موقف الشرع من كسبهم هذا؟","title":"حكم الاحتكار","answer":"الجواب: المحتكر: هو الذي يشتري السلع وقت مضايقة الناس، وقد جاء في الحديث لعن ذلك والوعيد فيه، والنبي ﷺ قال: لا يحتكر إلا خاطئ، وقال: من احتكر فهو خاطئ يعني: فهو آثم.\nقال العلماء: هم الذين يشترون السلع يعني: الطعام ونحوه مما يحتاجه الناس في وقت الشدة، ويخزنه إذا اشتد الغلاء حتى يبيعه بأكثر، هذا ما يجوز ومنكر وصاحبه آثم، ويجب على ولي الأمر إذا كان في البلاد ولي أمر ينفذ أمور الشرع، يجب على ولي الأمر أن يمنعه من ذلك، وأن يلزمه بيع الطعام بسعر المثل بسعر الوقت الحاضر الذي في الأسواق، ولا يمكنه من خزانته، هذا إذا كان في وقت الشدة.\nأما الذي يشتري الطعام أو غير الطعام مما يحتاجه الناس في وقت الرخاء وكثرته في الأسواق، وعدم الضرر على أحد، ثم إذا تحركت السلع باعه مع الناس من دون أن يؤخره إلى شدة الضرورة، بل متى تحركت وجاءت الفائدة باعه فلا حرج عليه، وهذا عمل التجار في قديم الزمان وحديثه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6025/حكم-الاحتكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09511.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8251,"question":"هنا رسالة باعثها أحد الإخوة يقول حامد فرحان من جدة، أخونا يقول: رجل تاب إلى الله  وعنده فيديو وأشرطة أفلام خليعة فهل يجوز له بيعها، وإذا كان لا يجوز بيعها فماذا يعمل بها؟ وهل يجوز أن يسجل فيها الخطب والبرامج والمشاهد المفيدة؟","title":"يملك أشرطة فيديو خليعة هل يجوز بيعها؟","answer":"الجواب: نعم، يسجل فيها ما ينفعه وهذا يمسح ما فيها من الباطل، يسجل فيها الطيب؛ وقد ذكر أهل الخبرة بأنه إذا سجل فيها غير ما فيها انمسح الذي فيها من الباطل، فإذا سجل فيها الطيب انتفع بها والحمد لله.\nأما بيعها فلا يجوز بيعها وهي على حالها الرديئة. نعم.","link":"https://binbaz.org.sa/fatwas/6065/يملك-اشرطة-فيديو-خليعة-هل-يجوز-بيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09806.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8513,"question":"هذه رسالة وردتنا من المرسل عبد الله أحمد عطية الزهراني من تهامة، يقول: أستفسر عن بيع السلعة بثمن أكثر من بيع النقد، وذلك بالمهلة لستة أشهر أو أكثر، كأن أشتري سيارة قيمتها بالنقد خمسة عشر ألف ريال، وأبيعها بثلاثة وعشرين ألف ريال مؤجلة، فهل هذا البيع جائز؟","title":"حكم البيع إلى أجل مع زيادة في الثمن","answer":"الجواب: لا حرج في هذا والحمد لله، لا بأس أن يبيع السلعة التي تساوي خمسة عشر بعشرين.. بثلاث وعشرين سيارة أو غيرها، لا بأس بهذا، وهكذا بيع الأقساط؛ أن يبيعها بأقساط.. كل شهر كذا.. كل سنة كذا، كله لا بأس به، وهذا من رحمة الله؛ لأن الناس ليسوا على حد سواء، فيهم من عنده النقود، وفيهم من يعجز عن النقود إلا مؤجلة، وقد صح عن رسول الله صلى الله عليه وسلم أنه أقر بيع بريرة ، وقد باعها أصحابها بتسع أواق في كل عام أوقية، وهذا بيع بالأقساط، فالمقصود أن بيع ما يساوي عشرة بخمسة عشر.. ما يساوي عشرين بخمس وعشرين إلى أجل معلوم لا حرج فيه؛ لأجل حاجة المشتري ولانتفاع البائع بالزيادة التي أجلت، فلا حرج في هذا عند أهل العلم، وقد جاءت به النصوص. نعم.\nالمقدم: جزاكم الله خير. وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6594/حكم-البيع-الى-اجل-مع-زيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20311.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8534,"question":"هذه رسالة وردتنا من العراق من محافظة صلاح الدين من السائل سالم مصطفى سالم، يقول في رسالته: قمت ببيع محصول زراعي بشكل جملة على ثلاثة بقالين، والمفروض أن يعطوني الثمن دفعة واحدة، إلا أنهم أعطوني كل واحد على حدة، وعندما ركبت السيارة وقمت بعد المال وجدت زيادة، ولما أخبرت السائق لم يأبه للتأكد ولو رجع لأعطيتهم الزيادة، فأكلت الزيادة فهل هي حرام أم حلال؟","title":"حكم أخذ البائع الزيادة على الثمن المتفق عليه","answer":"الجواب: نعم، عليك أن ترد الزيادة، وليس لك أن تأكلها إذا أعطوك الثمن وزاد الثمن فقد غلطوا، فعليك أن ترد الزيادة إليهم إذا عرفتهم، فإن لم تعرفهم وذهب عليك العلم بهم بعد الاجتهاد تصدقت بها عنهم في الفقراء والمساكين، أما إذا عرفتهم فعليك أن تردها إليهم إما بنفسك وإما برسول ثقة يذهب بها إليهم. نعم.\nالمقدم: جزاكم الله خير يعني: لابد أن يعيد الزيادة؟\nالشيخ: نعم.\nالمقدم: بارك الله فيك.\nالشيخ: لأنها دخلت عليه بغير حق، غلطاً منهم. نعم.","link":"https://binbaz.org.sa/fatwas/6625/حكم-اخذ-الباىع-الزيادة-على-الثمن-المتفق-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20516.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8546,"question":"هذه رسالة مقدمة من الأخ (س. م. ت) من الرياض، يقول في رسالته: أنا شاب وأملك جهاز فيديو، وتعلمون أن هذا الجهاز لا يجلب إلا شر -والعياذ بالله- مما يعرض فيه من أفلام ساقطة خليعة؛ ولعلمي بذلك فقد قررت بيعه مستعيناً بالله، فهل يجوز ثمنه أم أن أهديه لشخص غير مسلم كمسيحي أو بوذي، أم أحرقه، أم أتلفه، ماذا أفعل؟","title":"حكم بيع الأفلام وأجهزة الفيديو","answer":"الجواب: لاشك أن الفيديو فيه خطر كبير على المسلمين بسبب الأفلام الخبيثة التي فيه، فإذا كانت الأفلام كما أشار السائل رديئة، فالواجب إحراقها، أو عمل ما يزيل ما فيها مما سجل فيها بأشياء طيبة؛ لأنه بلغني أنه إذا سجل فيها شيء أزال ما قبله وسلم الشريط لصاحبه ينتفع به، فإذا أمكن أن يزال ما فيها من الشر بإملاء شيء طيب وتسجيل شيء طيب فالحمد لله، وإلا وجب إحراقها، وليس لك أن تبيعها وليس لك أن تهديها؛ لأن هذا من باب التعاون على الإثم والعدوان.\nالمقدم: هذا بالنسبة للأفلام؟\nالشيخ: للأفلام نعم.\nالمقدم: أما الجهاز؟\nالشيخ: أما الجهاز نفسه يباع؛ لأنه يوجد فيه الشر والخير، مثل الراديو وأشباهه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6622/حكم-بيع-الافلام-واجهزة-الفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20513.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8787,"question":"المستمع (أ. ش. م) مصري العنوان: قنا الوقف، بعث برسالة للبرنامج، يقول فيها: هناك البعض يقوم بتهريب بعض السلع ودخولها إلى الدولة، علماً بأن الدولة تمنع استيراد هذه السلعة، أي: الفاكهة، ويقومون ببيعها إلى بعض الأفراد، فيشترونها ويقومون ببيعها إلى تجار الفاكهة بثلاثة أمثال سعر الشراء، أو ضعف سعر الشراء، ويقومون التجار ببيعها بضعف سعر الشراء من الأفراد، أي: الكيلو الواحد يصل إلى المستهلك بأربعة أضعاف سعر الشراء من الأفراد الذين يقومون بتهريبها ودخولها إلى الدولة؛ نظراً لوساطة الأفراد والتجار، علماً بأن سعر الكيلو كان يساوي ثمن السعر الحالي، قبل أن يمنع استيراده، فهل هذه الأموال للذين يقومون بالوساطة بين المهربين والتجار، وأيضاً المكاسب التي يأخذها التجار حرام أم حلال؟ وإن كانت هذه الأموال حرام، فكيف يتم التصرف فيها، وما حكم الدين في كسب هذه الأموال، أفيدونا أفادكم الله؟","title":"حكم تهريب السلع إلى داخل البلاد بدون إذن الدولة","answer":"الجواب: إذا كانت الدولة منعت من استيراد الأشياء لمصلحة المسلمين، ومصلحة الشعب؛ ولأن استيرادها يضر الشعب في دينه أو دنياه، فالواجب على الشعب أن يمتثل ما فعلته الدولة؛ لأنها تهدف إلى المصلحة العامة، وتهدف إلى حماية الشعب مما يضره، وحماية المسلمين مما يضرهم، فلا يجوز التهريب الذي يخالف ما نصت عليه الدولة، ويسبب وقوع المشاكل بين الشعب والدولة، ويوقع في الحرام أيضاً، فالواجب على الشعب أن يمتثل وأن يساعد الدولة في منع ما ينبغي منعه، وفي بقاء ما ينبغي بقاؤه؛ لأن ذلك فيه التعاون على ما فيه مصلحة الجميع.\nأما إذا كان ذلك التهريب الذي وقع من بعض الناس فيما يتعلق بالحرام كتهريب الخمور، وتهريب ما حرم الله هذا يكون أشد وأعظم، حتى لو ..... به الدولة، لا يجوز إدخاله البلاد، ولا يجوز التعاون في فعله؛ لأنه يضر المجتمع في دينه، فلا يجوز للمسلم أن يسبب وقوع المسلمين فيما حرم الله عليهم من خمر أو تدخين، أو غير هذا مما حرم الله عز وجل، بل يجب أن يساعد في منع ذلك، لو قدر أن الدولة لم تمنعه، فكيف إذا منعته، فإن الواجب أن نساعدها في ذلك، وأن يكون معها في منع كل ما يضر المسلمين، وفي منع كل ما حرم الله ؛ لأن هذا من باب التعاون على البر والتقوى. نعم.","link":"https://binbaz.org.sa/fatwas/6942/حكم-تهريب-السلع-الى-داخل-البلاد-بدون-اذن-الدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22005.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8905,"question":"أخونا أيضاً يقول: بعض المحلات تبيع الأشياء المباحة وأشياء محرمة، هل يجوز للمسلم أن يرتاد تلك المحلات كيما يشتري ما هو مباح منها رغم أنها تبيع الأشياء المحرمة؟","title":"حكم الشراء من المحلات التي تبيع المباح والحرام","answer":"الجواب: لا حرج على الإنسان أن يتصل بالدكاكين والحوانيت أو غيرها من الأسواق ويشتري حاجته منها المباحة وإن كان يوجد فيها بيع لشيء محرم؛ لأن الله يقول: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164]، لكن إذا كان يستطيع إنكار ذلك فعليه إنكار المحرم والتحذير منه وأنه لا يجوز بيع هذا المحرم، وإذا تيسر سوق أو دكان يبيع المباح دون المحرم فهذا أولى؛ لأن فيه تشجيعاً له وفيه بعد عن مساعدة أهل الحرام وأهل المضرة بالناس، فإذا تيسر له دكان أو سوق يبيع حاجاته المباحة فلينتقل إليه وليشتر وليعامله، وليترك ذاك الذي قد خلط حلالاً بحرام حتى لا يكون مشجعاً له، أما إذا دعت الحاجة إلى أن يشتري من ذاك الدكان فلا حرج إن شاء الله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7061/حكم-الشراء-من-المحلات-التي-تبيع-المباح-والحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_141/14102.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":8993,"question":"الرسالة التالية من السودان أيضًا وباعثها أخونا عبدالخالق مشدود عبدالوهاب من شركة الأسمنت من عطيرة فيما يبدو، أخونا يثني ثناءً عطرًا في مقدمة رسالته ويطرح بعض الأسئلة، سؤاله الأول: ما حكم الإسلام في التهريب للسلع العادية وليست المحرمة؟","title":"حكم تهريب السلع المباحة","answer":"الجواب: ليس للرجل ولا لغير الرجل أن يهرب السلع التي منعتها الدولة، ليس له أن يهرب، وإذا كانت محرمة صار الإثم أكبر؛ لأن التهريب يضر الناس، ويضر إخوانه في البيع والشراء، ويخالف الدولة، والمسلم مأمور بالسمع والطاعة في المعروف، وهذا من المعروف؛ لأن الدولة قد ترى المصلحة في ذلك.\nفالمقصود أنه ليس له التهريب، وأما ما هو محرم كالمخدرات وأنواع الخمور وما أشبه ذلك مما حرمه الله فهذا لا يجوز توريده ولو كان بغير تهريب فكيف بالهريب؟ فهو محرم بكل حال، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا، من فعل ذلك سماحة الشيخ؟\nالشيخ: يستحق أن يعاقب بما يراه ولي الأمر؛ لأن العقوبات يردع الله بها عن الإجرام، يقول عثمان بن عفان الخليفة الراشد : «إن الله يزع بالسلطان ما لا يزع بالقرآن».\nوكثير من الناس لا يردعه إيمانه ولا يردعه خوفه من الله وإنما يردعه العقوبة السلطانية، العقوبة في ماله في بدنه بالسجن، نعم، ونحو ذلك.\nالمقدم: بارك الله فيكم، الواقع سماحة الشيخ ميزة يمتاز بها الإسلام ولعلها فرصة تتفضلوا بشرحها وإلقاء الضوء عليها، تلكم الميزة هي وضع دستور واضح وصريح وصلاحيات واسعة أمام ولي الأمر كيما يتخذ من الأحكام ما يصلح الأمة؟\nالشيخ: نعم، في باب التعزيرات التي ينفع الله بها المسلمين، وفي باب التنظيمات التي ينفع الله بها المسلمين، هذه متروكة لولي الأمر، يضع نظام مرور، يضع نظام آخر لا يخالف الشرع فيما يتعلق بالبيع والشراء ونحو ذلك في الأسواق، وفي غير ذلك مما لا يخالف الشرع، وهكذا العقوبات التي تردع الناس عن المعاصي التي ليس فيها حدود، له أن يضع ما يراه مناسبًا وعليه أن يستشير أهل العلم في ذلك حتى يضع العقوبات المناسبة للجريمة التي تناسبها العقوبة.","link":"https://binbaz.org.sa/fatwas/7151/حكم-تهريب-السلع-المباحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17604.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9062,"question":"السؤال الأخير الذي نعرضه من أسئلة أخينا عن حكم بيع التورق؟","title":"حكم بيع التورق (الوعدة)","answer":"الجواب: التورق معاملة معروفة عند أهل العلم فيها خلاف بين أهل العلم، والصواب أنه لا بأس بها، فالمعاملة التي يسمونها التورق ويسميها العامة الوعدة هي أن يبيع الإنسان سلعة على إنسان محتاج إلى أجل معلوم، وهذا المشتري يبيعها بعدما يقبضها يبيعها بنقد ويقضي بها حاجته من زواج أو قضاء دين أو بناء سكن أو غير ذلك، فيأتي زيد وهو محتاج إلى عمرو وهو من التجار ويقول له: أريد سيارة، أو أريد أكياس من أرز أو من السكر أو كذا تبيعني إياها إلى أجل معلوم فيقول: نعم، فيتفقان على ثمن معلوم وعلى أقساط معلومة فيتم البيع على ذلك، وهذا المشتري بعدما يقبضها ويحوزها إليه يتصرف فيها كما يشاء يبيعها بثمن معجل حتى يقضي حاجته من زواج أو قضاء دين أو غير ذلك.\nولكن يقع في هذا أخطاء لهؤلاء ولهؤلاء ينبغي التنبيه عليها بل يجب التنبيه عليها، وقد نبهنا عليها كثيرًا في هذا البرنامج وفي غيره، وهي أن البائع قد يبيع ما ليس عنده، التاجر قد يبيع سيارة ما هي بعنده عند التجار، أو عند الشركات، قد يبيع أكياس من الرز ما هي بعنده وبعد البيع يذهب يشتريها هذا لا يجوز، النبي ﷺ قال: لا تبع ما ليس عندك وقد صح عنه عليه السلام: أنه نهى أن تباع السلع حيث تبتاع حتى يحوزها التجار إلى رحالهم وجاءه حكيم بن حزام  فقال: يا رسول الله! الرجل يأتيني يريد السلعة فأبيعها عليه ثم أذهب فأشتريها، قال: لا تبع ما ليس عندك.\nفالحاصل أن البائع قد يخطي والمشتري قد يخطي، فالبائع قد يبيع ما ليس عنده ثم يذهب يشتري، وهذا لا يجوز، بل لا يبيع سيارة ولا أكياس ولا خام ولا كذا إلا إذا كان عنده في حوزته في ملكه في بيته في دكانه، والمشتري المحتاج ليس له أن يبيع أيضًا حتى يقبض، لا يبيعها على الذي باع عليه، ولا يبيعها وهي عنده، بل يقبضها وينقلها إلى بيته أو إلى السوق أو إلى بيت فلان أو دكان فلان، يعني: ينقلها من بيت البائع من محل البائع ثم يتصرف بعد ذلك، هكذا يجب على هذا وهذا، فإذا باع أحدهما قبل أن يقبض فهذا هو الذي لا يجوز وهو الذي يخل به كثير من الناس وتأتي المشكلة من هذا الجانب، والله ولي التوفيق، نعم.\nالمقدم: جزاكم الله خيرًا، إذا كان هناك اتفاق سماحة الشيخ بين هذا البائع وبين المتورق أو الذي في حاجة إلى نقود على أن العشرة تكون بثلاثة عشر أو بخمسة عشر أو ما أشبه ذلك، هل ترون جواز هذا؟\nالشيخ: ما يضر، الاتفاق ما يضر لكن لا يتم بيع إلا بعد ذلك.\nالمقدم: لا يتم البيع.\nالشيخ: إلا بعد ذلك، إلا بعد القبض والحوز، لو جاءه قال أنا ..............","link":"https://binbaz.org.sa/fatwas/7220/حكم-بيع-التورق-الوعدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17807.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9231,"question":"وهذه رسالة وردتنا من علي إبراهيم علي من جمهورية السودان، يقول: إن عمي أخي والدي له مال يشغله بالأرباح الربوية على الناس بزيادة خمسين بالمائة في مدة ثلاثة أشهر فقط حتى ازداد المال بشدة، هل هذا المال حلال؟ وإذا لم يكن حلالاً فماذا يفعل؟","title":"حكم بيع النقود بالنقود إلى أجل والسلعة والتورق","answer":"الجواب: الواجب على المسلم أن يبتعد عن أعمال الربا وأن يحذرها؛ لأن الربا من أكبر الكبائر، يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:278-279]، ويقول : وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ ۝ يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ وَاللَّهُ لا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ [البقرة:275-276].\nفالربا أمره خطير، فالواجب الحذر منه، وهذه المسألة التي سألت عنها فيها تفصيل: فإن كان يبيع النقود بالنقود، المائة بمائة وخمسين، والعشرة بخمسة عشر إلى أجل أو يداً بيد هذا رباً صريح محرم عند جميع أهل العلم.\nأما إن كان قصدك أنه يشتري السلعة ثم يبيعها بزيادة هذا له شأن آخر، فإذا اشترى السلعة بمائة ثم بعد ما يحوزها وتكون في ملكه ويقبضها يبيعها على المحتاج إلى أجل معلوم بمائة وخمسين أو بمائة وأربعين أو بمائة وستين أو بأكثر أو بأقل إلى أجل معلوم هذا لا بأس به على الصحيح، ولا حرج فيه عند جمهور أهل العلم؛ لأن المسألة المذكورة تدعو لها الحاجة، وليس كل واحد يجد حاجته بالهدية أو بالقرض فيحتاج إلى أن يشتري السلع إلى أجل معلوم ولو بالزيادة، وقد يحتاجها للاستعمال كما يشتري سيارة ليستعملها، وكما يشتري البساط ليفرشه ويجلس عليه، وكما يشتري الطعام ليأكله، وقد يشتري ذلك ليبيعه بنقد لحاجته إلى النقد ليسدد ديناً عليه، أو ليعمر بيتاً له، أو ليتزوج، أو لأغراض أخرى، فهذه الصور كلها جائزة إذا كان البائع قد ملك المبيع وقبضه وحازه لديه، من سيارات أو أراضي أو أمتعة أخرى قد حازها وملكها وقبضها ثم باعها إلى أجل معلوم، باع ما يشترى مائة بمائة وخمسين، أو ما يساوي ألفاً بألف وخمسمائة، أو أكثر أو أقل، فالصحيح أنه لا حرج في ذلك، سواء كان أراد بذلك الاستعمال، أو أراد أن يبيع السلعة بنقد ليستعمل النقد في حاجته، وهذه الأخيرة تسمى: التورق، كونه يشتري السلعة إلى أجل أن يبيعها بالنقد ثم ينتفع بالنقد هذا يسميها بعض أهل العلم: مسألة التورق، ويسميها العامة: الوعدة، مسألة الوعدة، وهذه صحيحة لا بأس بها في أصح قولي العلماء لما عرفت من الأسباب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7394/حكم-بيع-النقود-بالنقود-الى-اجل-والسلعة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23404.mp3","categories":["الربا والصرف","البيوع"]},{"id":9302,"question":"سؤاله الثاني الأخ الصادق من السودان يقول: أنا أعمل تاجر، فهل يجوز لي أن أزن بالقرطاس -أي: كيس الورق- أم لا يجوز ذلك خاصة إذا كان المشتري ليس لديه إناء يأخذ فيه البضاعة؟الشيخ: أعد؟المقدم: يقول: هل يجوز لي أن أزن بالقرطاس -أي: كيس الورق- يضعه في كفة الميزان ويزن به أم أن هذا يؤثر على الوزن؟","title":"المعيار في وزن المبيعات في البيع","answer":"الجواب: لم أفهم جيداً مراد السائل، وإن كان مراده أن الشيء الموزون من الحبوب، أو الشاي، أو القهوة، أو غير ذلك كونه يضعه في قرطاس ثم يزنه، ويلاحظ أن هذا القرطاس لا يخل بالوزن فلا بأس بذلك، إذا كان القرطاس خفيف أو يزاد في الوزن قليلاً في مقابل القرطاس فلا حرج في ذلك والحمد لله.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7461/المعيار-في-وزن-المبيعات-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23605.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9330,"question":"الرسالة التالية وصلت إلى البرنامج من شقراء بتوقيع أحد الإخوة يقول: (ص. ع. م) أخونا يقول في رسالته: المعروف حالياً أن الناس يأخذون من بعضهم أموالاً كقرضة ويسمونها ديناً وهي غير السلف، وسؤالي: هل الدين بالمفهوم الحالي حرام، وما هي الطريقة الإسلامية الشرعية لذلك، أفيدونا بذلك وجزاكم الله خيراً؟","title":"الفرق بين القرض والسلم","answer":"الجواب:  ليس الدين حراماً إذا كان على الوجه الشرعي، وليس القرض حراماً إذا كان على الوجه الشرعي ويسمى ديناً أيضاً، قال الله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ[البقرة:282]، فالله سبحانه أباح لعباده المؤمنين التداين، وأن يكتب ذلك الدين إلى أجل، فلا بأس بالمداينة ولا بأس بالاقتراض، والمداينة كأن تشتري من أخيك سلعة من أرض أو بيت أو دكان أو سيارة أو غير ذلك إلى أجل معلوم لحاجتك إليها، لتسكن البيت، لتزرع الأرض، لتستعمل السيارة، أو لتستفيد منها تبيعها وتستفيد منها إلى غير ذلك من المقاصد، هذه تسمى مداينة إلى أجل مسمى، هذا شيء لا حرج فيه إذا كان المبيع مملوكاً للبائع وفي حوزة البائع فإن هذا البيع يسمى بيعاً ويسمى ديناً. ومن المداينة ما يسمونه بالسلم وهو: أن تأخذ من شخص دراهم معينة معجلة يشتري بها شيئاً من ذمتك كقهوة، سكر، رز غير ذلك، تأخذ منه مثلاً عشرة آلاف ريال على أنك تعطيه بكل ريال صاعاً من الحنطة نوعها كذا أو صاعاً من الأرز بعد سنة بعد سنتين بعد أشهر معينة هذا يسمى السلم ويسمى السلف، وهو ما عجل ثمنه وأخر مثمنه، إذا كان معلومًا تامة شروطه إلى أجل معلوم، أو سيارة قد علم موديلها وصفاتها الكاملة تبيعها عليه من ذمتك إلى أجل معلوم فتأخذ منه عشرة آلاف أو عشرين ألفًا على أنك تدفع له بعد سنة أو بعد سنتين سيارة صفتها كذا وصفتها كذا وموديلها كذا معروفة ليس فيها شبهة، أو آصعًا معلومة من الأرز أو من الحنطة أو من غير ذلك أو من القهوة أو من السكر إلى غير ذلك، شيء معلوم، قال النبي ﷺ لما قدم المدينة وهم يسلفون الثمار السنة والسنتين قال عليه الصلاة والسلام: من أسلف فليسلف في كيل معلوم ووزن معلوم إلى أجل معلوم هذا كله يسمى مداينة. ومنها القرض أيضاً كأن تقول لأخيك في الله أو لأخيك من النسب أو لابن عمك أو لصهرك أبي زوجتك أو أخي زوجتك أو غيرهم تقول له: أقرضني كذا، أقرضني ألف ريال، أقرضني عشرة آلاف ريال قرضاً بدون فائدة لله، هذا يسمى دينًا ويسمى قرضًا، فإذا أعطاك أخوك في الله أو قريبك أو صهرك مطلوبك من المال فهذا يسمى قرضًا، إذا كان من دون فائدة مجرد احتساب، هذا يسمى قرضًا؛ لأنه إرفاق، ويسمى ديناً؛ لأنه في الذمة، فهذا لا حرج فيه ولا بأس به. لكن لو قال: على أن تعطيني زيادة كذا وكذا صار ربا، لو قال: نعم، أنا أعطيك قرض عشرة آلاف لكن بشرط أن تعطيني في كل ألف عشرة أو مائة أو خمسين من أجل التأخير الذي يتأخر المال عندك هذا هو الربا المعروف لا يجوز، أو قال: أنا أعطيك عشرة آلاف قرضاً لكن على أن تعطيني سيارتك الفلانية أستعملها شهرين ثلاثة أكثر أقل في مقابل هذا القرض، هذا لا يصلح؛ لأنه قرض بشرط وهذا لا يجوز. كذلك لو قال: نعم، أنا أعطيك عشرة آلاف أو مائة ألف قرضاً على أن تعطيني أرضك الفلانية أزرعها وأستفيد منها حتى تعطيني قرضي، حتى يستفيد من الأرض بدون أجر في مقابل هذا القرض، أما إن استأجرها بأجرة المثل من دون شرط استأجرها بالعادة بنصف الزرع بثلث الزرع بآصع معلومة، بدراهم معلومة، كما يستأجرها الأجنبي من دون شرط بينكم وقد استأجرها بعد ذلك منك فلا بأس، لكن الله يعلم ما في القلوب، إذا كانت من دون شرط وبالأجرة المعتادة التي يأخذها غيره. نعم. المقدم: الصور الموجودة في السوق، لعل سماحة الشيخ بلغه بعض منها؟\nالشيخ: نعم، وهي؟ المقدم: وهي كأن يأتي إنسان محتاج إلى تاجر يبيع ويشتري في أقمشة أو في مواد غذائية أو نحو ذلك، ويقول: تشتري هذه البضاعة بمبلغ كذا وتسدد القيمة بعد عام بمبلغ كذا وكذا، بطبيعة الحال المبلغ يكون زائد لكن ذلك المحتاج لا يستلم تلك البضاعة.\nالشيخ: هذا ما يصلح، هذا يسمونه التورق ولكن يسيئون الاستعمال، ويسمونها العامة: الوعدة ويسيئوا الاستعمال، يبيع المال وهو ..... جالس ما يقبض، وهكذا الآخر يبيعه وهكذا الآخر، لا ما يصلح هذا، التجارة الشرعية والمداينة الشرعية أن يشتري مالاً موجوداً عند البائع في حوزة البائع ثم يقبضه المشتري ويحوزه المشتري ويتصرف فيه، باستعماله إن كان أرضاً باستعمالها إن كانت سيارة، بغير ذلك من أنواع الاستعمال يعني: يقبضه، هذا هو البيع الشرعي، أما أن يشتري منه هذا المال الموجود ...... ثم يتركه ويبيعه عند البائع يبيعه على زيد أو على عمرو، هذا ما يجوز، نعم. هذا فيه الحديث الصحيح: لا تبع ما ليس عندك، لا يحل سلف وبيع ولا بيع ما ليس عندك. نعم.","link":"https://binbaz.org.sa/fatwas/7480/الفرق-بين-القرض-والسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15504.mp3","categories":["البيوع","السلف والقرض"]},{"id":9345,"question":"رسالة وصلت إلينا من أحد الإخوة من السودان الشقيق وباعثها أحد الإخوة من هناك يسأل -سماحة الشيخ- ويقول: أسألكم عن حكم الاتجار في السوق السوداء، وحكم الاتجار بواسطتها. وباعث الرسالة هو الأخ: إبراهيم فقير أحمد؟","title":"حكم الاتجار في السوق السوداء","answer":"الجواب: لا أعلم شيئًا في هذا.. أقول: لا أعلم شيئًا في هذا الأمر. نعم.\nالمقدم: إذًا: نعد أخانا بالعودة إلى مثل سؤاله بعد البحث عن هذا سماحة الشيخ؟\nالشيخ: لا. هو واضح، المقصود: البيع والشراء في السوق السوداء ما نعلم فيه حرجًا.\nالمقدم: ليس فيه حرجًا؟\nالشيخ: لا نعلم فيه حرجًا.\nالمقدم: هذا قصدكم؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرا، كنت أتصور أنكم تقولون: لا نعلم الحكم.\nالشيخ: لا، لا نعلم فيه حرجًا.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7500/حكم-الاتجار-في-السوق-السوداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18502.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9425,"question":"الأخ السائل يقول في رسالته: من المعروف أن الشمة حرام، وبالتالي يكون ثمنها حرام، وأنا لي جار يبيعها، ونحن نشترك معه في شراء الطعام بحيث يدفع كل واحد منا ما ينوبه ونأكل جميعاً أكلاً مشتركاً، فما حكم أكلي معه، علماً بأن مصدر رزقه الوحيد هو بيع الشمة، أفيدوني أفادكم الله؟","title":"حكم الاشتراك في شراء الطعام وأكله مع بائع الشمة","answer":"الجواب: ينبغي لك أن تنفصل عن هذا الاشتراك ما دام مصراً على بيع الشمة المحرمة، وهي طريق رزقه، ينبغي لك أن تنفصل عنه، وأن لا تخالطه؛ لأن مخالطته تشجيع له على هذا المحرم، وأنت تشاركه في هذا المحرم، والله يقول سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ[المائدة:2].\nفنصيحتي لك أن تبتعد عن هذه المشاركة، وأن تنصح أخاك حتى يدع الشمة والتجارة فيها، وحتى يلتمس سبباً آخر وتجارة أخرى مما أباح الله، هدى الله الجميع لما فيه رضاه.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7590/حكم-الاشتراك-في-شراء-الطعام-واكله-مع-باىع-الشمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25504.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9496,"question":"وهذه رسالة وردت إلينا من تركيا من النامي عمر يقول في رسالته: قال المولى جل وعلا: الَّذِينَ يَأْكُلُونَ الرِّبَا لا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ [البقرة:275] إلى آخر الآية، ثم ساق حديث ابن مسعود : لعن رسول الله ﷺ آكل الربا، وموكله رواه مسلم وزاد الترمذي وغيره: وشاهديه وكاتبه يسأل ويقول: إننا نأخذ سيارة أو حنطة أو شعيراً أو عدساً أو غير ذلك من البنك بزيادة في الثمن، هل يجوز لنا هذا أم لا، أفيدونا أفادكم الله؟","title":"حكم شراء السلعة إلى أجل بزيادة في الثمن","answer":"الجواب: هذا شيء آخر غير الربا، كونه أن يشتري سيارة أو كذا من البنك أو من التجار بثمن مؤجل زائد على الثمن الحال هذا لا حرج فيه، هذا البيع إلى أجل، والذي عليه جمهور أهل العلم وهو كالإجماع منهم أنه لا حرج فيه، فإذا اشتريت سيارة من البنك أو من التاجر الفلاني قيمتها عشرة آلاف نقداً فاشتريتها بأحد عشر ألفًا أو بأكثر إلى أجل معلوم فلا بأس، أو اشتريت ذرة أو حنطة أو أرزًا قيمته ألف، فاشتريته إلى أجل بألفين أو بأكثر فلا بأس بهذا، سواء من البنك أو من غير البنك. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7657/حكم-شراء-السلعة-الى-اجل-بزيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25511.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9598,"question":"السؤال الرابع: هل يمكن أن أعطي شخصًا مالًا ليتاجر به ويعمل فيه لوحده والفائدة تقسم بيننا، نرجو توضيح ذلك من ناحية الحلال والحرام بالنسبة لي أنا الذي لم أشاركه في العمل أفيدونا أفادكم الله؟","title":"حكم المضاربة في التجارة","answer":"الجواب: هذه الشركة يقال لها: المضاربة، وقد فعلها أصحاب النبي ﷺ، وهي جائزة بإجماع المسلمين ليس فيها نزاع يجوز للإنسان أن يدفع مالًا لآخر يعمل فيه يتجر فيه بأنواع التجارة ويكون الربح بينهما، أو يكون الربع للمالك والثلاثة الأرباع للعامل أو العكس على ما اتفقا عليه لكن يكون بجزء مشاع معلوم، فهذا لا حرج فيه أنصافًا أو أثلاثًا أو أرباعًا أو غير ذلك، المعنى: بالجزء المشاع المعلوم لكن لا يجوز أن يقول: اعمل فيها على أنه يكون لك مائة ريال كل شهر أو خمسين ريال كل شهر أو ألف ريال لا، لابد يكون ..... لك الربع لك الثلث لك النصف لك السدس والباقي لي، أو يقول: لي أنا أيها المالك صاحب المال لي السدس لي الخمس والباقي لك أيها العامل كل هذا لا بأس به أو الربح بيننا لا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/7764/حكم-المضاربة-في-التجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19308.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":9628,"question":"بارك الله فيكم، يسأل ثانيةً ويقول: هل سماع الأغاني حرام؟ وما حكم البيع والشراء فيها؟ وإذا كان الجواب بالمنع، فما الحكم في هذه المحلات الكثيرة المنتشرة في بلاد المسلمين في بيع أشرطة الأغاني والاتجار بها، وأهلها منهم المصلي وكثير منهم يصرف على أهل بيته ويتصدق من ربح بيع الأغاني وشرائها، ومثلها أشرطة التمثيليات والأغاني المصورة بالفيديو ونحوها، أفيدونا أفادكم الله؟","title":"حكم سماع وبيع وشراء الأغاني","answer":"الجواب: سماع الأغاني وبيعها وشراؤها والتجارة فيها كله محرم كله منكر، وفيه فساد عظيم، ومن أعظم الأسباب لمرض القلوب وصدها عن ذكر الله وعن الصلاة، فيجب الحذر من ذلك، وكون الناس يفعلون هذا ليس بحجة، فالناس يفعلون منكرات كثيرة، ففعل الناس ليس بحجة، وإنما الحجة قال الله وقال رسوله عليه الصلاة والسلام.\nفالواجب على المسلم أن يحذر هذه المحرمات وأن يبتعد عنها، وأن لا يتجر فيها، ومع ذلك يدعو لإخوانه المسلمين بالهداية والتوفيق والصلاح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7794/حكم-سماع-وبيع-وشراء-الاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25005.mp3","categories":["البيوع"]},{"id":9695,"question":"وهذه رسالة من عبدالله بن علي من جيزان يقول في رسالته: أردت أن أشتري أغراضاً كهربائية لمنزلي حتى أسكن فيه أنا وأولادي لكن ليس معي نقود فذهبت إلى شخص لديه نقود فقال: أشتريها لك، فاشتراها بمبلغ سبعة آلاف وخمسمائة وأربعين ريال وباعها إلي بمبلغ تسعة آلاف وأربعمائة ريال بيعاً مؤجلاً أسددها على أقساط شهرية في كل شهر ألف ريال.الشيخ: أعد السؤال.المقدم: يقول  احتجت إلى أغراض كهربائية وليس معي نقود.الشيخ: أغراض؟المقدم: إي نعم، أدوات يعني.الشيخ: نعم.المقدم: وليس معي نقود، فذهبت إلى شخص لديه نقود فاشتراها لي بمبلغ سبعة آلاف وخمسمائة وأربعين ريالاً وباعها علي بمبلغ تسعة آلاف وأربعمائة مؤجلاً أسدده على أقساط شهرية كل قسط قدره ألف ريال فما حكم الشرع في ذلك؟","title":"حكم بيع السلعة بالتقسيط مع الزيادة في الثمن","answer":"الجواب: إذا حازها الذي باع عليك، حاز هذه الأغراض وهذه الأدوات وتملكها، ثم باع عليك بعد ذلك بمبلغ معلوم مقسط فلا بأس، لكن ليس له البيع عليك قبل أن يملكها، إذا عرف أنك تريدها وأنك محتاج لها فاشتراها وحازها من أهلها في بيته أو في السوق أو في أي مكان نقلها إليه من ملك البائع، ثم باع عليك هذه الأدوات بثمن معلوم مقسط في كل شهر كذا، في كل سنة كذا فلا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/7850/حكم-بيع-السلعة-بالتقسيط-مع-الزيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25209.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10131,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية -مرسى مطروح- وباعثها المستمع عبد الحليم بن عبد الله بن موسى بن علي بن عامر أخونا يسأل ويقول: هل يجوز بيع المحاصيل الزراعية قبل الحصاد؟","title":"حكم بيع المحاصيل الزراعية قبل حصادها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذا السؤال فيه إجمال، فبيع المحاصيل قبل الحصاد إن كان في الذمة يبيعه آصعاً معلومة أو كيلوات معلومة في الذمة لمدة كذا وكذا هذا يتعلق بالذمة ولا حرج إلى أجل معلوم، كأن يقول: أبيعك -مثلاً- ألف كيلو من الرز أو من الحنطة إلى مدة شهرين ثلاثة أربعة أقل أكثر بأجل معلوم بثمن معلوم يقبض الثمن حالاً هذا لا حرج فيه.\nأو يبيع المحاصيل بعد بدو الصلاح، إذا صلحت الثمرة واشتد الحب يبيعها لا بأس أيضاً، يقول: اشتر مني هذه المزرعة بعدما اشتد حبها وذهبت عنها الآفات لا بأس، النبي ﷺ نهى عن بيع الزرع حتى يشتد وعن بيع الثمر حتى يبدو صلاحها، فإذا كان قد اشتد الحب واستوى واشترى منه المزرعة بكذا وكذا لا بأس بالنقود، اشترى المزرعة بالنقود لا بالطعام بالنقود أو بالطعام الحاضر يسلمه له حتى لا يقع الربا، مثل مزرعة رز اشتراها بآصع من بر أو من تمر يداً بيد لا بأس، أو اشتراها بنقود لا بأس ما دام اشتد الزرع الحب الرز استوى لا بأس بها، إن كان بنقود لا بأس ولو في الذمة أما إن كان بربوي كأن يبيع مزرعة الرز بآصع من بر أو من تمر أو من عدس هذا لا بد أن يكون يداً بيد، يتسلم الزرع هذا ويتولى حصاده وذاك يتولى يقبض الثمن وهذا يكون له الزرع بالتخلية، متى حصد قبض الثمرة.\nالحال الثالث: أن يبيع المحاصيل قبل الحصاد على أنها تجز في الحال، يقول له: أنا أبيعك زرعي هذا وهو ما بعد استوى أبيعك إياه على أنك تجزه، تحصله الآن علف، أنا محتاج ما نبغيه يستوي، أنا محتاج إلى النقود ويبيع الزرع قبل أن يستوي ليحصد لا ليبقى، فهذا لا بأس به لأنه حينئذ ما فيه خطر ولا فيه ضرر يحصده الآن ولا بأس يبيع زروع علف تحصد الآن ولو ما استوت لا بأس.\nفهذه الأقسام الثلاثة تبين الحكم الشرعي: القسم الأول: أن يبيع الحبوب في ذمته إلى أجل معلوم ويعطيه من هذه الزراعة لا بأس إذا سلم الثمن في الحال يسمى سلم، إذا استلم الثمن تسلم الثمن في الحال يداً بيد يكون سلماً، والنبي ﷺ لما قدم المدينة وجدهم يسلمون في الثمار السنة والسنتين، فقال ﷺ: من أسلف في شيء فليسلف في كيل معلوم ووزن معلوم إلى أجل معلوم.\nالحال الثانية: أن يبيع الزرع أو التمر عندما اشتد واستوى، فهذا لا بأس به، إن باعه بنقود فلا بأس وإن باعه بغير النقود بشيء من الربا -من الربويات- كأن يبيع زرع الرز بآصع من بر أو من شعير أو من تمر فلا بأس لكن يداً بيد، حتى لا يقع الربا يكون يداً بيد، ..... يتقبض يقبض الثمن ويكون الزرع في ملك المشتري، يتولى حصاده أو يشترط عليه حصاده لا بأس، يشترط على المالك الحصاد لا بأس.\nالحال الثالث: أن يبيع الزرع قبل أن يستوي لكن ليحصده حالاً، يبيع الزرع من الرز أو من الحنطة أو غيرهما ليحصده حالاً علف يعلف به البهائم ما يخليه حتى يستوي يبيعه في الحال يحصده في الحال، هذا لا بأس به لعدم الغرر وعدم الخداع وعدم الخطورة التي قد تحصل في الزرع لو ترك حتى يبدو صلاحه؛ لأن هذا فيه خطر قد يبدو صلاحه وقد لا يبدو صلاحه، قد يصيب بآفة، فلهذا نهى النبي ﷺ عن بيع الثمر حتى يبدو صلاحها، الثمرة حتى يبدو صلاحها، لأنها إذا بيعت قبل ذلك قد تصاب بآفة، أما إذا كان يقطعه في الحال يجزه في الحال هذا ما فيه خطر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8295/حكم-بيع-المحاصيل-الزراعية-قبل-حصادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30501.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10201,"question":"هل الجوائز التي تقدم عن طريق بعض أنواع البضائع حكمها مثل حكم اليانصيب المحرم؛ لأن الجائزة قد تكون عشرة آلاف ريال لمن حالفه الحظ، وقد اشترى تلك البضاعة بريال واحد مثلًا؟","title":"حكم الجوائز التي ترصدها الشركات التجارية لترويج بضائعها","answer":"الجواب: هذه من القمار ما يجوز، قمار ميسر، إذا كان يجعل الجائزة لمن حصل الرقم الفلاني فهذا من القمار. نعم.","link":"https://binbaz.org.sa/fatwas/8360/حكم-الجواىز-التي-ترصدها-الشركات-التجارية-لترويج-بضاىعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33411.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10216,"question":"ما مقدار المكسب في التجارة، هل هو محدد بنسبة معينة؟","title":"حد الربح في التجارة","answer":"الجواب: ليس بمحدد، ولم يرد في الشرع ما يقتضي التحديد، لكن يستحب للمؤمن أن يرفق بإخوانه، وأن يرضى بالفائدة القليلة؛ رحمةً لإخوانه وتعاوناً معهم على الخير؛ لأن المسلم أخو المسلم، ومن كان في حاجة أخيه؛ كان الله في حاجته، ولقوله ﷺ: من يسر على معسر، يسر الله عليه في الدنيا والآخرة ولقوله ﷺ: يسروا ولا تعسروا فإذا سامح إخوانه ورضي بالقليل من الفائدة، فهذا خير، ولكن ليس هناك حد محدود، لا الثلث ولا الربع ولا النصف، فلو اشترى سلعةً بأربعين وتغيرت الأحوال جاز أن يبيعها بمائة، ما فيه حد محدود، على حسب تغير الأسواق.\nأما أنه يغش الناس تكون السلعة في الأسواق بأربعين، ويبيع عليهم بخمسين أو ستين ولا يخبرهم بالأسعار ما يجوز له؛ لأن هذا ظلم لإخوانه، فإذا كانت السلعة في الأسواق تباع بهذا ...... معروفة عند الأسواق يبيعونها بأربعين، فإنه يخبرهم يقول: السلعة بأربعين تباع في الأسواق لكن أنا ما أنا بايعها بهذا المبلغ، ما أبيعها بهذا المبلغ إذا أردت تشتريها مني بالزيادة فلا بأس، وإلا يمكن تجدها في الأسواق الأخرى، وهكذا لو كان مثلاً طعام الصاع بكذا، أو الكيلو بكذا في الأسواق، لا يبيع بأكثر إلا حتى يعلم صاحبه، يقول: يباع في الأسواق بكذا، تشتري مني بزيادة وإلا تروح الأسواق تشتري منها.\nالحاصل أنه لا يغش إخوانه في الأسعار، يخبرهم بالحقيقة، إذا كان السعر معروف في الأسواق محدد معروف أما إذا كان لا السعر ما هو محدد، يتغير يزيد وينقص يبيع بما قسم الله له. نعم.\nالمقدم: جزاكم الله خيراً، بمعنى أنه لابد أن يلتزم السعر السائد في السوق؟\nالشيخ: نعم، يخبر به الناس، نعم حتى لا يغشهم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8388/حد-الربح-في-التجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31005.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10220,"question":"ما مقدار المكسب في التجارة، هل هو محدد بنسبة معينة؟","title":"حد الربح في التجارة","answer":"الجواب: ليس بمحدد، ولم يرد في الشرع ما يقتضي التحديد، لكن يستحب للمؤمن أن يرفق بإخوانه، وأن يرضى بالفائدة القليلة؛ رحمةً لإخوانه وتعاوناً معهم على الخير؛ لأن المسلم أخو المسلم، ومن كان في حاجة أخيه؛ كان الله في حاجته، ولقوله ﷺ: من يسر على معسر، يسر الله عليه في الدنيا والآخرة ولقوله ﷺ: يسروا ولا تعسروا فإذا سامح إخوانه ورضي بالقليل من الفائدة، فهذا خير، ولكن ليس هناك حد محدود، لا الثلث ولا الربع ولا النصف، فلو اشترى سلعةً بأربعين وتغيرت الأحوال جاز أن يبيعها بمائة، ما فيه حد محدود، على حسب تغير الأسواق.\nأما أنه يغش الناس تكون السلعة في الأسواق بأربعين، ويبيع عليهم بخمسين أو ستين ولا يخبرهم بالأسعار ما يجوز له؛ لأن هذا ظلم لإخوانه، فإذا كانت السلعة في الأسواق تباع بهذا ...... معروفة عند الأسواق يبيعونها بأربعين، فإنه يخبرهم يقول: السلعة بأربعين تباع في الأسواق لكن أنا ما أنا بايعها بهذا المبلغ، ما أبيعها بهذا المبلغ إذا أردت تشتريها مني بالزيادة فلا بأس، وإلا يمكن تجدها في الأسواق الأخرى، وهكذا لو كان مثلاً طعام الصاع بكذا، أو الكيلو بكذا في الأسواق، لا يبيع بأكثر إلا حتى يعلم صاحبه، يقول: يباع في الأسواق بكذا، تشتري مني بزيادة وإلا تروح الأسواق تشتري منها.\nالحاصل أنه لا يغش إخوانه في الأسعار، يخبرهم بالحقيقة، إذا كان السعر معروف في الأسواق محدد معروف أما إذا كان لا السعر ما هو محدد، يتغير يزيد وينقص يبيع بما قسم الله له. نعم.\nالمقدم: جزاكم الله خيراً، بمعنى أنه لابد أن يلتزم السعر السائد في السوق؟\nالشيخ: نعم، يخبر به الناس، نعم حتى لا يغشهم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8388/حد-الربح-في-التجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31005.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10342,"question":"مستمع من عدن هو الحاج: حسن دبله -فيما يبدو- أخونا يقول في رسالته: أنا رجل أتاجر في بيع القات وأجمع منه بعض النقود، وأريد التوجه إلى الحج من فائدة القات، هل يجوز لنا هذا، أفيدونا جزاكم الله خيرا؟","title":"حكم بيع القات والذهاب للحج من كسب القات","answer":"الجواب: القات محرم ولا يجوز تعاطيه ولا بيعه وشراؤه كالدخان، فالواجب عليك الحذر من ذلك، وأن لا تحج منه، بل ما عندك من المال من ثمن القات تصدق به على الفقراء والمساكين أو في وجوه الخير، والتمس عملًا آخر وكسبًا آخر طيبا؛ لأن في القات أضرارًا كثيرة كما ذكر العلماء العارفون به من علماء اليمن وغيرهم، فاتق الله يا أخي! واحذر هذه الشجرة الخبيثة لا تشربها ولا تستعملها ولا تبعها ولا تتاجر فيها، ولا تحج من ثمنها، وهكذا الدخان وهكذا سائر المخدرات والمسكرات يجب الحذر منها، لضررها العظيم، والله سبحانه وتعالى حرم على عباده أن يتعاطوا ما يضرهم أو يزيل عقولهم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8513/حكم-بيع-القات-والذهاب-للحج-من-كسب-القات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/338004.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10398,"question":"امرأة وكلت امرأة أخرى ببيع حليها وقالت لها: بيعيه بهذا الثمن وما زاد فهو لك وباعته المرأة الأخرى بالتقسيط دون إذن المالكة، ودفعت لصاحبتها الثمن الذي حددته لتكسب الباقي، هل في هذا ربا؟","title":"حكم من وكَّل شخصًا في بيع شيء نقدًا فباعه تقسيطًا","answer":"الجواب: إذا سمحت صاحبة المال بالتقسيط فلا بأس وإلا فلا؛ لأنها لم تأذن لها بالتقسيط، إنما أمرتها بالبيع بكذا وكذا وما زاد فهو لها، فإذا سمحت بالبيع بالتقسيط فلا حرج في ذلك؛ لأن الحق حقها.\nالمقدم: جزاكم الله خيرًا، إذا دفعت الثمن تلك مقدمًا وهي استلمت القيمة بالتقسيط.\nالشيخ: إذا باعته بثمن مؤجل ومعجل بأن قالت لها: بيعيه بعشرة آلاف وباعته بعشرة آلاف معجلة وثلاثة آلاف أو أربعة مؤجلة فالزيادة لها.\nالمقدم: الزيادة للبائعة؟\nالشيخ: للبائعة الوكيلة؛ لأنها لم تضر الموكلة، المال الذي طلبته الموكلة أعطته إياه حصل لها، وهو عشرة مثلًا.\nفالمقصود: أنه إذا حصل مطلوب الموكلة الآذنة فالزائد للدلالة. نعم.\nالمقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8570/حكم-من-وكل-شخصا-في-بيع-شيء-نقدا-فباعه-تقسيطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34005.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10591,"question":"تسأل وتقول: إذا كان لدي مبلغ معين من المال، ثم أعطيته قريباً لي ليتاجر به ويعطيني جزءاً من الربح، فهل هذا جائز؟","title":"المضاربة الجائزة والممنوعة","answer":"الجواب: إذا كان الجزء جزءاً مشاعاً كالربع أو الخمس لا بأس، تقولين له: اعمل فيه ولي الربع أو الخمس أو السدس هذا لا حرج فيه، هذا يسمى: المضاربة، أما أن يعطيك شيئاً معين خمسة أريل كل شهر أو عشرة أريل كل شهر هذا ما يجوز هذا ربا، أما إذا قلت: أنت تعمل فيه والربح بيننا أنصاف أو أثلاث، أو لي السدس أو الخمس ولك الباقي هذا كله لا بأس به. نعم.","link":"https://binbaz.org.sa/fatwas/8769/المضاربة-الجاىزة-والممنوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32507.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10595,"question":"تسأل وتقول: إذا كان لدي مبلغ معين من المال، ثم أعطيته قريباً لي ليتاجر به ويعطيني جزءاً من الربح، فهل هذا جائز؟","title":"المضاربة الجائزة والممنوعة","answer":"الجواب: إذا كان الجزء جزءاً مشاعاً كالربع أو الخمس لا بأس، تقولين له: اعمل فيه ولي الربع أو الخمس أو السدس هذا لا حرج فيه، هذا يسمى: المضاربة، أما أن يعطيك شيئاً معين خمسة أريل كل شهر أو عشرة أريل كل شهر هذا ما يجوز هذا ربا، أما إذا قلت: أنت تعمل فيه والربح بيننا أنصاف أو أثلاث، أو لي السدس أو الخمس ولك الباقي هذا كله لا بأس به. نعم.","link":"https://binbaz.org.sa/fatwas/8769/المضاربة-الجاىزة-والممنوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32507.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10741,"question":"المستمع عبد العزيز اليماني من تعز بالجمهورية العربية اليمنية بعث برسالة يقول فيها: موظف يعمل في إحدى الشركات، ويتقاضى راتبًا شهريًا، لكن هذا الراتب لا يكفيه، ويضطر لشراء بعض السلع من الشركة التي يعمل بها بزيادة عن سعرها الأصلي، بحكم أنها دين، فيقوم ببيع هذه السلع بسعر أقل من السعر الذي اشتراها به؛ لينتفع بثمنها، هل هذا جائز أم لا؟ أفيدونا أفادكم الله.","title":"صور بيع المداينة الجائزة والمحرمة","answer":"الجواب: لا حرج في ذلك إذا كانت السلع موجودة عند الشركة، في حوزتها أو في ملكها، واشتراها إلى أجل معلوم ليبيعها ويقضي حاجته فلا بأس، وهكذا لو اشتراها من غير الشركة ممن هي عنده موجودة، ثم باعها وقضى حاجته وقضى دينه، أو تزوج، أو دفع أجرة البيت، أو ما أشبه ذلك، لا حرج في ذلك. لكن لابد أن تكون السلعة موجودة عند البائع قد حازها، أما أن يبيعها ثم يذهب يشتريها من التجار لا، لابد أن تكون السلعة موجودة عند البائع، وفي حوزته، وفي قبضته، ثم يبيع على غيره بنقد أو إلى آجال معلومة، لا بأس بهذا، ولا حرج؛ لعموم قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] والنبي ﷺ استدان وأقر الدين فلا حرج في ذلك. لكن إذا اشتراه قبل أن يشتريه البائع، هو عند الناس، عند التجار، فلا يجوز هذا؛ لأن الرسول ﷺ قال: لا تبع ما ليس عندك وقال عليه الصلاة والسلام: لا يحل سلف وبيع، ولا بيع ما ليس عندك، ولما سأله حكيم بن حزام قال: الرجل يأتيني يا رسول الله! يريد السلعة فأبيعها عليه ثم أذهب فاشتريها، قال: لا تبع ما ليس عندك فلا يجوز له أن يبيع ما ليس عنده. فالشركة وغيرها ليس لها أن تبيع الشيء وما هو عندها، وإنما تبيع ما كان حاضرًا عندها موجودًا في حوزتها في ملكها. وهكذا الرجل الذي يداين الناس ليس له أن يبيع إلا شيئًا عنده قد ملكه وحازه وقبضه من التجار، وانتهت إجراءات شرائه. نعم. المقدم: جزاكم الله خيرًا، إذا كان هذا الرجل متفق مع تجار معينين، بأنه عندما يأتيه رجل يحوله إليهم ليأخذ منهم البضاعة التي عندهم، هل تختلف الصورة؟ الشيخ: ما في شيء، إذا حول عليهم، إذا حول عليهم على أنهم يسلمون له السلعة التي اشتراها منهم، أما أنه وكيل يكون وكيل. أما إذا كان قد اشتراها وتم شراؤها، ثم حول عليهم باعها عليه، باع السلعة عليه إذا كان قد قبضها وحازها في مكانٍ آخر، لا يبيعها وهي عندهم أيضًا، لا بد يبيعها وقد حازها، ونقلها من أصحابه الذين اشترى منهم، فإذا حوله عليهم وقد باعها عليه بثمن اتفقا عليه، وقد حولها عنهم، وحازها، أو حوله عليهم لينظرها ويتأملها، ثم يكون البيع بعد ذلك هذا فيه تفصيل، لا بد من التفصيل: إن كان قد حازها فلا بأس أن يبيعها عليه، ويحولها لمن وهي عنده، فإذا اشتراها من زيد، ثم حولها إلى بيت عمرو أو إلى السوق، وقال له: هي في المحل الفلاني، ويعرفها الشخص أو تنضبط بالأوصاف وباعها عليه، ثم حوله على مكانها الذي قد حازها إليه، أو نقلها إليه فلا بأس. أما أن يبيعها وهي عندهم ما قبضها بعد، فلا، لا يبيعها وهي عندهم حتى يقبضها. المقدم: حتى وإن كان هناك اتفاق بين التاجر والشركة؟ ولو، ما دام الشركة ما اشترت، لا بد أن تشتري الشركة من التاجر، تحوز السلعة عندها، ثم تبيع، أما أن تبيع شيئًا عند التجار لا، لا تبع ما ليس عندك، هكذا قال النبي ﷺ: لا تبع ما ليس عندك، وقال ﷺ: لا يحل سلف وبيع، ولا بيع ما ليس عندك، الرسول نص على هذا ﷺ. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8927/صور-بيع-المداينة-الجاىزة-والمحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34610.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":10746,"question":"المستمع عبد العزيز اليماني من تعز بالجمهورية العربية اليمنية بعث برسالة يقول فيها: موظف يعمل في إحدى الشركات، ويتقاضى راتبًا شهريًا، لكن هذا الراتب لا يكفيه، ويضطر لشراء بعض السلع من الشركة التي يعمل بها بزيادة عن سعرها الأصلي، بحكم أنها دين، فيقوم ببيع هذه السلع بسعر أقل من السعر الذي اشتراها به؛ لينتفع بثمنها، هل هذا جائز أم لا؟ أفيدونا أفادكم الله.","title":"صور بيع المداينة الجائزة والمحرمة","answer":"الجواب: لا حرج في ذلك إذا كانت السلع موجودة عند الشركة، في حوزتها أو في ملكها، واشتراها إلى أجل معلوم ليبيعها ويقضي حاجته فلا بأس، وهكذا لو اشتراها من غير الشركة ممن هي عنده موجودة، ثم باعها وقضى حاجته وقضى دينه، أو تزوج، أو دفع أجرة البيت، أو ما أشبه ذلك، لا حرج في ذلك. لكن لابد أن تكون السلعة موجودة عند البائع قد حازها، أما أن يبيعها ثم يذهب يشتريها من التجار لا، لابد أن تكون السلعة موجودة عند البائع، وفي حوزته، وفي قبضته، ثم يبيع على غيره بنقد أو إلى آجال معلومة، لا بأس بهذا، ولا حرج؛ لعموم قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] والنبي ﷺ استدان وأقر الدين فلا حرج في ذلك. لكن إذا اشتراه قبل أن يشتريه البائع، هو عند الناس، عند التجار، فلا يجوز هذا؛ لأن الرسول ﷺ قال: لا تبع ما ليس عندك وقال عليه الصلاة والسلام: لا يحل سلف وبيع، ولا بيع ما ليس عندك، ولما سأله حكيم بن حزام قال: الرجل يأتيني يا رسول الله! يريد السلعة فأبيعها عليه ثم أذهب فاشتريها، قال: لا تبع ما ليس عندك فلا يجوز له أن يبيع ما ليس عنده. فالشركة وغيرها ليس لها أن تبيع الشيء وما هو عندها، وإنما تبيع ما كان حاضرًا عندها موجودًا في حوزتها في ملكها. وهكذا الرجل الذي يداين الناس ليس له أن يبيع إلا شيئًا عنده قد ملكه وحازه وقبضه من التجار، وانتهت إجراءات شرائه. نعم. المقدم: جزاكم الله خيرًا، إذا كان هذا الرجل متفق مع تجار معينين، بأنه عندما يأتيه رجل يحوله إليهم ليأخذ منهم البضاعة التي عندهم، هل تختلف الصورة؟ الشيخ: ما في شيء، إذا حول عليهم، إذا حول عليهم على أنهم يسلمون له السلعة التي اشتراها منهم، أما أنه وكيل يكون وكيل. أما إذا كان قد اشتراها وتم شراؤها، ثم حول عليهم باعها عليه، باع السلعة عليه إذا كان قد قبضها وحازها في مكانٍ آخر، لا يبيعها وهي عندهم أيضًا، لا بد يبيعها وقد حازها، ونقلها من أصحابه الذين اشترى منهم، فإذا حوله عليهم وقد باعها عليه بثمن اتفقا عليه، وقد حولها عنهم، وحازها، أو حوله عليهم لينظرها ويتأملها، ثم يكون البيع بعد ذلك هذا فيه تفصيل، لا بد من التفصيل: إن كان قد حازها فلا بأس أن يبيعها عليه، ويحولها لمن وهي عنده، فإذا اشتراها من زيد، ثم حولها إلى بيت عمرو أو إلى السوق، وقال له: هي في المحل الفلاني، ويعرفها الشخص أو تنضبط بالأوصاف وباعها عليه، ثم حوله على مكانها الذي قد حازها إليه، أو نقلها إليه فلا بأس. أما أن يبيعها وهي عندهم ما قبضها بعد، فلا، لا يبيعها وهي عندهم حتى يقبضها. المقدم: حتى وإن كان هناك اتفاق بين التاجر والشركة؟ ولو، ما دام الشركة ما اشترت، لا بد أن تشتري الشركة من التاجر، تحوز السلعة عندها، ثم تبيع، أما أن تبيع شيئًا عند التجار لا، لا تبع ما ليس عندك، هكذا قال النبي ﷺ: لا تبع ما ليس عندك، وقال ﷺ: لا يحل سلف وبيع، ولا بيع ما ليس عندك، الرسول نص على هذا ﷺ. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8927/صور-بيع-المداينة-الجاىزة-والمحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34610.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11037,"question":"يقول هذا السائل: ما حكم شراء أي بضاعة بدين لمدة معينة بسعر أكثر مما يستحق نقدًا بالحاضر، فهل هناك إثم أو ربا على البائع والمشتري؟","title":"حكم الزيادة في السعر إذا كان سداد الثمن مؤجلاً","answer":"الجواب:  لا حرج في ذلك، إذا اشترى سلعة تساوي مائة نقدًا، واشتراها بمائة وعشرين إلى شهر شهرين سنة سنتين لا بأس، المقصود: أن الزيادة من أجل الأجل لا حرج في ذلك. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9215/حكم-الزيادة-في-السعر-اذا-كان-سداد-الثمن-موجلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28719.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11407,"question":"يقول: أقوم بشراء قطع غيار، وصاحب محل قطع الغيار يقوم بمكافأة عملائه الراغبين في صورة مادية من ربحه الخاص، وهو راضٍ بذلك؛ لأنه.الشيخ: أعد. أقوم بشراء قطع غيار، وصاحب محل قطع الغيار يقوم بمكافأة عملائه الراغبين في صورة مادية من ربحه الخاص، وهو راضٍ بذلك؛ لأنه يلقى رواجًا لبيع بضاعته، فهل إذا أخذت منه هذه المكافأة الغير متفق عليها، والتي يعطيها برغبته، ورضا نفسه، هل في ذلك شيء، جزاكم الله خيرًا.","title":"حكم المكافآت التي يعطيها التجار لعملائهم","answer":"الجواب:  لا حرج -إن شاء الله- بشرط أن تؤدي الأمانة، أما إذا كنت تأتي له، تشتري منه لأجل الفائدة، وقد تضر غيرك إذا كنت تشتري لغيرك؛ فلا يجوز، وأما إذا كنت تشتري منه مثل غيره، مع أداء الأمانة، وإذا كنت وكيلًا تؤدي الأمانة، تجتهد في أن تشتري السلعة بأثمانها منه، ومن غيره، وأعطاك شيئًا، فالنبي ﷺ قال: ما جاءك من هذا المال، وأنت غير مشرف، ولا سائل؛ فخذه أما إذا كنت لا، إنما تأتي له لتخصه بالمجيء لأجل الفائدة التي يعطيك، وتهمل غيره لأجل الفائدة، هذا لا. لكن إذا كان لقصد أنك رأيت أن سلعته مناسبة، أو أن ثمنه مناسبًا، أو مثل غيره؛ لا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9587/حكم-المكافات-التي-يعطيها-التجار-لعملاىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38007.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11410,"question":"تقول: عندنا في المدارس يطلبون على البنات مبلغًا يسيرًا من المال في حدود عشرة ريالات، وإذا جاء آخر العام يعطون البنات المبلغ، ومثله معه، فهل هذا جائز؟","title":"حكم المال يؤخذ من الطالب ويرد مضاعفًا نهاية العام","answer":"الجواب:  إن كان هذا لسلع يشترونها للتجارة في المدرسة، يجعلوا من يجمع الدراهم هذه، يبيع أشياء، يشتري أشياء، ويبيع أشياء على الطلبة، فجمعوا أرباحًا؛ فلا بأس، أما أن يعطي عشرة، ويأخذ عشرين في آخر الوقت؛ لا يجوز، هذا ربا، لكن، أما إذا كان لا، إنما لهم وكيل يشتري حاجات من شراب، ومثل غيره، مثل عطور، ومثل غيره، يجمع شيئًا من الربح؛ فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9589/حكم-المال-يوخذ-من-الطالب-ويرد-مضاعفا-نهاية-العام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38009.mp3","categories":["الربا والصرف","البيوع"]},{"id":11515,"question":"بعد هذا ننتقل إلى الجمهورية العربية السورية لنقرأ رسالة بعث بها أحد الإخوة المستمعين من هناك، وهو حين كتب الرسالة في جدة، يقول: فيصل بن أحمد العلي أخونا له قضية يقول: رجل ما بحاجة إلى نقود، ولا يستطيع الاستدانة إلا أن يشتري حاجة بضعف ثمنها، ثم يبيعها كي يحصل على النقود، مثال على ذلك: أن رجلًا استدان سيارة ثمنها في السوق خمسمائة ألف ليرة، وعندما استدانها لمدة سنة اشتراها بتسعمائة ألف ليرة، ثم باعها بخمسمائة، فهل هذا العمل جائز، علمًا بأن كلام الناس قد كثر في هذا، فمنهم من يقول: إنه ربا، ومنهم من يقول: إنه جائز، فما هو توجيه سماحتكم؟","title":"حكم من اشترى سلعة بالتقسيط ثم باعها بأقل من ثمنها","answer":"الجواب:  الصواب في ذلك أنه جائز، هذا الذي عليه جمهور أهل العلم، لا حرج في ذلك، وهذا يسمى بيع التقسيط، فإذا كانت السلعة عند البائع موجودة عنده قد حازها وملكها، ثم باعها على إنسان بالدين لأقساط معلومة، ثم المشتري باعها بأقل ليقضي حاجته من زواج، أو غيره؛ فلا حرج في ذلك، وقد ثبت في الصحيحين من حديث عائشة -رضي الله عنها- أن أهل بريرة باعوها بأقساط، باعوها لعائشة بأقساط، كل سنة أربعون درهمًا أوقية تسع سنين بأقساط، واشترتها عائشة نقدًا. فالمقصود: أن الأقساط أمرها معروف حتى في عهد النبي ﷺ، فلا بأس أن يشتري الإنسان السلعة بأقساط، ثم يبيعها بنقد أقل لحاجته للزواج، أو لبناء مسكن، أو لقضاء دين، قد أشغله أهله، أو ما أشبه ذلك، لكن يكون البائع قد ملك السلعة، قد حازها، حصلت عنده السلعة، ما هو بيبيع شيئًا عند الناس، النبي ﷺ قال: لا تبع ما ليس عندك وقال ﷺ: لا يحل سلف وبيع، ولا بيع ما ليس عندك ونهى أن تباع السلع حيث تبتاع حتى يحوزها التجار إلى رحالهم. فيبيع سلعة قد ملكها وحازها لا بأس، أما أن يبيع عند الناس سلعًا عند الناس، ثم يشتري هذا ما يجوز هذا، والمشتري يشتري السلعة التي عند الإنسان الذي قد ملكها يشتريها بأقساط معلومة، ثم إذا قبضها، وحازها؛ يبيعها بعد ذلك، ويقضي حاجته، ولو بأقل، ولو بضعف، والنبي ﷺ اشترى في بعض الغزوات اشترى البعير بالبعيرين إلى إبل الصدقة، اللهم صل عليه وسلم، نعم.  المقدم: اللهم صل وسلم عليه.","link":"https://binbaz.org.sa/fatwas/9695/حكم-من-اشترى-سلعة-بالتقسيط-ثم-باعها-باقل-من-ثمنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38411.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11694,"question":"المستمع أبو أحمد من الرياض بعث يسأل ويقول: شخص استدان بذورًا وأسمدة لمدة مؤجلة، بفرق ثلاثة ريالات في الكيس عن السعر الحالي في السوق، وتقارب هذه المدة ثلاثة أشهر، وأعطى أهل البضاعة شيكًا بالمبلغ مؤجلًا لحين الصرف، فهل يعد هذا من الربا؟","title":"حكم شراء السلعة إلى أجل معلوم مع زيادة الثمن","answer":"الجواب:  شراء السلع إلى أجل معلوم بأقساط زائدة على السعر الحاضر لا بأس، هذا شأن الدين؛ لأن الدين غير النقد، فالذي يشتري بالدين تكون قيمته أغلى، والإنسان إنما يشتري بالدين عند عجزه عن النقود، والإنسان يبيع بالدين لأجل الفائدة، فلا حرج في ذلك إذا باع ما يساوي ثلاثين بأربعين أو بخمسين مقسطة على آجال معلومة، لا بأس. وهكذا إذا أعطاه شيكًا بها في أوقاتها كل ذلك لا بأس به، وهنا المداينة الشرعية المذكورة في قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] والنبي ﷺ اشترى إلى أجل، ومات ودرعه مرهونة في طعام لأهله -عليه الصلاة والسلام- فلا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا، حتى إذا كان الشيك نفسه مؤجلًا؟ الشيخ: يبين تاريخ التعريفة، يحول في يوم كذا وشهر كذا لا بأس ... المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9873/حكم-شراء-السلعة-الى-اجل-معلوم-مع-زيادة-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39103.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11772,"question":"إذا بعت ثوبًا قديمًا لشخص مقابل ثوب جديد، مع أني سوف أزيد في الفرق، هل هذا يعتبر ربًا؟","title":"حكم بيع ثوب قديم بثوب جديد مع الزيادة","answer":"الجواب:  لا حرج في ذلك، كأن يبيع بيتًا مع بيت، أو سيارة مع سيارة بفرق؛ لا حرج. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/9954/حكم-بيع-ثوب-قديم-بثوب-جديد-مع-الزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39416.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11782,"question":"من أبها رسالة بعث بها مستمع يقول (م. ص) عسيري يسأل ويقول: بعض الناس يحتاجون إلى مبالغ، ويذهبون يشترون سيارات بالتقسيط، ثم يقومون ببيعها كاش بسعر أقل من الذي اشتروها به، فهل ذلك جائز، أم أنه داخل في الربا؟ وجهونا جزاكم الله خيرًا.","title":"حكم شراء سلعة بثمن مؤجل وبيعها نقداً بسعر أقل","answer":"الجواب:  لا حرج في ذلك؛ لأن الحاجة تدعو إلى هذا الأمر، الحاجة تدعو إلى مثل هذا الأمر، أن يشتري الإنسان السلعة كالسيارة بثمن مؤجل أقساطًا؛ لأنه في حاجة إلى أن يبيعها بعد ذلك ويتزوج، أو يقضي ديونًا عليه، أو يعمر سكنًا له، أو يكمل سكنًا له، أو ما أشبه ذلك. المقصود: أن هذا لا بأس به، إذا اشترى سيارة، أو غيرها بأقساط لآجال معلومة، ثم باعها بأقل من ذلك بعد قبضها إذا اشتراها من مالكها التي هي عنده، إذا اشتراها من مالكها الذي هي موجودة عنده، ثم باعها بعد قبضها، وحوزها بثمن أقل، أو مماثل أو أكثر، فلا حرج في ذلك؛ لأن الحاجة تدعو إلى هذا، ليس كل واحد يجد من يقرضه، فيبيع السيارة ونحوها، ثم يتزوج، أو يكمل عمارة بيته، أو يستعين بها في شيء آخر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9968/حكم-شراء-سلعة-بثمن-موجل-وبيعها-نقدا-بسعر-اقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39506.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":11827,"question":"الأخت (م. م. ق. العبدلي الفيفي) بعثت تسأل وتقول: ما رأي سماحتكم فيمن يبيع مثلًا أساور من ذهب من دكان ما، ثم يقبض مبلغ الأساور بيده، وبعد ذلك يشتري أساور جديدة من نفس الدكان، هل يلزمه أن يبيع الأساور في دكان، ثم يشتري من دكان غير الذي باعهن فيه؟","title":"حكم بيع الذهب وقبض ثمنه ثم شراء ذهب آخر","answer":"الجواب:  لا حرج في ذلك أن يبيع في دكان، ويشتري من صاحب الدكان، إذا لم يكن ذلك مشارطة؛ فلا بأس، .... باعت الأسورة، ثم اشترت أسورة أخرى، أو خواتم، أو قلائد؛ لا حرج في ذلك إذا لم يكن تواطؤ وشرط. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10008/حكم-بيع-الذهب-وقبض-ثمنه-ثم-شراء-ذهب-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39511.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12001,"question":"بعد هذا رسالة بعث بها المستمع محمد نعمان من اليمن، يقول: نهى الرسول ﷺ عن بيع الحاضر للباد، أرجو توضيح هذه الصورة؟","title":"ما معنى: «نهى رسول الله أن يبيع حاضر لبادٍ»؟","answer":"الجواب:  بيع الحاضر للبادي، الحاضر: هو المقيم في البلد، والبادي: هو الذي يجيء من خارج، مثل: البادية الذين يبتعدون عن صنعاء، إذا جلبوا إلى صنعاء لا يتولى الحاضر البيع لهم يبيعون بأنفسهم. وهكذا الذي خارج الرياض إذا جلب إلى الرياض يبيع بنفسه، لا يبيع له الحاضر؛ لأنه إذا باع الحاضر؛ شدد على الناس، وأما البادي إذا باع بنفسه؛ كان أرخص للناس، ولهذا نهى النبي ﷺ عن بيع الحاضر للبادي فإذا قدم جماعة من البادية معهم غنم، أو لبن، أو أقط، أو غير ذلك يبيعون بأنفسهم، حتى يستفيد الناس منهم، إذا قدموا صنعاء، قدموا تعز، قدموا الرياض، قدموا الأحساء، قدموا حائل، قدموا المدينة، لا يتولى الحاضر البيع لهم، يتولون بأنفسهم هم، يبيعون بأنفسهم؛ لأن هذا أقرب إلى مصلحة الناس، والرسول ﷺ يقول: دعوا الناس يرزق الله بعضهم من بعض فإذا تولى الحاضر؛ شدد عليهم في الأثمان. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10186/ما-معنى-نهى-رسول-الله-ان-يبيع-حاضر-لباد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43115.mp3","categories":["شروح الحديث","البيوع"]},{"id":12075,"question":"أرجو أن توضحوا لنا البيوع المحرمة؟","title":"التعريف بالبيوع المحرمة","answer":"الجواب:  البيوع المحرمة كثيرة، ضابطها أن تبيع غررًا فيه خطورة، إذا كان غررًا أو بيعًا اختل فيه شرطه، أو بيع معدوم، أو نحو ذلك، فهذا هو البيع الباطل، والبيوع الباطلة هي التي نهى عنها الشارع، إما لكونها غررًا، وإما لكونها ربًًا، وإما لكونها اشتملت على بعض الشروط الباطلة، فليس هناك حد محدود لجمعها، لكن ضابطها إذا اختل الشرط، أو وجد ما يوجب البطلان من كون المبيع محرمًا، كالربا، أو خنزيرًا، أو خمرًا، أو ما أشبه ذلك، نعم. أو فيه غرر كأن يبيع على غير ضبط، كأن يقول: أبيعك كذا وكذا، وليس معلوم لهما المبيع، أو أبيعك ولد الناقة الذي ما بعد ولد، أو أبيعك ناقتي الفلانية، وهو ما يعرف صفاتها، كل هذه غرر، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10260/التعريف-بالبيوع-المحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43508.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12298,"question":"تقول في آخر سؤال لها في هذه الحلقة: إذا أخذت من بائع ثوبًا مثلًا بخمسة دنانير نقدًا، مع أن هذا البائع يبيع الثوب نفسه بسبعة دنانير لمن يريده بالتقسيط، فهل هذا يعتبر من الربا؟ وهل يحرم علي التعامل معه؟ أفيدونا، جزاكم الله خيرًا.","title":"حكم الزيادة في بيع التقسيط","answer":"الجواب:  ليس هذا من الربا؛ لأن بيع التقسيط غير بيع النقد المعجل، فبيع النقد المعجل يكون أرخص، فإذا كانت السلعة ثوبًا، أو إناءً، أو سيارة تساوي مبلغًا معينًا بالنقد، ومبلغًا أكثر بالتقسيط؛ فلا حرج في ذلك، فإذا اشتريت الثوب نقدًا بعشرة، وإلى آجال بخمسة عشر، أقساطًا، كل شهر خمسة، أو كل سنة خمسة؛ فلا حرج في ذلك، إذا كان المبيع مملوكًا للبائع، وعنده، وحاضرًا لديه في حوزته، فبيع التقسيط يكون أوسع، يكون أكثر ثمنًا من بيع المعجل، ولا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10498/حكم-الزيادة-في-بيع-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45304.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12471,"question":"يقول: يوجد لدينا في الأسواق أناس يبتاعون ويشترون في السمن والعسل، وهذه بضاعة مغشوشة، ويحلفون بالله أنها غير مغشوشة، فبماذا توجهونهم؟","title":"نصيحة للتجار بوجوب الأمانة والحذر من الغش والخيانة","answer":"الجواب:  الواجب على المؤمن الحذر من الغش في السمن، وفي العسل وفي غيرهما، والواجب عليه أداء الأمانة والصدق؛ لقول النبي ﷺ: من غشنا فليس منا والله يقول سبحانه: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]، ويقول -جل وعلا- في وصف المؤمنين: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8].  فالواجب على من يتعاطى البيع والشراء أن يتقي الله، وأن يتحرى الأمانة، وأن يحذر الغش والخيانة في السمن، وفي العسل، وفي غيرهما قد مر النبي ﷺ على صبرة من طعام في السوق فأدخل يده فيها فنالت أصابعه بللًا، فقال: ما هذا يا صاحب الطعام؟! فقال: يا رسول الله! أصابته السماء -يعني: مطر- قال له النبي ﷺ: ألا جعلته فوق الطعام.. أفلا جعلته فوق الطعام كي يراه الناس، من غشنا فليس منا. فإذا كان يجعل الرديء الأسفل من الرطب، أو من الفواكه، أو من الحبوب، ويجعل الطيب فوق؛ حتى يرى الناس الطيب، ويخفى عليهم الرديء، هذا من الغش، وهكذا إذا أدخل في السمن ما ليس منه، أو في العسل ما ليس منه، هذا من الغش، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10672/نصيحة-للتجار-بوجوب-الامانة-والحذر-من-الغش-والخيانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40413.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12504,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع إبراهيم عبدالله، الأخ إبراهيم يسأل ويقول: رجل اشترى جملًا بألف جنيه مصري، وباعه على رجل آخر لشهر معين في سنة، مثل شهر ستة بمبلغ ألف ومائتين جنيه مصري، رغم أن ثمن الجمل لا يساوي إلا ألف جنيه مصري، إنما الزيادة؛ لسبب أنه صبر، فهل هذا البيع ربا، أم أنه جائز؟ جزاكم الله خيرًا.","title":"حكم البيع إلى أجل مع زيادة في الثمن","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا البيع وأمثاله لا حرج فيه، ولا بأس به، إذا كان البائع قد ملك الجمل، وحازه، وصار في قبضته، ثم باعه بأجل مسمى بزيادة؛ فلا بأس بذلك، لعموم قوله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] ولعموم قوله سبحانه: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275] هذا من البيع الحلال وهو: بيع التقسيط، وقد بيعت بريرة في عهد النبي ﷺ بالتقسيط، باعها ملاكها نفسها بتسع أواق مقسطة في كل عام أوقية، فالبيع إلى أجل بالتقسيط لا حرج فيه، إذا كان البائع قد ملك المبيع، وصار في قبضته، وحوزته، ثم باعه بآجال مقسطة بأكثر من ثمنه، فلا حرج في ذلك، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، الملاحظ أن هذا ليس مقسطًا سماحة الشيخ، وإنما هو بعد سنة مثلًا.. الشيخ: نعم، هذا البيع إلى أجل. المقدم: إلى أجل؟ الشيخ: نعم. المقدم: فليس فيه ربا؟ الشيخ: لا بأس أن يباع بأكثر من ثمنه الحالي، يباع بأكثر؛ لأن البيع إلى أجل غير البيع الحالي، النقد له شأن، والأجل له شأن، فالبائع يستفيد بالفائدة الزائدة، والمشتري يستفيد بمهلته، وينتفع بالمبيع. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10706/حكم-البيع-الى-اجل-مع-زيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40701.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12594,"question":"من المستمع (ع. ع العتيبي) سؤال يقول فيه: إنني مزارع، وأحتاج إلى مال لكي أسدد به، وأنفق فيه على هذه المزرعة، فأذهب إلى أحد الوسطاء، فآخذ منه قرضًا مقابل أن أبيع خضرتي عنده، ويأخذ دلالته فقط، فما الحكم جزاكم الله خيرًا؟","title":"حكم بيع المقترض خضار مزرعته على المقرض","answer":"الجواب:  إذا كان ذلك شرطًا لم يجز، إذا كان لم يقرضك إلا بشرط أن تجعل الخضرة عنده يبيعها؛ هذا لا يجوز؛ لأنه قرض جر منفعة، فلا يجوز بإجماع المسلمين. أما إذا اقترضت منه، وبعت عنده الخضرة ليستوفي حقه من دون مشارطة، إنما اخترته أنت ليبيعها، ويأخذ حقه؛ فلا بأس من دون شرط، أما بشرط أنك تعطيه الخضرة يبيعها؛ فهذا لا يجوز. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10804/حكم-بيع-المقترض-خضار-مزرعته-على-المقرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41307.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12664,"question":"يقول: إذا اختلف العلماء في تحريم شيء معين، فما حكم الاتجار بذلكم الشيء؟","title":"حكم الاتجار فيما اختلف العلماء في تحريمه","answer":"الجواب:  هذا يختلف إذا كان ذلك الشيء المعين فيه دليل يدل على تحريمه، لم يجز للمسلم بيعه على الناس، ولا عرضه على الناس، ولا تشجيعهم على مباشرته، إذا علم أن الله -جل وعلا- حرم ذلك فليس له أن يحتج بخلاف المخالفين، بل يجب عليه أن يحذر ما حرم الله عليه، ويبتعد عن ذلك، مثلما أسكر كثيره، بعض الفقهاء يقول: إذا كان القليل لا يسكر؛ جاز استعماله، وهذا غلط، بل «ما أسكر كثيره فقليله حرام» كما قاله النبي ﷺ هكذا ثبت عنه ﷺ أنه قال: ما أسكر كثيره؛ فقليله حرام فإذا علم أن هذا العصير، أو هذا الشراب، أو هذا المأكول كثيره يسكر؛ وجب ترك قليله، حرم على الناس تعاطي قليله وكثيره جميعًا؛ سدًا للذريعة وحسمًا للمادة، وعملًا بالحديث الصحيح: ما أسكر كثيره فقليله حرام وهكذا ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10874/حكم-الاتجار-فيما-اختلف-العلماء-في-تحريمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45816.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12696,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول جمانة عبدالكريم جابر صاحبة الرسالة تسأل سؤالين، في أحدهما تقول: سافرت لإحدى الدول، فوجدت هناك سوقًا يدعى سوق المحار، في هذا السوق تباع أصداف اللؤلؤ، وربما يجد المشتري في الأصداف اللؤلؤ، وفي أغلب الأحيان لا يجد شيئًا، أرجو معرفة موقف الشريعة الإسلامية من هذه التجارة، جزاكم الله خيرًا؟","title":"حكم بيع الغرر","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذه الأصداف التي تباع في الأسواق، وقد لا يوجد في بعضها لؤلؤ، الذي يظهر أنه لا حرج في ذلك؛ لأن الغالب وجود المطلوب، والنادر لا حكم له، كما تباع أنواع الفواكه من البطيخ وغيره، وقد يكون في بعض تلك الفواكه شيء من الخلل، ولا يضرها ذلك، لأن الاعتبار بالأغلب. نعم. السؤال: جزاكم الله خيرًا، إذًا ليس في هذا شيء من بيع المجهول كما يقولون؟  الجواب: لا لأن الغالب هو السلامة، نعم. السؤال: بارك الله فيكم، هي تقول: إن الغالب أن المشتري لا يجد شيئًا؟  الشيخ: أعد السؤال، أعد. السؤال: تقول: سافرت لأحدى الدول، فوجدت هناك سوقًا يدعى سوق المحار، في هذا السوق تباع أصداف اللؤلؤ، وربما يجد المشتري في الأصداف اللؤلؤ، وفي أغلب الأحيان لا يجد شيئًا، أرجو معرفة موقف الشريعة الإسلامية في هذه التجارة؟ الجواب: إذا كان الواقع كما ذكرت؛ فالبيع غير صحيح؛ لأن الغالب عدم وجود شيء، فهو بغرر ومخاطرة؛ فلا يصح، أما إذا كان العكس أن الغالب وجود الشيء المطلوب؛ فلا حرج في ذلك. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10906/حكم-بيع-الغرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45901.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12797,"question":"رسالة وصلت إلى البرنامج من المستمع محمد علي العجلان يقول في الرسالة: من المعاملات الشائعة بين الناس: استئجار المحلات بثمن محدود، وتأجيره لآخر بمبلغ أكثر من الأجرة الأولى، في نظير العودة إلى الأجرة السابقة في الأعوام القادمة، وهذا ما يعرف لدى العامة بنقل القدم، وللتوضيح نضرب مثالًا لذلك: يستأجر أحدنا محلًا بمبلغ عشرين ألف ريال مثلًا، ويطلب ممن يريد استئجاره منه أن يدفع مبلغ عشرة آلاف ريال في نظير إخلائه، وتسليمه إياه، والعودة إلى الأجرة السابقة، وهي عشرون ألف ريال في الأعوام القادمة، ما حكم المال الذي أخذ بهذه الطريقة، وهو المعروف بنقل القدم؟","title":"حكم بيع إخلاء القدم بعد انتهاء مدة الاستئجار","answer":"الجواب:  أما نقل القدم فلا يجوز الأخذ عنه؛ لأنه ليس ملكًا له، بل ملك للمالك، الدكان والبيت ملك للمالك، أما إذا أجر مدته التي قد ملكها بالأجرة؛ فلا بأس أن يؤجرها بأكثر، فإذا استأجر بيتًا، أو دكانًا بعشرين ألفًا، ثم أجره بأكثر من ذلك؛ فلا حرج في ذلك. أما إذا انتهت مدته فليس له أن يبيع نقل القدم، ويأخذ عوضًا عن نقل القدم، وقد انتهت مدته، فالحق ليس له، بل للمالك، ومدته انقضت، فليس له أن يأخذ عن خروجه شيئًا؛ لأنه ما بقي له حق، بل الحق للمالك، وهو انتهت مدته، ولا يجوز له أن يأخذ نقل قدم؛ فإنه لا مقابل له، ليس له مقابل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11011/حكم-بيع-اخلاء-القدم-بعد-انتهاء-مدة-الاستىجار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46202.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":12946,"question":"هذا السائل: (ع. أ. أ) يقول: ما حكم بيع التورق، وما صفته؟","title":"حكم بيع التورق وبيان صفته","answer":"الجواب:  التورق على الصحيح لا بأس به، صفته: أن تشتري من زيد سلعة مؤجلة، ثم تبيعها بالنقد لحاجته إلى النقد، للزواج، أو لتعمر بيتك، أو لوفاء دين عليك، هذا التورق، تشتري السلعة بأجل، وأنت تريد بيعها لمصلحتك، تجي فلانًا تقول: يا فلان! أشتري منك السيارة هذه بمائة ألف ريال مقسطة، كل شهر خمسة آلاف، أو كل سنة عشرون ألفًا، مقسطة بالسنين، أو بالشهور، ثم بعد قبضها تبيعها أنت نقدًا على من تشاء؛ حتى تتزوج، أو توفي دينًا عليك، أو تعمر بيتك، أو ما أشبه ذلك، هذا الصواب، لا حرج في ذلك، نعم؛ لأن هذا داخل في قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] هذا دين، ولأن الله -جل وعلا- قال: وَأَحَلَّ اللَّهُ الْبَيْعَ [البقرة:275] وهذا بيع.  فلا حرج في كونه يشتري السلعة التي يقتنيها، أو ليأكلها كالبر والشعير، أو يشتريها ليبيعها، والتجار يشترون ليبيعون، التجار يشترون السلع ليبيعوها، فأنت إذا شريت سيارة، أو أرضًا، أو بيتًا، والمقصود من شرائه أن تبيعه، اشتريته بأجل ونيتك أن تبيع بالنقد من أجل حاجة للزواج، أو غرماء آذوك توفيهم، أو ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11161/حكم-بيع-التورق-وبيان-صفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50205.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13410,"question":"جزاكم الله خيرًا، من الصيدلي (ع. أ. ح) بعث يسأل عددًا من الأسئلة، من بينها سؤال يقول: أسألكم عن بيع بعض الأدوية التي يشك الصيدلي في أن المشتري سيسيء استخدامها، رغم أن هذه الأدوية غير ممنوعة، ومعروف عنها علميًا أنها ليست من المخدرات، مع العلم أنه لو امتنع عن بيعها قد يتعرض للكذب، وذلك بإنكاره وجود هذه الأدوية عنده، وأنه لابد من وجودها في الصيدلية؛ وذلك لأن معظم المرضى يستعملونها للعلاج، وأنه لو امتنع عن بيعها لمن يسيء استعمالها قد يعرض صاحب العمل لبعض النقص في الإيراد المادي، وجهونا حول هذه القضية، جزاكم الله خيرًا.","title":"حكم بيع الأدوية التي يشك في سوء استعمالها","answer":"الجواب: هذا فيه تفصيل: إن كان يعلم أن الحبوب التي تطلب يستعان بها على الزنا، والفواحش هذا لا يبيع عليهم إذا كان يعرف عنهم هذا الشيء، أو يغلب على ظنه أن المشتري يستعملها فيما حرم الله. أما مجرد الشكوك والظنون السيئة؛ فلا عبرة بها، يبيع ولا يمتنع ما دامت علاجًا للمرض الذي يريد الشراء من أجله، فلا يمتنع، بل يبيع، إلا إذا عرف أن هذا المشتري يستعملها فيما حرم الله، أو غلب على ظنه ذلك، فهذا من باب التعاون على البر والتقوى، وعدم التعاون على الإثم والعدوان، لا مانع أن يمتنع من بيعها بأي عذر شرعي يستطيعه، نعم، يلتمس عذرًا شرعيًا ليس فيه كذب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11703/حكم-بيع-الادوية-التي-يشك-في-سوء-استعمالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47708.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13415,"question":"يسأل ويقول: بيع هذه الأدوية لهذا المشتري بأكثر من سعرها هل هو جائز؟","title":"حكم بيع السلعة بزيادة عن سعرها المحدد","answer":"الجواب: ليس له أن يزيد، بل يبيع بالسعر المحدد عنده، ولا يجوز له أن يزيد على بعض الناس، بل يجب أن يبيع مثلما يبيع على الناس الآخرين، نعم، إذا كان سعرها محدد من الجهة المختصة، أو في أسواق الناس ليس له أن يزيد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11709/حكم-بيع-السلعة-بزيادة-عن-سعرها-المحدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47709.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13424,"question":"بيع العبوة الأكبر من الدواء للمريض رغم وجود العبوة الصغيرة، ورغم أن استعمال العبوة الصغيرة قد يكفي، ولكن العبوة الكبيرة سعرها أكثر، مع العلم أن العبوة الكبيرة لا يضر المريض استعمالها، وأن الطبيب لم يحدد العبوة المطلوبة؟","title":"حكم بيع علبة الدواء الكبيرة مع أن الصغيرة تكفي المريض","answer":"الجواب: عليه أن يبين الحقيقة يبين هذا وهذا، ويشرح لصاحب الحاجة هذا وهذا، يقول: عندي عبوة كبيرة سعرها كذا، وعبوة صغيرة سعرها كذا، ويبين فوائد هذه، وفوائد هذه، ويتقي الله في ذلك، ولا حرج عليه.  أما أن يخص الكبيرة هذا يضر الناس، ولكن يبين هذا وهذا؛ لأن بعض الناس دخله ضعيف، يحتاج إلى العبوة الصغيرة ما دامت تكفي. فالحاصل: أن يبين هذا وهذا، ويشرح لصاحب الحاجة هذا وهذا، وأن هذا سعره كذا، وهذا سعره كذا، وهذا فائدته كذا، وهذا فائدته كذا، ويصدق في ذلك، ويتقي الله في ذلك، ثم صاحب الحاجة يشتري ما شاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11718/حكم-بيع-علبة-الدواء-الكبيرة-مع-ان-الصغيرة-تكفي-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47711.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13425,"question":"يقول: إن بعض المشترين لا يساوم في البيع والشراء، فماذا إذا بعنا على أولئك بسعر يختلف عن المساومين؟","title":"حكم بيع السلعة بسعر واحد لكل الناس","answer":"الجواب: الواجب أن يباع بسعر واحد إذا كان هو المعروف، ولا يستغل جهل الجاهلين، وغفلة الغافلين، أما إذا كان السعر على شيء واحد معروض، ولكنه نزل لهذا من أجل محبته له، أو صداقته له، أو فقره، أو ما أشبه له، والمال ماله، فسامح بعض الناس وإلا السعر معروف.. فالسعر عنده للعموم عشرة، ولكن قد يسامح بعض الأصدقاء، أو بعض الفقراء، فيبيعه بتسعة، أو بثمانية؛ هذا لا بأس. أما أنه يستغل الجهلة، والمغفلين، فيبيع ما سعره عشرة باثنى عشر، أو ثلاثة عشر، أو بأكثر لأنهم لا يكاسرون؛ هذا لا يجوز، الواجب أن يبيع عليه بالسعر الذي يبيع على الناس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11719/حكم-بيع-السلعة-بسعر-واحد-لكل-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47712.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13431,"question":"أيضًا أسأل عن بيع السلعة الأغلى مع أن هناك سلعة أرخص منها تؤدي نفس الغرض؟","title":"حكم بيع السلعة الأغلى مع وجود الأرخص","answer":"الجواب: مثلما تقدم يبين هذا وهذا يشرح للراغب حال السلعتين، وفائدة السلعتين، وقيمة السلعتين حتى يكون المشتري على بصيرة، إن شاء أخذ هذا، وإن شاء أخذ هذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11724/حكم-بيع-السلعة-الاغلى-مع-وجود-الارخص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47713.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13639,"question":"يقول السائل: ما حكم بيع السلعة بالتقسيط مع رفع ثمنها عن السعر الأصلي؟","title":"حكم بيع السلعة بالتقسيط مع رفع الثمن","answer":"الجواب: لا بأس إذا باعها بالتقسيط، وزاد في الثمن لا حرج؛ لأن بيع الأجل غير بيع النقد، فإذا كانت السيارة تساوي خمسين ألف نقدًا، وباعها بستين ألفًًا أو سبعين ألفًا في كل سنة كذا وكذا، أو في كل شهر كذا وكذا؛ فلا حرج في ذلك، داخل في قوله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] لا بأس به، هذا بيع أجل، بيع دين ولا حرج. وقد ثبت عنه ﷺ أنه أقر أهل بريرة لما باعوها بتسع أواق كل عام أوقية، باعوها نفسها بتسع أواق، تسع سنين، كل سنة أوقية؛ أربعين درهمًا، وهذا نوع من التقسيط. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11972/حكم-بيع-السلعة-بالتقسيط-مع-رفع-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52814.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13670,"question":"هذه السائلة أم عبدالله من الرياض تقول في هذا السؤال بأنها تبيع البخور للنسوة، وهؤلاء النسوة اللاتي أبيع لهن البخور يخرجن متعطرات ومتبخرات، فهل علي إثم في بيعي لهن هذا البخور؟ أرجو الإفادة.","title":"حكم بيع البخور لمن يُعلم خروجهن متبخرات","answer":"الجواب: إذا كنت تعلمين أن هؤلاء يفعلن ذلك لا تبيعي عليهن، إذا كنت تعلمين أنهن يطيبن في خروجهن في الأسواق؛ فلا تفعلي؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2].  فإذا كنت تعلمين أن هذه المرأة التي تشتري منك العود، أو غيره من الطيب، تتبرج به في الأسواق، أو عند الأجانب، هذا لا يجوز؛ لأنك في هذه الحالة تعينينها على المعصية، أما إذا كنت لا تعلمين؛ فلا حرج عليك أن تبيعي على النساء، وغير النساء، أما إذا علمت أن فلانة بنت فلان التي تشتريها منك أنها تفعل هذا الفعل؛ لا تبيعي عليها. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12014/حكم-بيع-البخور-لمن-يعلم-خروجهن-متبخرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52913.mp3","categories":["إخراج الزكاة وأهلها","البيوع","قضايا المرأة"]},{"id":13760,"question":"بعد ذلك ننتقل إلى رسالة هذا السائل، يقول في سؤاله: هل يجوز الربح في السلعة المباعة بأكثر من النصف؟ وهل هناك حد للربح في البيع والشراء؟","title":"هل هناك حد للربح في البيع؟","answer":"الجواب: هذا يختلف، ليس فيه حد، لكن يبيع مثلما يبيع الناس، لا يغش الناس، يبيع مثلما يبيع الناس، لكن إذا باع سلعة ليس لها سعر عند الناس، وهي مرغوبة، وباعها بثمن كبير؛ لأنه يرغبوها، وهي مرغوبة؛ فلا بأس، لكن الشيء الذي سعره عند الناس معروف في الأسواق، لا يغر الناس، يبيع مثلهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12131/هل-هناك-حد-للربح-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53524.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13780,"question":"من الأطاولة في الباحة هذه رسالة بعث بها المستمع سعيد محمد الزهراني، أخونا يقول: قمت ببيع سيارة إلى أحد الأصدقاء بمبلغ أربعين ألف ريال على أن تدفع قيمتها على أقساط شهرية قيمة القسط ألف ريال، وصديقي هذا يمر بأزمة مالية فطلب مني أن أبيعها في المعرض حيث أن السيارة لا زالت باسمي، وقد أخذت في الثمن كمبيالة فاشترطت على صديقي أن يكون حاضرًا معي وقت البيع ليقبض هو الثمن ويكون البيع برضاه، فوافق وتم بيع السيارة في المعرض بمبلغ سبعة وعشرين ألف ريال، وقام بعد ذلك بقبض ثمن السيارة حيث سدد به بعض ديونه وأنا لم يكن عندي مال أقرضه ولم يكن عندي سوى سيارتي التي اشتراها مني كما ذكرت سابقًا حتى أنه لم يكن لي رغبة في بيعها، فهل في معاملتي هذه شيء من الربا؟ وهل البيع بالتقسيط جائز؟ مع العلم أن سيارتي كلفتني مبلغ خمسة وثلاثين ألف ريال؟ أفتونا جزاكم الله خيرًا.","title":"هل البيع بالتقسيط جائز؟","answer":"الجواب: البيع بالتقسيط لا حرج فيه إذا كانت الأقساط معلومة والآجال معلومة، لعموم قوله : يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282]، الله أباح المداينة إلى أجل مسمى، فإذا كانت الأقساط واضحة معلومة والآجال معلومة فلا بأس كما فعلت مع صاحبك، في كل شهر ألفين هذا شيء معلوم والجملة معروفة أربعون ألفًا، ليس في هذا شيء، إذا كنت حين بعت السيارة وهي في ملكك وتحت قبضتك وتصرفك فلا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا. عن بيعه لسيارة أخيه؟\nالشيخ: أما كونك توليت بيعها لا يضر أنت محسن في هذا، وهذا من باب الوكالة فأنت في هذا محسن ومأجور ما دمت فعلته لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12141/هل-البيع-بالتقسيط-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60103.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":13987,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع رزق الله سلمان من الأردن، أخونا عرضنا سؤالًا له في حلقة مضت، وفي هذه الحلقة يقول: ذهب بعض الفقهاء إلى أنه لا يجوز للبائع أن يربح أكثر من الثلث، فهل حدد الشرع نسبة معينة لا يجوز تعديها؟","title":"هل حدد الشرع مقدار الربح في البيع؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فليس في الشرع المطهر تحديد للربح، وقول من قال: إنه يحدد بالثلث، قول ضعيف لا دليل عليه، والصواب أنه لا حد في ذلك، ولكن يشرع للمؤمن أن يتحرى الربح المناسب في حق أخيه، بحيث لا يشق عليه ولا يثقله، فيتحرى في كل مقام ما يناسبه، وليس هناك حد محدود، قد يكون الربح خمسة في العشرة، قد يكون خمسة في المائة، وقد يكون عشرة في المائة، قد يكون أكثر وقد يكون أقل على حسب أحوال من عليه الدين، وعلى حسب الآجال، قلة وكثرة وطولًا وقصرًا، فالبيعان يتحريان ما فيه الخير للجميع والسهولة على الجميع. نعم.\nالمقدم: جزاكم الله خيرًا، إذا كان البيع حاضرًا -سماحة الشيخ- ليس بدين؟\nالشيخ: كذلك ولو حاضر، ليس فيه حد محدود أبدًا؛ إنما ليس له أن يخدع الناس، إذا كان يعرف أن السعر في السوق هذا الشيء بريال، ليس له أن يبيع بريال ونص، بل يبين للناس أن السعر كذا وكذا، ولكن أنا ما أبيعك إلا بكذا، ترى تشتري مني، وإلا روح اشتر من المحلات الأخرى، أما أنه يخدع الناس، السعر في السوق بريال، وهو يبيع بريالين يخدع الجاهل ما يجوز له بل يدله على الخير؛ لأن المؤمن أخو المؤمن يرشده، يقول: هذا الشيء يباع في السوق بكذا وكذا، وأنا أرشدك إلى المحلات الفلانية، أما أنا إذا كان ما يستطيع يبيع بها السعر، يقول: أنا ما أبيع بها السعر، أبيع بكذا وكذا، ترى تشتري مني بهذا الشيء لأنه علي غالي، وأنه دخل علي غالي، يبين الأسباب التي تدعوه إلى ذلك.\nالمقصود: أن عليه عدم خيانة أخيه وعدم خداعه، فإذا كانت الأسعار في السوق رخيصة ومعروفة كالسلعة المعينة، أو فيها الطعام المعين أو في الأواني المعينة معروفة، فليس له أن يخدع أخاه بأن يبيع عليه بأكثر، المسلم أخو المسلم نعم.\nالمقدم: الله المستعان.. الله المستعان.","link":"https://binbaz.org.sa/fatwas/12395/هل-حدد-الشرع-مقدار-الربح-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48301.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14012,"question":"المستمع (د. م) سوداني مقيم في المملكة يقول: لدى بعض دلالي الأغنام في السودان عادة سيئة، وهي كثرة الحلف بالطلاق لترويج أغنامهم، وبعضهم متزوج وقد يكون ما حلف عليه بالطلاق مخالف للواقع، ما حكم هذا الحلف؟ وهل يقع الطلاق فعلًا؟ وهل هناك كفارة؟ وجهوهم شيخ عبد العزيز، جزاكم الله خيرًا.","title":"حكم ترويج البضاعة بالحلف بالطلاق","answer":"الجواب: هذا عمل لا يجوز لا بالطلاق ولا بغير الطلاق، ليس له أن يروج بضاعته بالأيمان لا بالأيمان بالله ولا بالطلاق كل ذلك لا يجوز؛ لأن هذا تغرير للناس وخداع للناس وربما كذب في ذلك، فإن من أكثر الأيمان يغلب عليه الكذب، ثم إنه يخدع الناس، قد يكون كاذبًا في ذلك ويخدع الناس بأيمانه حتى يشتروا سلعته، وإن كانت رديئة أو يشتروها بأكثر من ثمنها لكثرة أيمانه.\nوقد جاء في الحديث عنه عليه الصلاة والسلام أنه قال: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: أشيمط زاني يعني: شائب زاني وعائل مستكبر يعني: فقير ومستكبر ورجل جعل الله بضاعته لا يشتري إلا بيمينه ولا يبيع إلا بيمينه. فكثرة الحلف في البيع والشراء أمر منكر وخطير، ومن أسباب غضب الله ، فينبغي للمؤمن أن يحذر ذلك وأن لا يكثر الأيمان، فإن دعت الحاجة إلى اليمين فليكن صادقًا من غير إكثار، فإن اتهموه بأنه غاش في كذا أو غاش في كذا وهو ليس بغاش بل صادق وحلف لهم يمينًا بالله أنه صادق فلا بأس بذلك عند الحاجة، أما إكثار الأيمان بالطلاق أو بالله فهذا لا يجوز، وهو من أسباب الكذب، ومن أسباب الخداع والغش، وإذا كان صادقًا في طلاقه لا يقع شيء، لكن لا ينبغي له استعمال ذلك؛ لأنه وسيلة إلى وقوع الباطل ووسيلة إلى الطلاق الكاذب، وسيلة إلى فراق أهله، فينبغي للمؤمن أن يحذر ذلك، وأن يعتاد الصدق مع قلة الأيمان والمحافظة عليها، والله يقول سبحانه: وَاحْفَظُوا أَيْمَانَكُمْ[المائدة:89]. والإكثار من الأيمان من أسباب الكذب، من أسباب الوقوع في الكذب، ومن أسباب غش الناس وخديعة الناس، فالواجب الحذر من ذلك. وإذا كان في يمينه صادقًا أو في طلاقه صادقًا فلا شيء عليه لكن لا ينبغي له الإكثار من ذلك، بل يكون عند الحاجة مع القلة والعناية بعدم الكثرة حتى يسلم من الوعيد الشديد ومن غضب الله ، أما الكاذب هذا فيه وعيد الكذب -نسأل الله العافية-، وهو على خطر عظيم من الوعيد في كذبه في أيمانه وفي طلاقه، ويقول النبي ﷺ: من حلف على يمين وهو فيها كاذب لقي الله وهو عليه غضبان نسأل الله العافية.  فالواجب على المؤمن أن يحذر، وإذا كان كاذبًا، فقد ذهب أكثر أهل العلم إلى أنه يقع الطلاق نسأل الله العافية، والصواب أنه لا يقع الطلاق؛ لكنه لا يجوز له إذا كان قصده في يمينه أن يصدق في ذلك، وأن تقبل سلعته، وأن يأمنه الناس في ذلك فهو في ذلك مجرم إذا كان كاذبًا، ولكن ليس قصده إيقاع الطلاق وإنما قصده أن يصدقه الناس وأن يقبلوا سلعته، فهو على كل حال في هذا ظالم ومجرم ولا يجوز له فعله، وأما وقوع الطلاق لا يقع؛ لأن قصده تصديقه وليس قصده إيقاع الطلاق فيكون كفارة يمين في أصح قولي العلماء، لكن لا يجوز له تعاطي ذلك بل يجب عليه الحذر من ذلك؛ لئلا يوهم الناس ولئلا يخدع الناس، ولأن الكذب محرم مطلقًا. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/12433/حكم-ترويج-البضاعة-بالحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61103.mp3","categories":["الأيمان والنذور","البيوع"]},{"id":14125,"question":"سمعت في إحدى حلقات برنامجكم هذا سؤالًا يدور حول صحة رفع السعر لسلعة معينة إذا كان بالتقسيط، وقد أشكل علي فهم الإجابة، فكيف يصح للبائع أن يرفع سعر سلعته لمن أراد أن يدفع بالتقسيط، مع العلم أن ثمن السلعة مائة ريال مثلًا، فإذا أراد أن يبيعها مقسطة باعها بمائة وخمسين ريالًا، أليس هذا يشابه الربا إذا اقترض شخص مائة ريال لسد حاجته اشترط عليه المقرض أن يدفع مائة وخمسين ريالًا مقابل التأجيل وضحوا لي هذه المسألة. جزاكم الله خيرًا.","title":"هل الزيادة في بيع التقسيط ربا؟","answer":"الجواب: ليست مسألة التقسيط من جنس الربا، بل للناس أن يتبايعوا بالمداينة بما تراضوا عليه والتقسيط يختلف، قد تكون أقساطًا كثيرة، تحتاج إلى زيادة في الثمن وقد تكون قليلة، تكون الزيادة قليلة، فليس المداينة من جنس بيع النقد، ولا حرج في ذلك عند عامة العلماء، عند جمهور أهل العلم، بل هو كالإجماع، أنه لا حرج في الزيادة من أجل الأجل وليس هذا من الربا، لعموم قوله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] ولم يقل: بسعر الوقت ولا بسعر الحاضر.\nوقد جرت عادة المسلمين من عهد النبي ﷺ إلى يومنا هذا بأن البيع إلى أجل يكون فيه الزيادة، فإذا كانت السلعة تساوي مائة باعها بمائة و عشرين بمائة وثلاثين، مائة وأربعين، مائة وخمسين على حسب الآجال، فإذا كان الأجل قريب صار الربح قليلًا، وإذا كان الأجل طويلًا صار الربح كثيرًا والأقساط كثيرة، وقد باع أهل بريرة بريرة بتسع أواق في كل عام أوقية، ولم يسألهم النبي ﷺ: هل هذا سعرها في الوقت الحاضر أم لا، بل أقرهم النبي ﷺ على بيعها بالتقسيط، واشترتها عائشة بذلك أيضًا، وأعتقتها ولم يسأل هل بعتموها بسعر الحاضر أم لا، ولم يزل الناس يتبايعون في عهده ﷺ ولم يقل: لهم لا تبيعوا إلا بسعر الحاضر. الناس يستدينون والمداينة لا بد يكون فيها زيادة، لولا الزيادة ما باع إلى أجل، كان باع بيعاً معجلًا حتى يأخذ الثمن، لكن من أجل الزيادة أنظره، فالمشتري ينتفع بالسلعة التي اشتراها بثمن مؤجل، والبائع ينتفع بالزيادة التي تحصل له بالمداينة، فلا حرج في ذلك، هذا هو الذي عليه جمهور أهل العلم، وليس هذا من الربا في شيء، نعم.\nالمقدم: جزاكم الله خيرًا، يا أخ (ن. هـ. د) سنعود إلى أسئلتك في حلقة قادمة إن شاء الله تعالى.","link":"https://binbaz.org.sa/fatwas/12563/هل-الزيادة-في-بيع-التقسيط-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48420.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14126,"question":"هذه رسالة بعث بها المستمع رزق الله سلمان من المملكة الأردنية الهاشمية، الأخ رزق الله يسأل ويقول: اقترض رجل مبلغ مائة ريال من أحد أصدقائه على أن يعطيه في موسم الحصاد بدلًا منها عشرين صاعًا قمحًا، مع العلم أن العشرين صاعًا تساوي مائة وخمسين ريالًا، فهل هذه الزيادة مشروعة؟ وإن كانت مشروعة فإن فيها زيادة ليست مقابل شيء إلا مقابل التأجيل، أرجو توضيح هذه المسألة. جزاكم الله خيرًا.","title":"حكم إعطاء شخص مبلغًا على أن يعيده آصاعًا معلومة","answer":"الجواب: إذا كان ذلك على سبيل السلم، فلا بأس أن يعطيه مائة ريال في عشرين صاع يسلمها له في رمضان في شوال، هذا يسمى السلم، والنبي ﷺ قال لما قدم المدينة وهم يسلفون في الثمار السنة والسنتين قال: من أسلف في شيء فليسلف في كيل معلوم ووزن معلوم إلى أجل معلوم، فإذا أعطاه مائة ريال في عشرين صاعًا، أو أعطاه ألف ريال في مائة صاع أو أكثر إلى أجل معلوم من الذرة أو من الحنطة أو من الأرز فلا بأس، هذا يسمى السلم ما يسمى قرض، أما إذا أعطاه مائة ريال قرضًا وقال: شرط أنك تعطيني عنها عشرين صاعًا وقت كذا ووقت كذا، فهذا معناه السلم، لكن سوء تعبير، تسمى سوء تعبير ما هي بقرض. أما إذا أعطاه قرضًا على أنه يعطيه أكثر من مائة في الأجل المعلوم يعطيه مائة وعشرين ريال، مائة وثلاثين ... يزيده هذا ربا ما يصح، لكن بعض الناس قد لا يحسن عبارة السلم، فإذا أعطاه مائة ريال قال: هذه مائة ريال تقضي بها حاجتك الآن، وتعطيني مقابلها في شهر كذا عشرين صاعًا، ثلاثين صاعًا من الأرز من الحنطة من الذرة، هذا يسمى السلم أو تمر كذلك، إذا صار أجل معلوم والمطلوب معلوم أصواعًا معلومة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12565/حكم-اعطاء-شخص-مبلغا-على-ان-يعيده-اصاعا-معلومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48421.mp3","categories":["السلف والقرض","البيوع"]},{"id":14149,"question":"هذه السائلة أم إبراهيم من الكويت تقول: أود أن أسأل إذا أردت أن أشتري سيارة من شركة بالتقسيط مع العلم أن هذه الشركة تأخذ على كل مائة دينار ثمان دنانير فائدة، وتزيد هذه الفائدة حسب السنين، هل في ذلك شيء من الحرام؟الشيخ: أعد.المقدم: تقول السائلة: إذا أردت أن أشتري سيارة من شركة للسيارات بالأقساط، مع العلم بأن هذه الشركة تأخذ على كل مائة دينار ثمان دنانير فائدة، وتزيد هذه الفائدة حسب السنين، هل في ذلك شيء من الحرام؟","title":"حكم بيع التقسيط مع الزيادة في الثمن","answer":"الجواب: ما فيه شيء إذا اشترى الإنسان سيارة أو بيت أو غير ذلك بأقساط معينة وربح معلوم فلا بأس، لابد أن يكون على بصيرة بأقساط معلومة إلى آجال معلومة، ثم يبيعها هو لحاجاته أو يستمتع بها لا بأس.\nالمقصود إذا اشترط أنها ربحًا معينًا في أقساط معلومة فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12590/حكم-بيع-التقسيط-مع-الزيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54614.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14338,"question":"ما حكم من تعامل مع البنوك الزراعية بالطريقة الآتية: إذا طلب الشخص من بعض البنوك بابور زراعي، فأعطاه البنك مبلغ البابور؛ ليأخذه من بعض الشركات على أن يدفع المبلغ عن طريق القسط للبنك لمدة ثلاث سنوات، بزيادة معلومة على سعر الوابور الحالي،  هل هذا يعتبر ربًا، أم بيع لأجل؟ وما هو حكم بيع الأجل؟ هل هو حرام أم حلال؟","title":"حكم دفع البنك قيمة السلعة للمقترض وتقسيط المبلغ بزيادة","answer":"الجواب: هذا يعتبر من الربا، إذا أعطاه مالًا ليشتري به البابور، أو سيارة أو غير ذلك، أو المكينة على أنه يرد أكثر منه، فهذا من الربا، ولا يجوز. أما إذا اشترى له، إذا اشترى سلعة سيارة أو غيرها أو ماطورًا أو مكينة اشتراها البنك وتسلمها وحازها، ثم باعها عليه بآجال وأقساط معلومة فلا حرج في ذلك. وبيع التأجيل لا بأس به، وبيع الأقساط لا بأس به إذا كان المبيع مملوكًا للبائع، وفي حوزته قد قبضه، وحازه، ثم باعه بعد ذلك هذا هو الذي يجوز. أما أن يبيع شيئًا عند الناس، وفي مال التجار فلا يجوز؛ لأن الرسول  نهى عن بيع ما لا يملكه الإنسان، وقال ﷺ: لا تبع ما ليس عندك وقال: لا يحل سلف وبيع، ولا بيع ما ليس عندك.\nفالواجب على المؤمن أن يحذر ما حرم الله، وألا يبيع شيئًا عند الناس، وإذا أعطاه ألفًا على أن يرد ألفًا ومائة، أو أكثر أو أقل، ما يجوز هذه الزيادة ربا، ولا يكون بيعًا، هذا قرض، يسمى قرضًا. البيع أن تشتري منه السلعة بنفسك، يبيعها عليك بعدما حازها وملكها بعد هذا يبيعها بنقد مقدم أو بآجال، أو بنقد وآجال، كل ذلك لا بأس به، إذا كانت الأقساط معلومة واضحة، وكانت السلعة مملوكة للبائع، وفي حوزته، قد قبضها وحازها، فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12835/حكم-دفع-البنك-قيمة-السلعة-للمقترض-وتقسيط-المبلغ-بزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62312.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14345,"question":"ما حكم من تعامل مع البنوك الزراعية بالطريقة الآتية: إذا طلب الشخص من بعض البنوك بابور زراعي، فأعطاه البنك مبلغ البابور؛ ليأخذه من بعض الشركات على أن يدفع المبلغ عن طريق القسط للبنك لمدة ثلاث سنوات، بزيادة معلومة على سعر الوابور الحالي،  هل هذا يعتبر ربًا، أم بيع لأجل؟ وما هو حكم بيع الأجل؟ هل هو حرام أم حلال؟","title":"حكم دفع البنك قيمة السلعة للمقترض وتقسيط المبلغ بزيادة","answer":"الجواب: هذا يعتبر من الربا، إذا أعطاه مالًا ليشتري به البابور، أو سيارة أو غير ذلك، أو المكينة على أنه يرد أكثر منه، فهذا من الربا، ولا يجوز. أما إذا اشترى له، إذا اشترى سلعة سيارة أو غيرها أو ماطورًا أو مكينة اشتراها البنك وتسلمها وحازها، ثم باعها عليه بآجال وأقساط معلومة فلا حرج في ذلك. وبيع التأجيل لا بأس به، وبيع الأقساط لا بأس به إذا كان المبيع مملوكًا للبائع، وفي حوزته قد قبضه، وحازه، ثم باعه بعد ذلك هذا هو الذي يجوز. أما أن يبيع شيئًا عند الناس، وفي مال التجار فلا يجوز؛ لأن الرسول  نهى عن بيع ما لا يملكه الإنسان، وقال ﷺ: لا تبع ما ليس عندك وقال: لا يحل سلف وبيع، ولا بيع ما ليس عندك.\nفالواجب على المؤمن أن يحذر ما حرم الله، وألا يبيع شيئًا عند الناس، وإذا أعطاه ألفًا على أن يرد ألفًا ومائة، أو أكثر أو أقل، ما يجوز هذه الزيادة ربا، ولا يكون بيعًا، هذا قرض، يسمى قرضًا. البيع أن تشتري منه السلعة بنفسك، يبيعها عليك بعدما حازها وملكها بعد هذا يبيعها بنقد مقدم أو بآجال، أو بنقد وآجال، كل ذلك لا بأس به، إذا كانت الأقساط معلومة واضحة، وكانت السلعة مملوكة للبائع، وفي حوزته، قد قبضها وحازها، فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12835/حكم-دفع-البنك-قيمة-السلعة-للمقترض-وتقسيط-المبلغ-بزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62312.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14462,"question":"يسأل سؤال آخر ويقول: نتوجه إلى البنك الإسلامي لكي يقوم البنك بشراء ما نريده مثل سيارة أو مواد للبناء، أو ما شابه ذلك، ويحاسب التاجر، ويقسط المبلغ علينا، ويربح البنك نسبة معينة فوق التسعيرة العادية، ما صحة ذلك في الشريعة الإسلامية؟جزاكم الله خيرًا.","title":"ما حكم بيع المداينة؟","answer":"الجواب: لا حرج في ذلك، هذا بيع المداينة، بيع الأجل، والله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ[البقرة:282] ويقول ﷺ: من أسلف فليسلف في كيل معلوم، ووزن معلوم، إلى أجل معلوم فإذا اشترى البنك الإسلامي الحاجات التي لكم من أدوات فلاحة، من سيارات، من غير ذلك، اشتراها وقبضها وحازها، وصارت إلى ملكه، ثم باعها عليكم بثمن مؤجل بربح معين؛ فلا بأس بذلك؛ لأن البنك يستفيد الربح، وأنتم تستفيدون التأجيل، وعدم تكليفكم بالثمن الحاضر، حتى تقضوا حاجاتكم، فأنتم مستفيدون وهو مستفيد، أنتم مستفيدون بالإمهال وإنظاركم، وهو مستفيد بالربح الذي فرضه عليكم، ورضيتم به. فقد اشترى السيارة مثلًا بثلاثين ألفًا، وباعها عليكم بخمس وثلاثين ألفًا، كل سنة خمسة آلاف، أو كل شهر ألف، أو ما أشبه ذلك، هذا كله لا حرج فيه، لكن بشرط أن يكون قد حاز المبيع هذا، لا يبيع عليكم عند الشركة، لا، يبيع شيء عنده قد حازه واشتراه وقبضه، ثم يبيع؛ لقول النبي ﷺ: لا تبع ما ليس عندك ويقول ﷺ: لا يحل سلف ولا بيع، ولا بيع ما ليس عندك فليس للبنك أن يبيع شيئًا ليس عنده، إنما يبيع الشيء الذي عنده فقط، قد حازه وملكه واشتراه وصار في قبضته، يبيع بعد ذلك عليكم وعلى غيركم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12947/ما-حكم-بيع-المداينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63203.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14873,"question":"أيضًا يسأل ويقول: ما هو رأي سماحتكم فيمن يخلط الزيت النباتي بالسمن البقري، ثم يبيعه سمنًا، وحين اعترضت على بعض من يفعل ذلك، وقلت له: هذا غش وحرام، أجاب: إن بقرتي تنتج في الأسبوع قارورة سعة لتر واحد، وثمن اللتر مائة ريال، وهذه المائة لا تكفي في الأسبوع ثمن العلف الذي تأكله البقرة، لكني أخلط الزيت بالسمن لتكون ثلاث قوارير، يعني: بثمن ثلاثمائة ريال، وبذلك أستطيع أشتري ما يكفي دابتي من قوت الأسبوع. أرجو التوجيه والنصح والتوضيح حول هذا الموضوع. جزاكم الله خيرًا.","title":"حكم بيع السمن المخلوط بالزيت","answer":"الجواب: هذا من الغش، ولا يجوز خلط الزيت بالسمن، وهذا العذر الذي قاله عذر فاسد، لا يقبل، ولا يجيز له هذا الغش، بل عليه أن يبيع الزيت وحده، والسمن وحده، ويسأل ربه التوفيق، ويستعين بالله، والله يبارك له إذا صدق، وترك الخيانة، وأدى الأمانة، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فالواجب على التجار وعلى أهل البيع والشراء أن يتقوا الله، وأن يؤدوا الأمانة، وأن يحذروا الغش والخيانة، ولو كانوا فقراء، الله يغنيهم من فضله ، فليس الفقر عذرًا في الغش والخيانة، بل يجب على المؤمن والمؤمنة التحري للحق والعناية بالأمانة الشرعية والحذر من الغش والخداع، ولو كان فقيرًا، الله -جل وعلا- هو الذي يغنيه من فضله ، وإذا اتقاه يسر أمره. فالواجب الحذر غاية الحذر من هذه الخيانات التي حرمها الله على عباده، والله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27] ويقول سبحانه: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58] ويقول  في صفة أهل الإيمان: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13367/حكم-بيع-السمن-المخلوط-بالزيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64510.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":14973,"question":"إضافة إلى سؤالها السابق تقول: إن بقايا القماش الصغيرة التي أرميها مع النفايات هل علي فيها حرام؟ علمًا بأنه إذا كانت كبيرة أعيدها مع القماش إلى أهلها. جزاكم الله خيرًا.","title":"حكم عدم رد الخياطة قطع القماش الصغيرة لأهلها","answer":"الجواب: إذا كانت القطعة لا يرغبها أهلها فلا حرج، أما إذا كنت تشكين فأعيديها إليهم يتصرفون فيها، أما إذا كنت تعلمين أنهم يرغبون في إتلافها، وتركها في القمامة فلا بأس. وأما الزكاة فليس عليك زكاة، الزكاة ليس عليك زكاة إذا كانت النقود تصرف في حاجة البيت، ولا يمضي عليها سنة.  أما إذا كانت تبقى عندك نقود، يمضي عليها سنة، وهي نصاب فعليك الزكاة، فعلى هذا لو كان عندك ألف ريال مثلًا، بقي عندك سنة، ما أنفقتيه تؤدين زكاته، وهي ربع العشر، خمسة وعشرون من ألف، أما إذا كانت الأجرة تنفق في وقتها، أو بعد وقتها، لكن لا تبقى سنة فليس عليك زكاة، إلا إذا اجتمع مال من هذه الخياطة، يبلغ النصاب ودارت عليه السنة فإنه يزكى، وأقل النصاب ستة وخمسون ريال فضة، أو ما يقوم مقامها من النقود الورقية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13473/حكم-عدم-رد-الخياطة-قطع-القماش-الصغيرة-لاهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49210.mp3","categories":["قضايا المرأة","البيوع"]},{"id":15040,"question":"زوج أختي ذلكم الذي ذكرت في السؤال السابق، يسكن في قرية بعيدة عنا، وأقوم بصلتهم، علمًا أن والدي متوفى، وأنا الذي أحل محله، فإذا أحضروا لي الطعام فهل يصح أن آكل منه؟ وإذا اقترضت منهم مبلغًا من المال وعلى طول أقوم بسداده، فهل هذا المال يحرم علي؟","title":"حكم الأكل من طعام تارك الصلاة والاقتراض منه","answer":"الجواب: أما أنت فلا مانع أن تصلهم بالمعروف، رجاء أن يهديه الله، ويسلم، ولا سيما إذا كان فقيرًا، لا بأس أن تحسن إليه؛ لأن معه أختك، لا بأس؛ ولعل الله أن يهديه، ويرجع إلى الحق بأسباب حسن خلقك، وطيب عملك معه.  وأما الاقتراض منه ينبغي أن تستغني عنه ما دام بهذه الحالة، ولا أن تعاشره، ولا أن تتخذه صاحبًا، ولا أن تزوره، بل تهجره لعله يتوب، لكن إذا أحسنت إليه لا بأس. أما الطعام ينظر فيه، فإذا كان الطعام فاكهة أو نحوه لا بأس، أما إن كان شيء يذبح هو الذي ذبحه بنفسه فذبيحته لا تحل، أما إن كان طعام من غير ذبحه، لحم من السوق، أو فاكهة، أو نحو هذا مما ليس فيه ذبح، فلا حرج في قبوله إذا رأيت ذلك، وإن رأيت رده إليه من باب الهجر، ومن باب إظهار كراهتك لعمله، وغضبك عليه، فهذا حسن -إن شاء الله-، وإن رأيت أن قبول الهدية فيها مصلحة لتأليفه، ودعوته إلى التوبة، فأنت بهذا تجتهد وتعمل ما هو الأصلح، لكن مع كراهتك لعمله، وهجرك إياه، وتحذيرك إياه من هذا العمل السيئ، لعل الله يتوب عليه بأسبابك؛ لأن عمله عظيم، الجرم شديد الخبث، وهو ترك الصلاة نعوذ بالله، الصلاة عمود الإسلام من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع. والمقصود: أن تعالج الأمر بما ترجو فيه الخير، مع هجره وعدم زيارته إلا على وجه تزوره فيه للدعوة فقط، لا للطعام والشراب والأنس معه، ولكن تزوره إذا رأيت المصلحة للدعوة، والتوجيه إلى الخير، وتحذيره غضب الله، وإخباره بأن هذا العمل ردة عن الإسلام في أصح قولي العلماء، على هذا السبيل تكون مأجورًا -إن شاء الله-، أما على سبيل التحاب أو الأنس به، فلا تزره على هذا الوجه، بل يستحق الهجر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13540/حكم-الاكل-من-طعام-تارك-الصلاة-والاقتراض-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49310.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15135,"question":"يقول في سؤاله الأول: ما حكم بيع الذهب الحلي بالريالات السعودية؟ وهل يجوز أن يبقي بعض الثمن أو كله وليس هناك زيادة في السعر؟","title":"حكم تأجيل ثمن الذهب أو جزءًا منه عند بيعه","answer":"الجواب: لا يجوز أن يبيع ذلك إلا يدًا بيد، لا يبع الذهب بالريالات السعودية، ولا بغيرها من العُمَل إلا يدًا بيد، هكذا؛ لأن هذه العمل في منزلة الذهب والفضة، فلا يجوز بيع الذهب بالورق إلا يدًا بيد مطلقًا، سواءٌ كان دنانير أو دولارات أو دراهم سعودية، لا بد يكون يدًا بيد، نعم.","link":"https://binbaz.org.sa/fatwas/13640/حكم-تاجيل-ثمن-الذهب-او-جزءا-منه-عند-بيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66503.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15232,"question":"له سؤال آخر يقول: يوجد عندي سيارة، وبعتها إلى إخواني الاثنين منذ أربعة أشهر على أن يستردوها بعد كذا من الزمن، وعندما طلبت.الشيخ: أعد.المقدم: يوجد عندي سيارة، وبعتها إلى إخواني الاثنين منذ أربعة أشهر، على أن يستردوا ثمنها -يعني: يردوا ثمنها علي- بعد كذا من الزمن، وعندما طلبت ثمنها، قالوا لي: حتى نسحب من البنك. علماً أن البنك يتعامل بالفائدة، وعلماً أن كل سنة يسحبون مبلغًا من البنك ويسددونه بالفائدة. أفتوني عن المبلغ هذا هل يجوز لي أن آخذه منهم أم لا؟","title":"حكم من باع شيئاً وأعطي ثمنه من الربا","answer":"الجواب: الواجب عليهم أن يؤدوا لك الحق عند مضي الأجل، إذا مضى الأجل وجب عليهم أن يؤدوا الحق لك، وهو الثمن.\nلكن إذا أخذوا الثمن من مال ربوي فإنه ليس لك قبول ذلك؛ لأنه مال حرام.  أما إن أدوا إليك من مال لا تعرفه ولا تدري عنه فلا بأس تأخذه والإثم عليهم، أما إذا علمت أن هذا المال المعين من الربا فلا تأخذه، واطلب منهم مالًا آخر، ولا تأخذ مال الربا، نعم.","link":"https://binbaz.org.sa/fatwas/13735/حكم-من-باع-شيىا-واعطي-ثمنه-من-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67303.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15633,"question":"بالنسبة للشخص الذي يشتري السلعة بثمن يزيد عن ثمنها مرة ونصف إلى أجل مسمى لمدة ستة شهور أو أكثر، أفيدونا هل هذا حلال أم حرام؟","title":"حكم البيع إلى أجل مع زيادة الثمن","answer":"الجواب: لا حرج إذا اشترى السلعة بأكثر من ثمنها إلى أجل، أو إلى آجال لا حرج؛ لأن الدين لا بد يزاد فيه، ما هو مثل النقد، فإذا شرى السلعة التي تساوي مائة اشتراها بمائة وخمسين إلى آجال أو بمائتين أيضًا إلى آجال؛ فلا بأس بذلك، ولا حرج في ذلك لقوله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ[البقرة:282] فلا حرج في ذلك؛ لأن الحاجة في.....، إنما أجله عليه من أجل الزيادة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم..","link":"https://binbaz.org.sa/fatwas/14175/حكم-البيع-الى-اجل-مع-زيادة-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57116.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15711,"question":"سماحة الشيخ، ما هي بعض الطرق المحرمة في البيع بالتقسيط؟","title":"صورة محرمة في بيع التقسيط","answer":"الجواب: إذا باعه على من اشتراه منه، فإذا اشترى شيئًا مؤجلًا أقساطًا، ثم باعه نقدًا على من شراه منه، هذا يسمى عينة؛ فلا يجوز، لكن إذا باعه على غيره لا بأس، إذا اشترى سيارة بالتقسيط، ثم باعها على آخر، زيد أو عمرو نقدًا؛ ليتزوج، أو ليوفي دين، أو يعمر سكنًا؛ لا بأس بذلك.  أما أنه يشتري السيارة أو غيرها بالتقسيط، ثم يبيعها بالنقد على صاحبها هذا يسمى العينة، لأنه حيلة على أخذ الدراهم نقدًا بدراهم أكثر منها مؤجلة. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/14269/صورة-محرمة-في-بيع-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57401.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15745,"question":"سماحة الشيخ، هذا السائل من الإمارات، العين، رمز لاسمه بـ (ع. م. س) يقول في هذا أخي اشترى سيارة، وقالوا له: إذا دفعت المبلغ دفعة واحدة نخفض من سعرها، وإذا دفعت المبلغ بالأقساط كل شهر مبلغ معين، نزيد في سعرها، ومن هنا أتساءل يا سماحة الشيخ: هل يجوز لأخي أن يشتري السيارة بالأقساط وعليها الفائدة؟ وهل يعتبر ذلك من الربا؟","title":"جواز بيع التقسيط","answer":"الجواب: إذا اتفقوا على هذا أو هذا، فلا بأس، إذا اتفقوا على النقد فلا بأس، وإن اتفقوا على أقساط معلومة فلا بأس، كل شهر كذا وكذا معين؛ لقول الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282] هذا يعم الأقساط والقسط الواحد، إذا اتفقوا على ذلك كل شهر بشيء معلوم، أو كل سنة شيء معلوم، وإن اتفقوا على النقد، وتفرقوا على النقد بشيء معلوم فلا بأس، أما أن يتفرقون وهم لم يجتمعوا على شيء لا هذا ولا هذا، ما يصح، لا بد أن يجزموا على النقد، أو على التأجيل قبل أن يتفرقوا.\nالمقدم: حفظكم الله يا سماحة الشيخ، لعلكم تبسطون القول في البيوع في وقتنا الحاضر، ما هو المحرم منها، وما هو الجائز؛ لأنها أشكلت على كثير من الناس سماحة الشيخ.\nالشيخ: الله سبحانه يقول: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275] البيع حلال إذا كان سليم من الجهالة بثمن معلوم، والمبيع معلوم، أو بأجل معلوم لا بأس، أما إذا كان مجهول الأجل، أو مجهول الثمن، أو مجهول المبيع، ما يصح، لا بد أن يكون المبيع معلومًا، والثمن معلومًا، إما نقدًا، وإما مؤجلًا بأجل معلوم، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14330/جواز-بيع-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57507.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15884,"question":"رسالة وصلت إلى البرنامج من المستمع محمد واصل السلمي، يسأل فيها سؤالين:في سؤاله الأول يقول: ما هو حكم بيع سيارة قديمة، واستبدالها بسيارة أخرى جديدة، مع الزيادة على القيمة؟جزاكم الله خيرًا.","title":"حكم استبدال سيارة قديمة بجديدة مع زيادة في الثمن","answer":"الجواب: ليس في ذلك حرج أن يبيع سيارة بسيارة، مع الزيادة من أحد الجانبين لا بأس بذلك، أو أرضًا بأرض مع الزيادة لأحد الجانبين، أو حيوانًا بحيوان، كبعير ببعير، أو شاة بشاة، أو ما أشبه ذلك. فالمقصود: لا حرج في البيع سلعة بسلعة مع زيادة إذا لم تكن تلك السلعة ربوية، أما بيع الذهب بفضة، فهذا لا بد أن يكون يدًا بيد، أما بيع ذهب بذهب فلا بد أن يكون مثلًا بمثل، سواءً بسواء، يدًا بيد، أو بيع فضة بفضة كذلك لا بد أن يكون مثلًا بمثل، سواءً بسواء، يدًا بيد.  أما بيع السيارة فليس من أمور الربا، بيع سيارة بسيارة ليس من أمور الربا، وهكذا بيع أرض بأرض، أو بعير ببعير، أو ما أشبه ذلك، ولو كان في أحد الجانبين زيادة في النقود، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14477/حكم-استبدال-سيارة-قديمة-بجديدة-مع-زيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74504.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15915,"question":"من جمهورية مصر العربية محافظة الإسكندرية، المستمع: ناجي فايز، يسأل ويقول: نحن أناس مزارعون، وعندما نريد بيع الخضار والفواكه نجعل النوع الجيد في أعلى السلال، والرديء في أدناها، أو الحبة الصغيرة، في أسفل السلال، فما حكم عملنا هذا؟وجهونا، جزاكم الله خيرًا، وقد نوقشنا في هذه المسائل، فالبعض يقول: إن هذا من توريد البضاعة، والبعض الآخر يقول: إنه من تزوير البضاعة، فما هو القول الصحيح؟جزاكم الله خيرًا.","title":"حكم إخفاء البضاعة الرديئة وإظهار الجيدة","answer":"الجواب: الواجب على المسلم ألا يغش إخوانه في كل شيء، فإذا عرض بضاعة بعضها رديء وبعضها طيب، لا بد يبين الجميع، لا يجعل الرديء أسفل، والطيب فوق، بل يجعله في إناء يتضح في الجميع، أو الوكيل يبين، يقول: ترى الأسفل كذا، صفته كذا، وصفته كذا، يبين ولا يغش الناس، لا يجوز لكم ولا لغيركم أن تغشوا الناس، لا في الفواكه، ولا في التمور، ولا في غير ذلك، يجب أن يكون أسفل البضاعة مثل ظاهرها، يبين كل شيء؛ لأن المسلم أخو المسلم، لا يغره، ولا يخونه، ولا يغشه، يقول النبي ﷺ: من غشنا فليس منا والله يقول -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27] هكذا يقول : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27] ويقول سبحانه: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58] ويقول -جل وعلا-: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8] هذه صفة المؤمن. وصح عن النبي ﷺ أنه مر على صبرة من طعام في السوق، مر في السوق على إنسان يبيع الطعام، فأدخل يده في الصبرة، فنالت أصابعه بللًا، فقال: يا صاحب الطعام ما هذا؟ قال: أصابته السماء يا رسول الله -يعني: أصابه المطر- قال: أفلا جعلته فوق الطعام، كي يراه الناس، من غشنا فليس منا هذا واضح في المسألة، مسألتك أيها السائل، هذه منها، فإذا عرضت حبوبًا أو فواكه أو غير ذلك، فالواجب عليك يا أخي أن تبين كل شيء، وعلى وكيلك ذلك أيضًا، وإلا صار خائنًا غاشًا، فعليك وعلى الوكيل بيان الحقيقة، الباطن والظاهر، من التمر، والفواكه وغير ذلك، حتى يكون المشتري على بينة، وحتى تسلم من قول النبي ﷺ: من غشنا فليس منا وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14509/حكم-اخفاء-البضاعة-الرديىة-واظهار-الجيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_708/nour_70806.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15950,"question":"ننتقل بعد هذا إلى رسالة من الطائف بني سعد باعثها المستمع فيصل المندومي، أخونا يسأل عن حكم اقتراض الحيوان بالحيوان؟ جزاكم الله خيرًا.","title":"حكم اقتراض الحيوان بالحيوان","answer":"الجواب: لا بأس إذا اقترض منه شاة، أو بقرة، أو بعيرًا، وضبط صفاته ورد عليه مثله لا بأس بذلك؛ لأن أمره واضح، والصفات تحفظ المقترض وتبينه، والتساهل بين المسلمين في هذا واقع، مثلما يقترض الدراهم والدنانير والطعام، كذلك لا بأس إذا اقترض الحيوان: من شاة، أو بعير، أو غيرهما من الحيوانات التي تملك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14559/حكم-اقتراض-الحيوان-بالحيوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71009.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15975,"question":"هذه في البداية رسالة من السائل عبدالله الدوسري، من الرياض، يقول: ذهبت يومًا من الأيام إلى سوق السيارات المسمى بالحراج، ووقفت عند سيارة أريد شراءها، وسألت صاحبها: بكم هذه؟ فقال لي مثلًا: بعشرة آلاف ريال، فأخذت أنظر في السيارة وأتفحصها، ثم جاء رجل وسأل صاحبها: بكم هذه؟ فقال له مثلما قال لي، فزاد هذا الرجل مائتين، وقال صاحب السيارة: هي من نصيبك، فتردد الرجل، وقال: سأذهب أشاور، ونحن لا زلنا عند السيارة، فقال صاحبها: إذا كنتم تريدونها بهذا السعر فخذوها بما أراد هذا الرجل شراءها به، فاشتريناها منه، فهل فعلي هذا يعتبر من بيع المسلم على بيع أخيه، أو شرائه على شرائه؟ إذا كان كذلك، فأرشدونا ماذا نفعل الآن؟","title":"صورة بيع المسلم على بيع أخيه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان الواقع هو ما ذكره السائل فلا حرج في ذلك؛ لأن صاحب السيارة لم يبعها على ذاك الذي قال: أشاور، بل تركه، وقال: إن كنتم تريدون شراءها بهذا فخذوها، فما دام المالك لم يرض ببيعها على من قال: عشرة آلاف ومائتين، وسوف أشاور لما قال: نعم، وأراد بيعها على من حضر فلا بأس، من حضر وأخذها بعشرة آلاف ومائتين فلا بأس؛ لأن صاحب السيارة لم يجزم ببيعها على ذاك، بل لما قال له: سوف أشاور، أعرض عنه، وقال: من أراد أن يأخذها بكذا وكذا، فهذا معناه أنه لم يرض بانتظاره، وأراد أن يبيعها في الحال. فأنت -يا أيها السائل- إذا كنت أخذتها بما قال فلا بأس، وليس هذا من بيع المسلم على بيع أخيه، نعم البيع على بيع أخيه إذا باعها عليك وانتهى الأمر فليس لأحد أن يزيد عليك، هذا معناه، أما ما دام يقول: من أراد أن يشتري فله الشراء فهو حتى الآن ما باع على أحد، نعم.\nالمقدم: لو تتفضلون بذكر مثال لبيع الرجل على بيع أخيه لعله يتضح؟\nالشيخ: المثال واضح؛ إذا باع السيارة عليه قال: نصيبك بعشرة آلاف أو بأقل أو بأكثر فليس لأحد بعد هذا أن يزيد عليه لا في المجلس ولا بعده؛ ولهذا الرسول ﷺ نهى عن بيع المسلم على بيع أخيه، وهكذا الشراء على شرائه ما يجوز، ما دام قال: نصيبك هي لك فليس لأحد أن يشتري على شرائه أو يقول له: بع بكذا وكذا، ولا يبيع على بيع أخيه، يذهب للذي شراها بعشرة آلاف، ويقول له: عندي سيارة أحسن منها، أريد أعطيك إياها بتسعة آلاف أو بعشرة آلاف حتى يهون عن هذا، فليس له البيع على بيع أخيه ولا الشراء على شراء أخيه، فالشراء على شرائه أن يأتي واحد ويقول: أنا آخذها بأكثر، هذا لا يجوز، والبيع على بيعه كونه يذهب للمشتري ويقول: أعطيك سيارة أحسن منها بكذا وكذا، أو مثلها بأقل منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14599/صورة-بيع-المسلم-على-بيع-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68001.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":15979,"question":"هذه في البداية رسالة من السائل عبدالله الدوسري، من الرياض، يقول: ذهبت يومًا من الأيام إلى سوق السيارات المسمى بالحراج، ووقفت عند سيارة أريد شراءها، وسألت صاحبها: بكم هذه؟ فقال لي مثلًا: بعشرة آلاف ريال، فأخذت أنظر في السيارة وأتفحصها، ثم جاء رجل وسأل صاحبها: بكم هذه؟ فقال له مثلما قال لي، فزاد هذا الرجل مائتين، وقال صاحب السيارة: هي من نصيبك، فتردد الرجل، وقال: سأذهب أشاور، ونحن لا زلنا عند السيارة، فقال صاحبها: إذا كنتم تريدونها بهذا السعر فخذوها بما أراد هذا الرجل شراءها به، فاشتريناها منه، فهل فعلي هذا يعتبر من بيع المسلم على بيع أخيه، أو شرائه على شرائه؟ إذا كان كذلك، فأرشدونا ماذا نفعل الآن؟","title":"صورة بيع المسلم على بيع أخيه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان الواقع هو ما ذكره السائل فلا حرج في ذلك؛ لأن صاحب السيارة لم يبعها على ذاك الذي قال: أشاور، بل تركه، وقال: إن كنتم تريدون شراءها بهذا فخذوها، فما دام المالك لم يرض ببيعها على من قال: عشرة آلاف ومائتين، وسوف أشاور لما قال: نعم، وأراد بيعها على من حضر فلا بأس، من حضر وأخذها بعشرة آلاف ومائتين فلا بأس؛ لأن صاحب السيارة لم يجزم ببيعها على ذاك، بل لما قال له: سوف أشاور، أعرض عنه، وقال: من أراد أن يأخذها بكذا وكذا، فهذا معناه أنه لم يرض بانتظاره، وأراد أن يبيعها في الحال. فأنت -يا أيها السائل- إذا كنت أخذتها بما قال فلا بأس، وليس هذا من بيع المسلم على بيع أخيه، نعم البيع على بيع أخيه إذا باعها عليك وانتهى الأمر فليس لأحد أن يزيد عليك، هذا معناه، أما ما دام يقول: من أراد أن يشتري فله الشراء فهو حتى الآن ما باع على أحد، نعم.\nالمقدم: لو تتفضلون بذكر مثال لبيع الرجل على بيع أخيه لعله يتضح؟\nالشيخ: المثال واضح؛ إذا باع السيارة عليه قال: نصيبك بعشرة آلاف أو بأقل أو بأكثر فليس لأحد بعد هذا أن يزيد عليه لا في المجلس ولا بعده؛ ولهذا الرسول ﷺ نهى عن بيع المسلم على بيع أخيه، وهكذا الشراء على شرائه ما يجوز، ما دام قال: نصيبك هي لك فليس لأحد أن يشتري على شرائه أو يقول له: بع بكذا وكذا، ولا يبيع على بيع أخيه، يذهب للذي شراها بعشرة آلاف، ويقول له: عندي سيارة أحسن منها، أريد أعطيك إياها بتسعة آلاف أو بعشرة آلاف حتى يهون عن هذا، فليس له البيع على بيع أخيه ولا الشراء على شراء أخيه، فالشراء على شرائه أن يأتي واحد ويقول: أنا آخذها بأكثر، هذا لا يجوز، والبيع على بيعه كونه يذهب للمشتري ويقول: أعطيك سيارة أحسن منها بكذا وكذا، أو مثلها بأقل منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14599/صورة-بيع-المسلم-على-بيع-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68001.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16058,"question":"هل يجوز شراء العملة بثمن رخيص، وبيعها بثمن أغلى؟","title":"حكم شراء العملة بثمن رخيص وبيعها بأغلى","answer":"الجواب: لا حرج إذا تيسر شراؤها من دون مخادعة، ولا ظلم، قد اشتراها من السوق، وبقيت عنده، ثم باعها بأغلى، إذا غليت؛ لا حرج في ذلك، لكن لا يخدع أحدًا، يشتريها شراء شرعيًا، ثم إذا غليت؛ باعها بما يسر الله له، لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14684/حكم-شراء-العملة-بثمن-رخيص-وبيعها-باغلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74813.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16121,"question":"من أسئلة هذا السائل -يا سماحة الشيخ- يقول: ما حكم من اشترى شيئًا مسروقًا، وهو لا يعلم بذلك، ثم تبين له بأنه مسروق، هل يقوم برده إلى من سرق منه إذا كان يعلمه؟","title":"حكم رد من تبين له أن ما اشتراه كان مسروقًا","answer":"الجواب: نعم إذا علم أنه مسروق؛ فالبيع باطل، وعليه رده إلى من علم أنه ماله، ويطالب الذي باع عليه بالثمن، يلتمسه، ويطلب منه الثمن، ولا يجوز له استعمال المسروق الذي يعلم أنه مسروق، بل يرده إلى صاحبه، هذا هو الواجب عليه.. المسلمون إخوة، والواجب عليه رد ما عرف أنه ظلم، وسرقة، نعم.","link":"https://binbaz.org.sa/fatwas/14772/حكم-رد-من-تبين-له-ان-ما-اشتراه-كان-مسروقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57927.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16130,"question":"رسالة من أحد الإخوة المستمعين آثر عدم ذكر اسمه يسأل في سؤاله الأول ويقول: الذي يكون عاقًا لوالديه، هل تقبل منه صلاته وصومه وصدقته؟ وبماذا تنصحون الناس؟ جزاكم الله خيرًا.","title":"حكم قبول أعمال العاق لوالديه والحلف على المصحف","answer":"الجواب: عقوق الوالدين من كبائر الذنوب، ومن المحرمات العظيمة، فالواجب الحذر منه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: إن الله حرم عليكم عقوق الأمهات وقال -عليه الصلاة والسلام-: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين وكان متكئًا فجلس فقال: ألا وقول الزور، ألا وشهادة الزور متفق على صحته.  والله يقول في كتابه الكريم : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] يعني: أمر أن لا تعبدوا إلا إياه وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23، 24] ويقول سبحانه في سورة لقمان: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]. فالواجب على الولد أن يشكر لوالديه، وأن يحسن إليهما، وأن يبرهما، وأن يطيعهما في المعروف، ويحرم عليه عقوقهما لا بالكلام، ولا بالفعل، فليس له أن يرفع صوته عليهما، وليس له ضربهما، وليس له عدم النفقة عليهما مع الحاجة إلى ذلك، وليس له عصيانهما في المعروف، بل يجب عليه طاعتهما في المعروف، وبرهما، وخفض الصوت إذا خاطبهما، والتأدب معهما في كل شيء. لكن لا يطيعهما في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلو أمراه أن يزني، أو يشرب الخمر، أو لا يصلي في الجماعة؛ لا يطيعهما، لكن يطيعهما في المعروف، يبرهما في المعروف، يحسن إليهما، يخاطبهما بالتي هي أحسن، ينفق عليهما إذا احتاجا إلى ذلك، هكذا المؤمن مع والديه، فحقهما عظيم، وبرهما من أهم الواجبات،. لكن ليس عقوقهما مبطلًا للصلاة، ولا للصوم، ولا للأعمال الصالحات، ولكن صاحبه على خطر من هذه الكبيرة العظيمة. وإنما تبطل الأعمال بالشرك، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] أما بالعقوق، أو قطيعة الرحم، أو المعاصي الأخرى فإنها لا تبطل الأعمال، وإنما يبطلها الشرك الأكبر. وكذلك رفع الصوت على رسول الله ﷺ يخشى منه بطلان العمل في حياته ﷺ كما قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لا تَشْعُرُونَ [الحجرات:2] يعني: لئلا تحبط أعمالكم، فهذا يفيد أنه يخشى على من رفع صوته على النبي ﷺ وجهر له بالقول أن يحبط عمله، وهذا وعيد عظيم، ولهذا كان الصحابة يتأدبون مع الرسول ﷺ ويتكلمون معه كلامًا خفيفًا لينًا مخفوضًا تأدبًا معه، عليه الصلاة والسلام. فالمقصود: أن الواجب على المؤمن أن يبر والديه، وأن لا يعقهما، وأن يحسن إليهما في حياتهما، وبعد وفاتهما، ويحرم عليه العقوق لهما بالكلام السيء، أو السب، أو الضرب، أو أي إساءة لهما، أو رفع الصوت عليهما، أو عدم طاعتهما في المعروف، كل هذا من العقوق. المقدم: جزاكم الله خيرًا.  الشيخ: نسأل الله العافية. المقدم: اللهم آمين. المقدم: يسأل أيضًا أخونا ويقول: إذا حلف إنسان على القرآن وهو يحلف في نفسه، هل يجوز هذا، أم لا؟ الشيخ: كيف؟ المقدم: يقول: إذا حلف إنسان على القرآن، وهو يحلف في نفسه -لعله يقصد سرًا- هل يجوز، أم لا؟ جزاكم الله خيرًا. الشيخ: هذا السؤال ليس بواضح، إذا حلف على القرآن؛ صار أشد في اليمين، وليس هناك حاجة إلى الحلف بالقرآن، يحلف ولا حاجة إلى أن يحضر القرآن، يتقي الله وهو يحلف، ويتحرى الصدق، ولا يلزم إحضار القرآن، كثير من الناس يطلب إحضار القرآن، هذا لا أصل له، ولا حاجة إليه. الواجب على المؤمن أن يصدق أينما كان، ولا يجوز الكذب لا مع قرآن، ولا مع غير القرآن، يجب أن يصدق في الخصومات وفي غيرها، وليس له الكذب إلا إذا كان مظلومًا، إذا كان مظلومًا؛ فله الكذب، ويتأول إذا كان مظلومًا. وأما إذا كان غير مظلوم؛ فليس له أن يكذب، وليس له أن يحلف في أي شيء كاذبًا، كأن يدعى عليه أنه أخذ مال فلان، أو ضرب فلانًا، أو قتل فلانًا، ليس له أن يحلف، ينكر ذلك، بل عليه أن يقر بالحق، يعطيهم مالهم، يلزمه القصاص إذا توفرت شروطه، لا يكذب. أما إذا كان مظلومًا هذا شيء آخر، له أن يتأول إذا كان مظلومًا، أن يقال له: احلف أنك ما فعلت كذا وكذا، وهو لم يفعله، ولم يقع منه، فيحلف بالله أنه لم يقع منه، وليس في هذا شيء عليه؛ لأنه صادق. المقصود: أنه ليس له أن يكذب لا بإحضار القرآن، ولا في غير القرآن، بل عليه أن يتحرى الصدق إلا في المسائل التي أباح فيها النبي ﷺ الكذب، كالإصلاح بين الناس، والحرب، وحديث الرجل امرأته، فإذا كان ألزم باليمين في هذا، أو رأى المصلحة في هذا؛ فلا بأس أن يقول: والله ما كان كذا في الحرب، أو والله ما فعلت كذا في الحرب، إذا رأى فيه المصلحة للمسلمين. أو والله ما -يقول لامرأته-: والله ما فعلت هذا ليرضيها، ولا يضر غيره، ولا غيرها، أو في الإصلاح بين الناس، يجي قبيلة ويقول: والله ما قال هذا فلان ... يصلح بينهم، أو والله ما قالت القبيلة، أو والله إنها تحبكم، أو والله إنها تود الصلح معكم؛ ليصلح بينهم على وجه لا يضر أحدًا، هذا كله لا بأس به. المقدم: جزاكم الله خيرًا، إذًا نفهم من سماحتكم أن الحلف على المصحف أمر غير مشروع. الشيخ: ليس له أصل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14786/حكم-قبول-اعمال-العاق-لوالديه-والحلف-على-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80311.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":16626,"question":"من المستمعة (ل. ع. ف) من الباحة رسالة تقول فيها: لقد قمنا ببيع ذهبنا على البائع، ووزنه البائع أمامنا، وأخبرنا عن قيمته، علمًا بأننا لم نستلم منه شيئًا، ثم أخبرناه بأننا سوف نشتري منه ذهبًا آخر، وبالفعل اشترينا منه الذهب، وعدنا إلى مكاننا، وبعد فترة علمنا من بعض الناس أن هذا نوع من الربا، وهو ربا الفضل، وبعدها ذهبنا إلى البائع نفسه، بعد فترة، وبعنا له الذهب الجديد الذي اشتريناه منه، واستلمنا قيمته بأيدينا، وذهبنا إلى بائع آخر، واشترينا منه ذهبًا غير ذلك، و هل ما سمعناه من الناس: أن فعلنا نوع من ربا، وهو ربا الفضل؟ وهل تصرفنا صحيح؟ جزاكم الله خيرًا.","title":"أحكام بيع الذهب بالذهب","answer":"الجواب: الواجب في بيع الذهب والفضة بذهب وفضة، أو بالعمل الورقية؛ التقابض، فإذا باع الإنسان ذهبًا، أو فضة على صواغ، أو صيرفي، أو غيرهما، لا بد من القبض، لا يتم البيع إلا بالقبض؛ لقوله ﷺ: الذهب بالذهب، والفضة بالفضة، وزنًا بوزن، مثلًا بمثل، سواء بسواء، فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم، إذا كان يدًا بيد إذا اختلفا يكون يدًا بيد، ذهب بفضة، ذهب بدولار، ورق بأريلة، ورق بجنيهات، ورق يدًا بيد، لا بد أن يكون يدًا بيد، لا يتفرقان حتى يتقابضا؛ وإلا يكون ربا، فإذا جاءت المرأة بالذهب إلى صيرفي، أو صائغ، أو غيرهما تبيع عليه؛ لا بد تقبض الثمن، إذا كان الثمن ذهبًا، مثلًا بمثل، سواء بسواء، يدًا بيد، وإن كان فضة كذلك، لا بد يدًا بيد، أو عمل ورقية، لا بد يدًا بيد. فالبيع الذي فعلتم أولًا لا يجوز، لا بد من القبض، قبض الثمن، ثم بعد القبض أنتم بالخيار، إن شريتم منه، أو من غيره ذهبًا آخر، وهكذا بيع الفضة، سواء سواء، بيع الفضة بفضة، أو بذهب، إن كان بفضة؛ لابد مثلًا بمثل، سواء بسواء، لا يزيد هذا على هذا شيء، لابد من التقابض، فإن كان فضة بالذهب فلابد من القبض فقط، يدًا بيد، ولو بعمل ورقية، لا بد يدًا بيد؛ لأنها منزلة منزلة الذهب والفضة، هذه العمل، فلابد أن يتقابضا: دينارًا بدولار، يدًا بيد، مائة دولار بمائتي درهم، أو بثلاثمائة درهم، لابد يدًا بيد، هكذا دنانير بجنيهات، أو بدراهم سعودية، أو بغير ذلك، لابد يدًا بيد، وبذلك يسلم المؤمن والمؤمنة من الربا. أما لو باع الذهب بشيء آخر مثل باع عليه، باعت مثل أسورة على زيد، أو عمرو بسيارة، أو بأواني موجودة؛ فهذه لا بأس في التفرق؛ لأنها معينة، وليست ذهبًا، ولا فضة، ولا عمل، أو بأرض، أو ببيت يتفرقون؛ لا بأس، يشتري بيتًا بآلاف من الدنانير، أو من الذهب، أو من الدراهم إلى أجل معلوم، لا بأس، أو سيارة، أو أواني، أو ملابس، أو فرش، أو حيوانات، أو ما أشبه ذلك، المقصود أنه إذا كان بغير العمل. أما بالعملة لابد يدًا بيد، ذهب بأي عملة، أو فضة بأي عملة، لابد يدًا بيد، فإن كان ذهبًا بذهب نفسه، أو فضة بفضة، لابد من أمرين: التساوي في الوزن، والقبض، لابد أن يكون وزنًا بوزن، ما يزيد هذا ولا شعرة، وزنًا بوزن، يعني: دينار ذهب بدينار ذهب، لا يزيد شيئًا، درهم فضة بدرهم فضة، لا يزيد شيئًا، ومع التقابض، كما أمر النبي ﷺ. وهكذا العمل الموجودة دولارات بدولارات، لابد يدًا بيد، مثلًا بمثل، عشرة بعشرة، عشرة دولارات بعشرة دولارات، عشرة ريالات سعودية بعشرة ريالات، يدًا بيد، سواء بسواء. نعم. المقدم: جزاكم الله خيرًا، أما وقد فعلوا سماحة الشيخ، فما هو توجيهكم؟ الشيخ: مثل ما فعلوا يرجعون على صاحبهم، يفسخون البيع، يأخذون سلعهم، ويردون عليه دراهمه؛ لأن البيع ما هو صالح، أو يتبايعان في الحال، يقلن: الآن نبي نتبايع يعني: الآن الدراهم عندهم، والذهب عنده ... الآن، نتبايع الآن من جديد على الدراهم التي عندهم بالسعر الحاضر، يكون بيعًا جديدًا بالسعر الحاضر. المقدم: إذًا ما فعلوه هو الصحيح؟ الشيخ: نعم ... المقدم: نعم، عادوا إليه، وباعوا عليه الذهب، ثم اشتروا ذهبًا من مكان آخر. الشيخ: نعم، باعوا عليه ذهبهم هم. المقدم: ذهبهم نعم. الشيخ: نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15361/احكام-بيع-الذهب-بالذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75905.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16720,"question":"من المستمع إبراهيم علي المشهد سوري، ويعمل في الأردن، كما في رسالته، يسأل جمعًا من الأسئلة، من بينها سؤال يقول: ما حكم بيع سلعة، أو دراجة آلية مثلًا لمدة ستة أشهر بزيادة عن ثمنها قدره عشرة آلاف ليرة سورية، هل يعتبر هذا من الربا؟ أم أنه جائز؟ جزاكم الله خيرًا، وأحسن إليكم.","title":"ما حكم بيع سلعة بزيادة عن ثمنها؟","answer":"الجواب: ليس للثمن، والربح حد محدود، فإذا بعت الدراجة، أو السيارة بثمن معلوم إلى أقساط وآجال؛ فلا بأس، اشتريت السيارة، والدراجة بعشرة آلاف، وبعتها بعشرين ألفًا في كل شهر خمسمائة، أو في كل شهر ألفًا، أو بالسنة؛ لا حرج في ذلك، ولو كان الثمن أكثر من ثمنها بالنقد؛ لأن هذا أمر معروف الأجل غير النقد، فليس في هذا شيء. لكن عليك أن ترفق بالمشتري إذا كان ما يفهم، توضح له الأمر، وتبين له الأمر؛ حتى لا تخدعه بشيء يضره: المسلم أخو المسلم لا يظلمه فعليك أن تراعي في هذا البيع المعتاد، والثمن المعتاد إذا كان صاحبك غرًا لا يفهم الأمور، فعليك بالرفق به، وأن تبيعه كما تبيع الناس الفاهمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15476/ما-حكم-بيع-سلعة-بزيادة-عن-ثمنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76109.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16764,"question":"يقول: إذا اشتريت بضاعة بثمن مؤجل، وبعتها قبل أن يأتي أجل سدادها، هل لي أن أنتفع بثمنها في البيع والشراء قبل أن يحين أجل السداد؟","title":"حكم التصرف بثمن السلعة قبل سداد قيمتها","answer":"الجواب: نعم، لا بأس عليك، تنتفع بثمنها، وإذا جاء وقت السداد تسدد من ثمنها، وإلا من غيره، لا يلزمك حتى يحضر الأجل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15542/حكم-التصرف-بثمن-السلعة-قبل-سداد-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82213.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16774,"question":"يقول: إذا اشتريت بضاعة بثمن مؤجل، وبعتها قبل أن يأتي أجل سدادها، هل لي أن أنتفع بثمنها في البيع والشراء قبل أن يحين أجل السداد؟","title":"حكم التصرف بثمن السلعة قبل سداد قيمتها","answer":"الجواب: نعم، لا بأس عليك، تنتفع بثمنها، وإذا جاء وقت السداد تسدد من ثمنها، وإلا من غيره، لا يلزمك حتى يحضر الأجل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15542/حكم-التصرف-بثمن-السلعة-قبل-سداد-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82213.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16874,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من أحد الإخوة المستمعين، سمى نفسه السديس، أخونا له بعض الأسئلة في أحدها يقول: شركة تعرض بطاقات للتخفيض بالاشتراك بمبلغ محدد في السنة، يعطى حاملها تخفيضًا بنسبة معينة، وذلك في بعض الجهات التجارية دون بعض، ما حكم الاستفادة منها؟ جزاكم الله خيرًا.","title":"حكم بطاقات التخفيض التي تعرضها الشركات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فحكم هذه المعاملة عدم الجواز، بل ذلك من الربا؛ لأنه يدفع أموالًا من النقود في مقابل تخفيض في محلات معينة، إذا اشترى منهم في مقابل هذا المال الذي قدمه للشركة، وقد صدر من اللجنة الدائمة للبحوث العلمية، والإفتاء -برئاستي واشتراكي- فتاوى كثيرة في هذا الباب كلها تفيد المنع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15626/حكم-بطاقات-التخفيض-التي-تعرضها-الشركات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82419.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":16973,"question":"أحسن الله إليكم، بالنسبة للتسمية سماحة الشيخ في الطعام، والشراب سرًا، أم جهرًا؟","title":"الأفضل الجهر بالبسملة عند الطعام والشراب","answer":"الجواب:  جهرًا حتى يسمع الحاضرون، ويستفيدوا، ويتأسى بعضهم ببعض، وكان ﷺ يأمر من حضر أن يسمي، ولما جاء أعرابي يريد أن يأكل أمسك بيده حتى سمى، وقال لغلام كان يأكل معه وهو ربيبه عمر بن أبي سلمة: يا غلام سم الله، وكل بيمينك، وكل مما يليك هذه طعمته ﷺ الكيفية، يسمي الله، ويأكل بيمينه، ويأكل مما يليه، ولهذا قال عمر بن أبي سلمة: «هذه طعمتي» من حين علمه النبي ﷺ يعني هذه الكيفية، يسمي الله، ويأكل بيمينه، يقول بسم الله الرحمن الرحيم، أو بسم الله، وإن كملها بسم الله الرحمن الرحيم يكون أفضل، ويأكل بيمينه، ويأكل مما يليه، إلا إذا كان الطعام متنوعًا له أن يأكل من النوع الثاني.","link":"https://binbaz.org.sa/fatwas/15757/الافضل-الجهر-بالبسملة-عند-الطعام-والشراب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58622.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":17037,"question":"من المغرب السائل خالد يقول: ما حكم الشخص الذي باع بهيمة مريضة، وهو يعلم بمرضها؟","title":"حكم بيع البهيمة المريضة","answer":"الجواب: الواجب أن يبين لا يغش الناس، يقول: ترى فيها مرض كذا وكذا، يبين، أما إذا غش الناس لا يجوز، الرسول ﷺ يقول: من غشنا فليس منا هكذا يقول ﷺ: من غشنا فليس منا فيقول: إنها مريضة بكذا وكذا. حتى يكون المشتري على بصيرة، ويقول النبي ﷺ في البيعان: إن صدقا وبينا؛ بورك لهما في بيعهما، وإن كتما وكذبا؛ محقت بركة بيعهما نسأل الله العافية، وإذا درى المشتري عن المرض؛ فله الرد، له الخيار. نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15825/حكم-بيع-البهيمة-المريضة","audio":"","categories":["البيوع","الأطعمة والأشربة"]},{"id":17116,"question":"من أسئلة هذه السائلة، تقول: ما حكم الجائزة التي تكون مقابل شراء شيء، مثلًا: يدفع لك شيئًا عندما تشتري من هذه البقالة، وغيرها؟","title":"حكم أخذ الجائزة مقابل الشراء","answer":"الجواب: إذا أعطوك شيئًا ما قصدته إنما هو هدية منهم لا بأس، أما ما يفعله بعض الناس، من اشترى منهم كذا وكذا يعطون كذا، فالأولى ترك ذلك؛ لأن هذا ترغيب في الشراء منهم، وقد يفضي إلى تعطيل الآخرين، والشحناء، ترك هذا أولى. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15924/حكم-اخذ-الجاىزة-مقابل-الشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58913.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":17254,"question":"هذا سائل للبرنامج يقول، سماحة الشيخ أبو محمد يقول في هذا  هل البيع بالتقسيط مع زيادة سعر البضاعة ربًا؟ أم لا؟","title":"هل البيع بالتقسيط مع زيادة سعر البضاعة ربًا؟","answer":"الجواب: لا حرج في بيع التقسيط لا بأس، إذا كانت السلعة تساوي أربعين نقدًا، وباعها بستين أقساطًا، كل شهر خمسة آلاف، أو كل سنة خمسة آلاف، لا بأس بهذا، بريرة -رضي الله عنها- قد بيعت بالتقسيط، بيعت تسع أواق، كل عام أوقية، أربعين درهمًا، فاشترتها عائشة بنقد، فلا بأس بالتقسيط، وفيه فرج للناس، فإذا باع البيت، أو السيارة، أو غيرهما بالتقسيط، فلا حرج فيه، إذا كانت الأقساط معلومة، والآجال معلومة، لا حرج في ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16091/هل-البيع-بالتقسيط-مع-زيادة-سعر-البضاعة-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59208.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":17429,"question":"سماحة الشيخ عبد العزيز حفظكم الله، البعض من الناس يلزمون أنفسهم بهذه النذور، ومن ثم يعجزون عنها، ويطلبون الفتيا من المشايخ، ما الواجب على الناس في ذلك يا شيخ؟","title":"توجيه لمن يلزمون أنفسهم بالنذور","answer":"الجواب: النذر لا ينبغي، الرسول نهى عن النذر، وقال ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل.  فالواجب على الناس ترك النذور، وعدم التعاطي، يعني: ينبغي للمسلم أن يتجنب النذور؛ لأنه ينذر، ثم يندم، فالواجب تجنب النذور، لكن متى نذر طاعةً؛ وجب الوفاء؛ لأن الله قال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7] ويقول سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270] يعني: فيجازيكم عليه، والنبي يقول ﷺ: من نذر أن يطيع الله فليطعه.  فإذا وقع النذر نظر فيه، فإن كان طاعةً لله؛ وجب الوفاء، وإن كان غير طاعة؛ كفَّر عن نذره، لكن لا ينبغي له أن ينذر أولًا، يعني: يعلم ألا ينذر أبدًا، لكن متى نذر طاعةً، كأن يقول مثلما تقدم: إن الله شفى مريضي؛ صمت شهرًا، أو صمت عشرة أيام.. تصدقت بألف ريال، وما أشبه ذلك؛ يلزمه الوفاء، لكن أولًا يقال له: لا تنذر، لكن متى نذر طاعة؛ لزمه الوفاء، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16300/توجيه-لمن-يلزمون-انفسهم-بالنذور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77122.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":17727,"question":"هذا سائل للبرنامج يقول: هل السمسرة حلال أم حرام؟ وهو ما يقوم الوسيط بالاتفاق بين البائع والمشتري؟","title":"حكم السمسرة أو الوساطة بين البائع والمشتري","answer":"الجواب: لا حرج في ذلك، السمسار الدلال كونه يبيع له إبله أو بقره أو غنمه أو ثمرته أو ملابس أو ..، لا حرج، أو أرض أو غير ذلك، يسمى الدلال، لا حرج وهو السمسار. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16686/حكم-السمسرة-او-الوساطة-بين-الباىع-والمشتري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59533.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":17728,"question":"يقول السائل أيضًا: هل في البيع والشراء ربح محدود حددته الشريعة الإسلامية؟","title":"هل حددت الشريعة ربحًا معينًا في البيع؟","answer":"الجواب: ما فيه شيء محدود، لكن ينبغي للمؤمن أن لا يشق على الناس، وأن لا يستغل الجاهل.. يبيع مثلما يبيع الناس، ويأخذ الربح مثل الناس.. لا يستغل الجاهل والضعيف اللي ما يفهم ويزيد عليه، يبيع مثل ما يبيع للناس، ويقنع بالربح المناسب.. هذا هو الأفضل. نعم.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16687/هل-حددت-الشريعة-ربحا-معينا-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59534.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":17800,"question":"سماحة الشيخ! هذا السائل يقول: في شخص أخذ منه عشرة آلاف ريال ... السنة يقول: أعطيته مائتين كرتون صابون، تطلع عليَّ بستة عشر ألف ريال، فأفيدونا يا سماحة الشيخ، هل في ذلك ربا؟","title":"حكم التعامل بالسلم في الصابون","answer":"الجواب: إذا كان سلم أسلم له عشرة آلاف ....... صابون، مع صابون معروف إلى أجل معلوم لا بأس، مثلما يسلم في تمر ورز وغيره، إذا كان .. الصابون شيء معروف لا يخفى، وضبطوه بالصفة إلى أجل معلوم- سنة أو أكثر- لا بأس، لا حرج. إذا كان قبض الثمن في المجلس. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16781/حكم-التعامل-بالسلم-في-الصابون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59711.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":17843,"question":"السائل يقول: إذا اشترى المشتري ثوبًا بمائة ريال مثلًا ووجد أن الثوب غير مناسب من حيث المقاس فذهب إلى البائع لإرجاعه ولكن البائع رفض ذلك حيث إن البائع قد اشترط بأن البضاعة المباعة لا ترد ولا تستبدل، وعندما لم يستطع المشتري أن يرجع الثوب قال المشتري للبائع: خذ الثوب وأعطني خمسين ريال بدلًا من مائة ريال، فوافق البائع، والسؤال يبقى يا سماحة الشيخ: هل هذا يعتبر من الربا؟","title":"حكم الخصم من قيمة البضاعة عند إرجعها","answer":"الجواب: لا حرج في هذا إذا اشترى ثوبًا أو غيره شراءً جازمًا ما فيه خيار، ثم ذهب إلى أهله أو غيره ثم رجع وقال: إنه ما ناسبنا الثوب ما يلزم البائع أن يقبل، تم البيع، يقول النبي ﷺ: البيعان بالخيار ما لم يتفرقا، فإن تفرقا وجب البيع فإذا تفرق البيعان ولم يشترطا خيارًا وجب البيع، فإذا اشترى ثوبًا، أو إناءً، أو دابة، أو سيارة، ثم ذهب وفارق المجلس، ثم رجع يريد ردها لا، ليس له الرد إلا برضى البائع، فإذا قال البائع: لا. تم البيع بيننا، فليس له شيء إلا أن يجد فيها عيبًا إذا وجد فيها عيبًا هذا له خيار، فإذا باعها على البائع بثمن أقل فلا بأس، لا حرج، اشتراها من مائة وباعها بخمسين أو بثمانين أو بسبعين لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16836/حكم-الخصم-من-قيمة-البضاعة-عند-ارجعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78002.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18196,"question":"يسأل سماحتكم -شيخ عبد العزيز - عن شخص في حاجة إلى بعض المال، لأمر الزواج مثلًا، ويقول: هل لي أن أشتري سيارة -مثلًا- وأبيعها، وأستفيد بثمنها، مع فارق في البيع والشراء؟ جزاكم الله خيرًا.","title":"حكم الشراء بالتقسيط ثم البيع بأقل لأجل النقد","answer":"الجواب: نعم، له أن يشتري السيارة، أو غيرها، ثم يبيعها وينتفع بثمنها في الزواج، يشتريها بأقساط مؤجلة مثلًا، أو لأجلٍ معلوم، ولو قسطًا واحدًا، ثم يبيعها ويتزوج، لا بأس بهذا، هذا من المداينة الجائزة، إذا كان البائع قد ملكها، وحازها، ثم باع عليه، لا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17231/حكم-الشراء-بالتقسيط-ثم-البيع-باقل-لاجل-النقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73114.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18461,"question":"يقول هذا السائل: أنا أعمل بالتجارة، وبعض الأحيان يأتي شخص يطلب سلعة معينة، وهي غير موجودة عندي، فأقول له بأنها موجودة، ثم آخذ التليفون وأبحث في السوق حتى أجدها، ثم آخذها من التاجر الآخر بسعر معين على أن أسدد له المبلغ عندما يأخذها الزبون، والآن أسأل عن ذلك مأجورين سماحة الشيخ؟","title":"عدم مشروعية البيع إلا بعد التملك","answer":"الجواب: إذا اشتريت السلعة وأحضرتها في محلك، ثم بعتها على الشخص لا بأس، لا تبيع حتى تحضرها، تشتريها، تحضرها، تنقلها إلى محلك، فإذا اشترى الإنسان السلعة من زيد أو عمرو ثم نقلها إلى محله جازمًا عليها ثم باعها بعد ذلك لا بأس. أما أن يبيع والشيء عند غيره لا؛ لأن الرسول ﷺ قال: لا تبع ما ليس عندك، لا يبيع الإنسان ما ليس عنده، لكن إذا شراها ذهب وشراها أو بالتلفون وأرسلت إليه، وجاءت إليه سلعة في محله مشتريًا لها، ثم باعها بعد ذلك؛ فلا بأس. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17565/عدم-مشروعية-البيع-الا-بعد-التملك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78515.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18610,"question":"انتشر في هذه الأيام شراء السيارات بطريقة معينة؛ وذلك أن يأتي المشتري إلى بائعي السيارات، ويأخذ سيارة منهم، ويسدد مبلغها كل شهر بقيمة معينة، مع زيادة في الثمن، وقد يستمر هذا التسديد لمدة سنة أو سنتين أو أكثر، فما هو توجيهكم؟ هل هذا جائز؟جزاكم الله خيرًا.","title":"جواز بيع التقسيط","answer":"الجواب: ليس فيه محذور، هذا بيع التقسيط، إذا اشترى منه السيارة أو البيت أو الأرض أو غير ذلك بثمن مقسط كل أجل له كذا، آجال معلومة، كل شهر أو كل سنة معلومة، فلا حرج في ذلك، إذا كان المبيع موجودًا عند البائع، في ملكه وحوزته، لا يبيع ثم يروح يشتري لا، لا بد .....، كله عنده في حوزته قد قبضه، فإذا باع بالأقساط أو بالنقد المعجل لا بأس، كله طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17717/جواز-بيع-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73410.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18647,"question":"الفقرة الأخيرة سماحة الشيخ في رسالة السائل (م. م. ج) يقول: هل يجوز بيع الثمار وهي على الشجر دون معرفة وزنها؟","title":"حكم بيع الثمار وهي على الشجر","answer":"الجواب: إذا كان بدا صلاحها لا بأس، إذا بدا صلاحها يجوز بيع النخل ثمرة النخل أو العنب إذا بدا صلاحه، وهي عاد في رؤوس الشجر لا بأس؛ لأنه ﷺ \"نهى عن بيع الثمرة حتى يبدو صلاحها\" فإذا بدا صلاحها فلا حرج. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17764/حكم-بيع-الثمار-وهي-على-الشجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78723.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18650,"question":"الفقرة الأخيرة سماحة الشيخ في رسالة السائل (م. م. ج) يقول: هل يجوز بيع الثمار وهي على الشجر دون معرفة وزنها؟","title":"حكم بيع الثمار وهي على الشجر","answer":"الجواب: إذا كان بدا صلاحها لا بأس، إذا بدا صلاحها يجوز بيع النخل ثمرة النخل أو العنب إذا بدا صلاحه، وهي عاد في رؤوس الشجر لا بأس؛ لأنه ﷺ \"نهى عن بيع الثمرة حتى يبدو صلاحها\" فإذا بدا صلاحها فلا حرج. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17764/حكم-بيع-الثمار-وهي-على-الشجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78723.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18774,"question":"هذا سائل للبرنامج أرسل بهذه الرسالة، وضمنها مجموعة من الأسئلة، محمد الطيب سوداني، يقول في هذا  ما حكم الذي يحلف بالطلاق في البيع والشراء، وهو يعلم بأنه كاذب ليروج سلعته؟وجزاكم الله خيرًا.","title":"حكم ترويج السلع بالأيمان الكاذبة","answer":"الجواب: حكمه أنه مجرم ظالم لنفسه عاصٍ، سواءً حلف بالطلاق، أو باليمين بالله، أو بغير ذلك، وهو كاذب قد خان الأمانة، فالواجب عليه التوبة إلى الله من ذلك، فالكذب محرم في البيع والشراء، وإن لم يطلق، وإن لم يحلف، فإذا أكد بالحلف والطلاق صار أشد في الإثم، نعوذ بالله. فالواجب عليه التوبة إلى الله من ذلك، والحذر من العود إلى هذا، يقول النبي ﷺ في البيعان: إن صدقا وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما ويقول ﷺ: ثلاث لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم -وذكر منهم- الرجل يبيع السلعة بعد العصر، ويقول: أعطي بها كذا وكذا، وهو كاذب نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17902/حكم-ترويج-السلع-بالايمان-الكاذبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79108.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":18798,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من المستمع (ع. م. ح) من الرياض أخونا بدأ رسالته بقوله: بسم الله الرحمن الرحيم. سماحة الشيخ عبد العزيز بن عبد الله بن باز أثابه الله، السلام عليكم ورحمة الله وبركاته، وبعد:لقد اطلعت على فتوى سماحتكم والمرفق صورتها، وهي قيام بعض المؤسسات والمحلات التجارية بنشر إعلانات في الصحف وغيرها عن تقديم جوائز لمن يشتري من بضائعهم المعروضة، مما يغري الناس على الشراء من هذا المحل دون غيره، إلى آخره، وأن هذا نوع من القمار المحرم شرعًا. وسؤالي هو: هل محطات البنزين التي تزود من يشتري منها بنزين لسيارته بكرت مكتوب عليه: عند حصولك على كروت بكمية ثلاثة آلاف لتر بنزين يحق لك غسيل سيارتك لدينا مجانًا، هل هذا من القمار المحرم شرعًا أيضًا كسابقه؟نرجو منكم الإفادة، أثابكم الله.والواقع أنه أرفق إعلان، وأرفق أيضًا صورة من الفتوى التي صدرت منكم سماحة الشيخ.الشيخ: تقرأ الإعلان.المقدم: إذا رأيتم هذا؟الشيخ: نعم.المقدم: محطة كذا لخدمة السيارات وللمحروقات في المكان الفلاني، إلى زبائننا الكرام اطلب كرت بموجب الكمية المصروفة في سيارتك عند حصولك على كروت بكمية ثلاثة آلاف لتر بنزين، يحق لك غسيل سيارتك لدينا مجانًا، ومذكور اسم المحطة، ومكانها.","title":"حكم الجوائز التي ترصدها الشركات لترويج منتجاتها","answer":"الجواب: هذا فيه نظر، ويحتاج إلى تأمل ودراسة؛ لأنه قد يحصل بذلك هجر المحلات الأخرى التي لا تعلن هذا الإعلان تشويش عليها، فيحصل مثلما يحصل في إعلان التجار الذي أشار إليه السائل.  فالأحوط في مثل هذا عدم العمل بهذا الإعلان، وعدم الالتفات إليه؛ لأنه قد يحصل به من الأذى للآخرين ما هو معلوم، أما الجزم بأنه محرم فهو يحتاج إلى مزيد عناية في حلقة أخرى -إن شاء الله-. المقدم: إن شاء الله، إذًا أبقي إليكم هذه الرسالة، وما أرفق بها؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17938/حكم-الجواىز-التي-ترصدها-الشركات-لترويج-منتجاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92103.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":18799,"question":"أبو محمد من الرياض بعث بجملة أو مجموعة من الأسئلة يقول: سماحة الشيخ، ما معنى \"النهي عن بيعتين في بيعة\"؟","title":"معنى \"النهي عن بيعتين في بيعة\"","answer":"الجواب: بيعتان في بيعة: أن يبيعه سلعة بشرط بيعة أخرى، أن يقول: أبيعك داري هذه بشرط أن تبيعني دارك أو أرضك أو بشرط أن تقرضني كذا وكذا؛ لقوله ﷺ: لا يحل سلف وبيع ولأنه نهى عن بيعتين في بيعة. ومن ذلك أن يبيعه السلعة إلى أجل ثم يشتريها بأقل، وهذه بيعتان في بيعة وهي تسمى العينة (ربا) لا تجوز، يبيعه السلعة مثلًا بمائة، ثم يشتريها بثمانين نقدًا أو ستين نقدًا منه فهذه حيلة على الربا كأنه أعطاه ستين نقدًا حتى يرد عليه مائة مؤجلة، فهذه بيعتان في بيعة، وهي من أصول الربا، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17942/معنى-النهي-عن-بيعتين-في-بيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79120.mp3","categories":["شروح الحديث","البيوع"]},{"id":18850,"question":"رسالة وصلت إلى البرنامج من المستمع : محمود بيرام إلياس من العراق، أخونا له جمع من الأسئلة في سؤاله الأول يقول: إن القرآن لا يشترى، بمعنى: أننا إذا ذهبنا إلى السوق لا نقول: بكم هذا القرآن، إنما نقول: بكم تعطيني هذه الهدية، هل قولي صحيح أم لا؟ وما هي العبارات التي تستحسنون أن نرددها عند هذا المقام؟","title":"حكم بيع وشراء المصحف","answer":"الجواب: لا حرج في شراء المصحف، ولا بأس بذلك في الصحيح من قولي العلماء، فإذا قلت: بعني هذا المصحف، أو بكم هذا المصحف، فلا حرج في ذلك؛ لأن القرآن مكتوب في الأوراق، فأنت تشتري الأوراق والجلد الذي فيه القرآن، فلا حرج في ذلك، تشتريه وتنفق فيه المال، وتقرأ أو تحسن إلى الناس بشرائه حتى تضعه في المساجد، أو تعطيه بعض إخوانك حتى يستفيدوا، أنت مأجور في هذا، ولا حرج في شرائه وبيعه جميعًا على الصحيح. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17985/حكم-بيع-وشراء-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92203.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":19129,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: علي الرفاعي علي جلال مصري الجنسية، ومقيم بسلطنة عمان، أخونا يسأل ويقول: قد سأل أخ من السودان سؤالًا وبالتحديد في يوم ثلاثين إحدى عشر سبعة وثمانين ميلادي، وكان سؤال هذا الأخ هو: هل الاتجار في السوق السوداء حلال أم حرام، وقد أجاب على هذا السؤال سماحة الشيخ عبد العزيز بن عبد الله بن باز، وكانت إجابة سماحته بأنه لا مانع من التجارة في السوق السوداء، وأنا لي تعليق هنا على هذه الإجابة وهو: المعروف عن السوق السوداء هو احتكار البضاعة ومنعها لحين أن تنتهي من السوق، وبعد ذلك يتم بيعها للمسلمين بأسعار مرتفعة، وفي هذه الحالة يضطر المسلمون للشراء بأسعار مرتفعة؛ لاحتياجهم لهذه السلع؛ ولأنها ليست متوفرة إلا بالسوق السوداء، وهذا استغلال للمسلمين، وبمنطق -الفترة فيما يبدو- هذا شيء غير محلل في الإسلام.فكيف أحل سماحة الشيخ ابن  باز التجارة في السوق السوداء، والحال ما ذكر؟ يرجى الإفادة، وجزاكم الله خيرًا.","title":"حكم الاتجار في السوق السوداء","answer":"الجواب: الذي جرى فيه الجواب هو أننا نعتقد أن السوق السوداء هي السوق العامة التي يبيع فيها الناس، ويشتري فيها الناس غير ما يقع في البنوك والمصارف المعروفة، فالسوق السوداء التي جرى فيها الفتوى هي ما يقع بين الناس في أسواقهم بيعهم وشرائهم، وأنه لا حرج أن يبيع في السوق العامة، ولا يتقيد بما في البنوك من الأسعار، هذا هو الذي أردنا. أما إذا كان هناك سلع تحتكر وتضر المسلمين، يضر المسلمين احتكارها، فهذا مسألة أخرى، هذه مسألة أخرى مسألة الاحتكار، والاحتكار ممنوع، النبي ﷺ قال في المحتكر: لا يحتكر إلا خاطئ، فلا يجوز الاحتكار في الأطعمة، ولا نحوها على الصحيح مما يضر المسلمين، فالذي مثلًا يحبس السلع التي يحتاجها المسلمون من طعام أو غيره، مما يحتاجه الناس حتى يغلى، حتى يرتفع، حتى يبيع على الناس بثمن مرتفع، هذا لا يجوز، لا في السوداء ولا في غير السوداء. لا يجوز للمسلم أن يحتكر ما يضر المسلمين احتكاره حتى يبيعه بالغلاء، بل يجب أن يبيع مع الناس، ويوسع على الناس، فليس لمن عنده طعام والناس محتاجون إليه أن يحتكره حتى يرتفع سعره، وليس لمن عنده سلاح وقت الحاجة إلى الجهاد في البلد أن يحتكره حتى يرتفع سعره، لا، بل عليه أن يبيع في الحال التي يحتاجها المسلمون للجهاد الشرعي، أو لأكلهم وشربهم، أو لبسهم ونحو ذلك، وليس له أن يحتكر شيئًا يضر المسلمين احتكاره، هذه قاعدة على الصحيح، وبعض أهل العلم قيد هذا بالطعام. والصواب أنه لا يتقيد بالطعام، بل كل شيء احتكاره يضر المسلمين فإنه يمنع احتكاره، والواجب على المسلم أن لا يحتكره طعامًا أو غير طعام، هذا هو جواب السائل. نعم. المقدم: جزاكم الله خيرًا، إذًا: وصف هذه السوق بالسوداء يبدو لي أنه لكونه يقع فيها هذا النوع من المعاملات سماحة الشيخ؟ الشيخ: هذا يمكن اصطلاح لبعضهم، لعلها تختلف السوداء في اصطلاح الناس. نعم. المقدم: بارك الله فيكم. ذكرتم سماحة الشيخ أنه لا يجوز الاحتكار بأي حال من الأحوال سواء كان في الأطعمة أو في غيرها، يشمل هذا السيارات والحديد وما أشبهه؟ الشيخ: إذا كان يضر المسلمين، إذا كان احتكاره يضر المسلمين، أما إذا كانت السلعة منشورة وكثيرة، وكونه يبقيها عنده حتى يتغير السعر لا يضر المسلمين لا بأس. المقدم: بطبيعة الحال هناك ضرر سماحة الشيخ كونه يشتري السلعة اليوم بعشرة آلاف، وإذا اختفت فترة سوف أشتريها بإحدى عشر ألف؟ الشيخ: إذا كان حبسه لها لا يغير السعر، ولا يضر الناس، إذا كان حبسه لها لا يضر السعر، ولا يضر الناس، ولكن هو اشتراها يقول: لعل الله يأتي فيها نصيب بعد حين لا بأس. المقدم: بارك الله فيكم. إذًا: إذا أدى الأمر إلى تغير السعر وارتفاعه فحينئذٍ يكون هذا من باب الاحتكار؟ الشيخ: هذا الاحتكار. نعم. المقدم: بارك الله فيكم، وهو ممنوع بطبيعة الحال؟ الشيخ: نعم. ممنوع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18309/حكم-الاتجار-في-السوق-السوداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88503.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":19191,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية، وباعثها أحد الإخوة من هناك يقول: أخوكم علاء الدين، أخونا علاء له قضية يقول فيها: نرجو منكم أن تتفضلوا بتوضيح الرأي في ظاهرة منتشرة، وهي أن مندوبي المشتريات الموكلين من قبل شركاتهم أو مؤسساتهم لشراء الأغراض يحصلون على مبلغ من المال لأنفسهم من خلال عملية الشراء، وتحدث هذه العملية غالبًا في صورتين:الصورة الأولى: أن يطلب مندوب المشتريات من البائع وضع سعر مرتفع عن السعر الحقيقي للسلعة على الفاتورة، ويقوم مندوب المشتريات بأخذ هذا الفرق في السعر لنفسه.أما الصورة الثانية: فإن مندوب المشتريات يطلب من البائع أن يكتب له الفاتورة بنفس سعر السلعة الحقيقي في السوق، ثم يطلب من البائع مبلغًا من المال لنفسه يتناسب مع كمية السلع المشتراة ويكون ذلك نظير تشجيع لمندوب المشتريات لكي يقصد هذا المحل دائمًا، نرجو أن تتفضلوا بالتوجيه، جزاكم الله خيرًا.","title":"حكم أخذ مندوب المشتريات نسبة ممن يتعامل معه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهاتان الصورتان اللتان سأل عنهما صاحب السؤال كلتاهما محرمة، وكلتاهما خيانة، سواء كان اتفق مع صاحب السلعة على زيادة الثمن على السعر المعروف في السوق حتى يأخذ الزيادة، أو أعطاه شيئًا فيما بينه وبينه ولم يجعل في الفاتورة إلا السعر المعروف، كل ذلك محرم، وكل ذلك خيانة، وكل هذا من أسباب أن يختار لنفسه من الباعة من يناسبه ولا يبالي بالسعر الذي ينفع الشركة ويبرئ الذمة، بل إنما يبالي بالشيء الذي يحصل به مطلوبه من البائعين، ولا يبالي بعد ذلك بالحرص على مصلحة الشركة، وأن يتطلب السعر المناسب المنخفض من أجل النصح لها وأداء الأمانة، فهذا كله لا يجوز؛ لأنه خيانة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18377/حكم-اخذ-مندوب-المشتريات-نسبة-ممن-يتعامل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93301.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":19251,"question":"من المستمع عبد الله محمد عبد الله يمني من بيحان مقيم في الرياض صدر رسالته -سماحة الشيخ- بقوله: إنني أحبكم في الله، ثم يسأل سماحتكم فيقول: ما حكم بيع السلعة لزبون، وبعدما يوافق على سعرها آتي بها من محل ثانٍ وأنا متأكد من كسبي، وجهوني جزاكم الله خيرًا.","title":"حكم عرض السلعة وبعد الموافقة يأتي بها من محل ثانٍ","answer":"الجواب: أما المحبة في الله فنقول: أحبك الله الذي أحببتنا له، والتحاب في الله من أفضل القربات، يقول النبي ﷺ: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا على ذلك وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال: إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليًا -يعني: ما عنده أحد- ففاضت عيناه يعني: خوفًا من الله، كل هؤلاء يظلهم الله في ظله يوم لا ظل إلا ظله، ومنهم المتحابون في الله. ويقول النبي ﷺ: يقول الله يوم القيامة: أين المتحابون بجلالي اليوم أظلهم في ظلي يوم لا ظل إلا ظلي جعلنا الله وإياكم وسائر إخواننا من المتحابين فيه . أما بيع السلعة قبل أن تشتريها هذا لا يجوز، لا يجوز للإنسان أن يبيع ما ليس عنده، يقول النبي ﷺ: لا يحل سلف وبيع ولا بيع ما ليس عندك، وسأله حكيم بن حزام  قال: يا رسول الله! الرجل يأتيني يريد السلعة وليست عندي، فأبيعها عليه ثم أذهب فأشتريها فقال ﷺ: لا تبع ما ليس عندك، فأنت إذا أردت البيع؛ تشتري أول السلعة، فإذا قبضتها وحزتها وصارت عندك، تبيع بعد ذلك، وتقول لمن رغب إليك: اصبر حتى أشتريها، فإذا شريت السلع عندك، وصارت في حوزتك وقبضتها، تبيعها على من شئت. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18444/حكم-عرض-السلعة-وبعد-الموافقة-ياتي-بها-من-محل-ثان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73814.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":19252,"question":"يسأل سؤالًا آخر فيقول سماحة الشيخ: ما الحكم إذا كان عندي بضاعة وأخفيتها، هل يجوز ذلك أو لا؟","title":"حكم إخفاء بعض السلع وبيعها في وقت آخر","answer":"الجواب: هذا فيه تفصيل: إن كان إخفاؤك لها من أجل الإغلاء على الناس والاحتكار، يعني: يضرهم إخفاؤها واحتكارها فلا يجوز لك، الرسول ﷺ قال: لا يحتكر إلا خاطئ يعني: إلا آثم. أما إن كان إخفاؤها وعدم بيعها لا يضر الناس؛ فلا بأس أن تدخر سلعًا عندك إلى وقت آخر حتى تبيعها في وقت آخر؛ إذا كان هذا لا يضر الناس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18445/حكم-اخفاء-بعض-السلع-وبيعها-في-وقت-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73815.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":19433,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من قطر باعثها أخونا محمد فهد القحطاني، الأخ محمد يسأل سؤالين في سؤاله الأول يقول: ما الحكم فيمن اشترى بعض السلع من شخص بمبلغ معين لأجل مسمى، وباع هذه السلع في نفس الوقت على شخص آخر بسعر أقل من سعر الشراء لحاجته للمال في ذلك الوقت؟","title":"حكم بيع التورق والفرق بينه وبين بيع العينة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذه المعاملة يسميها بعض الفقهاء التورق، ويسميها بعض العامة الوعدة، وهي أن يشتري سلعة إلى أجل ثم يبيعها بثمن أقل نقدًا لحاجته إلى النقد ليتزوج، أو ليقضي دينًا عليه، أو ليعمر سكنًا له، أو غير ذلك من الأغراض، وهذه المعاملة لا بأس بها على الصحيح. قد كرهها بعض أهل العلم، ومنع منها؛ لأنها في المعنى بيع نقود بنقود بواسطة السلعة، ولكن الصواب أنه لا حرج فيها، والناس محتاجون إلى هذه المعاملة لقضاء حوائجهم، وهي داخلة في قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ[البقرة:282].. الآية، فهي مداينة، فإذا كان البائع عنده السلعة موجودة في ملكه، وفي حوزته، ثم باعها إلى أجل معلوم، أو بأقساط إلى آجال معلومة؛ فلا بأس بذلك، لكن ليس له أن يبيع ما ليس عنده ثم يذهب فيشتريه لا، إنما يبيع ما كان عنده، وفي حوزته، وفي قبضته؛ لأنه ثبت عن رسول الله ﷺ أنه قال لحكيم بن حزام لما سأل عن هذا قال: لا تبع ما ليس عندك، إن حكيمًا سأله قال: «يا رسول الله! الرجل يأتيني يريد السلعة، وليست عندي فأبيعها عليه، ثم أذهب فأشتريها؟ فقال له عليه الصلاة والسلام: لا تبع ما ليس عندك، وصح عنه  أنه قال: لا يحل سلف وبيع، ولا بيع ما ليس عندك.\nفليس له أن يبيع سيارة أو غيرها لم يملكها بل سوف يذهب فيشتريها، أما إذا كانت السيارة عنده، أو الخام، أو الرز، أو نحو ذلك عنده في ملكه، وفي حوزته، في بيته، أو في متجره، أو في السوق قد ملكه فلا بأس أن يبيعه إلى أجل مسمى أو إلى آجال لا حرج في ذلك، ولا حرج على المشتري أن يبيعه أيضًا بأقل أو بأكثر، أو بالمساوي إذا قبضه أيضًا هو المشتري إذا قبضه، وحازه، وصار في ملكه ونقله من ملك البائع فإنه يبيعه بعد ذلك على من يشاء، ولا يبيعه على من اشتراه منه، لا يبيعه عليه، بل يبيعه على غيره، أما إذا باعه عليه بأقل من الثمن صارت مسألة العينة ولا تجوز، أما إن باعه على من باع عليه بمثل ما اشتراه به، يعني: تغيرت الأحوال، أو باع عليه بأكثر فلا بأس، لكن لا يبيعها على من اشتراها منه بأقل فإن ذلك لا يجوز لأنه بيع العينة وهي أن يشتري سلعة بثمن في الذمة أو مؤجل، ثم يبيعها على من اشتراها منه بأقل فهذا هو عين الربا؛ لأنه حيلة على أن يأخذ دراهم قليلة بالدراهم الكثيرة إلى أجل فلا يجوز.\nلكن إذا باع السلعة على غير من اشتراها منه، باعها في السوق، باعها على شخص آخر بثمن نقد ليقضي حاجته فلا بأس بذلك، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18670/حكم-بيع-التورق-والفرق-بينه-وبين-بيع-العينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94401.mp3","categories":["البيوع","الأطعمة والأشربة"]},{"id":19691,"question":"من أسئلة هذا السائل يقول: يا سماحة الشيخ، ما هو بيع العينة، وما حكمه؟","title":"تعريف بيع العينة وحكمه","answer":"الجواب: بيع العينة ربا، أن تبيع سلعة على إنسان بثمن مؤجل، ثم تشتريها منه بنقد هذه العينة، تبيع عليه مثلًا سيارة بستين ألف أقساط، ثم تبيعها عليه بنقد، تبيعها عليه بأربعين نقدًا يعطيك إياه. فالمعنى أنك أخذت أربعين بستين ربا حيلة، السيارة هنا جعلت حيلة، هذه هي العينة، أن تبيع سلعة بأجل، ثم تأخذها ممن اشتراها منك بنقد، تبيعها عليه بنقد، يعني: يعطيك نقدًا ويرد السلعة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/19001/تعريف-بيع-العينة-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95037.mp3","categories":["الربا والصرف","البيوع"]}]
